/// The inert open: nothing is contacted, and the answer is the same
/// instruction a refused anchor gives — show the route in words.
const fn inert_open_settings(_pane: crate::menu::PrivacyPane) -> crate::menu::SettingsOpen {
    crate::menu::SettingsOpen::Refused
}

/// The inert reset: nothing ran, so every folder is `ToolAbsent`, which is not a
/// decline (`reset_outcome` folds it apart).
fn inert_run_reset(plan: &ResetPlan) -> Vec<ResetAttempt> {
    plan.folders()
        .iter()
        .map(|folder| ResetAttempt::tool_absent(*folder))
        .collect()
}

/// How long one `tccutil` invocation may hold the main thread before it is
/// killed. `tccutil reset` answers in milliseconds; this is a ceiling, not a
/// budget.
///
/// It runs on the main thread from the reducer and talks to `tccd`, and an
/// unbounded main-thread wait on `tccd` can stall the event loop until the
/// WindowServer watchdog takes the GUI session down. An owner gesture may cost a
/// visible moment, never the event loop.
const RESET_INVOCATION_CEILING: std::time::Duration = std::time::Duration::from_millis(1000);

/// How often the bounded wait looks at the child. Small enough that the common
/// case (a few milliseconds) returns promptly, large enough not to spin.
const RESET_POLL_INTERVAL: std::time::Duration = std::time::Duration::from_millis(10);

/// Wait for `child` for at most `ceiling`, then kill and reap it. Returns the exit
/// code, or `None` when the child was signalled (as a killed child is), which
/// [`ResetAttempt::from_exit_status`] folds to `Declined { code: None }`: a
/// timeout is a decline, never a success or `ToolAbsent` (the tool did run). The
/// shape is `Child::wait`'s, so no caller can tell a timeout from a signal and
/// claim more than was observed.
fn wait_bounded(
    child: &mut aterm_uds::spawnfd::Child,
    ceiling: std::time::Duration,
) -> Option<i32> {
    let deadline = std::time::Instant::now() + ceiling;
    loop {
        match child.try_wait() {
            Ok(Some(status)) => return status.code(),
            Ok(None) => {
                if std::time::Instant::now() >= deadline {
                    let _ = child.kill();
                    // Reap, or the child stays a zombie for the life of the process.
                    return child.wait().ok().and_then(|s| s.code());
                }
                std::thread::sleep(RESET_POLL_INTERVAL);
            }
            Err(_) => return None,
        }
    }
}

/// The only spawn in this file: one `tccutil` invocation per folder, in plan
/// order, each recorded independently (§3.7). A folder whose invocation could not
/// start is `ToolAbsent`, not a decline. Each is bounded by
/// [`RESET_INVOCATION_CEILING`].
fn run_tccutil_reset(plan: &ResetPlan) -> Vec<ResetAttempt> {
    plan.commands()
        .into_iter()
        .map(|(folder, argv)| {
            let Some((program, args)) = argv.split_first() else {
                return ResetAttempt::tool_absent(folder);
            };
            // On Windows `spawnfd::command` gives a console tool a windowless console.
            match aterm_uds::spawnfd::command(program).args(args).spawn() {
                // The tool could not even start: not a decline.
                Err(_) => ResetAttempt::tool_absent(folder),
                Ok(mut child) => ResetAttempt::from_exit_status(
                    folder,
                    wait_bounded(&mut child, RESET_INVOCATION_CEILING),
                ),
            }
        })
        .collect()
}

/// The panel's whole string table, in render order. Built by
/// [`macos_access_copy`] and rendered by [`macos_access_card`]; the copy tests
/// drive it directly, which is how "no banned phrase" and "no coverage claim"
/// are checked over the entire matrix rather than over one screenshot.
#[derive(Clone, Debug, PartialEq, Eq)]
pub(crate) struct MacosAccessCopy {
    /// The live state line, from the cached probe.
    pub(crate) headline: String,
    /// Why the probe said that — including "no syscall was performed".
    pub(crate) probe_detail: String,
    /// What a grant is, and what aterm has not measured about it.
    pub(crate) coverage: String,
    /// The trade, in one sentence, unsoftened.
    pub(crate) trade: String,
    /// Who grants Full Disk Access — the peer of the debugger row's line
    /// (debugger design §3.3).
    pub(crate) grants: String,
    /// How long a Full Disk Access grant lasts, and what it applies to.
    pub(crate) lasts: String,
    /// Whether an interruption remains possible.
    pub(crate) prompt: String,
    /// The route in words. Always shown: `openURL:` reports that System
    /// Settings took the URL, never that it scrolled to the row.
    pub(crate) route: String,
    /// aterm reports its own probe and never the System Settings switch.
    pub(crate) observation: String,
    /// Where this process runs from, and what that means for a grant.
    pub(crate) identity: String,
    /// The bundle this process runs from is gone from its name, so no grant
    /// can be checked. `None` while the anchor is healthy. Painted as its own
    /// Danger line under the headline, which can still read "granted".
    pub(crate) anchor_fault: Option<String>,
    /// Why a dialog about a tool run here names aterm — and which sessions are
    /// attributed to a previous copy.
    pub(crate) responsible: String,
    /// One line per service class, in the verb's order, each saying exactly
    /// what has been measured about it: nothing, or a verdict.
    pub(crate) services: Vec<String>,
    /// The rebuild explanation, when the grant is bound to an identity that
    /// does not survive one. `None` otherwise — it is not a general caveat.
    pub(crate) rebuild: Option<String>,
    /// One line per folder the warm-up has an answer for.
    pub(crate) folders: Vec<String>,
    /// The denied-state sentence, plus whatever the last *Ask again* did.
    pub(crate) repair: Vec<String>,
    /// The conflicting copies of the app on this Mac, when the census found any.
    pub(crate) claimants: Vec<String>,
    /// What the last *Move to Trash* did, one line per copy.
    pub(crate) retired: Vec<String>,
    /// How the latest *Move to Trash* is going or went.
    pub(crate) retire_status: Option<String>,
    /// The debugger-access row, the Full Disk Access row's peer. (The
    /// Developer Tools list has its own card, [`devtools_card_copy`].)
    pub(crate) debugger: DebuggerRowCopy,
}

/// THE DEVELOPER TOOLS CARD's words (`docs/DESIGN-macos-debugger-access-2026-09-29.md`
/// §9.1; owner ask 2026-10-15: "make sure that there is a status screen in
/// settings on this"). Built by [`devtools_card_copy`] as a total function of
/// the published facts and `evidence`: the state comes from the JOINED verdict
/// the digest line and the helper panel act on, worded by where it came from
/// (the switch's row when aterm read it, else tccd's answer, held to spike D13);
/// what being listed skips says "should" until spike D14; the why, the how and
/// the trade are `atpkg::devtools`' one spelling, which the panel and `aterm
/// doctor` print too.
#[derive(Clone, Debug, PartialEq, Eq)]
pub(crate) struct DevToolsCardCopy {
    /// Whether aterm is on the list, from the joined verdict and keyed by
    /// source; or why aterm can't tell; or not checked when the privacy checks
    /// are off.
    pub(crate) state: String,
    /// The state in a word or two, for the card's one-row floor, where the full
    /// sentence would be cut short: "on", "off", "not listed", "can't tell"…
    pub(crate) state_short: &'static str,
    /// How the state line is set: Success only for a verdict of granted.
    pub(crate) state_style: StyleRef,
    /// The joined verdict is granted: the card keeps the state line, the trade
    /// and the button.
    pub(crate) granted: bool,
    /// The list was refused for want of Full Disk Access: the card below grants
    /// it. `None` otherwise.
    pub(crate) unread: Option<String>,
    /// What the list is, in Apple's words, and what it is not: debugger access,
    /// the "Developer Tools Access" password dialog.
    pub(crate) kind: String,
    /// Why aterm asks (`atpkg::devtools::why`).
    pub(crate) why: String,
    /// tccd's measured cost in its window, when its log was read whole and it
    /// checked any program.
    pub(crate) checked: Option<String>,
    /// How to add aterm, switch on the row it has, or — listed and on while
    /// macOS still checks — that there is nothing to add
    /// (`atpkg::devtools::Step::how`).
    pub(crate) how: String,
    /// The route in words, with the installed bundle when there is one.
    /// Before the trade, whose "there" it is.
    pub(crate) route: String,
    /// The trade (`atpkg::devtools::trade`).
    pub(crate) trade: String,
    /// Which switch matters (`atpkg::devtools::only_aterm`), so an owner does not
    /// switch Terminal on for want of a word on why it is listed.
    pub(crate) only: String,
    /// When aterm last opened the page for the owner. `None` when it never has.
    pub(crate) opened: Option<String>,
    /// The owner's Not now while it holds and aterm is not granted: why aterm
    /// leaves the page alone, until when, and that the button still opens it.
    pub(crate) declined: Option<String>,
}

/// The debugger-access row (`docs/DESIGN-macos-debugger-access-2026-09-29.md`
/// §3.3), in render order. Built by [`debugger_row_copy`] as a total function of
/// the published facts: what it says the rule is comes only from the cached
/// `-status` probe, never from a change's exit code.
#[derive(Clone, Debug, PartialEq, Eq)]
pub(crate) struct DebuggerRowCopy {
    /// "Debugger access — allowed / not allowed / not recognised / not
    /// observed", or not checked when the privacy checks are off.
    pub(crate) headline: String,
    /// What the row is, and what it is not: the Developer Tools list.
    pub(crate) kind: String,
    /// The observed state in words (the design's by-state table), with the
    /// not-hardened sentence where the button it explains is drawn.
    pub(crate) state: String,
    /// What the last confirmed press or change came to, if anything.
    pub(crate) status: Option<String>,
    /// The four facts the Full Disk Access row states too, plus the trade.
    pub(crate) stops: String,
    pub(crate) grants: String,
    pub(crate) lasts: String,
    pub(crate) undo: String,
    pub(crate) trade: String,
    /// Machine-wide like THIS MAC, but never applied automatically: it changes
    /// only on the owner's yes in aterm's alert.
    pub(crate) cross_link: String,
    /// Which of the two buttons is drawn: at most one, since the rule is
    /// either off (Allow) or on (Turn Off). `None` where pressing could not
    /// help this account or would overwrite a rule aterm does not recognise.
    pub(crate) button: Option<DebuggerButton>,
}

/// The debugger row's one button, and whether a press would be taken now.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) struct DebuggerButton {
    pub(crate) change: aterm_containment::consent::DebuggerChange,
    /// [`crate::debugger_access::DebuggerFacts::offers`]: nothing under way,
    /// and the probe shows the change's precondition.
    pub(crate) enabled: bool,
    /// A change child is in flight: drawn busy, never pressable.
    pub(crate) busy: bool,
}

impl DebuggerButton {
    pub(crate) const fn action(self) -> &'static str {
        match self.change {
            aterm_containment::consent::DebuggerChange::On => MACOS_ACCESS_DEBUGGER_ON,
            aterm_containment::consent::DebuggerChange::Off => MACOS_ACCESS_DEBUGGER_OFF,
        }
    }

    pub(crate) const fn label(self) -> &'static str {
        match self.change {
            aterm_containment::consent::DebuggerChange::On => "Allow Debugger Access\u{2026}",
            aterm_containment::consent::DebuggerChange::Off => "Turn Off Debugger Access\u{2026}",
        }
    }
}

/// The item's display name, taken from the consent module's own string table
/// rather than typed here. `native_settings.rs` holds no protected-folder
/// literal of any shape (the aterm-census guard `protected-folder`).
///
/// It was a capitalisation of the config token until the roster grew a member
/// whose name is not a folder's: "app-data" title-cases to something no human
/// wrote, so the label is now the module's to say.
fn macos_access_folder_label(folder: Folder) -> String {
    folder.label().to_string()
}

/// A service class in words, from the verb's token. Every roster class goes
/// through [`macos_access_folder_label`], so this file holds no protected-folder
/// literal (the aterm-census guard `protected-folder`); the other arms are
/// coverage classes nothing warms up.
fn macos_access_service_label(service: &str) -> String {
    match Folder::parse(service) {
        Some(folder) => macos_access_folder_label(folder),
        None => match service {
            "network-volumes" => "Network drives".to_string(),
            "removable-volumes" => "Removable drives".to_string(),
            "file-provider-domains" => "Cloud-storage folders (File Provider)".to_string(),
            "media-library" => "Music and media library".to_string(),
            "photos" => "Photos library".to_string(),
            "app-bundles" => "Other apps' bundles (App Management)".to_string(),
            "contacts" => "Contacts".to_string(),
            other => other.to_string(),
        },
    }
}

/// One warm-up row in words. `Denied` is the only one that carries a verdict,
/// and it carries §3.7's exact sentence.
///
/// The noun comes from the item ("this folder", "this data"), so the sentence
/// stays true for a roster member that is not a folder of the human's.
fn macos_access_row_label(folder: Folder, row: crate::consent_warmup::WarmupRow) -> String {
    match row {
        crate::consent_warmup::WarmupRow::Unknown => "not asked by this aterm process".to_string(),
        crate::consent_warmup::WarmupRow::Asking => "asking\u{2026}".to_string(),
        #[cfg(any(target_os = "macos", test))]
        crate::consent_warmup::WarmupRow::Allowed => "allowed".to_string(),
        crate::consent_warmup::WarmupRow::Denied => format!(
            "denied \u{2014} macOS is not asking again for this {}",
            folder.noun()
        ),
        #[cfg(any(target_os = "macos", test))]
        crate::consent_warmup::WarmupRow::Error => "could not be read".to_string(),
    }
}

/// The whole string table, as a total function of the published facts.
///
/// Read the section header above before changing a sentence: the service rows
/// distinguish Apple's documented coverage from measured propagation, and
/// nothing promises that interruptions are eliminated.
pub(crate) fn macos_access_copy(access: &MacosAccess) -> MacosAccessCopy {
    let headline = if !access.enabled {
        "File access \u{2014} not checked. aterm's privacy checks are switched off in aterm.toml."
    } else {
        match access.fda {
            FdaState::Granted => "Full disk access \u{2014} granted to aterm.",
            FdaState::Denied => {
                "File access \u{2014} not confirmed. Full Disk Access may already be enabled."
            }
            FdaState::Unknown if access.probe == ProbeLabel::Pending => {
                "File access \u{2014} checking\u{2026}"
            }
            FdaState::Unknown => "Full disk access \u{2014} unknown.",
        }
    };
    let probe_detail = match access.probe {
        ProbeLabel::Pending => "aterm is checking access in the background.".to_string(),
        ProbeLabel::OpenOk => "aterm's own check succeeded.".to_string(),
        ProbeLabel::OpenEperm => "aterm's own check was refused by macOS.".to_string(),
        ProbeLabel::OpenErrno(errno) => {
            format!("aterm's own check failed with error {errno}, which is not a privacy verdict.")
        }
        ProbeLabel::RefusedOutOfBundle => {
            "aterm did not check: this build is not running from an application bundle.".to_string()
        }
        ProbeLabel::RefusedNoExe => {
            "aterm did not check: the running program could not be resolved.".to_string()
        }
        ProbeLabel::RefusedDisabled => {
            "aterm did not check: the privacy check is switched off in aterm.toml.".to_string()
        }
        ProbeLabel::RefusedNoHome => {
            "aterm did not check: this account has no home directory set.".to_string()
        }
        ProbeLabel::RefusedBadPath => {
            "aterm did not check: the store path could not be used.".to_string()
        }
        ProbeLabel::UnsupportedPlatform => {
            "There is no macOS privacy database on this system.".to_string()
        }
    };
    // Gated on measured evidence (§7 S4): `fda_coverage_measured` is false on this
    // tree, so the second arm ships. Neither arm names a folder or claims a class
    // measured beyond app-data (the "access data from other applications" request,
    // measured on macOS 26.6). One line, since the card paints each line at a fixed
    // height. The tall card's service rows say class by class what is measured;
    // the compact card paints none, so the shipping arm does not point at them
    // (the measured arm must drop its pointer on compact before the flag flips).
    let coverage = if access.evidence.fda_coverage_measured {
        "Full Disk Access stops macOS's \"access data from other applications\" request; the \
         rows below list what else it reaches on this Mac."
    } else {
        "Full Disk Access stops macOS's \"access data from other applications\" request."
    };
    let identity = {
        let posture = match access.install {
            "installed" => "installed in Applications",
            "mounted-image" => "on a mounted disk image",
            "translocated" => "in a quarantined copy macOS made",
            "not-a-bundle" => "outside an application bundle",
            _ => "at a location aterm could not read",
        };
        let consequence = match access.install {
            "installed" => "check the Full Disk Access entry for this installed app.",
            _ => {
                "a grant made for the copy in Applications does not reach this one; move it \
                  there and open that copy."
            }
        };
        match access.running.as_deref() {
            Some(path) => format!("Running from {path} ({posture}) \u{2014} {consequence}"),
            None => format!("Running {posture} \u{2014} {consequence}"),
        }
    };
    // The one state the rest of the panel cannot show: the bundle is gone from its
    // name, so macOS has nothing to check a grant against and asks again for
    // everything, while the headline can still read "granted" (the probe checks the
    // exec-time path). A copy macOS cannot match also clears every copy's access.
    // Stated as a fact with no instruction; the recovery is aterm's to perform.
    let anchor_fault = access.anchor.grant_unverifiable().then(|| {
        "This aterm's bundle has moved or been deleted: macOS asks again for everything and \
         clears every copy's access."
            .to_string()
    });
    let responsible = {
        let mut text = String::from(
            "Programs run in aterm ask macOS as aterm, so a dialog about a tool you ran here \
             names aterm.",
        );
        if access.sessions_adopted > 0 {
            text.push_str(&format!(
                " {} of {} sessions kept running across an update. This check does not establish \
                 their access. A new tab starts a fresh session under the running copy; existing \
                 work can keep running.",
                access.sessions_adopted, access.sessions_total
            ));
        }
        text
    };
    let services = {
        let mut rows = Vec::new();
        for service in access.covers.iter() {
            if *service == "app-data" && !access.evidence.fda_coverage_measured {
                // MEASURED 2026-09-19, so this row no longer attributes its
                // claim to Apple's documentation. `fda_coverage_measured` is
                // still false (its doc says why) although the five classes it
                // gates are measured too: the arm stays, its sentence changes.
                rows.push(
                    "Other applications' data \u{2014} stopped by Full Disk Access".to_string(),
                );
                continue;
            }
            rows.push(format!(
                "{} \u{2014} measured: Full Disk Access applies",
                macos_access_service_label(service)
            ));
        }
        for service in access.unmeasured.iter() {
            // App-data sits here whenever this host's grant is not observed, but
            // the class itself was measured (macOS 26.6): say what the grant does.
            rows.push(if *service == "app-data" {
                "Other applications' data \u{2014} stopped once Full Disk Access is granted"
                    .to_string()
            } else {
                format!(
                    "{} \u{2014} not measured",
                    macos_access_service_label(service)
                )
            });
        }
        for service in access.uncovered.iter() {
            rows.push(format!(
                "{} \u{2014} Full Disk Access does not apply",
                macos_access_service_label(service)
            ));
        }
        rows
    };
    let trade = "Full disk access on a terminal is broad: everything you run in aterm could then \
                 read everything this account can read.";
    // The two facts the debugger row states too (debugger design §3.3), so
    // the peers are read the same way: who grants each, and how long it lasts.
    let grants = "Who grants: Only you, in System Settings. aterm opens the page; macOS has no \
                  dialog for this.";
    let lasts = "Lasts: While this aterm keeps its signature. Applies to programs run in aterm.";
    // A held grant reads differently from a missing one: with the coverage
    // measurement unrun, `prompt_possible` stays true after a grant, so this line
    // must still show that the grant took.
    let prompt = if access.prompt_possible() && access.fda == FdaState::Granted {
        // The coverage line above already says what was measured and what
        // was not; this line says what that leaves, pointing at the rows.
        "Granted. A row below marked not measured, or one Full Disk Access does not apply to, can still interrupt a program."
    } else if access.prompt_possible() {
        "A program running in aterm can still be interrupted by a macOS file-access request."
    } else {
        "For the services measured as covered, macOS is not expected to interrupt a program run in \
         aterm."
    };
    let mut route =
        crate::menu::privacy_settings_path_words(crate::menu::PrivacyPane::FullDiskAccess)
            .to_string();
    if access.install == "installed"
        && let Some(bundle) = access.running.as_deref().and_then(|path| {
            aterm_containment::consent::app_bundle_root(std::path::Path::new(path))
        })
    {
        route.push_str(&format!(
            " \u{2014} enable {}; use + to add it if absent. App Management is a different setting.",
            bundle.display()
        ));
    }
    let observation =
        "This shows what aterm's own check found, never the switch in System Settings.";
    // §3.7's suppression branch. It fires for the identity classes whose grants
    // do not survive a build — and it says what actually happened, which is
    // that a rebuild invalidated them, not that the owner refused anything.
    let rebuild = (access.reset_offer() == ResetOffer::ExplainRebuild).then(|| {
        "This build's saved answers were invalidated by a rebuild, not by you. macOS binds every \
         answer to the exact code identity that asked, and this build's identity changes each time \
         it is built \u{2014} so clearing the saved answers here would not hold. A build signed \
         with a stable Developer ID identity keeps one identity across builds, which is what \
         shipped aterm releases carry."
            .to_string()
    });
    let folders = access
        .warmup_rows
        .iter()
        .map(|(folder, row)| {
            format!(
                "{} \u{2014} {}",
                macos_access_folder_label(*folder),
                macos_access_row_label(*folder, *row)
            )
        })
        .collect::<Vec<_>>();
    let mut repair = Vec::new();
    let denied = access.denied_folders();
    if !denied.is_empty() {
        // Worded by what the block offers: *Ask Again* is not drawn with the
        // checks off, without `tccutil`, or for an identity it cannot repair.
        repair.push(
            if access.shows_reset_button() {
                "macOS is not asking again for the folders above. Both ways out of that are \
                 yours to start, and neither happens on its own."
            } else {
                "macOS is not asking again for the folders above. The way out is yours to take \
                 in Files & Folders, and it does not happen on its own."
            }
            .to_string(),
        );
    }
    if let Some(report) = access.reset.as_ref() {
        repair.extend(macos_access_reset_lines(report, access.warmup_offered));
    }
    MacosAccessCopy {
        headline: headline.to_string(),
        probe_detail,
        coverage: coverage.to_string(),
        trade: trade.to_string(),
        grants: grants.to_string(),
        lasts: lasts.to_string(),
        prompt: prompt.to_string(),
        route,
        observation: observation.to_string(),
        identity,
        anchor_fault,
        responsible,
        services,
        rebuild,
        folders,
        repair,
        claimants: macos_access_claimant_lines(access),
        retired: access
            .retired
            .iter()
            .flatten()
            .map(|(path, outcome)| macos_access_retired_line(path, outcome))
            .collect(),
        retire_status: access.retire_status.clone(),
        debugger: debugger_row_copy(access),
    }
}

/// A wall-clock second as the row writes a moment: the UTC stamp the message
/// log's copy text uses, which says its zone. Pure: no clock, no zone read.
fn debugger_stamp_words(secs: u64) -> String {
    aterm_messages::words::stamp_words(secs.saturating_mul(1000))
}

/// The day of a wall-clock second, `YYYY-MM-DD` in UTC.
fn debugger_date_words(secs: u64) -> String {
    let mut stamp = debugger_stamp_words(secs);
    stamp.truncate(10);
    stamp
}

/// The rule's mode as a word, for "it already read …".
const fn debugger_mode_words(mode: aterm_containment::consent::DebuggerMode) -> &'static str {
    use aterm_containment::consent::DebuggerMode;
    match mode {
        DebuggerMode::Enabled => "allowed",
        DebuggerMode::Disabled => "off",
        DebuggerMode::Unrecognized => "in a shape aterm does not recognise",
        DebuggerMode::Unknown => "not readable",
    }
}

/// THE ROW'S O8 SENTENCE (owner, 2026-09-29): an aterm that is not hardened
/// offers the change too, and says beside the button what it exposes. `None`
/// for a hardened aterm. The alert says it in its own bullet
/// ([`debugger_alert_not_hardened_bullet`]).
fn debugger_not_hardened_sentence(
    hardening: aterm_containment::consent::SelfHardening,
) -> Option<&'static str> {
    use aterm_containment::consent::SelfHardening;
    match hardening {
        SelfHardening::Hardened => None,
        SelfHardening::NotHardened => Some(
            "This aterm is not hardened (a development build), so after this any program you \
             run could take control of this aterm and drive it past aterm's alert.",
        ),
        SelfHardening::Unknown => Some(
            "aterm could not read whether this aterm is hardened. If it is not (a development \
             build), after this any program you run could take control of this aterm and drive \
             it past aterm's alert.",
        ),
    }
}

/// The rule the debugger row's headline states: the completed cached probe's mode,
/// or `None` when aterm did not look or the probe is still out. Never an exit code
/// or an outcome: the Tier-1 bind reads a surface's claim here
/// (`DebuggerAccessChange`'s `claim`).
pub(crate) fn debugger_row_states(
    facts: &crate::debugger_access::DebuggerFacts,
) -> Option<aterm_containment::consent::DebuggerMode> {
    (facts.enabled && facts.probe.label != aterm_containment::consent::DebuggerProbeLabel::Pending)
        .then_some(facts.probe.mode)
}

/// The debugger row's string table (debugger design §3.3): an aterm that is not
/// hardened offers *Allow* too and says what that exposes. A total function of the
/// published facts; the rule's state comes only from the cached probe.
pub(crate) fn debugger_row_copy(access: &MacosAccess) -> DebuggerRowCopy {
    use crate::debugger_access::{Origin, Outcome};
    use aterm_containment::consent::{
        DEBUGGER_ACCESS_REVERT, DebuggerChange, DebuggerMember, DebuggerMode, DebuggerProbeLabel,
        SelfHardening,
    };
    let facts = &access.debugger;
    let probe = facts.probe;
    let headline = if !facts.enabled {
        "Debugger access \u{2014} not checked. aterm's privacy checks are switched off in \
         aterm.toml."
    } else {
        match debugger_row_states(facts) {
            None => "Debugger access \u{2014} checking\u{2026}",
            Some(DebuggerMode::Enabled) => "Debugger access \u{2014} allowed.",
            Some(DebuggerMode::Disabled) => "Debugger access \u{2014} not allowed.",
            Some(DebuggerMode::Unrecognized) => "Debugger access \u{2014} not recognised.",
            Some(DebuggerMode::Unknown) => "Debugger access \u{2014} not observed.",
        }
    }
    .to_string();
    let kind = "macOS developer mode. Not the Privacy & Security \u{25B8} Developer Tools list. \
                That list governs running software that fails the security policy, and does not \
                help with this dialog."
        .to_string();
    let not_hardened = debugger_not_hardened_sentence(facts.self_hardened);
    let with_not_hardened = |text: &str| match not_hardened {
        Some(extra) => format!("{text} {extra}"),
        None => text.to_string(),
    };
    // D4, measured: `-disable` writes Apple's rule back with `shared` false,
    // so after a round trip every new debugger asks; the probe reads only
    // `-status`, so the sentence holds for both shapes.
    let asks = "macOS asks for a password when a debugger attaches: under Apple's original rule \
                once, then quiet for up to 10 hours, during which the same access is open without \
                asking; once developer mode has been turned off with DevToolsSecurity, at every \
                new debugger. An unanswered dialog has waited 12 hours.";
    let member_unread = if probe.member == DebuggerMember::Unknown {
        " aterm could not read whether this account is an administrator or developer, and the \
         switch helps only those accounts."
    } else {
        ""
    };
    // GATED ON D2 (`devtools_enable_measured`, measured): `DevToolsSecurity`
    // run by aterm's worker puts up one administrator dialog, so the row says
    // macOS asks; under `UNMEASURED` it says macOS SHOULD ask.
    let measured = access.evidence.devtools_enable_measured;
    let state = if let Some(flight) = facts.in_flight {
        // The change's own child, or a predecessor's read from its marker:
        // either way a second press cannot start a second child.
        if measured {
            format!(
                "Waiting for macOS's administrator dialog (since {}).",
                debugger_stamp_words(flight.since)
            )
        } else {
            format!(
                "Waiting for DevToolsSecurity to finish; macOS should be asking for an \
                 administrator in its own dialog (since {}).",
                debugger_stamp_words(flight.since)
            )
        }
    } else if !facts.enabled {
        "aterm did not read the debugger rule.".to_string()
    } else {
        match (probe.mode, probe.label) {
            (_, DebuggerProbeLabel::Pending) => "Not read yet.".to_string(),
            (DebuggerMode::Disabled, _) if probe.member == DebuggerMember::NotMember => {
                "Allowing it would not change this for your account: macOS still asks accounts \
                 outside admin and _developer."
                    .to_string()
            }
            (DebuggerMode::Disabled, _) => {
                let lead = match facts.drift_since {
                    Some(since) => format!(
                        "Was allowed ({}); it is off now. {asks}",
                        debugger_date_words(since)
                    ),
                    None => asks.to_string(),
                };
                with_not_hardened(&format!("{lead}{member_unread}"))
            }
            (DebuggerMode::Enabled, _) => {
                let origin = match facts.recorded {
                    Some(marker) if marker.mode == DebuggerMode::Enabled => match marker.origin {
                        Origin::Aterm => format!(
                            ", turned on from aterm on {}",
                            debugger_date_words(marker.since)
                        ),
                        Origin::Outside => ", set outside aterm".to_string(),
                        Origin::Unknown => String::new(),
                    },
                    _ => String::new(),
                };
                match facts.self_hardened {
                    SelfHardening::Hardened => format!("Allowed for this Mac{origin}."),
                    SelfHardening::NotHardened => format!(
                        "Allowed for this Mac{origin}, and this aterm is not hardened: any \
                         program you run can take control of this aterm."
                    ),
                    SelfHardening::Unknown => format!(
                        "Allowed for this Mac{origin}, and aterm could not read whether this aterm \
                         is hardened: if it is not, any program you run can take control of it."
                    ),
                }
            }
            (DebuggerMode::Unrecognized, _) => {
                "macOS reports this rule in a shape aterm does not recognise; aterm leaves it \
                 alone."
                    .to_string()
            }
            (DebuggerMode::Unknown, DebuggerProbeLabel::ToolAbsent) => {
                "DevToolsSecurity is not on this Mac.".to_string()
            }
            (DebuggerMode::Unknown, DebuggerProbeLabel::RefusedOutOfBundle) => {
                "aterm did not read it: this build is not running from an application bundle."
                    .to_string()
            }
            (DebuggerMode::Unknown, DebuggerProbeLabel::UnsupportedPlatform) => {
                "There is no macOS debugger rule on this system.".to_string()
            }
            (DebuggerMode::Unknown, _) => "Not read yet.".to_string(),
        }
    };
    let status = if let Some(why) = facts.refusal {
        Some(format!("Nothing was changed: {}.", why.words()))
    } else {
        facts.last_outcome.map(|outcome| match outcome {
            Outcome::Changed(change) => format!(
                "aterm read the rule again after DevToolsSecurity finished: {} now.",
                debugger_mode_words(change.target())
            ),
            Outcome::NotChanged(_) => {
                "aterm read the rule again after DevToolsSecurity finished: unchanged. aterm does \
                 not try again on its own."
                    .to_string()
            }
            Outcome::Unrecognized(_) => {
                "aterm read the rule again after DevToolsSecurity finished: macOS reports it in a \
                 shape aterm does not recognise."
                    .to_string()
            }
            Outcome::Unobserved(_) => {
                "aterm could not read the rule again after DevToolsSecurity finished.".to_string()
            }
            Outcome::NotDue(_, DebuggerMode::Unknown) => {
                "Nothing was changed: aterm could not read the rule again before starting."
                    .to_string()
            }
            Outcome::NotDue(_, mode) => format!(
                "Nothing was changed: when aterm checked again, the rule already read {}.",
                debugger_mode_words(mode)
            ),
            Outcome::NotStarted(_) => {
                "Nothing was changed: aterm could not start DevToolsSecurity.".to_string()
            }
            Outcome::PeerInFlight(_) => {
                "Nothing was changed: another aterm on this Mac is already changing debugger \
                 access."
                    .to_string()
            }
        })
    };
    // GATED ON D5 (`devtools_silences_lldb`, measured): without that evidence
    // the row says the switch SHOULD stop the dialog, never that it does.
    let stops = if access.evidence.devtools_silences_lldb {
        "Stops: The \"Developer Tools Access\" password dialog when lldb or Xcode attaches to your \
         programs. Does not stop \"take control\" dialogs from other debuggers, or attaching to \
         hardened apps."
    } else {
        "Stops: Should stop the \"Developer Tools Access\" password dialog when lldb or Xcode \
         attaches to your programs. Does not stop \"take control\" dialogs from other debuggers, \
         or attaching to hardened apps."
    }
    .to_string();
    let grants = if measured {
        "Who grants: An administrator, once, in macOS's own password dialog. aterm starts it \
         and never sees the password."
    } else {
        "Who grants: An administrator, once; macOS should ask in its own password dialog. aterm \
         starts DevToolsSecurity and never sees the password."
    }
    .to_string();
    let lasts = "Lasts: Until turned off. Applies to the whole Mac: every app, and every admin or \
                 developer account. aterm re-checks it."
        .to_string();
    let undo = format!("Undo: Turn Off Debugger Access\u{2026}, or run {DEBUGGER_ACCESS_REVERT}.");
    let mut trade = String::from(
        "Trade: Any program run by an admin or developer account, in any app, could use Apple's \
         debugger on that account's other unhardened programs without asking, and read or change \
         their memory: Homebrew tools, node, gpg-agent, anything built with cargo, development \
         builds of aterm. Hardened apps and macOS itself stay protected.",
    );
    match facts.self_hardened {
        SelfHardening::Hardened => {}
        SelfHardening::NotHardened => trade.push_str(" This aterm is not hardened, so it is one of them."),
        SelfHardening::Unknown => trade.push_str(
            " aterm could not read whether this aterm is hardened; if it is not, it is one of them.",
        ),
    }
    let cross_link =
        "Machine-wide, like THIS MAC below, but changed only when you say yes.".to_string();
    // A button only where pressing can help this account (O8: aterm's own
    // hardening is not a reason to withhold it; the row and the alert say what
    // it exposes). Drawn disabled while anything is under way; a rule aterm
    // does not recognise gets none, since `-enable` would overwrite it.
    let button = (facts.enabled)
        .then(|| match probe.mode {
            DebuggerMode::Disabled if probe.member != DebuggerMember::NotMember => {
                Some(DebuggerChange::On)
            }
            DebuggerMode::Enabled => Some(DebuggerChange::Off),
            _ => None,
        })
        .flatten()
        .or_else(|| facts.in_flight.map(|flight| flight.change))
        .map(|change| DebuggerButton {
            change,
            enabled: facts.offers(change),
            busy: facts.in_flight.is_some(),
        });
    DebuggerRowCopy {
        headline,
        kind,
        state,
        status,
        stops,
        grants,
        lasts,
        undo,
        trade,
        cross_link,
        button,
    }
}

/// How long ago tccd's newest answer came, in words.
fn devtools_age_words(minutes: u64) -> String {
    match minutes {
        0 => "under a minute ago".to_string(),
        1 => "1 minute ago".to_string(),
        n => format!("{n} minutes ago"),
    }
}

/// How long ago aterm last opened the page, in words: minutes for the first
/// hour, hours for the first two days, then days (the marker outlives a
/// launch, and "4320 minutes ago" says nothing at a glance).
fn devtools_opened_words(minutes: u64) -> String {
    match minutes {
        0..=59 => devtools_age_words(minutes),
        60..=119 => "1 hour ago".to_string(),
        120..=2_879 => format!("{} hours ago", minutes / 60),
        _ => format!("{} days ago", minutes / 1_440),
    }
}

/// The Developer Tools card's string table (debugger design §9.1): a total
/// function of the published facts and `evidence`. The state line follows the
/// joined verdict (the one the digest line and the helper panel act on, so the
/// three never disagree) and says where it came from:
///
/// * the switch's row, when aterm read the list: on (since the day it last
///   changed), off, absent, or on while tccd's newer answer still checks;
/// * otherwise tccd's answer: "not on the list" only for its measured
///   `unlisted` shape, "switched off" for `denied` only once spike D13 is
///   measured (before that, "did not allow it"), and "can't confirm yet" when
///   that answer is older than aterm's last opening of the page — the owner
///   may have switched it on since, and tccd answers only for a new program;
/// * otherwise why aterm can't tell, in atpkg's words ("Checking…" while a
///   reading is out).
///
/// What being listed skips says "should" until spike D14
/// (`devtool_skips_first_run_check`): the why and the trade take it.
pub(crate) fn devtools_card_copy(access: &MacosAccess) -> DevToolsCardCopy {
    use aterm_containment::consent::{DevToolListLabel as LL, DevToolListing as Li};
    use aterm_containment::{DevToolGrant as G, DevToolProbeLabel as L, DevToolState as S};
    let facts = &access.devtools;
    let probe = facts.probe;
    let list = facts.list;
    let shapes = access.evidence.devtool_answer_shapes_measured;
    let skips = access.evidence.devtool_skips_first_run_check;
    let observed = facts.enabled && probe.label == L::Observed;
    let list_read = facts.enabled && list.label == LL::Read && list.listing != Li::Unknown;
    let granted = facts.enabled && facts.grant == G::Granted;
    // tccd's answer, with its age when it carries one.
    let latest = || match facts.answer_minutes {
        Some(minutes) => format!("macOS's latest answer, {}", devtools_age_words(minutes)),
        None => "macOS's latest answer".to_string(),
    };
    let stale = facts.grant == G::NotGranted
        && facts
            .answer_minutes
            .zip(facts.opened_minutes)
            .is_some_and(|(answer, opened)| answer > opened);
    // The same verdict in a word or two, for the one-row floor.
    let state_short = if !facts.enabled {
        "not checked"
    } else if list_read {
        match (list.listing, facts.grant) {
            (Li::On, G::Granted) => "on",
            (Li::On, _) => "still checks",
            (Li::Off, G::Granted) => "off, allowed",
            (Li::Off, _) => "off",
            (Li::Absent | Li::Unknown, _) => "not listed",
        }
    } else {
        match facts.grant {
            G::Granted => "allowed",
            G::NotGranted if stale => "unconfirmed",
            G::NotGranted => match probe.state {
                S::Unlisted => "not listed",
                S::Denied if shapes => "off",
                S::Denied | S::Allowed | S::Unknown => "not allowed",
            },
            G::Unknown if probe.label == L::Pending || list.label == LL::Pending => {
                "checking\u{2026}"
            }
            G::Unknown => "can't tell",
        }
    };
    let state = if !facts.enabled {
        "Not checked: aterm's privacy checks are switched off in aterm.toml.".to_string()
    } else if list_read {
        // The switch as aterm read it. A read row decides the verdict unless
        // tccd answered after it last changed (`consent::devtool_grant`).
        match (list.listing, facts.grant) {
            (Li::On, G::Granted) => {
                let mut text = "aterm is on the list and switched on.".to_string();
                if let Some(at) = list.modified_at_s.and_then(|s| u64::try_from(s).ok()) {
                    text.push_str(&format!(" Since {}.", debugger_date_words(at)));
                }
                text
            }
            (Li::On, _) => {
                "aterm is switched on, but macOS still checks its new programs.".to_string()
            }
            (Li::Off, G::Granted) => "aterm is on the list, switched off, though macOS's newest \
                                      answer allowed it."
                .to_string(),
            (Li::Off, _) => "aterm is on the list, switched off.".to_string(),
            (Li::Absent | Li::Unknown, _) => "aterm is not on the list.".to_string(),
        }
    } else {
        // No read row: tccd's observed answer decides, or nothing does.
        match facts.grant {
            G::Granted => format!("{}: aterm is allowed.", latest()),
            G::NotGranted if stale => {
                "Can't confirm yet: macOS answers again when aterm next starts a new program."
                    .to_string()
            }
            G::NotGranted => match probe.state {
                S::Unlisted => format!("{}: aterm is not on the list.", latest()),
                // Gated on spike D13: which listed state a `denied` is stays
                // unmeasured until then, so it reads "did not allow it".
                S::Denied if shapes => format!("{}: aterm is on the list, switched off.", latest()),
                S::Denied | S::Allowed | S::Unknown => match facts.answer_minutes {
                    Some(minutes) => format!(
                        "macOS checked a new program aterm started {} and did not allow it.",
                        devtools_age_words(minutes)
                    ),
                    None => "macOS checked a new program aterm started and did not allow it."
                        .to_string(),
                },
            },
            G::Unknown if probe.label == L::Pending || list.label == LL::Pending => {
                "Checking\u{2026}".to_string()
            }
            G::Unknown => {
                let list_why = if list.label == LL::Read {
                    "the list answered in a shape aterm does not recognise"
                } else {
                    atpkg::devtools::list_reason(list.label)
                };
                let log_why = if probe.label == L::Observed {
                    "macOS's answer was not recognised"
                } else {
                    atpkg::devtools::log_reason(probe.label)
                };
                if list_why == log_why {
                    format!("aterm can't tell: {list_why}.")
                } else {
                    format!("aterm can't tell: {list_why}, and {log_why}.")
                }
            }
        }
    };
    let state_style = if granted {
        StyleRef::Success
    } else if !facts.enabled || facts.grant == G::Unknown {
        StyleRef::Quiet
    } else {
        StyleRef::Primary
    };
    let unread = (facts.enabled && !granted && list.label == LL::NoFullDiskAccess)
        .then(|| "Full Disk Access (below) lets aterm read this list.".to_string());
    let kind = "macOS's Privacy & Security \u{25B8} Developer Tools list: in Apple's words, apps \
                allowed to \"run software locally that does not meet the system's security \
                policy\". Not debugger access: it does not stop the \"Developer Tools Access\" \
                password dialog."
        .to_string();
    // By what the read row holds of aterm (`atpkg::devtools::Step`): off needs its
    // switch, never a second drag; on while macOS still checks has nothing to add.
    // Otherwise — no row, or no read — the drag paired with +.
    let how = if list_read && !granted {
        atpkg::devtools::Step::of(&list).how()
    } else {
        atpkg::devtools::HELPER_HOW
    }
    .to_string();
    let mut route =
        crate::menu::privacy_settings_path_words(crate::menu::PrivacyPane::DeveloperTools)
            .to_string();
    // The bundle to drag or to choose after +, for an install outside
    // /Applications too.
    if access.install == "installed"
        && let Some(bundle) = access.running.as_deref().and_then(|path| {
            aterm_containment::consent::app_bundle_root(std::path::Path::new(path))
        })
    {
        route.push_str(&format!(" \u{2014} this aterm is {}.", bundle.display()));
    }
    DevToolsCardCopy {
        state,
        state_short,
        state_style,
        granted,
        unread,
        kind,
        why: atpkg::devtools::why(skips).to_string(),
        checked: if observed {
            crate::devtools_helper::checked_words(probe.not_allowed)
        } else {
            None
        },
        how,
        route,
        // atpkg's one spelling of the trade, which the helper panel and `aterm
        // doctor` print too, gated on D14 the same way.
        trade: atpkg::devtools::trade(skips).to_string(),
        only: atpkg::devtools::only_aterm(false).to_string(),
        opened: facts.opened_minutes.map(|minutes| {
            format!(
                "aterm last opened this list in System Settings for you {}.",
                devtools_opened_words(minutes)
            )
        }),
        declined: facts.declined.filter(|_| !granted).map(|(at, until)| {
            format!(
                "You said Not now on {}: aterm won't open System Settings at this list by \
                 itself until {}. Open Developer Tools\u{2026} still opens it.",
                debugger_date_words(at),
                debugger_date_words(until)
            )
        }),
    }
}

/// Why a press of the debugger row's button for `change` is not taken, in the
/// owner's words for "Nothing was changed: {why}.": `None` exactly when
/// [`crate::debugger_access::DebuggerFacts::offers`] says the button is live, so
/// the arm and the drawn button agree. Never aterm's own hardening.
fn debugger_press_refusal(
    facts: &crate::debugger_access::DebuggerFacts,
    change: aterm_containment::consent::DebuggerChange,
) -> Option<&'static str> {
    use crate::debugger_access::Refusal;
    use aterm_containment::consent::{DebuggerChange, DebuggerMember};
    if facts.offers(change) {
        return None;
    }
    Some(if !facts.enabled {
        Refusal::PrivacyOff.words()
    } else if facts.in_flight.is_some() {
        Refusal::InFlight.words()
    } else if facts.busy {
        "aterm is still reading debugger access, or the result of the last change"
    } else if facts.probe.mode != change.precondition() {
        Refusal::State(change, facts.probe.mode).words()
    } else if change == DebuggerChange::On && facts.probe.member == DebuggerMember::NotMember {
        "allowing it would not change this for your account, since macOS still asks accounts \
         outside admin and _developer"
    } else {
        "debugger access cannot be changed from here right now"
    })
}

/// Who raises [`debugger_access_alert`]: the owner's press on the Security
/// page, or the App's once-per-Mac launch ask (owner ruling O29), whose alert
/// says first that aterm asks this once per Mac and sends the undo to the
/// Security page.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum DebuggerAlertFrom {
    Press,
    Launch,
}

/// THE ALERT'S O8 BULLET: what an aterm that is not hardened, or that cannot
/// tell, exposes once the rule is loosened, as one bullet line of
/// [`debugger_access_alert`]. `None` for a hardened aterm. The Security row
/// says it in its own sentence ([`debugger_not_hardened_sentence`]).
fn debugger_alert_not_hardened_bullet(
    hardening: aterm_containment::consent::SelfHardening,
) -> Option<&'static str> {
    use aterm_containment::consent::SelfHardening;
    match hardening {
        SelfHardening::Hardened => None,
        SelfHardening::NotHardened => Some(
            "\u{2022} Not protected: this aterm (a development build). Any program you run could \
             take control of it and get past this alert.",
        ),
        SelfHardening::Unknown => Some(
            "\u{2022} Maybe not protected: this aterm, if it is a development build. Any program \
             you run could then take control of it and get past this alert.",
        ),
    }
}

/// aterm's own alert before a debugger-access change (debugger design §3.4
/// step 1; owner rulings O7, O8 and O29). A pure function of the facts, so
/// what it must say is tested without an alert (no test reaches
/// `menu::confirm_owner`): the not-hardened bullet exactly when aterm is not
/// hardened, a measured or hedged administrator-password line by the
/// evidence (the owner's own only on an admin account), the revert line in
/// every On body, and no path to the tool but
/// the `-disable` one. Returns `(title, body, proceed)`.
///
/// Short paragraphs and `•` bullet lines (owner, 2026-10-20: "more concise and
/// organized"), which NSAlert's informative text shows as written. The launch
/// ask's alert (`from` [`DebuggerAlertFrom::Launch`], only ever for turning it
/// on) opens with why it is up unasked and sends the undo to the Security page;
/// every other line is the press's.
pub(crate) fn debugger_access_alert(
    change: aterm_containment::consent::DebuggerChange,
    facts: &crate::debugger_access::DebuggerFacts,
    evidence: SpikeEvidence,
    from: DebuggerAlertFrom,
) -> (String, String, &'static str) {
    use aterm_containment::consent::{
        DEBUGGER_ACCESS_REVERT, DebuggerChange, DebuggerMember, SelfHardening,
    };
    // GATED ON D2 and D4 (`devtools_enable_measured`, measured): Apple's tool
    // puts up one administrator dialog for either change, so the alert says
    // macOS asks; under `UNMEASURED` it says macOS SHOULD ask. The dialog's
    // name was measured on 26.6.2 and 27.0 (design §7 D2): SecurityAgent names
    // Apple's tool, "SamplingTools", never aterm, so the owner is told what to
    // expect before an unfamiliar name asks for their password. The password
    // is "yours" only on an admin account: the tool's write is authorized
    // against `config.modify.` (`[is-root, authenticate-admin]`, design §1.3),
    // so a `_developer` member, or an account outside both groups turning it
    // off, types an administrator's.
    let password_of = if facts.probe.member == DebuggerMember::Admin {
        "your admin password"
    } else {
        "an admin's password"
    };
    let dialog = match (change, evidence.devtools_enable_measured) {
        (DebuggerChange::On, true) => {
            format!("asks for {password_of} in a dialog named \"SamplingTools\", Apple's tool")
        }
        (DebuggerChange::On, false) => format!(
            "should ask for {password_of} in its own dialog, named \"SamplingTools\", Apple's tool"
        ),
        (DebuggerChange::Off, true) => {
            format!("asks for {password_of} in a dialog named \"SamplingTools\"")
        }
        (DebuggerChange::Off, false) => format!("should ask for {password_of} in its own dialog"),
    };
    let password = format!("Next, macOS {dialog}. aterm never sees it.");
    match change {
        DebuggerChange::On => {
            let mut bullets = vec![
                "\u{2022} Whole Mac: every admin and developer account, not just aterm",
                "\u{2022} Exposed: Homebrew tools, node, gpg-agent, cargo builds",
                if facts.self_hardened == SelfHardening::Hardened {
                    "\u{2022} Still protected: hardened apps (this aterm too) and macOS"
                } else {
                    "\u{2022} Still protected: hardened apps and macOS"
                },
            ];
            bullets.extend(debugger_alert_not_hardened_bullet(facts.self_hardened));
            bullets.push("\u{2022} Apple advises administrators not to change this rule");
            let undo = match from {
                DebuggerAlertFrom::Press => "press Turn Off Debugger Access\u{2026} here",
                DebuggerAlertFrom::Launch => {
                    "aterm's Settings \u{25b8} Security \u{25b8} Turn Off Debugger Access\u{2026}"
                }
            };
            let mut paragraphs = Vec::new();
            if from == DebuggerAlertFrom::Launch {
                paragraphs.push("aterm asks this once per Mac.".to_owned());
            }
            paragraphs.extend([
                "Afterwards, programs you run can debug your other programs without a password, \
                 and read or change their memory."
                    .to_owned(),
                bullets.join("\n"),
                password,
                format!("To undo: {undo}, or run {DEBUGGER_ACCESS_REVERT}."),
            ]);
            (
                "Allow debugger access on this Mac?".to_owned(),
                paragraphs.join("\n\n"),
                "Allow\u{2026}",
            )
        }
        DebuggerChange::Off => (
            "Turn off debugger access on this Mac?".to_owned(),
            // D4, measured: `-disable` leaves Apple's rule unshared, so
            // every new debugger asks, not once per 10 hours.
            format!(
                "Debuggers will need a password again each time one attaches. Apple's original \
                 10 hours without asking, after an answer, does not come back.\n\n{password}"
            ),
            "Turn Off\u{2026}",
        ),
    }
}

/// The census on the panel: nothing unless it found a copy that conflicts,
/// then the mechanism once and one line per copy.
fn macos_access_claimant_lines(access: &MacosAccess) -> Vec<String> {
    use aterm_containment::consent::{MAX_CLAIMANT_ROWS, TrashOffer};
    let Some(census) = access.claimants.as_ref() else {
        return Vec::new();
    };
    let conflicting = census.conflicting();
    if conflicting.is_empty() {
        return Vec::new();
    }
    let mut lines = vec![
        "Other copies of aterm on this Mac are signed differently. macOS keeps one record of \
         aterm's code and replaces it with whichever copy asks last, which clears this access \
         for every copy."
            .to_string(),
    ];
    // Each row says why its copy stays, by the rule the button reads
    // (`TrashOffer`); the two reasons that hold for every copy on this Mac are
    // said once, below the rows.
    let listed = census.listed(access.trash_tool);
    for (copy, offer) in &listed {
        let signed = match (copy.signing, copy.team.as_deref()) {
            ("adhoc", _) => "signed ad hoc".to_string(),
            ("unsigned", _) => "not signed".to_string(),
            (_, Some(team)) => format!("signed by team {}", owner_text(team)),
            _ => "signature unreadable".to_string(),
        };
        // A copy is listed with the links that lead to it, whatever keeps it
        // (`Claimant::links`); when a link is the reason, the clause says so.
        let links = match copy.links.as_slice() {
            [] => None,
            [link] => Some(format!("{} leads to it", owner_path(link))),
            [link, more @ ..] => Some(format!(
                "{} and {} more {} lead to it",
                owner_path(link),
                more.len(),
                if more.len() == 1 { "link" } else { "links" }
            )),
        };
        let stays = ", so it stays where it is";
        let why = match offer {
            TrashOffer::Signature => stays.to_string(),
            TrashOffer::Requirement => {
                format!("; aterm cannot read its code identity as one build's{stays}")
            }
            TrashOffer::Linked
            | TrashOffer::Offered
            | TrashOffer::RunningUnstable
            | TrashOffer::NoTool => String::new(),
        };
        let row = match (offer, links) {
            (TrashOffer::Linked, Some(links)) => format!("{signed}; {links}{stays}"),
            (_, Some(links)) => format!("{signed}{why}; {links}"),
            (_, None) => format!("{signed}{why}"),
        };
        lines.push(format!("{} \u{2014} {row}", owner_path(&copy.path)));
    }
    if conflicting.len() > MAX_CLAIMANT_ROWS {
        lines.push(format!(
            "\u{2026}and {} more.",
            conflicting.len() - MAX_CLAIMANT_ROWS
        ));
    }
    let any = |reason: TrashOffer| listed.iter().any(|(_, offer)| *offer == reason);
    if any(TrashOffer::RunningUnstable) {
        lines.push(
            "The copy running here does not keep its access across updates, so aterm offers \
             none of these for the Trash: one of them may be the release."
                .to_string(),
        );
    }
    if any(TrashOffer::NoTool) {
        lines.push(
            "This macOS has no trash tool aterm can use, so these stay where they are.".to_string(),
        );
    }
    lines
}

/// One copy's outcome from the last *Move to Trash*.
fn macos_access_retired_line(
    path: &std::path::Path,
    outcome: &aterm_containment::consent::Retired,
) -> String {
    use aterm_containment::consent::Retired;
    let path = owner_path(path);
    match outcome {
        Retired::Moved => format!("Moved to the Trash: {path}."),
        Retired::NotOffered => {
            format!("Left in place: {path} \u{2014} a fresh check no longer offers it.")
        }
        Retired::InUse => {
            format!("Left in place: {path} \u{2014} aterm could not rule out that it is in use.")
        }
        Retired::Failed(reason) => format!("Not moved: {path} \u{2014} {}", owner_text(reason)),
    }
}

/// What the last *Ask again* did, reported at the exact strength it earned.
/// Only [`ResetOutcome::AllReset`] speaks for the whole set; a partial success
/// names the folders it actually cleared, and every nonzero invocation gets its
/// own line with the exit status.
fn macos_access_reset_lines(report: &MacosAccessReset, warmup_offered: bool) -> Vec<String> {
    // The advice names the warm-up button only where it is drawn.
    let (again, again_those) = if warmup_offered {
        (
            "Ask for folder access now to let it ask again.",
            "Ask for folder access now to let it ask again about those.",
        )
    } else {
        (
            "macOS asks again the next time aterm opens one.",
            "macOS asks again about those the next time aterm opens one.",
        )
    };
    let names = |folders: &[Folder]| {
        folders
            .iter()
            .map(|folder| macos_access_folder_label(*folder))
            .collect::<Vec<_>>()
            .join(", ")
    };
    let mut out = Vec::new();
    match report.outcome {
        ResetOutcome::AllReset => out.push(format!(
            "macOS cleared its saved answer for every folder asked: {}. {again}",
            names(&report.reset)
        )),
        ResetOutcome::Partial => out.push(format!(
            "macOS cleared its saved answer for {} only. {again_those}",
            names(&report.reset)
        )),
        ResetOutcome::NoneReset => {
            out.push("macOS cleared no saved answer.".to_string());
        }
        ResetOutcome::ToolAbsent => {
            out.push(
                "Nothing was changed: the macOS tool that clears a saved answer could not be run."
                    .to_string(),
            );
        }
        ResetOutcome::NotAttempted => {}
    }
    for (folder, code) in &report.declined {
        out.push(match code {
            Some(code) => format!(
                "macOS declined to clear {} (exit status {code}).",
                macos_access_folder_label(*folder)
            ),
            None => format!(
                "macOS declined to clear {} (the command was ended by a signal).",
                macos_access_folder_label(*folder)
            ),
        });
    }
    out
}

/// The action ids this block owns. They are the ONLY way to reach the warm-up
/// (§3.5) and the reset and *Move to Trash* (§3.7) from Settings, and with the
/// App's once-per-Mac launch ask (owner ruling O29; the same alert, raised by
/// aterm itself and by nothing a session can send) the only ways to the owner's
/// debugger-access change (`docs/DESIGN-macos-debugger-access-2026-09-29.md`
/// §3.4): none is a `VERBS` row, no config key, environment variable or band
/// capsule invokes one, `act` refuses every id under
/// [`MACOS_ACCESS_GESTURE_PREFIX`], and the five that change this Mac ask the
/// owner in an alert first — a consent-raising or destructive action a program
/// inside a session could fire would be a surface an agent controls.
pub(crate) const MACOS_ACCESS_GESTURE_PREFIX: &str = "settings/macos-access/";
pub(crate) const MACOS_ACCESS_OPEN_FDA: &str = "settings/macos-access/full-disk-access";
pub(crate) const MACOS_ACCESS_OPEN_FILES: &str = "settings/macos-access/files-and-folders";
pub(crate) const MACOS_ACCESS_WARM_UP: &str = "settings/macos-access/warm-up";
pub(crate) const MACOS_ACCESS_ASK_AGAIN: &str = "settings/macos-access/ask-again";
pub(crate) const MACOS_ACCESS_TRASH: &str = "settings/macos-access/trash-copies";
/// *Allow Debugger Access…*. Two ids rather than one toggle: a press carries
/// its direction, so a render and a press that disagree about the rule can
/// never flip what the press means.
pub(crate) const MACOS_ACCESS_DEBUGGER_ON: &str = "settings/macos-access/debugger-on";
/// *Turn Off Debugger Access…*.
pub(crate) const MACOS_ACCESS_DEBUGGER_OFF: &str = "settings/macos-access/debugger-off";
/// The owner's `sudo` askpass relay off switch
/// (`docs/DESIGN-sudo-askpass-2026-10-15.md` §3.1). Two ids so a press carries
/// its direction, like the debugger pair: it writes or removes aterm's own
/// state-dir marker. `act` refuses the prefix; controller keys still drive the
/// page, so the reducer also requires the owner's confirmation.
pub(crate) const MACOS_ACCESS_ASKPASS_OFF: &str = "settings/macos-access/askpass-off";
/// *Allow sudo Password Prompts* — the other direction of the off switch.
pub(crate) const MACOS_ACCESS_ASKPASS_ON: &str = "settings/macos-access/askpass-on";
/// *Open Developer Tools…*, the Developer Tools card's one button: brings
/// System Settings forward at the Developer Tools list (debugger design §9.1)
/// through the hand-over (`App::hand_devtools_to_owner`), which also shows
/// aterm's helper panel beside it while aterm is not on. It never puts aterm on
/// the list or flips a switch, and asks nothing. On a list read whole and empty,
/// where macOS shows no Developer Tools page at all, the press first runs
/// `spctl developer-mode enable-terminal`, which adds Terminal, switched off, so
/// the page exists; its bar says so while it runs, and the panel says Terminal
/// is aterm's doing and stays off. Under the prefix, so `act` refuses it.
pub(crate) const MACOS_ACCESS_OPEN_DEVTOOLS: &str = "settings/macos-access/developer-tools";

/// The first decline's quiet; each decline in a row doubles it, up to
/// [`OWNER_QUIET_MAX`].
const OWNER_QUIET_FIRST: std::time::Duration = std::time::Duration::from_secs(10);
/// The longest quiet.
const OWNER_QUIET_MAX: std::time::Duration = std::time::Duration::from_secs(5 * 60);
/// A decline this long after the last quiet ended starts the doubling over.
const OWNER_QUIET_FORGET: std::time::Duration = std::time::Duration::from_secs(10 * 60);

/// The owner's recent answers to the block's alerts, one record for every
/// view: the declines in a row that quiet the gestures (see
/// [`SettingsViewState::owner_confirms`]), and the yeses the park has not yet
/// taken up.
#[derive(Debug, Default)]
pub(crate) struct OwnerQuiet {
    until: Option<QuietStamp>,
    declines: u32,
    /// A warm-up the owner said yes to, in any view, that the park has not taken
    /// up yet: a press queued in another view behind that alert reads it and does
    /// not ask again.
    warmup_confirmed: bool,
    /// The same for a move to the Trash.
    retire_confirmed: bool,
    /// The same for a debugger-access change (either direction): one owner
    /// yes starts at most one change, whatever view a queued press lands in.
    debugger_confirmed: bool,
    /// A sudo preference answer that the host has not yet consumed.
    askpass_confirmed: bool,
    /// The owner answered a debugger-access alert in this process, yes or no
    /// (not a quieted or unshown one). Never settled: the App's once-per-Mac
    /// launch ask reads it and asks nothing over an answer already given.
    debugger_answered: bool,
}

/// A moment on two clocks. `Instant` stops while the Mac sleeps, so a quiet timed
/// by it alone would outlast a night asleep, and the wall clock can be set back; a
/// quiet ends when either clock says it has. A wall clock set forward only ends
/// one early, and the alert is still the fence.
#[derive(Clone, Copy, Debug)]
struct QuietStamp {
    awake: std::time::Instant,
    wall: std::time::SystemTime,
}

impl QuietStamp {
    fn now() -> Self {
        Self {
            awake: std::time::Instant::now(),
            wall: std::time::SystemTime::now(),
        }
    }

    fn after(self, span: std::time::Duration) -> Self {
        Self {
            awake: self.awake + span,
            wall: self.wall + span,
        }
    }

    /// Whether this is before `other` on both clocks.
    fn before(self, other: Self) -> bool {
        self.awake < other.awake && self.wall < other.wall
    }

    /// How long after `earlier` this is, by whichever clock says longer.
    fn since(self, earlier: Self) -> std::time::Duration {
        let wall = self.wall.duration_since(earlier.wall).unwrap_or_default();
        self.awake
            .saturating_duration_since(earlier.awake)
            .max(wall)
    }
}

/// One [`OwnerQuiet`] for the whole process, armed into every Settings view.
pub(crate) type SharedOwnerQuiet = std::sync::Arc<std::sync::Mutex<OwnerQuiet>>;

impl OwnerQuiet {
    fn quiet_at(&self, now: QuietStamp) -> bool {
        self.until.is_some_and(|until| now.before(until))
    }

    fn declined(&mut self, now: QuietStamp) {
        if self
            .until
            .is_some_and(|until| now.since(until) > OWNER_QUIET_FORGET)
        {
            self.declines = 0;
        }
        self.declines = self.declines.saturating_add(1);
        let doubled = OWNER_QUIET_FIRST
            .checked_mul(1 << self.declines.saturating_sub(1).min(16))
            .unwrap_or(OWNER_QUIET_MAX);
        self.until = Some(now.after(doubled.min(OWNER_QUIET_MAX)));
    }

    fn accepted(&mut self) {
        self.until = None;
        self.declines = 0;
    }

    /// Count a decline the owner gave outside aterm's alert: a debugger-access
    /// change whose re-probe reads the rule unchanged (Cancel in macOS's
    /// administrator dialog, a wrong password, a failed write; design §3.4 step 4).
    /// The same doubling quiet as an alert's Cancel, so a program pressing again
    /// meets a quiet page, not a dialog.
    pub(crate) fn note_decline(&mut self) {
        self.declined(QuietStamp::now());
    }

    /// Whether a gesture asked now would be quieted (a recent decline).
    pub(crate) fn quiet_now(&self) -> bool {
        self.quiet_at(QuietStamp::now())
    }

    /// The owner answered a debugger-access alert, yes or no.
    pub(crate) fn note_debugger_answered(&mut self) {
        self.debugger_answered = true;
    }

    /// Whether the owner answered a debugger-access alert in this process.
    pub(crate) const fn debugger_answered(&self) -> bool {
        self.debugger_answered
    }

    /// The App's launch ask took the owner's yes to a debugger-access change: a
    /// press queued in any view behind that alert does not ask again, until the
    /// park settles it ([`Self::settle_confirmed`]).
    pub(crate) fn note_debugger_confirmed(&mut self) {
        self.debugger_answered = true;
        self.debugger_confirmed = true;
    }

    /// The park has taken up every confirmed gesture (started it, or said why
    /// not): what is under way is the projection's to say from here.
    pub(crate) fn settle_confirmed(&mut self) {
        self.warmup_confirmed = false;
        self.retire_confirmed = false;
        self.debugger_confirmed = false;
        self.askpass_confirmed = false;
    }

    #[cfg(test)]
    pub(crate) fn confirm_both_for_test(&mut self) {
        self.warmup_confirmed = true;
        self.retire_confirmed = true;
        self.debugger_confirmed = true;
        self.askpass_confirmed = true;
    }

    /// Whether a press right now would be quieted, for the host's tests of
    /// what counts as a decline.
    #[cfg(test)]
    pub(crate) fn is_quiet_now_for_test(&self) -> bool {
        self.quiet_at(QuietStamp::now())
    }

    #[cfg(test)]
    pub(crate) const fn has_confirmed_for_test(&self) -> bool {
        self.warmup_confirmed
            || self.retire_confirmed
            || self.debugger_confirmed
            || self.askpass_confirmed
    }
}

/// The owner's yes in one of aterm's own alerts. Its field is private to this
/// module, so only [`owner_confirms_with`] mints one, after
/// `ConsentGestures::confirm` raised the alert and the owner chose its proceed
/// button. It has two callers: the Security page's presses
/// ([`SettingsViewState::owner_confirms`]) and the App's once-per-Mac
/// debugger-access launch ask (`App::offer_debugger_access_at_launch`, through
/// `DebuggerChangeLane::offer`; owner ruling O29). The debugger-access change is built on it all the way down: only
/// `DebuggerChangeLane::begin` mints a `debugger_access::ChangeTicket`, and
/// only from a yes; a `DevtoolsJob` — what the worker that runs
/// `DevToolsSecurity` takes — is built only from a ticket. So no control verb,
/// palette entry or band action in this crate can start the change without the
/// owner's yes. The containment runner beneath it,
/// `aterm_containment::consent::run_devtools_change`, is `pub` across the crate
/// boundary; the aterm-census guard `devtools-door` keeps it to its one caller,
/// `debugger_access::spawn_devtools_worker`. Neither `Clone` nor `Copy`: one yes
/// is spent by one change. The sudo preference writer likewise consumes one
/// before changing its marker.
#[derive(Debug, PartialEq, Eq)]
pub(crate) struct OwnerYes(());

impl OwnerYes {
    /// A yes minted outside an alert, for tests only.
    #[cfg(test)]
    pub(crate) const fn for_test() -> Self {
        Self(())
    }
}

/// Ask the owner in aterm's alert, through `gestures`' confirm arm, unless a
/// recent decline quiets every Security gesture (`quiet`): the one place an
/// [`OwnerYes`] is minted. A yes ends the quiet, a no starts or doubles it, and
/// an alert that could not be shown is [`OwnerAnswer::NotAsked`], never a yes.
pub(crate) fn owner_confirms_with(
    quiet: &SharedOwnerQuiet,
    gestures: &ConsentGestures,
    title: &str,
    body: &str,
    proceed: &str,
) -> OwnerAnswer {
    if quiet
        .lock()
        .unwrap_or_else(|p| p.into_inner())
        .quiet_at(QuietStamp::now())
    {
        return OwnerAnswer::Quiet;
    }
    // No lock is held while the alert is up: it runs a modal loop.
    let answer = gestures.confirm(title, body, proceed);
    let mut quiet = quiet.lock().unwrap_or_else(|p| p.into_inner());
    match answer {
        Some(true) => {
            quiet.accepted();
            OwnerAnswer::Yes(OwnerYes(()))
        }
        Some(false) => {
            quiet.declined(QuietStamp::now());
            OwnerAnswer::No
        }
        None => OwnerAnswer::NotAsked,
    }
}

/// How [`owner_confirms_with`] came out. Not `Copy`: it may carry the owner's
/// yes.
#[derive(Debug, PartialEq, Eq)]
pub(crate) enum OwnerAnswer {
    Yes(OwnerYes),
    No,
    /// Not asked: one of these alerts was declined recently.
    Quiet,
    /// Not asked: no alert could be shown.
    NotAsked,
}

impl OwnerAnswer {
    /// A yes minted outside an alert, for tests only.
    #[cfg(test)]
    pub(crate) const fn yes_for_test() -> Self {
        Self::Yes(OwnerYes::for_test())
    }

    const fn is_yes(&self) -> bool {
        matches!(self, Self::Yes(_))
    }

    /// The block's feedback for every answer but yes.
    fn refusal(&self, declined: &'static str) -> &'static str {
        match self {
            Self::Yes(_) | Self::No => declined,
            Self::Quiet => {
                "You declined one of these a moment ago, so aterm did not ask again yet."
            }
            Self::NotAsked => "Nothing was changed: aterm could not show its question.",
        }
    }
}

/// A path as the owner reads it in this block and its alerts; see
/// [`owner_text`].
fn owner_path(path: &std::path::Path) -> String {
    owner_text(&path.to_string_lossy())
}

/// Text the owner reads in this block and its alerts that someone else chose —
/// a copy's folder name, its signing team, or a system message quoting it.
/// Control characters, the line and paragraph separators, the interlinear
/// annotation marks, the Egyptian format controls, and every Unicode
/// `Default_Ignorable_Code_Point` (the direction, joiner, filler, variation and
/// tag characters among them) are shown escaped, so it cannot start a new line,
/// reorder the text around it, or carry any of those invisible characters.
fn owner_text(text: &str) -> String {
    let mut out = String::new();
    for c in text.chars() {
        if c.is_control()
            || matches!(
                c,
                // Default_Ignorable_Code_Point (DerivedCoreProperties.txt),
                // whole: the assigned and the reserved ranges alike, through
                // U+E0FFF below.
                '\u{00AD}'
                    | '\u{034F}'
                    | '\u{061C}'
                    | '\u{115F}'..='\u{1160}'
                    | '\u{17B4}'..='\u{17B5}'
                    | '\u{180B}'..='\u{180F}'
                    | '\u{200B}'..='\u{200F}'
                    | '\u{202A}'..='\u{202E}'
                    | '\u{2060}'..='\u{206F}'
                    | '\u{3164}'
                    | '\u{FE00}'..='\u{FE0F}'
                    | '\u{FEFF}'
                    | '\u{FFA0}'
                    | '\u{FFF0}'..='\u{FFF8}'
                    | '\u{1BCA0}'..='\u{1BCA3}'
                    | '\u{1D173}'..='\u{1D17A}'
                    | '\u{E0000}'..='\u{E0FFF}'
                    // Not default-ignorable, but format controls drawn as
                    // nothing (Egyptian hieroglyph joiners), or characters that
                    // break or annotate a line.
                    | '\u{13430}'..='\u{1343F}'
                    | '\u{2028}'..='\u{2029}'
                    | '\u{FFF9}'..='\u{FFFB}'
            )
        {
            out.push_str(&format!("\\u{{{:04X}}}", u32::from(c)));
        } else {
            out.push(c);
        }
    }
    out
}

/// Whether the Security page carries the block right now: only once the host has
/// published a posture (a headless instance, a unit test and every non-macOS
/// build publish none, so the block is absent rather than an invented card).
fn prefers_macos_access(state: &SettingsViewState) -> bool {
    state.route == SettingsRoute::Security
        && state.search.trim().is_empty()
        && state.macos_access.is_some()
}

/// Exact authored height, so the page budget sees the same card the renderer
/// draws. Grows with the rows and repair lines it actually has, and with the
/// rows its buttons take in `text_width`, the card's measure.
fn macos_access_height(access: &MacosAccess, lead: AccessLead, text_width: f32) -> f32 {
    let scale = settings_text_scale();
    let line_height = 24.0_f32.max(20.0 * scale);
    let heading_height = access_card_heading(MACOS_ACCESS_HEADING, "MACOS ACCESS", text_width).1;
    let copy = macos_access_copy(access);
    let (above, below) = macos_access_rows(&copy, access, lead);
    let lines = macos_access_visual_lines(&above, text_width)
        + macos_access_visual_lines(&below, text_width)
        + macos_access_visual_lines(&debugger_row_lines(&copy.debugger), text_width);
    let debugger_actions = debugger_access_actions(&copy, text_width).map_or(0.0, |(_, h)| h);
    heading_height
        + lines as f32 * line_height
        + macos_access_actions_height(access, text_width)
        + debugger_actions
        + 12.0
        + 24.0
}

/// One text line of the MACOS ACCESS block: `(key, text, role, style)`.
type MacosAccessLine = (String, String, SemanticRole, StyleRef);

/// How much of the MACOS ACCESS block's verdict sits above its actions row,
/// MEASURED for the window ([`macos_access_lead`]); what is not above is the
/// first lines under the row, so the block says the same at every size and
/// only their order moves.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum AccessLead {
    /// The state, a broken anchor, the coverage claim and the trade the owner
    /// makes by granting.
    Whole,
    /// The trade is the first line under the row.
    NoTrade,
    /// The state and a broken anchor (it overrides a "granted" headline) alone:
    /// the coverage claim and the trade follow the row.
    State,
}

impl AccessLead {
    /// Every lead, the most above the row first.
    const ALL: [Self; 3] = [Self::Whole, Self::NoTrade, Self::State];
}

/// THE BLOCK'S TEXT LINES, ABOVE AND BELOW ITS ACTIONS ROW (s-22) — the one source
/// the card, its height and the first screen's budget read, so they cannot
/// disagree. Above the row: the verdict a press acts on — the state, a broken
/// anchor (it overrides a "granted" headline), and as `lead` holds them the
/// coverage claim and the trade the owner makes by granting — so *Open Privacy
/// & Security…*, the one press that fixes a Full Disk Access denial, sits a few
/// lines under the heading at every size instead of after two dozen detail
/// lines. Right under it: the verdict lines `lead` leaves there (still read
/// before the owner grants anything, which happens in System Settings after
/// the press), the rebuild line that says why Ask Again is missing, and the
/// Trash's status. Then, at every size — nothing the block says vanishes on a
/// short window or at large text — what a grant covers and how long it lasts,
/// the probe, the prompt, the observation, the route, the identity, who is
/// responsible, aterm's checks by service, the folders, the repair lines, other
/// copies and what the Trash took. `access` styles two lines; the counts never
/// read it.
fn macos_access_rows(
    copy: &MacosAccessCopy,
    access: &MacosAccess,
    lead: AccessLead,
) -> (Vec<MacosAccessLine>, Vec<MacosAccessLine>) {
    let line = |key: &str, text: &str, role: SemanticRole, style: StyleRef| {
        (
            format!("settings/macos-access/{key}"),
            text.to_string(),
            role,
            style,
        )
    };
    let headline_style = match (access.enabled, access.fda) {
        (false, _) => StyleRef::Quiet,
        (true, FdaState::Granted) => StyleRef::Success,
        (true, FdaState::Denied) => StyleRef::Primary,
        (true, FdaState::Unknown) => StyleRef::Quiet,
    };
    let mut above = vec![line(
        "state",
        &copy.headline,
        SemanticRole::Status,
        headline_style,
    )];
    if let Some(fault) = &copy.anchor_fault {
        above.push(line(
            "anchor-fault",
            fault,
            SemanticRole::Status,
            StyleRef::Danger,
        ));
    }
    let coverage = line(
        "coverage",
        &copy.coverage,
        SemanticRole::Status,
        StyleRef::Primary,
    );
    let trade = line("trade", &copy.trade, SemanticRole::Text, StyleRef::Primary);
    let mut below = Vec::new();
    match lead {
        AccessLead::Whole => above.extend([coverage, trade]),
        AccessLead::NoTrade => {
            above.push(coverage);
            below.push(trade);
        }
        AccessLead::State => below.extend([coverage, trade]),
    }
    if let Some(rebuild) = &copy.rebuild {
        below.push(line(
            "rebuild",
            rebuild,
            SemanticRole::Status,
            StyleRef::Danger,
        ));
    }
    if let Some(status) = &copy.retire_status {
        below.push(line(
            "retire-status",
            status,
            SemanticRole::Status,
            StyleRef::Primary,
        ));
    }
    below.extend([
        line("grants", &copy.grants, SemanticRole::Text, StyleRef::Quiet),
        line("lasts", &copy.lasts, SemanticRole::Text, StyleRef::Quiet),
        line(
            "probe",
            &copy.probe_detail,
            SemanticRole::Status,
            StyleRef::Quiet,
        ),
        line(
            "prompt",
            &copy.prompt,
            SemanticRole::Status,
            StyleRef::Primary,
        ),
        line(
            "observation",
            &copy.observation,
            SemanticRole::Text,
            StyleRef::Quiet,
        ),
        line("route", &copy.route, SemanticRole::Text, StyleRef::Quiet),
        line(
            "identity",
            &copy.identity,
            SemanticRole::Status,
            if access.install == "installed" {
                StyleRef::Quiet
            } else {
                StyleRef::Danger
            },
        ),
        line(
            "responsible",
            &copy.responsible,
            SemanticRole::Text,
            StyleRef::Quiet,
        ),
    ]);
    for (index, service) in copy.services.iter().enumerate() {
        below.push(line(
            &format!("service/{index}"),
            service,
            SemanticRole::Status,
            StyleRef::Primary,
        ));
    }
    for (index, folder) in copy.folders.iter().enumerate() {
        below.push(line(
            &format!("folder/{index}"),
            folder,
            SemanticRole::Status,
            StyleRef::Primary,
        ));
    }
    for (index, repair) in copy.repair.iter().enumerate() {
        below.push(line(
            &format!("repair/{index}"),
            repair,
            SemanticRole::Status,
            StyleRef::Quiet,
        ));
    }
    for (index, claimant) in copy.claimants.iter().enumerate() {
        below.push(line(
            &format!("claimant/{index}"),
            claimant,
            SemanticRole::Status,
            if index == 0 {
                StyleRef::Danger
            } else {
                StyleRef::Quiet
            },
        ));
    }
    for (index, retired) in copy.retired.iter().enumerate() {
        below.push(line(
            &format!("retired/{index}"),
            retired,
            SemanticRole::Status,
            StyleRef::Quiet,
        ));
    }
    (above, below)
}

/// What of the block the DEVELOPER TOOLS card above it leaves on the first
/// screen ([`DevToolsCardFit::stacked`]): down to the end of its actions row —
/// *Open Privacy & Security…* and the buttons beside it — with `lead` over it.
/// The row sits under the block's verdict lines ([`macos_access_rows`]), four
/// at most, so holding it costs the card a few lines; when it sat after every
/// detail line (two dozen once aterm's checks list their services) holding it
/// left the card one row and the row still below the glass (measured live,
/// 2026-10-16, on a 774x782 window), and the first screen kept only the block's
/// heading (s-22).
fn macos_access_kept_in_view(access: &MacosAccess, lead: AccessLead, text_width: f32) -> f32 {
    macos_access_reach(access, lead, text_width, None)
}

/// How far under the block's top its actions end with `lead` above them in
/// `text_width`: through every row of buttons, or through the first `rows`.
fn macos_access_reach(
    access: &MacosAccess,
    lead: AccessLead,
    text_width: f32,
    rows: Option<usize>,
) -> f32 {
    let scale = settings_text_scale();
    let line_height = 24.0_f32.max(20.0 * scale);
    let heading_height = access_card_heading(MACOS_ACCESS_HEADING, "MACOS ACCESS", text_width).1;
    let (above, _) = macos_access_rows(&macos_access_copy(access), access, lead);
    let lines = macos_access_action_rows(access, text_width);
    let all = lines.len().max(1);
    let rows = rows.map_or(all, |rows| rows.clamp(1, all));
    12.0 + heading_height
        + macos_access_visual_lines(&above, text_width) as f32 * line_height
        + button_line_set_height(&lines[..rows.min(lines.len())], MACOS_ACCESS_BUTTON_GAP)
}

/// How many visual lines `line` takes in the block's `text_width`: a fact
/// WRAPS to the card's measure, as the DEVELOPER TOOLS card's copy does, and
/// is never elided (the trade, a broken anchor's fault and the route ran past
/// an 80x24 card and were cut, seen once a headless instance could carry a
/// posture, s-24).
fn macos_access_line_count(line: &MacosAccessLine, text_width: f32) -> usize {
    let (px, _) = crate::native_ui::text_paint_metrics(line.2, line.3);
    wrapped_copy_lines(&line.1, px, text_width).len().max(1)
}

/// Every visual line of `lines` in `text_width` ([`macos_access_line_count`]).
fn macos_access_visual_lines(lines: &[MacosAccessLine], text_width: f32) -> usize {
    lines
        .iter()
        .map(|line| macos_access_line_count(line, text_width))
        .sum()
}

/// One fact of the block as its node: a line where it fits `text_width`, else
/// the sentence wrapped to it, its painted lines paint-only under the one node
/// that says it whole.
fn macos_access_line_node(line: MacosAccessLine, text_width: f32, line_height: f32) -> UiNode {
    let count = macos_access_line_count(&line, text_width);
    let (key, text, role, style) = line;
    if count == 1 {
        return UiNode::new(key, UiContent::Text(TextSpec { text, role, style }))
            .layout(Layout::default().height(Length::Fixed(line_height)));
    }
    let (mut node, _) = wrapped_copy_node(&key, &text, role, style, text_width, line_height, None);
    node.layout.height = Length::Fixed(count as f32 * line_height);
    node
}

/// The block's buttons, in order: *Open Privacy & Security…* first, then the
/// folder warm-up, Files & Folders and Ask Again where they apply, the Trash
/// where other copies are listed, and the `sudo` prompts switch.
fn macos_access_buttons(access: &MacosAccess) -> Vec<UiNode> {
    let mut buttons = vec![macos_access_button(
        MACOS_ACCESS_OPEN_FDA,
        "Open Privacy & Security\u{2026}",
        true,
        false,
    )];
    if access.warmup_offered {
        buttons.push(macos_access_button(
            MACOS_ACCESS_WARM_UP,
            "Ask for Folder Access Now",
            !access.warmup_live,
            access.warmup_live,
        ));
    }
    if !access.denied_folders().is_empty() {
        buttons.push(macos_access_button(
            MACOS_ACCESS_OPEN_FILES,
            "Open Files & Folders\u{2026}",
            true,
            false,
        ));
        // §3.7: absent tool, unusable bundle id, or a rebuild-invalidated
        // identity and the button is not drawn at all. A destructive gesture is
        // never offered on an unproven tool or an identity it cannot repair.
        if access.shows_reset_button() {
            buttons.push(macos_access_button(
                MACOS_ACCESS_ASK_AGAIN,
                "Ask Again",
                !access.warmup_live,
                false,
            ));
        }
    }
    if !access.retire_plan().is_empty() {
        buttons.push(macos_access_button(
            MACOS_ACCESS_TRASH,
            "Move Other Copies to the Trash",
            !access.retire_live,
            access.retire_live,
        ));
    }
    // The `sudo` askpass relay off switch (design §3.1): one button carrying
    // its direction. macOS only, so always relevant on this card.
    let (action, label) = if access.askpass_relay_off {
        (MACOS_ACCESS_ASKPASS_ON, "Allow sudo Password Prompts")
    } else {
        (MACOS_ACCESS_ASKPASS_OFF, "Turn Off sudo Password Prompts")
    };
    buttons.push(macos_access_button(action, label, true, false));
    buttons
}

/// THE BLOCK'S BUTTONS IN ROWS, EACH AT ITS LABEL'S WIDTH, by the one rule a
/// page's buttons keep ([`button_line_set`]): as many to a row as
/// `text_width` holds, the next row where the next does not fit — never one
/// row whose buttons split it and elide every label (five buttons painted
/// "Open Privacy &…", "Ask for Folder Ac…" on a 1074pt window, seen once a
/// headless instance could carry a posture, s-24). A label wider than the
/// whole measure takes a row of its own at that measure, its words on as
/// many lines as it needs: a fixed one-line row cut them ("Open…", "Turn O…"
/// at 2× text in a 22-column window). Each row with its height.
fn macos_access_action_rows(access: &MacosAccess, text_width: f32) -> Vec<(Vec<UiNode>, f32)> {
    button_line_set(
        macos_access_buttons(access),
        text_width,
        macos_access_button_lines(),
    )
}

/// How the block's buttons are set ([`button_line_set`]): each its label's
/// width and 28pt ([`page_button_width`]), 72pt at least, 8pt apart.
fn macos_access_button_lines() -> ButtonLines {
    ButtonLines {
        single: scaled_control_height(),
        least: 72.0,
        slack: 8.0,
        gap: MACOS_ACCESS_BUTTON_GAP,
    }
}

/// The gap between the block's buttons, and between their rows.
const MACOS_ACCESS_BUTTON_GAP: f32 = 8.0;

/// The block's heading's key.
const MACOS_ACCESS_HEADING: &str = "settings/macos-access/heading";

/// The height the block's button rows take in `text_width`
/// ([`macos_access_action_rows`]).
fn macos_access_actions_height(access: &MacosAccess, text_width: f32) -> f32 {
    button_line_set_height(
        &macos_access_action_rows(access, text_width),
        MACOS_ACCESS_BUTTON_GAP,
    )
    .max(scaled_control_height())
}

/// The heading of the MACOS ACCESS block or of the DEVELOPER TOOLS card over
/// it, keyed `key`: its small capitals in the heading's own slot where one
/// line holds them, as always; else wrapped to the card's column `text_width`
/// ([`caption_node`]), a caption line each, the same air under them — never
/// cut ("MACOS A…" at 2× text in a 22-column window). Returns the node and
/// its height.
fn access_card_heading(key: &str, caption: &str, text_width: f32) -> (UiNode, f32) {
    let slot = 28.0_f32.max(22.0 * settings_text_scale());
    let (mut node, lines) = caption_node(key, caption, text_width);
    let height = lines + (slot - caption_line_height()).max(0.0);
    node.layout.height = Length::Fixed(height);
    (node, height)
}

/// The debugger row's button, where the row offers one, on its own line by
/// the block's rule ([`macos_access_action_rows`]): its label's width, its
/// words on lines where it is wider than `text_width`. Returns the line and
/// its height.
fn debugger_access_actions(copy: &MacosAccessCopy, text_width: f32) -> Option<(UiNode, f32)> {
    let button = copy.debugger.button.as_ref()?;
    let mut lines = button_line_set(
        vec![macos_access_button(
            button.action(),
            button.label(),
            button.enabled,
            button.busy,
        )],
        text_width,
        macos_access_button_lines(),
    );
    let (buttons, height) = lines.pop()?;
    Some((
        UiNode::new(
            "settings/macos-access/debugger/actions",
            UiContent::Group(GroupSpec::new("Debugger access actions")),
        )
        .layout(
            Layout::row()
                .width(Length::Fill)
                .height(Length::Fixed(height))
                .gap(MACOS_ACCESS_BUTTON_GAP),
        )
        .children(buttons),
        height,
    ))
}

/// The debugger row's text lines in render order: `(key, text, role, style)`:
/// its state line, what it is not, the line that says whether it is allowed,
/// its status, the four facts, the trade and the cross-link to THIS MAC — at
/// every size, under the block's actions. The height and the card both read
/// this, so they cannot disagree.
fn debugger_row_lines(copy: &DebuggerRowCopy) -> Vec<(String, String, SemanticRole, StyleRef)> {
    let mut lines = vec![(
        "settings/macos-access/debugger/state".to_string(),
        copy.headline.clone(),
        SemanticRole::Status,
        StyleRef::Primary,
    )];
    lines.push((
        "settings/macos-access/debugger/kind".to_string(),
        copy.kind.clone(),
        SemanticRole::Text,
        StyleRef::Quiet,
    ));
    lines.push((
        "settings/macos-access/debugger/observed".to_string(),
        copy.state.clone(),
        SemanticRole::Status,
        StyleRef::Primary,
    ));
    if let Some(status) = copy.status.clone() {
        lines.push((
            "settings/macos-access/debugger/status".to_string(),
            status,
            SemanticRole::Status,
            StyleRef::Primary,
        ));
    }
    for (key, text) in [
        ("stops", &copy.stops),
        ("grants", &copy.grants),
        ("lasts", &copy.lasts),
        ("undo", &copy.undo),
        ("trade", &copy.trade),
        ("machine", &copy.cross_link),
    ] {
        lines.push((
            format!("settings/macos-access/debugger/{key}"),
            text.clone(),
            SemanticRole::Text,
            StyleRef::Quiet,
        ));
    }
    lines
}

/// One button in the block. Every one of them is an owner gesture on the main
/// thread; none of them is reachable without a press. Each is as wide as its
/// label where it is set in its lines ([`macos_access_button_lines`]); alone
/// in its row too, since a bar that fills the card reads as a text field.
fn macos_access_button(action: &str, label: &str, enabled: bool, busy: bool) -> UiNode {
    UiNode::new(
        action.to_string(),
        UiContent::Button(
            Control::new(ButtonSpec::new(label), ActionId::new(action.to_string()))
                .state(ControlState {
                    enabled,
                    busy,
                    ..ControlState::default()
                })
                .style(StyleRef::Secondary),
        ),
    )
    .layout(
        Layout::default()
            .width(Length::Fill)
            .height(Length::Fixed(scaled_control_height())),
    )
}

/// The block itself.
fn macos_access_card(access: &MacosAccess, lead: AccessLead, text_width: f32) -> UiNode {
    let line_height = 24.0_f32.max(20.0 * settings_text_scale());
    let copy = macos_access_copy(access);
    let line = |line: MacosAccessLine| macos_access_line_node(line, text_width, line_height);
    let (above, below) = macos_access_rows(&copy, access, lead);
    let mut children =
        vec![access_card_heading(MACOS_ACCESS_HEADING, "MACOS ACCESS", text_width).0];
    children.extend(above.into_iter().map(line));
    let rows = macos_access_action_rows(access, text_width);
    let actions_height = macos_access_actions_height(access, text_width);
    children.push(
        UiNode::new(
            "settings/macos-access/actions",
            UiContent::Group(GroupSpec::new("macOS access actions")),
        )
        .layout(
            Layout::column()
                .width(Length::Fill)
                .height(Length::Fixed(actions_height))
                .gap(MACOS_ACCESS_BUTTON_GAP),
        )
        .children(
            rows.into_iter()
                .enumerate()
                .map(|(index, (row, height))| {
                    UiNode::new(
                        format!("settings/macos-access/actions/row-{index}"),
                        UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
                    )
                    .layout(
                        Layout::row()
                            .width(Length::Fill)
                            .height(Length::Fixed(height))
                            .gap(MACOS_ACCESS_BUTTON_GAP),
                    )
                    .children(row)
                })
                .collect(),
        ),
    );
    // What the verdict leaves under the row, and the detail lines it explains.
    children.extend(below.into_iter().map(line));
    // THE DEBUGGER ROW, the Full Disk Access row's peer (debugger design §3.3).
    children.extend(debugger_row_lines(&copy.debugger).into_iter().map(line));
    if let Some((actions, _)) = debugger_access_actions(&copy, text_width) {
        children.push(actions);
    }
    // The Developer Tools list is the Developer Tools card's, above this one
    // ([`devtools_card`]).
    UiNode::new(
        "settings/macos-access",
        UiContent::Group(GroupSpec::new("macOS access").style(StyleRef::Secondary)),
    )
    .layout(
        Layout::column()
            .height(Length::Fixed(macos_access_height(access, lead, text_width)))
            .padding(Insets::all(12.0))
            .gap(0.0)
            .clipped(),
    )
    .children(children)
}

/// The Security page's "This Mac" Apply Now action id (the button and the
/// contextual command share it).
pub(crate) const MACHINE_APPLY: &str = "machine/apply";

/// Whether Settings ▸ Security shows the "This Mac" status under the Universal
/// Control row: macOS only, once the host's machine read has completed — or,
/// in a copy without its package tool, where nothing can be read or applied,
/// the one line that says why (the row then leaves that note to it).
/// Unit tests and every non-macOS build stay without it rather than show an
/// invented posture.
fn shows_machine_status(state: &SettingsViewState, machine: &MachineProjection) -> bool {
    state.route == SettingsRoute::Security
        && state.search.trim().is_empty()
        && machine.supported
        && (machine.observed || machine.tool_missing)
}

/// The This Mac status in a copy without its package tool.
const MACHINE_TOOL_MISSING: &str =
    "This copy of aterm has no package tool, so it can\u{2019}t change Universal Control.";

/// The "This Mac" status, drawn in the Universal Control row's own group under
/// the row: what the Mac has, what Apply Now would do with the button beside
/// it (only while there is something to apply), what is in the way, and — but
/// `compact`, which the page draws only where a screen cannot hold the whole
/// status — what this launch changed. Every word comes from the packages
/// projection, so pixels, accessibility and introspection agree.
fn machine_status_node(
    packages: &PackagesProjection,
    text_width: f32,
    compact: bool,
    debugger_row: bool,
) -> (UiNode, f32) {
    let machine = &packages.machine;
    let line_height = 20.0_f32.max(18.0 * settings_text_scale());
    let gap = 4.0;
    let line = |key: &str, text: &str, role: SemanticRole, style: StyleRef, width: f32| {
        wrapped_copy_node(key, text, role, style, width, line_height, None)
    };
    let mut items = vec![if machine.tool_missing {
        line(
            "settings/machine/universal-control",
            MACHINE_TOOL_MISSING,
            SemanticRole::Status,
            StyleRef::Quiet,
            text_width,
        )
    } else {
        line(
            "settings/machine/universal-control",
            &machine.universal_control,
            SemanticRole::Status,
            StyleRef::Primary,
            text_width,
        )
    }];
    // Rosetta 2's line, only when there is something to say (missing, or unread).
    if let Some(rosetta) = machine.rosetta.as_deref().filter(|_| !machine.tool_missing) {
        items.push(line(
            "settings/machine/rosetta",
            rosetta,
            SemanticRole::Status,
            StyleRef::Primary,
            text_width,
        ));
    }
    let applying = packages.busy == Some(PackagesBusy::MachineApply);
    // Without the package tool nothing is read or applied: the one line says so.
    let live = !machine.tool_missing;
    if live && machine.refreshing {
        items.push(line(
            "settings/machine/refreshing",
            "Reading this Mac\u{2019}s settings\u{2026}",
            SemanticRole::Status,
            StyleRef::Quiet,
            text_width,
        ));
    } else if live && (applying || (!machine.next.is_empty() && !machine.nothing_to_apply)) {
        // What a press does, with the button beside it at its own width:
        // there while something is left to apply, greyed while other package
        // work runs, so the row doesn't jump as that work comes and goes.
        let button_width = page_button_width("Apply Now", text_width);
        let control_height = scaled_control_height();
        let mut button = UiNode::new(
            MACHINE_APPLY,
            UiContent::Button(
                Control::new(ButtonSpec::new("Apply Now"), ActionId::new(MACHINE_APPLY))
                    .state(ControlState {
                        enabled: machine.apply_enabled && !applying,
                        busy: applying,
                        ..ControlState::default()
                    })
                    .style(StyleRef::Secondary),
            ),
        )
        .layout(
            Layout::default()
                .width(Length::Fixed(button_width))
                .height(Length::Fixed(control_height)),
        );
        let beside = text_width - button_width - 8.0 >= 160.0;
        let (next, next_height) = line(
            "settings/machine/next",
            &machine.next,
            SemanticRole::Text,
            StyleRef::Quiet,
            if beside {
                text_width - button_width - 8.0
            } else {
                text_width
            },
        );
        let (layout, children, height) = if beside {
            let height = next_height.max(control_height);
            let mut next = next;
            next.layout.width = Length::Fill;
            (
                Layout::row().height(Length::Fixed(height)).gap(8.0),
                vec![next, button],
                height,
            )
        } else {
            button.layout.height = Length::Fixed(control_height);
            let height = next_height + gap + control_height;
            (
                Layout::column().height(Length::Fixed(height)).gap(gap),
                vec![next, button],
                height,
            )
        };
        items.push((
            UiNode::new(
                "settings/machine/actions",
                UiContent::Group(GroupSpec::new("This Mac actions")),
            )
            .layout(layout)
            .children(children),
            height,
        ));
    }
    if let Some(reason) = machine.reason.as_deref().filter(|_| live) {
        items.push(line(
            "settings/machine/home",
            reason,
            SemanticRole::Text,
            StyleRef::Danger,
            text_width,
        ));
    }
    if let Some(saved) = machine.saved.as_deref().filter(|_| live) {
        items.push(line(
            "settings/machine/saved",
            saved,
            SemanticRole::Text,
            StyleRef::Quiet,
            text_width,
        ));
    }
    if live && !compact {
        if let Some(change) = machine.last_change.as_deref() {
            items.push(line(
                "settings/machine/last-applied",
                change,
                SemanticRole::Text,
                StyleRef::Quiet,
                text_width,
            ));
        }
        if let Some(verdict) = machine.last_verdict.as_deref() {
            items.push(line(
                "settings/machine/verdict",
                &format!("Last apply: {verdict}"),
                SemanticRole::Text,
                StyleRef::Quiet,
                text_width,
            ));
        }
        if debugger_row {
            // The other half of the debugger row's cross-link: both change the
            // whole Mac, but this one is applied by itself, and debugger access
            // only ever changes on your yes in aterm's alert (your press, or
            // the one question aterm asks on a new Mac).
            items.push(line(
                "settings/machine/debugger",
                "Machine-wide, like Debugger access above, but applied automatically; \
                 Debugger access changes only when you say yes.",
                SemanticRole::Text,
                StyleRef::Quiet,
                text_width,
            ));
        }
    }
    let height = items.iter().map(|(_, height)| height).sum::<f32>()
        + items.len().saturating_sub(1) as f32 * gap;
    (
        UiNode::new(
            "settings/machine",
            UiContent::Group(GroupSpec::new("This Mac status")),
        )
        .layout(
            Layout::column()
                .width(Length::Fill)
                .height(Length::Fixed(height))
                .gap(gap),
        )
        .children(items.into_iter().map(|(node, _)| node).collect()),
        height,
    )
}

/// One segment of a short choice drawn in its row.
#[derive(Clone, Debug, PartialEq, Eq)]
struct SegmentOption {
    value: String,
    label: String,
}

/// The least a compact row gives a choice control beside its label before
/// it stacks the control under the label: a picker's button, whose label is
/// fitted to it. A row of segments takes at least what its labels measure
/// ([`segmented_natural_width`]).
const COMPACT_INLINE_CHOICE_MIN: f32 = 250.0;

/// A SHORT CHOICE IS ITS ROW'S SEGMENTS, one click to choose, instead of a
/// full-page picker: two or three options, with the saved value one of them.
/// Returns the segments and the saved one. The kind is the setting's own at
/// every width and text size — the reducer reads it with no layout at hand
/// (`settings/segment/…`, `settings/set/…`, the keyboard's reseat) — and every
/// layout gives the segments the width their labels measure
/// ([`segmented_natural_width`]): a one-line row's slot grows to it, a compact
/// row stacks its control under the label where the slot beside it is
/// narrower, and a column narrower still sets the segments one under another
/// ([`wrap_segments`]), so a label is never cut and a control never turns
/// into another kind as a window narrows. The trail, its sound and the
/// display face (a mix) keep their pickers, and a saved value the segments
/// do not offer keeps the picker that names it.
fn segmented_choices(field: &EditField, value: &str) -> Option<(Vec<SegmentOption>, usize)> {
    if !matches!(field.kind, EditKind::Enum { .. })
        || matches!(
            field.key,
            prefs::EDIT_CURSOR_TRAIL_STYLE
                | prefs::EDIT_TRAIL_SOUND_STYLE
                | prefs::EDIT_DISPLAY_FONT
        )
    {
        return None;
    }
    let options = choices_for_field(field, &crate::app_config::ThemeCatalog::default())?;
    if !(2..=3).contains(&options.len()) {
        return None;
    }
    let segments = options
        .into_iter()
        .map(|value| SegmentOption {
            label: segment_label(field.key, &value),
            value,
        })
        .collect::<Vec<_>>();
    let value = if field.seed.is_some() {
        value.trim()
    } else {
        unset_choice_value(field, value)
    };
    let selected = segments
        .iter()
        .position(|segment| segment.value.eq_ignore_ascii_case(value))?;
    Some((segments, selected))
}

/// A segment's label: the picker's, shortened where the row's own label
/// already says what the choice is about. Window appearance's automatic
/// choice is "Auto", as the system's own appearance control says; its note
/// says what it follows.
fn segment_label(key: &str, value: &str) -> String {
    match (key, value) {
        (prefs::EDIT_MOTION, "full") => "Animate".to_string(),
        (prefs::EDIT_MOTION, "reduced") => "Reduce".to_string(),
        (prefs::EDIT_WINDOW_THEME, "auto") => "Auto".to_string(),
        (prefs::EDIT_WINDOW_THEME, _) => setting_choice_label(key, value),
        _ => choice_label(value),
    }
}

/// The width a row of `segments` needs to show every label whole: as many
/// equal segments as there are, each as wide as the widest label and its
/// padding, 2pt apart ([`segmented_choice_node`]).
fn segmented_natural_width(segments: &[SegmentOption]) -> f32 {
    let widest = segments
        .iter()
        .map(|segment| crate::native_ui::native_button_label_width(&segment.label) + 24.0)
        .fold(0.0_f32, f32::max);
    widest * segments.len() as f32 + 2.0 * segments.len().saturating_sub(1) as f32
}

/// Whether `field`'s segments, sharing a `text_width` column equally as a
/// stacked control band lays them ([`segmented_choice_node`]: Fill widths 2pt
/// apart), each paint their label whole: a segment centres its label in the
/// room a text button keeps clear of its edges
/// ([`crate::native_ui::text_button_label_room`]), and elides what that room
/// cannot hold. `true` where `field` is not drawn as segments.
fn segments_hold_their_labels(field: &EditField, text_width: f32) -> bool {
    let Some((segments, _)) = segmented_choices(field, SettingsState::display_value(field)) else {
        return true;
    };
    let count = segments.len() as f32;
    let share = (text_width - 2.0 * (count - 1.0)) / count;
    segments.iter().all(|segment| {
        let spec = ButtonSpec::new(segment.label.as_str());
        crate::native_ui::native_button_label_width(&segment.label)
            <= crate::native_ui::text_button_label_room(&spec, share)
    })
}

/// The width `field`'s segments need, where it is drawn as segments.
fn segmented_width_need(field: &EditField) -> Option<f32> {
    segmented_choices(field, SettingsState::display_value(field))
        .map(|(segments, _)| segmented_natural_width(&segments))
}

/// The room `key`'s segments have on their line of a stacked `row` whose
/// column is `text_width`: the column less what shares their line (the
/// Reset a stacked row keeps after them) — the box they are drawn in, so a
/// label wrapped to fit it fits it ("Recommen-" / "ded" was measured for the
/// whole column and painted 18pt short of its room), and segments wider than
/// it are wrapped although the column alone would hold them (three
/// segments at 2× ran a 108pt Reset 52pt past a wide Harness page's row).
fn segments_line_room(row: &UiNode, key: &str, text_width: f32) -> f32 {
    let segments_key = format!("settings/segments/{key}");
    row.children
        .iter()
        .find(|line| {
            line.children
                .iter()
                .any(|child| child.key.as_str() == segments_key)
        })
        .map_or(text_width, |line| {
            let others = line
                .children
                .iter()
                .filter(|child| child.key.as_str() != segments_key)
                .map(|child| match child.layout.width {
                    Length::Fixed(width) => width + line.layout.gap,
                    _ => 0.0,
                })
                .sum::<f32>();
            (text_width - others).max(0.0)
        })
}

/// SEGMENTS ON AS FEW LINES AS THEIR LABELS ALLOW where the column cannot
/// hold them side by side (the largest text in the narrowest window): as
/// many to a line as `text_width` holds at the width the widest label needs,
/// equal, each as tall as a touch target that holds its label's line; and
/// `row` (a stacked row: its label line, the band's gap, its control band)
/// as tall as its label line and those lines, so no label is cut and the
/// control stays the same control ([`segmented_choices`]).
fn wrap_segments(row: &mut UiNode, key: &str, text_width: f32) {
    let segments_key = format!("settings/segments/{key}");
    fn find<'a>(node: &'a mut UiNode, key: &str) -> Option<&'a mut UiNode> {
        if node.key.as_str() == key {
            return Some(node);
        }
        node.children.iter_mut().find_map(|child| find(child, key))
    }
    let px = crate::native_ui::native_type_px(crate::type_scale::TypeStep::Secondary).get();
    let segment_height = 44.0_f32.max((px * 1.25 + 12.0).ceil());
    let text_width = segments_line_room(row, key, text_width);
    let Some(group) = find(row, &segments_key) else {
        return;
    };
    let count = group.children.len();
    if count < 2 {
        return;
    }
    let widest = group
        .children
        .iter()
        .filter_map(|segment| match &segment.content {
            UiContent::Button(button) => button.spec.visual_label.as_deref(),
            _ => None,
        })
        .map(|label| crate::native_ui::native_button_label_width(label) + 24.0)
        .fold(0.0_f32, f32::max);
    let per_line = (((text_width + 2.0) / (widest + 2.0)).floor() as usize).clamp(1, count);
    // Never wider than the column: where even one segment's label is wider
    // than the column (the largest text in the narrowest window), it keeps
    // its words on as many lines as the column needs ([`button_words`]), its
    // line as tall as they are — never cut ("Long-t…", "Leave a…" at 2× text
    // on a phone-width page).
    let width = ((text_width - 2.0 * (per_line - 1) as f32) / per_line as f32)
        .max(widest)
        .min(text_width);
    let segments = std::mem::take(&mut group.children);
    let mut lines = Vec::new();
    let mut column = 0.0;
    let mut segments = segments.into_iter().peekable();
    while segments.peek().is_some() {
        let mut line_height = segment_height;
        let line: Vec<UiNode> = segments
            .by_ref()
            .take(per_line)
            .map(|mut segment| {
                segment.layout.width = Length::Fixed(width);
                segment.layout.height = Length::Fill;
                if width < widest
                    && let UiContent::Button(button) = &mut segment.content
                    && let Some(label) = button.spec.visual_label.clone()
                {
                    let (words, count) = button_words_in(&button.spec, &label, &[], width);
                    button.spec.visual_label = Some(words);
                    line_height = line_height.max(
                        crate::native_ui::native_button_height_for_lines(count, segment_height),
                    );
                }
                segment
            })
            .collect();
        column += line_height + if lines.is_empty() { 0.0 } else { 2.0 };
        lines.push(
            UiNode::new(
                format!("{segments_key}/line-{}", lines.len()),
                UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
            )
            .layout(
                Layout::row()
                    .width(Length::Fill)
                    .height(Length::Fixed(line_height))
                    .gap(2.0),
            )
            .children(line),
        );
    }
    group.layout = Layout::column()
        .width(Length::Fill)
        .height(Length::Fill)
        .gap(2.0);
    group.children = lines;
    let label = row.children.first().map_or(0.0, fixed_height);
    row.layout.height = Length::Fixed(label + 4.0 + column);
}

/// The key a segment has on glass: the saved one is the setting's control.
fn segment_focus_key(key: &str, index: usize, selected: usize) -> UiKey {
    UiKey::new(if index == selected {
        format!("settings/control/{key}")
    } else {
        format!("settings/segment/{key}/{index}")
    })
}

/// The segments themselves. The saved one carries the setting's identity
/// (`settings/control/<key>`, `settings/set/<key>`, its value in the words it
/// shows), so focus, automation, and introspection find the control where
/// they always did; each other segment saves its option.
fn segmented_choice_node(
    field: &EditField,
    segments: &[SegmentOption],
    selected: usize,
    value: &str,
    segment_facts: &[String],
    description: &str,
    state: ControlState,
) -> UiNode {
    let children = segments
        .iter()
        .enumerate()
        .map(|(index, segment)| {
            let semantic_facts = segment_facts.get(index).map_or("", String::as_str);
            let saved = index == selected;
            let (key, action) = if saved {
                (
                    format!("settings/control/{}", field.key),
                    format!("settings/set/{}", field.key),
                )
            } else {
                let key = format!("settings/segment/{}/{index}", field.key);
                (key.clone(), key)
            };
            let mut control = Control::new(
                ButtonSpec {
                    label: format!("{}: {}{semantic_facts}", field.label, segment.label),
                    visual_label: Some(segment.label.clone()),
                    visual_icon: None,
                    trailing_icon: None,
                    description: Some(description.to_string()),
                    badge: false,
                    swatches: Vec::new(),
                    chip: None,
                    chevron_row: None,
                },
                ActionId::new(action),
            )
            .state(ControlState {
                selected: saved,
                ..state
            })
            .style(StyleRef::Navigation);
            if saved {
                // The words the segment shows, never the config token: a
                // screen reader says "Auto (default)", not "implicit".
                let words = if value.trim().ends_with(" (default)") {
                    format!("{} (default)", segment.label)
                } else {
                    segment.label.clone()
                };
                control = control.value(SemanticValue::Text(words));
            }
            UiNode::new(key, UiContent::Button(control))
                .layout(Layout::default().width(Length::Fill).height(Length::Fill))
        })
        .collect();
    UiNode::new(
        format!("settings/segments/{}", field.key),
        UiContent::Group(GroupSpec {
            label: Some(field.label.to_string()),
            role: SemanticRole::Group,
            style: StyleRef::Secondary,
        }),
    )
    // Each segment takes the control's whole height: its hit target is the
    // row's, as the button it replaces had.
    .layout(Layout::row().gap(2.0))
    .children(children)
    // One control to the keyboard: one Tab stop, Left/Right between its
    // segments, Return or Space to choose ([`UiNode::segmented`]).
    .segmented()
}

/// A row's note on this page: [`prefs::footnote_of`], except the trail
/// colours' one, which says what they do for the saved cursor style
/// ([`prefs::trail_color_note`]: Classic's shifting colours, a style that
/// draws its own colours on a block, Laser's violet), as their placeholders
/// and Reset words already do.
fn row_footnote(state: &SettingsViewState, key: &str) -> Option<std::borrow::Cow<'static, str>> {
    if matches!(
        key,
        prefs::EDIT_CURSOR_TRAIL_COLOR | prefs::EDIT_CURSOR_TRAIL_ACCENT
    ) {
        return Some(std::borrow::Cow::Owned(prefs::trail_color_note(
            &spelled_trail_value(state),
            configured_cursor_is_block(state),
            // The colour law's pin, as the rows' placeholders read it.
            state.is_explicit(prefs::EDIT_CURSOR_COLOR),
        )));
    }
    prefs::footnote_of(key).map(std::borrow::Cow::Borrowed)
}

/// What Reset returns `key` to in `state`, in the words its control shows:
/// [`default_value_label`], except for the knobs whose default is the cursor
/// style's — the style aterm.toml names, as the row's own placeholder reads
/// it — not an empty aterm.toml's: the trail colours
/// ([`prefs::trail_color_default_words`]: Classic's shifting colours, Laser's
/// violet, the accent a brighter trail colour where one is chosen) and the
/// bloom size (the rainbow kitty's own).
fn modified_default_words(state: &SettingsViewState, key: &str) -> Option<String> {
    let style = || crate::app_config::resolve_trail_style(&top_authored_trail_value(state));
    match key {
        prefs::EDIT_CURSOR_TRAIL_COLOR | prefs::EDIT_CURSOR_TRAIL_ACCENT => {
            // As aterm.toml spells it: an old `classic mono` says a colour.
            Some(prefs::trail_color_default_words(
                key,
                &spelled_trail_value(state),
                prefs::trail_color_setting(
                    state.raw_value(prefs::EDIT_CURSOR_TRAIL_COLOR).as_deref(),
                ),
                // The colour law's pin, as the row's placeholder reads it.
                state.is_explicit(prefs::EDIT_CURSOR_COLOR),
            ))
        }
        prefs::EDIT_CURSOR_TRAIL_BLOOM_RADIUS => {
            let value = crate::app_config::Config::bloom_radius_style_default(style());
            let shown = value.to_string();
            Some(prefs::numeric_reading(key, f64::from(value), &shown).unwrap_or(shown))
        }
        _ => default_value_label(key).map(str::to_string),
    }
}

/// What Reset returns `key` to, in the words its control shows: the value an
/// empty aterm.toml resolves. `None` when that default has no one-line form.
fn default_value_label(key: &str) -> Option<&'static str> {
    static DEFAULTS: std::sync::OnceLock<Vec<(&'static str, String)>> = std::sync::OnceLock::new();
    DEFAULTS
        .get_or_init(|| {
            prefs::editable_fields(&crate::app_config::Config::default())
                .into_iter()
                .filter_map(|field| {
                    let shown = SettingsState::display_value(&field);
                    let shown = shown.strip_suffix(" (default)").unwrap_or(shown).trim();
                    let label = match field.kind {
                        EditKind::Bool => match shown {
                            "true" => "On".to_string(),
                            "false" => "Off".to_string(),
                            _ => return None,
                        },
                        // A short choice's default in the words its segment
                        // shows ("Auto"), any other choice's as its picker.
                        EditKind::Enum { .. } | EditKind::Theme => {
                            if segmented_choices(&field, shown).is_some() {
                                segment_label(field.key, shown)
                            } else {
                                setting_choice_label(field.key, shown)
                            }
                        }
                        // A number reads as its slider does, whatever note
                        // or unit follows it ("1.0 (solid)", "260 ms").
                        EditKind::Float | EditKind::Integer => {
                            let number = shown.split_whitespace().next().unwrap_or_default();
                            number
                                .parse::<f64>()
                                .ok()
                                .filter(|value| value.is_finite())
                                .and_then(|value| prefs::numeric_reading(field.key, value, number))
                                .unwrap_or_else(|| shown.to_string())
                        }
                        _ => shown.to_string(),
                    };
                    (!label.is_empty()).then_some((field.key, label))
                })
                .collect()
        })
        .iter()
        .find(|(candidate, _)| *candidate == key)
        .map(|(_, label)| label.as_str())
}

/// A list's setting row, finished. A compact column lays it out on one line
/// where it leaves the label a useful measure ([`compact_row_inline`]). Its
/// label line holds the name and its tags where they fit, else the name
/// (and Changed, where that fits too); under it, wrapped to `text_width`
/// instead of cut off, go the tags that did not fit, when a saved change
/// takes effect, and the row's own note (`note`). The selected tab color's
/// row also offers the Tab Color page's wheel, and Modified's Display face
/// row takes the control its own page gives it, a toggle per face. The
/// node's height is fixed.
///
/// A row whose box says once why its rows are idle (`shared_reason`,
/// [`shared_inactive_reason`]) leaves that tag off its own lines; its
/// accessible name still says it.
// The row's identity, its place, its measures, its note and the box's
// reason: one caller in three passes each, so a struct would only rename them.
#[allow(clippy::too_many_arguments)]
fn finish_setting_row_sharing(
    state: &SettingsViewState,
    index: usize,
    field: &EditField,
    modified_only: bool,
    width: SettingsWidth,
    text_width: f32,
    note: Option<&str>,
    shared_reason: Option<&str>,
) -> UiNode {
    finished_setting_row(
        state,
        index,
        field,
        modified_only,
        width,
        text_width,
        note.map(prefs::RowNote::Own),
        shared_reason,
        None,
    )
    .whole()
}

/// [`finish_setting_row_sharing`] in a column narrower than a field page's: the
/// control gives up width (to at most `control_width`) before the label is
/// cut, and the label line is fitted to what is left.
fn finish_setting_row_narrowed(
    state: &SettingsViewState,
    index: usize,
    field: &EditField,
    width: SettingsWidth,
    text_width: f32,
    note: Option<&str>,
    control_width: f32,
) -> UiNode {
    finished_setting_row(
        state,
        index,
        field,
        false,
        width,
        text_width,
        note.map(prefs::RowNote::Own),
        None,
        Some(control_width),
    )
    .whole()
}

/// [`finish_setting_row_sharing`] with its second line not yet placed.
/// `control_width` narrows the control (never widens it) before the label
/// line is fitted, for a column narrower than a field page's.
#[allow(clippy::too_many_arguments)]
fn finished_setting_row(
    state: &SettingsViewState,
    index: usize,
    field: &EditField,
    modified_only: bool,
    width: SettingsWidth,
    text_width: f32,
    note: Option<prefs::RowNote<'_>>,
    shared_reason: Option<&str>,
    control_width: Option<f32>,
) -> FinishedRow {
    let finished = finished_setting_row_as(
        state,
        index,
        field,
        modified_only,
        (width, text_width),
        note,
        shared_reason,
        control_width,
        false,
    );
    // A row laid on one line because the list is shorter than its stack
    // ([`large_text_rows_stack`]) stays so only where that line — the row
    // itself, its note listed after it — is whole in the list: one taller
    // (its name on lines of their own beside the control: Ai's Machine and
    // Fleet rows, 190pt in a 100pt list) stacks after all, its name and its
    // control each whole on a screen.
    match rows_too_tall_to_stack() {
        Some(room) if !finished.stacked && fixed_height(&finished.split(room).0) > room + 0.01 => {
            finished_setting_row_as(
                state,
                index,
                field,
                modified_only,
                (width, text_width),
                note,
                shared_reason,
                control_width,
                true,
            )
        }
        _ => finished,
    }
}

/// [`finished_setting_row`], stacked (`stack`) or as its width's rule lays
/// it out.
#[allow(clippy::too_many_arguments)]
fn finished_setting_row_as(
    state: &SettingsViewState,
    index: usize,
    field: &EditField,
    modified_only: bool,
    (width, text_width): (SettingsWidth, f32),
    note: Option<prefs::RowNote<'_>>,
    shared_reason: Option<&str>,
    control_width: Option<f32>,
    stack: bool,
) -> FinishedRow {
    let display_face = modified_only && field.key == prefs::EDIT_DISPLAY_FONT;
    let segment_need = segmented_width_need(field);
    // The row laid out one line (`inline_control`: its control's width
    // there), stacked (`stack`: its control under its name, as a compact row
    // lays it out) or by `width`'s own rule; the parts' row is the finished
    // row.
    let build = |inline_control: Option<f32>, stack: bool| -> (SettingRowParts, bool) {
        let inline = inline_control.is_some();
        let row_width = if display_face || stack {
            SettingsWidth::Compact
        } else if inline {
            SettingsWidth::Medium
        } else {
            width
        };
        let mut parts = setting_row_parts(state, index, field, modified_only, row_width);
        if let Some(reason) = shared_reason {
            parts.tags.facts.retain(|tag| tag != reason);
            parts.worst.facts.retain(|tag| tag != reason);
        }
        let mut row = parts.row;
        let stacked = row_width == SettingsWidth::Compact;
        if let Some(control_width) = inline_control {
            row.layout.height = Length::Fixed(compact_inline_row_height());
            if let Some(control) = row.children.get_mut(1) {
                control.layout.width = Length::Fixed(control_width);
            }
        }
        if let Some(narrow) = control_width.filter(|_| !stacked && !inline)
            && let Some(control) = row.children.get_mut(1)
            && let Length::Fixed(current) = control.layout.width
        {
            // Never below what its segments need: the label gives way instead.
            control.layout.width =
                Length::Fixed(current.min(narrow).max(segment_need.unwrap_or_default()));
        }
        // A column narrower than the segments sets them on as few lines as fit.
        if stacked
            && segment_need
                .is_some_and(|need| need > segments_line_room(&row, field.key, text_width) + 0.01)
        {
            wrap_segments(&mut row, field.key, text_width);
        }
        // Modified's Display face row is the setting's own control, the face
        // switches Text & Fonts draws ([`display_face_rows`]): under the row's
        // name, Default and Reset, a switch per face, so a mix reads as one.
        if display_face && row.children.len() > 1 {
            let faces = display_face_rows(state, width, text_width);
            let faces_height: f32 = faces.iter().map(|(_, height)| height).sum();
            let label_height = row.children.first().map_or(0.0, fixed_height);
            row.children[1] = UiNode::new(
                format!("settings/control/{}", field.key),
                UiContent::Group(GroupSpec {
                    label: Some("Display faces".to_string()),
                    role: SemanticRole::Group,
                    style: StyleRef::Plain,
                }),
            )
            .layout(
                Layout::column()
                    .width(Length::Fill)
                    .height(Length::Fixed(faces_height)),
            )
            .children(faces.into_iter().map(|(node, _)| node).collect());
            row.layout.height = Length::Fixed(label_height + 4.0 + faces_height);
        }
        // A page that owns the key shapes its control: a colour row's Choose…
        // opens the colour picker under it; the Window page's selected tab
        // color goes to Tab Color while it holds no draft.
        page_owned_control_form(
            state,
            field,
            modified_only,
            (width, inline, text_width),
            &mut row,
        );
        (SettingRowParts { row, ..parts }, stacked)
    };
    let mut inline_control = (width == SettingsWidth::Compact && !display_face && !stack)
        .then(|| compact_inline_choice_width(field, segment_need, text_width))
        .flatten();
    let (mut parts, mut stacked) = build(inline_control, stack);
    let floor = |parts: &SettingRowParts| one_line_name_floor(&parts.name);
    // ONE MEASURE FOR THE WHOLE LINE: a one-line row leaves its label its
    // floor ([`one_line_name_floor`]) beside EVERYTHING the line holds, so
    // what the row seats beside its control (the Theme row's Browse themes…,
    // a colour row's Choose…) comes out of the control's room where the name
    // needs it, and the row stacks where the control would fall below its
    // least, never cutting the name to a word or two.
    if inline_control.is_some() {
        if one_line_row_extras(&parts.row) > 0.0
            && one_line_label_room(&parts.row, text_width) + 0.01 < floor(&parts)
        {
            let beside = one_line_row_extras(&parts.row);
            inline_control = compact_inline_choice_width(field, segment_need, text_width - beside);
            (parts, stacked) = build(inline_control, false);
        }
        if inline_control.is_some()
            && one_line_label_room(&parts.row, text_width) + 0.01 < floor(&parts)
        {
            (parts, stacked) = build(None, false);
        }
    } else if !stacked {
        // A PAGE'S ONE-LINE ROW KEEPS THE SAME MEASURE: wider than Compact a
        // row lays its control out at its regular width, and where that
        // leaves the name less than its floor beside everything on the line
        // (Harness' Question priority, whose three segments left "Question"
        // 44pt, broken inside the word; a text field and Reset in the
        // narrowest wide column), the control gives up width first, down to
        // its least, then the row stacks the control under the name.
        let short = floor(&parts) - one_line_label_room(&parts.row, text_width);
        if short > 0.01 {
            let least = match field.kind {
                EditKind::Bool => f32::INFINITY,
                EditKind::Enum { .. } | EditKind::Theme => {
                    COMPACT_INLINE_CHOICE_MIN.max(segment_need.unwrap_or_default())
                }
                _ => 200.0,
            };
            match parts
                .row
                .children
                .get_mut(1)
                .map(|control| (control.layout.width, control))
            {
                Some((Length::Fixed(current), control)) if current - short + 0.01 >= least => {
                    control.layout.width = Length::Fixed(current - short);
                }
                _ => (parts, stacked) = build(None, true),
            }
        }
    }
    let SettingRowParts {
        mut row,
        name,
        tags,
        worst,
        timing,
    } = parts;
    if stacked {
        seat_stacked_reset(&mut row, &name, text_width);
    }
    fit_row_button_words(&mut row, &name, text_width, stacked);
    let unset = matches!(
        field.kind,
        EditKind::Text | EditKind::Color | EditKind::Float | EditKind::Integer
    )
    .then(|| unset_field_words(state, field))
    .flatten();
    fit_row_field_placeholder(
        &mut row,
        (&name, text_width, stacked),
        unset
            .as_deref()
            .map(|words| (words, field.kind == EditKind::Color)),
        field.seed.as_deref(),
    );
    let label_width = row_label_room(&row, stacked, text_width);
    FinishedRow {
        row,
        key: field.key,
        name,
        tags,
        worst,
        timing,
        note: prefs::RowNote::own(note).map(str::to_string),
        shared_note: prefs::RowNote::shared(note).map(str::to_string),
        error: state.field_errors.get(field.key).cloned(),
        label_width,
        stacked,
        text_width,
        facts_below: None,
        // Modified names a colour row's default; the default's colour rides
        // those words as the chip the row's field wears.
        default_chip: modified_only
            .then(|| color_picker::default_color_chip(state, field))
            .flatten(),
    }
}

/// The gap between a switch and the Reset place after it, for a switch row in
/// a `text_width` column of a page `width` wide, or `None` where Reset's place
/// is not after the switch: a one-line row keeps it after a 12pt gap
/// ([`compact_row_inline`]); a stacked row on its control line after the
/// band's 6pt gap, where that line holds both, else at the end of its label
/// line ([`seat_stacked_switch_reset`]). A card that draws its own switch rows
/// (the display faces) asks here, so its switches end where the page's do.
fn switch_tail(width: SettingsWidth, text_width: f32) -> Option<f32> {
    if width != SettingsWidth::Compact || compact_row_inline(&EditKind::Bool, text_width, true) {
        return Some(12.0);
    }
    // The stacked control band: its spacer, the switch at its least and
    // Reset's place ([`seat_stacked_switch_reset`]).
    stacked_switch_line_holds(
        switch_control_width(text_width).min(crate::native_ui::switch_least_width()),
        reset_slot_width(),
        text_width,
    )
    .then_some(STACKED_CONTROL_GAP)
}

/// A SWITCH IS NEVER WIDER THAN ITS LINE: its natural width — 104pt at 1×,
/// growing with the text to 1.4× — or the whole line `text_width` where that
/// is less (a phone-width column at large text), where its track and its
/// On/Off word still sit whole. A stacked switch row's fixed 145.6pt switch
/// used to run out of its card in a 116pt column at 2× text, cutting its
/// own word and the card's edge.
fn switch_control_width(text_width: f32) -> f32 {
    (104.0 * settings_text_scale().min(1.4)).min(text_width.max(0.0))
}

/// Whether a stacked switch row's control line — its spacer, the switch and
/// a Reset (or its place) `reset_width` wide, [`STACKED_CONTROL_GAP`] apart —
/// holds both in `text_width`; where it does not, Reset ends the label line.
fn stacked_switch_line_holds(switch_width: f32, reset_width: f32, text_width: f32) -> bool {
    switch_width + reset_width + 2.0 * STACKED_CONTROL_GAP <= text_width + 0.01
}

/// The gap between the controls on a stacked row's control line.
const STACKED_CONTROL_GAP: f32 = 6.0;

/// Where a stacked row keeps its Reset (or the place it keeps): after a
/// switch on its control line where that line holds both
/// ([`seat_stacked_switch_reset`]), else at the end of its label line —
/// unless the name `name` has a word that cannot sit beside it there (a
/// phone-width column, large text): then the name has the label line to
/// itself and Reset ends the row, on a line of its own under the control,
/// so the name wraps between its words and is never cut inside one.
fn seat_stacked_reset(row: &mut UiNode, name: &str, text_width: f32) {
    seat_stacked_switch_reset(row, text_width);
    let Some(line) = row
        .children
        .first()
        .filter(|line| line.key.as_str().starts_with("settings/label-line/"))
    else {
        return;
    };
    let room = one_line_label_room(line, text_width);
    // RESET SITS WHERE IT COSTS THE ROW LEAST: at the end of the label line
    // while the lines the name takes beside it, over those it takes alone,
    // cost no more than a line of Reset's own; else on a line of its own.
    // Measured with the place Reset keeps, so a row seats Reset in one
    // place empty or changed. Kept on the label line wherever a word fit
    // beside it, at 2× text in a 38-column window Reset's 108pt place left
    // "Supervise Gemini CLI sessions" 124pt, four lines where the line
    // alone holds it on two; "256-colour palette" broke at its hyphen.
    // A word the room cannot hold whole ([`line_pieces`]) is a cost no line
    // of Reset's own outweighs.
    if pieces_fit(name, room, &row_label_width) {
        let beside = row_name_lines(name, room).len();
        let alone = row_name_lines(name, text_width).len();
        let cost = beside.saturating_sub(alone) as f32 * row_detail_line_height();
        if cost <= fixed_height(line) + row.layout.gap + 0.01 {
            return;
        }
    }
    let mut line = row.children.remove(0);
    let key = line
        .key
        .as_str()
        .trim_start_matches("settings/label-line/")
        .to_string();
    let label = line.children.remove(0);
    let height = fixed_height(&line);
    let spacer = UiNode::new(
        format!("settings/reset-line/{key}/spacer"),
        UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
    )
    .layout(Layout::default().width(Length::Fill).height(Length::Fill));
    // Reset after a spacer, on its own line — and where Reset's place is the
    // line's whole width (a phone-width column at 2× text), Reset alone and
    // never wider than the line, so no gap pushes it past the edge.
    let mut trailing = vec![spacer];
    trailing.extend(line.children.into_iter().map(|mut reset| {
        if let Length::Fixed(width) = reset.layout.width {
            reset.layout.width = Length::Fixed(width.min(text_width));
        }
        reset
    }));
    let resets: f32 = trailing.iter().skip(1).map(fixed_width).sum();
    if resets + STACKED_CONTROL_GAP * (trailing.len() - 1) as f32 > text_width + 0.01 {
        trailing.remove(0);
    }
    row.children.insert(0, label);
    row.children.push(
        UiNode::new(
            format!("settings/reset-line/{key}"),
            UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
        )
        .layout(
            Layout::row()
                .width(Length::Fill)
                .height(Length::Fixed(height))
                .gap(STACKED_CONTROL_GAP),
        )
        .children(trailing),
    );
    row.layout.height = Length::Fixed(fixed_height(row) + row.layout.gap + height);
}

/// A stacked switch row's Reset (or the place it keeps) follows the switch on
/// its control line, so the name has the whole width — where that line holds
/// both. Where it does not (large text in a narrow column), Reset ends the
/// label line instead, as every other stacked row's does, so neither is cut.
fn seat_stacked_switch_reset(row: &mut UiNode, text_width: f32) {
    let Some(controls) = row
        .children
        .get_mut(1)
        .filter(|controls| controls.key.as_str().contains("/controls/"))
    else {
        return;
    };
    let line_width = |controls: &UiNode| -> f32 {
        let fixed: f32 = controls
            .children
            .iter()
            .map(|child| match child.layout.width {
                Length::Fixed(width) => width,
                _ => 0.0,
            })
            .sum();
        fixed + controls.layout.gap * controls.children.len().saturating_sub(1) as f32
    };
    let reset_at = controls
        .children
        .iter()
        .position(|child| is_reset_place(child.key.as_str()));
    // Decided by the switch at its least ([`crate::native_ui::switch_least_width`]):
    // a switch narrower than its natural width, its track and its On/Off
    // whole, beside its Reset leaves the name the whole label line. Decided
    // by its natural width, a 38-column window at 2× text sent Reset's place
    // to the label line and set "Supervise Gemini CLI sessions" a word to a
    // line beside it, four lines where the line alone holds it on two.
    let least = crate::native_ui::switch_least_width();
    let least_line = line_width(controls)
        - controls
            .children
            .iter()
            .filter(|child| matches!(child.content, UiContent::Switch(_)))
            .map(|child| match child.layout.width {
                Length::Fixed(width) => (width - least).max(0.0),
                _ => 0.0,
            })
            .sum::<f32>();
    let moved = match reset_at {
        Some(at) if least_line > text_width + 0.01 => Some(controls.children.remove(at)),
        _ => None,
    };
    // The switch takes what the line leaves it, never more than its natural
    // width ([`switch_control_width`]): the gaps and anything else on it come
    // first.
    let others = line_width(controls)
        - controls
            .children
            .iter()
            .filter(|child| matches!(child.content, UiContent::Switch(_)))
            .map(|child| match child.layout.width {
                Length::Fixed(width) => width,
                _ => 0.0,
            })
            .sum::<f32>();
    for control in &mut controls.children {
        if let (UiContent::Switch(_), Length::Fixed(width)) =
            (&control.content, control.layout.width)
        {
            control.layout.width = Length::Fixed(
                width
                    .min(switch_control_width(text_width - others))
                    .max(0.0),
            );
        }
    }
    let Some(reset) = moved else {
        return;
    };
    let label = row.children.remove(0);
    let height = fixed_height(&label);
    let key = label
        .key
        .as_str()
        .trim_start_matches("settings/label/")
        .to_string();
    row.children.insert(
        0,
        UiNode::new(
            format!("settings/label-line/{key}"),
            UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
        )
        .layout(
            Layout::row()
                .width(Length::Fill)
                .height(Length::Fixed(height))
                .gap(6.0),
        )
        .children(vec![label, reset]),
    );
}

/// Whether `key` is a row's Reset, the place it keeps, or Modified's
/// Discard for a draft: the button that ends a row's line.
fn is_reset_place(key: &str) -> bool {
    key.starts_with("settings/reset/")
        || key.starts_with("settings/reset-slot/")
        || key.starts_with("settings/draft-discard/")
}

/// What a one-line row seats beside its control other than its Reset (or
/// the place it keeps), each with the row's gap before it: the Theme row's
/// Browse themes…, a search hit's Choose… for the tab color.
fn one_line_row_extras(row: &UiNode) -> f32 {
    row.children
        .iter()
        .skip(2)
        .filter(|child| !is_reset_place(child.key.as_str()))
        .map(|child| match child.layout.width {
            Length::Fixed(width) => width + row.layout.gap,
            _ => 0.0,
        })
        .sum()
}

/// The room a row's label has on its label line: beside a stacked row's
/// Reset, or the place it keeps, else beside the controls of a one-line row.
fn row_label_room(row: &UiNode, stacked: bool, text_width: f32) -> f32 {
    if stacked {
        row.children
            .first()
            .filter(|line| line.key.as_str().starts_with("settings/label-line/"))
            .map_or(text_width, |line| one_line_label_room(line, text_width))
    } else {
        one_line_label_room(row, text_width)
    }
}

/// A finished setting row, its label and second line not yet laid out: a
/// box first decides where its rows' facts go ([`place_box_facts`]), then
/// lists each whole ([`Self::whole`]) or, where a row and its second line
/// together outgrow a screen, the second line as the stops right after the
/// row ([`Self::split`]). A refused value's reason is the row's own, so every
/// page that lists the row paints it under the row.
struct FinishedRow {
    row: UiNode,
    key: &'static str,
    name: String,
    tags: RowTags,
    /// The tags in the row's fullest state ([`SettingRowParts::worst`]).
    worst: RowTags,
    timing: Option<&'static str>,
    /// The row's own note, inside it under its name.
    note: Option<String>,
    /// A note the row shares with rows above it in its box, which it closes
    /// ([`prefs::RowNote::Shared`]): never inside its lines, but the stops
    /// after it ([`Self::shared_note_stops`]).
    shared_note: Option<String>,
    /// Why the row's last typed value was not saved.
    error: Option<String>,
    label_width: f32,
    stacked: bool,
    text_width: f32,
    /// Whether the row's box puts its facts under every name
    /// ([`place_box_facts`]); `None` for a row listed on its own.
    facts_below: Option<bool>,
    /// The colour of the default Modified names on a colour row: its chip
    /// follows the words that name it ([`Self::placed`]).
    default_chip: Option<[u8; 3]>,
}

impl FinishedRow {
    /// Whether the row's facts fit beside its name in its fullest state.
    fn facts_fit_inline(&self) -> bool {
        row_tag_fit(&self.name, &self.worst, self.label_room()).facts
    }

    /// The room the row's name and tags have on its label line: less a
    /// default's chip, which follows its words there.
    fn label_room(&self) -> f32 {
        self.label_width
            - self.default_chip.map_or(0.0, |_| {
                crate::native_ui::TEXT_FIELD_SWATCH_SIZE + crate::native_ui::TEXT_FIELD_SWATCH_GAP
            })
    }

    /// The row with its label laid out, and its second line's lines: the
    /// tags its label line has no room for and when a saved change takes
    /// effect, reserved to as many lines as the row's fullest state takes,
    /// then its note.
    ///
    /// A default's chip ([`Self::default_chip`]) follows the words naming
    /// it: on the label line while that keeps the default (its last tag),
    /// else after the second line's words that end with it, where nothing
    /// follows them; the third value is those words.
    fn placed(&self) -> (UiNode, Vec<String>, Option<String>) {
        let below = self.facts_below.unwrap_or_else(|| !self.facts_fit_inline());
        let mut row = self.row.clone();
        let placement = lay_out_row_label(
            &mut row,
            &self.name,
            &self.tags,
            &self.worst,
            self.label_room(),
            self.stacked,
            below,
        );
        let mut chip_words = None;
        if let Some(color) = self.default_chip {
            if placement.below.is_empty() {
                set_row_label_chip(&mut row, self.key, color, self.label_width);
            } else if self.timing.is_none() {
                chip_words = placement.below.last().cloned();
            }
        }
        let detail = row_second_line(
            &placement,
            self.timing,
            self.note.as_deref(),
            self.text_width,
        );
        (row, detail, chip_words)
    }

    /// The row with its second line inside it, and its refused value's
    /// reason under it.
    fn whole(&self) -> UiNode {
        let (row, detail, chip_words) = self.placed();
        let mut row = with_row_detail(row, self.key, &detail, self.stacked);
        if let (Some(color), Some(words)) = (self.default_chip, chip_words) {
            set_detail_chip(&mut row, self.key, &words, color, self.text_width);
        }
        self.with_error(row)
    }

    /// The row alone (with its refused value's reason), and its second line
    /// as blocks of their own, each at most `most` tall.
    fn split(&self, most: f32) -> (UiNode, Vec<(UiNode, f32)>) {
        let (row, detail, _) = self.placed();
        let blocks = if detail.is_empty() {
            Vec::new()
        } else {
            row_note_blocks(self.key, &detail, most)
        };
        (self.with_error(row), blocks)
    }

    fn with_error(&self, row: UiNode) -> UiNode {
        match self.error.as_deref() {
            Some(message) => with_row_error(row, self.key, message, self.text_width),
            None => row,
        }
    }

    /// The note the run of rows this row closes shares, as the stops after
    /// it, each at most `most` tall ([`shared_note_blocks`]).
    fn shared_note_stops(&self, most: Option<f32>) -> Vec<(UiNode, f32)> {
        self.shared_note
            .as_deref()
            .map(|note| shared_note_blocks(self.key, note, self.text_width, most))
            .unwrap_or_default()
    }
}

/// The room over a run's shared note, beyond the list's row gap: the note
/// belongs to the run, so it stands apart from the last row's own lines.
const SHARED_NOTE_GAP: f32 = 4.0;

/// A NOTE A RUN OF ROWS SHARES ([`prefs::RowNote::Shared`]) is the run's,
/// not its last row's: the stop after that row, keyed by it
/// (`settings/shared-note/<key>`), in the box footnote's quiet caption, set
/// apart from the row's own lines, never between a stacked row's name and
/// its control. Where it is taller than `most` (large type on a phone) it is
/// that many stops, each at most `most` tall (at least one line), as a row's
/// own second line is ([`row_note_blocks`]). Paint only: each row's control
/// says the note ([`setting_row_parts_with`]'s description).
fn shared_note_blocks(
    key: &str,
    note: &str,
    text_width: f32,
    most: Option<f32>,
) -> Vec<(UiNode, f32)> {
    let line_height = group_footnote_line_height();
    let lines = group_footnote_lines(note, text_width);
    let pitch = line_height + 2.0;
    let per_block = most.map_or(lines.len(), |most| {
        (((most - SHARED_NOTE_GAP + 2.0) / pitch).floor() as usize).max(1)
    });
    lines
        .chunks(per_block.max(1))
        .enumerate()
        .map(|(part, chunk)| {
            let height = SHARED_NOTE_GAP + chunk.len() as f32 * pitch - 2.0;
            let node = UiNode::new(
                if part == 0 {
                    format!("settings/shared-note/{key}")
                } else {
                    format!("settings/shared-note/{key}/part-{part}")
                },
                UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
            )
            .layout(
                Layout::column()
                    .width(Length::Fill)
                    .height(Length::Fixed(height))
                    .padding(Insets {
                        top: SHARED_NOTE_GAP,
                        right: 0.0,
                        bottom: 0.0,
                        left: 0.0,
                    })
                    .gap(2.0),
            )
            .children(
                chunk
                    .iter()
                    .enumerate()
                    .map(|(offset, line)| {
                        UiNode::new(
                            format!(
                                "settings/shared-note/{key}/line-{}",
                                part * per_block + offset
                            ),
                            UiContent::Text(TextSpec {
                                text: line.clone(),
                                role: SemanticRole::Status,
                                style: StyleRef::Quiet,
                            }),
                        )
                        .layout(Layout::default().height(Length::Fixed(line_height)))
                        .paint_only()
                    })
                    .collect(),
            );
            (node, height)
        })
        .collect()
}

/// A BOX LAYS OUT ITS ROWS' FACTS ALIKE: beside every name where every row's
/// facts fit there in its fullest state, else under every name, so two
/// sibling rows with the same kinds of facts never show them in two places.
/// A row without facts takes no part; a lone row decides for itself.
fn place_box_facts(rows: &mut [FinishedRow]) {
    let below = !rows.iter().all(FinishedRow::facts_fit_inline);
    for row in rows {
        row.facts_below = Some(below);
    }
}

/// A BOX'S UNSET FIELDS MARK THEIR DEFAULTS ALIKE. Each field fits its
/// placeholder to its own room ([`fit_row_field_placeholder`]), and one too
/// narrow for its " (default)" paints its default without it; so where any
/// field of the box had to, every field of the box paints its default
/// without the mark, never "Shifting colors (default)" beside a bare
/// "Brighter cursor color" for two settings equally unset. The quiet tint
/// still marks each as unset, and each field's value keeps its whole words.
fn agree_box_default_marks(rows: &mut [FinishedRow]) {
    let dropped = rows
        .iter()
        .any(|row| row_default_marks(&row.row).contains(&false));
    if dropped {
        for row in rows {
            drop_row_default_marks(&mut row.row);
        }
    }
}

/// Whether each unset text field in `node` (one whose value names its
/// default, "… (default)") paints that mark.
fn row_default_marks(node: &UiNode) -> Vec<bool> {
    let mut marks = Vec::new();
    if let UiContent::TextField(field) = &node.content
        && let SemanticValue::Text(value) = &field.value
        && value.ends_with(" (default)")
        && field.spec.input.is_none()
    {
        marks.push(
            field
                .spec
                .placeholder
                .as_deref()
                .is_some_and(|painted| painted.ends_with(" (default)")),
        );
    }
    for child in &node.children {
        marks.extend(row_default_marks(child));
    }
    marks
}

/// Paint every unset text field's default in `node` without its mark.
fn drop_row_default_marks(node: &mut UiNode) {
    if let UiContent::TextField(field) = &mut node.content
        && let Some(painted) = field.spec.placeholder.as_mut()
        && let Some(plain) = painted.strip_suffix(" (default)")
    {
        *painted = plain.to_string();
    }
    for child in &mut node.children {
        drop_row_default_marks(child);
    }
}

/// A row's second line: the tags its label line had no room for, then when
/// a saved change takes effect, as whole facts ([`fact_lines`]), padded to
/// as many lines as the row's fullest state takes, so nothing under them
/// moves when a tag comes or goes; then the row's own note.
fn row_second_line(
    placement: &RowTagPlacement,
    timing: Option<&str>,
    note: Option<&str>,
    text_width: f32,
) -> Vec<String> {
    let (px, _) = crate::native_ui::text_paint_metrics(SemanticRole::Text, StyleRef::Quiet);
    let with_timing = |tags: &[String]| -> Vec<String> {
        tags.iter()
            .cloned()
            .chain(timing.map(str::to_string))
            .collect()
    };
    let mut lines = fact_lines(&with_timing(&placement.below), px, text_width);
    let reserved = fact_lines(&with_timing(&placement.worst_below), px, text_width).len();
    if lines.len() < reserved {
        lines.resize(reserved, String::new());
    }
    if let Some(note) = note {
        lines.extend(wrapped_copy_lines(note, px, text_width));
    }
    lines
}

/// The least a one-line compact row leaves its label: room for a setting's
/// name, its tags moving to the second line where they do not fit.
const COMPACT_INLINE_LABEL_MIN: f32 = 170.0;

/// The least a one-line row leaves the label of a setting named `name`
/// beside everything its line holds: [`COMPACT_INLINE_LABEL_MIN`], or the
/// whole name where that is narrower ("Trail color" beside its field and
/// Choose…). Its tags move to the second line where they do not fit.
fn one_line_name_floor(name: &str) -> f32 {
    COMPACT_INLINE_LABEL_MIN.min(row_label_width(name).ceil())
}

/// [`compact_inline_control_width`] for `field`: a row of segments goes on
/// one line only where the column leaves it what its labels need beside the
/// label (`segment_need`), and stacks under the label where it does not.
fn compact_inline_choice_width(
    field: &EditField,
    segment_need: Option<f32>,
    text_width: f32,
) -> Option<f32> {
    let Some(need) = segment_need else {
        return compact_inline_control_width(&field.kind, text_width);
    };
    let scale = settings_text_scale();
    if large_text_rows_stack() {
        return None;
    }
    let spare = one_line_label_measure(0.0, text_width, true) - COMPACT_INLINE_LABEL_MIN;
    let most = need.max(270.0 * scale.min(1.25));
    (spare >= need).then(|| spare.min(most))
}

/// The width of a setting's control in a one-line compact row, beside its
/// label and the place its Reset keeps, or `None` where the column has no
/// room for that and the row stacks its control under its label. A slider,
/// field or choice gives up some of its regular width before the row stacks
/// (a choice never below the slot its segments are measured against).
fn compact_inline_control_width(kind: &EditKind, text_width: f32) -> Option<f32> {
    let scale = settings_text_scale();
    if large_text_rows_stack() {
        return None;
    }
    let (least, most) = match kind {
        EditKind::Bool => (104.0 * scale.min(1.4), 104.0 * scale.min(1.4)),
        EditKind::Enum { .. } | EditKind::Theme => {
            (COMPACT_INLINE_CHOICE_MIN, 270.0 * scale.min(1.25))
        }
        _ => (200.0, 300.0 * scale.min(1.25)),
    };
    let spare = one_line_label_measure(0.0, text_width, true) - COMPACT_INLINE_LABEL_MIN;
    (spare >= least).then(|| spare.min(most))
}

/// What a one-line row (label leading, then its control, a chooser and its
/// Reset or Reset's place, `gap` apart) leaves its label in `text_width`.
fn one_line_label_room(row: &UiNode, text_width: f32) -> f32 {
    let fixed: f32 = row
        .children
        .iter()
        .skip(1)
        .map(|child| match child.layout.width {
            Length::Fixed(width) => width,
            _ => 0.0,
        })
        .sum();
    (text_width - fixed - row.layout.gap * row.children.len().saturating_sub(1) as f32).max(0.0)
}

/// Why the rows of a box are idle, where every one of them (two or more) is
/// idle for the same reason (Music effects is off, no wallpaper): the box
/// says it once, under its caption, instead of every row repeating it. A box
/// where some rows still work says nothing for the box — each idle row keeps
/// its own tag — so the sentence never seems to claim a working row. The tag
/// the rows leave off, and the box's sentence, which speaks of them all:
/// "Rainbow kitty does not use these.", "These are inactive for now: Music
/// effects is Off."
fn shared_inactive_reason(state: &SettingsViewState, keys: &[&str]) -> Option<(String, String)> {
    if keys.len() < 2 {
        return None;
    }
    let reasons: Vec<Option<(String, String)>> = keys
        .iter()
        .map(|key| {
            setting_effect_projection(
                state,
                None,
                key,
                SettingsAvailability::for_state(state),
                state.presented_motion.get(),
            )
            .notes
            .into_iter()
            .find(|note| note.kind == EffectNoteKind::Inactive)
            .map(|note| {
                let words = note.visual.clone();
                let reason = note
                    .feedback
                    .strip_prefix("Currently inactive: ")
                    .map_or_else(|| words.clone(), str::to_string);
                (words, reason)
            })
        })
        .collect();
    let (words, reason) = reasons.first()?.clone()?;
    reasons
        .iter()
        .all(|other| other.as_ref().is_some_and(|other| other.0 == words))
        .then(|| {
            // A row's own reason speaks of one setting ("… does not use it");
            // the box's speaks of all of them.
            let sentence = match reason.strip_suffix(" does not use it") {
                Some(name) => format!("{name} does not use these."),
                None => format!("These are inactive for now: {reason}."),
            };
            (words, sentence)
        })
}

/// A setting row's tags, as its label line and second line say them: the
/// STATE tag first (Changed), which comes and goes as the row is written,
/// reset or undone, then its FACTS (an override, why it is idle, what Reset
/// returns it to).
#[derive(Clone, Debug, Default, PartialEq, Eq)]
struct RowTags {
    state: Vec<String>,
    facts: Vec<String>,
}

impl RowTags {
    fn iter(&self) -> impl Iterator<Item = &String> {
        self.state.iter().chain(&self.facts)
    }
}

/// Which of a row's tags fit beside its name on its name's last line: its
/// state tags, and its facts after them.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct RowTagFit {
    state: bool,
    facts: bool,
}

/// THE NAME WRAPS, NEVER CUT: a setting's name over as many lines of
/// `label_width` as it takes, as every other line of Settings copy wraps
/// ([`wrapped_copy_node`]), so two settings never read alike for the words a
/// narrow window or large text would cut off. The row's semantic label still
/// says it whole.
fn row_name_lines(name: &str, label_width: f32) -> Vec<String> {
    use crate::tray_raster::{LinesRule, kept_lines};
    // The one measured rule every line of a setting's or a fact's words
    // keeps: whole pieces, as many to a line as its box holds.
    let (px, face) = crate::native_ui::text_paint_metrics(SemanticRole::Text, StyleRef::Primary);
    kept_lines(LinesRule::RowName, face, name, px, label_width, || {
        wrap_to_box(name, label_width, &row_label_width)
    })
}

/// `base` and each of `tags` after it, joined by [`FACT_SEPARATOR`].
fn with_tags<'a>(base: &str, tags: impl IntoIterator<Item = &'a String>) -> String {
    let mut line = base.to_string();
    for tag in tags {
        line.push_str(FACT_SEPARATOR);
        line.push_str(tag);
    }
    line
}

/// Whether `text` fits a row's label line `label_width` wide: the label's
/// own box, no wider, so a line never paints past it.
fn row_label_fits(text: &str, label_width: f32) -> bool {
    // As the painter elides (`elide_text_label`: whole where its width is at
    // most the box's), with no slack of its own: a line a hair over its box
    // painted "Mark t…" where this said it fit (108.004pt of Noto Sans in
    // 108).
    row_label_width(text) <= label_width
}

/// How wide `text` paints on a row's label line.
fn row_label_width(text: &str) -> f32 {
    let (px, face) = crate::native_ui::text_paint_metrics(SemanticRole::Text, StyleRef::Primary);
    crate::tray_raster::ui_text_width_for(face, text, px)
}

/// Which of `worst` (a row's tags in its fullest state) fit beside its name.
fn row_tag_fit(name: &str, worst: &RowTags, label_width: f32) -> RowTagFit {
    let lines = row_name_lines(name, label_width);
    let last = lines.last().map_or(name, String::as_str);
    let state =
        worst.state.is_empty() || row_label_fits(&with_tags(last, &worst.state), label_width);
    let facts = worst.facts.is_empty()
        || (state && row_label_fits(&with_tags(last, worst.iter()), label_width));
    RowTagFit { state, facts }
}

/// Where a row's label puts its tags ([`place_row_tags`]).
#[derive(Clone, Debug, Default, PartialEq, Eq)]
struct RowTagPlacement {
    /// The label's painted lines: the name, wrapped, with the tags that fit
    /// beside it on its last line.
    lines: Vec<String>,
    /// The tags shown now that go to the row's second line.
    below: Vec<String>,
    /// The tags of the row's fullest state that go there: the room its
    /// second line keeps for them.
    worst_below: Vec<String>,
}

/// A ROW'S LAYOUT NEVER DEPENDS ON ITS STATE: where its tags go is decided
/// for its fullest state (`worst`: written, every fact its own value can
/// bring), so writing, typing, Reset or Undo only paints a tag in its place
/// and never adds a line or moves a row (a draft says so in its field).
/// The name wraps to `label_width`; its state tags follow it on its last
/// line where all of them fit there, and its facts after them where those
/// fit too and the box keeps facts beside its names (`facts_below` false).
/// What does not fit goes to the row's second line, whole.
fn place_row_tags(
    name: &str,
    tags: &RowTags,
    worst: &RowTags,
    label_width: f32,
    facts_below: bool,
) -> RowTagPlacement {
    let fit = row_tag_fit(name, worst, label_width);
    let facts_inline = fit.facts && !facts_below;
    let mut lines = row_name_lines(name, label_width);
    let pick = |tags: &RowTags, inline: bool| -> Vec<String> {
        let mut picked = Vec::new();
        if fit.state == inline {
            picked.extend(tags.state.iter().cloned());
        }
        if facts_inline == inline {
            picked.extend(tags.facts.iter().cloned());
        }
        picked
    };
    if let Some(last) = lines.last_mut() {
        *last = with_tags(last, &pick(tags, true));
    }
    RowTagPlacement {
        lines,
        below: pick(tags, false),
        worst_below: pick(worst, false),
    }
}

/// Lay out `row`'s label ([`place_row_tags`]) and paint its lines
/// ([`set_row_label_lines`]); returns where its tags went.
fn lay_out_row_label(
    row: &mut UiNode,
    name: &str,
    tags: &RowTags,
    worst: &RowTags,
    label_width: f32,
    stacked: bool,
    facts_below: bool,
) -> RowTagPlacement {
    let placement = place_row_tags(name, tags, worst, label_width, facts_below);
    set_row_label_lines(row, placement.lines.clone(), stacked);
    placement
}

/// Put a colour chip right after `line`, one line of painted words in
/// `style`, where `room` holds the words and the chip side by side
/// ([`crate::native_ui::COLOR_CHIP_AUDIT`]): the line becomes a row of its
/// words at their own width and the chip, keyed `chip_key`.
fn chip_after_line(
    line: &mut UiNode,
    chip_key: String,
    color: [u8; 3],
    style: StyleRef,
    room: f32,
) {
    let UiContent::Text(text) = &line.content else {
        return;
    };
    let (px, face) = crate::native_ui::text_paint_metrics(SemanticRole::Text, style);
    let chip = crate::native_ui::TEXT_FIELD_SWATCH_SIZE + crate::native_ui::TEXT_FIELD_SWATCH_GAP;
    let words = crate::tray_raster::ui_text_width_for(face, &text.text, px).ceil() + 1.0;
    if words + chip > room + 0.01 {
        return;
    }
    let height = line.layout.height;
    let mut words_node = line.clone();
    words_node.layout.width = Length::Fixed(words);
    *line = UiNode::new(
        format!("{}/row", line.key.as_str()),
        UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
    )
    .layout(Layout::row().width(Length::Fill).height(height))
    .children(vec![
        words_node,
        UiNode::new(
            chip_key,
            UiContent::Custom(AuditedCustomNode {
                audit_id: crate::native_ui::COLOR_CHIP_AUDIT,
                role: SemanticRole::Group,
                label: String::new(),
                value: Some(format!("#{:02X}{:02X}{:02X}", color[0], color[1], color[2])),
                action: None,
                focusable: false,
                focused: false,
                focus_visible: false,
            }),
        )
        .layout(
            Layout::default()
                .width(Length::Fixed(chip))
                .height(Length::Fill),
        )
        .paint_only(),
    ])
    .paint_only();
}

/// Put a colour chip after a setting row's painted label, on its last line
/// (`settings/label/<key>/visual/line-N`), `label_width` its room.
fn set_row_label_chip(row: &mut UiNode, key: &str, color: [u8; 3], label_width: f32) {
    fn find<'a>(node: &'a mut UiNode, key: &str) -> Option<&'a mut UiNode> {
        if node.key.as_str() == key {
            return Some(node);
        }
        node.children.iter_mut().find_map(|child| find(child, key))
    }
    let Some(line) = find(row, &format!("settings/label/{key}/visual"))
        .and_then(|visual| visual.children.last_mut())
    else {
        return;
    };
    chip_after_line(
        line,
        format!("settings/label/{key}/chip"),
        color,
        StyleRef::Primary,
        label_width,
    );
}

/// Put a colour chip right after the second line's words that end with
/// `tag` (Modified's "Default: …" when the row's name could not hold it),
/// where the line has the room.
fn set_detail_chip(row: &mut UiNode, key: &str, tag: &str, color: [u8; 3], text_width: f32) {
    fn find<'a>(node: &'a mut UiNode, key: &str) -> Option<&'a mut UiNode> {
        if node.key.as_str() == key {
            return Some(node);
        }
        node.children.iter_mut().find_map(|child| find(child, key))
    }
    let Some(detail) = find(row, &format!("settings/detail/{key}")) else {
        return;
    };
    let last_word = tag.split_whitespace().last().unwrap_or(tag);
    let Some(line) = detail.children.iter_mut().find(|line| {
        matches!(&line.content, UiContent::Text(text) if text.text.trim_end().ends_with(last_word))
    }) else {
        return;
    };
    chip_after_line(
        line,
        format!("settings/detail/{key}/chip"),
        color,
        StyleRef::Quiet,
        text_width,
    );
}

/// A row label's painted lines (`<label key>/visual/line-N`), paint only,
/// under one paint-only group (`<label key>/visual`). One line fills the
/// label's band and is centred in it, as a label always was; more stack at
/// the second line's line height.
fn row_label_visual(label_key: &str, lines: Vec<String>) -> UiNode {
    let single = lines.len() <= 1;
    let line_height = row_detail_line_height();
    let height = |count: usize| {
        if single {
            Length::Fill
        } else {
            Length::Fixed(count as f32 * line_height)
        }
    };
    let count = lines.len();
    UiNode::new(
        format!("{label_key}/visual"),
        UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
    )
    .layout(Layout::column().width(Length::Fill).height(height(count)))
    .children(
        lines
            .into_iter()
            .enumerate()
            .map(|(index, text)| {
                UiNode::new(
                    format!("{label_key}/visual/line-{index}"),
                    UiContent::Text(TextSpec {
                        text,
                        role: SemanticRole::Text,
                        style: StyleRef::Primary,
                    }),
                )
                .layout(Layout::default().width(Length::Fill).height(height(1)))
                .paint_only()
            })
            .collect(),
    )
    .paint_only()
}

/// Paint `lines` as `row`'s label. A label that takes more lines than its
/// band holds makes the row taller by what it adds — a stacked row's label
/// line, a one-line row as a whole, its controls keeping their own height
/// at its top — and one that fits is centred in its band.
fn set_row_label_lines(row: &mut UiNode, lines: Vec<String>, stacked: bool) {
    let line_height = row_detail_line_height();
    let block = lines.len().max(1) as f32 * line_height;
    let wrapped = row
        .children
        .first()
        .is_some_and(|line| line.key.as_str().starts_with("settings/label-line/"));
    let row_height = fixed_height(row);
    let padding = row.layout.padding.top + row.layout.padding.bottom;
    let Some(label) = (if wrapped {
        row.children
            .first_mut()
            .and_then(|line| line.children.first_mut())
    } else {
        row.children.first_mut()
    }) else {
        return;
    };
    let multi = lines.len() > 1;
    let visual = row_label_visual(label.key.as_str(), lines);
    label.children = vec![visual];
    if !multi {
        return;
    }
    let band = if stacked {
        fixed_height(label)
    } else {
        row_height - padding
    };
    if block <= band {
        label.layout.padding = Insets {
            top: ((band - block) / 2.0).max(0.0),
            ..Insets::default()
        };
        return;
    }
    let grow = block - band;
    if stacked {
        label.layout.height = Length::Fixed(block);
        if wrapped && let Some(line) = row.children.first_mut() {
            line.layout.height = Length::Fixed(block);
            // Reset (or its place) keeps its own height at the line's top.
            for trailing in line.children.iter_mut().skip(1) {
                trailing.layout.height = Length::Fixed(band);
            }
        }
    } else {
        // The controls keep the band they had, at the row's top, beside
        // the label's first line.
        for control in row.children.iter_mut().skip(1) {
            control.layout.height = Length::Fixed(band);
        }
    }
    row.layout.height = Length::Fixed(row_height + grow);
}

/// `row` with `lines` (laid out to the row's text width) under its label,
/// quiet: between the label and the controls of a `stacked` row, else under
/// the whole row. The node's height is fixed.
fn with_row_detail(mut row: UiNode, key: &str, lines: &[String], stacked: bool) -> UiNode {
    if lines.is_empty() {
        return row;
    }
    let lines = lines.to_vec();
    let line_height = row_detail_line_height();
    let detail_height = lines.len() as f32 * line_height;
    let detail_node = UiNode::new(
        format!("settings/detail/{key}"),
        UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
    )
    .layout(
        Layout::column()
            .width(Length::Fill)
            .height(Length::Fixed(detail_height)),
    )
    .children(
        lines
            .into_iter()
            .enumerate()
            .map(|(line, text)| {
                reserved_or_detail_line(
                    format!("settings/detail/{key}/line-{line}"),
                    text,
                    line_height,
                )
            })
            .collect(),
    );
    let row_height = fixed_height(&row);
    if stacked {
        // Under the name, over the control.
        row.children.insert(1, detail_node);
        row.layout.height = Length::Fixed(row_height + detail_height + 4.0);
        return row;
    }
    UiNode::new(
        format!("settings/row-detail/{key}"),
        UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
    )
    .layout(Layout::column().height(Length::Fixed(row_height + detail_height)))
    .children(vec![row, detail_node])
}

/// A row's second line as blocks of their own, for the stops right after
/// its row where the two outgrow a screen together: its quiet `lines`, as
/// many to a block as `most` holds (at least one), so every line can be
/// scrolled into view whole.
fn row_note_blocks(key: &str, lines: &[String], most: f32) -> Vec<(UiNode, f32)> {
    let line_height = row_detail_line_height();
    let per_block = ((most / line_height).floor() as usize).max(1);
    lines
        .chunks(per_block)
        .enumerate()
        .map(|(part, chunk)| {
            let height = chunk.len() as f32 * line_height;
            let node = UiNode::new(
                if part == 0 {
                    format!("settings/note/{key}")
                } else {
                    format!("settings/note/{key}/part-{part}")
                },
                UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
            )
            .layout(
                Layout::column()
                    .width(Length::Fill)
                    .height(Length::Fixed(height)),
            )
            .children(
                chunk
                    .iter()
                    .enumerate()
                    .map(|(offset, text)| {
                        reserved_or_detail_line(
                            format!("settings/note/{key}/line-{}", part * per_block + offset),
                            text.clone(),
                            line_height,
                        )
                    })
                    .collect(),
            );
            (node, height)
        })
        .collect()
}

/// One line of a row's second line, `key`, quiet and paint only; an empty
/// one is the room the row keeps for a tag its fullest state shows there
/// ([`row_second_line`]), and paints nothing.
fn reserved_or_detail_line(key: String, text: String, line_height: f32) -> UiNode {
    let content = if text.is_empty() {
        UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group))
    } else {
        UiContent::Text(TextSpec {
            text,
            role: SemanticRole::Text,
            style: StyleRef::Quiet,
        })
    };
    UiNode::new(key, content)
        .layout(Layout::default().height(Length::Fixed(line_height)))
        .paint_only()
}

/// `facts` laid out as a row's second line in `width`, at the quiet size
/// `px`: as many whole facts to a line as fit, joined by
/// [`FACT_SEPARATOR`], so a fact is never split across lines and no line
/// starts or ends with the separator; only a fact wider than the column
/// wraps, on lines of its own.
fn fact_lines(facts: &[String], px: f32, width: f32) -> Vec<String> {
    // The measure [`wrapped_copy_lines`] wraps to.
    let width = width.max(48.0);
    let fits = |text: &str| {
        crate::tray_raster::ui_text_width_for(crate::widget::TextFace::Ui, text, px) <= width
    };
    let mut lines: Vec<String> = Vec::new();
    // Whether the last line is one whole fact or more, and so takes another.
    let mut open = false;
    for fact in facts.iter().filter(|fact| !fact.trim().is_empty()) {
        if open && let Some(last) = lines.last_mut() {
            let joined = format!("{last}{FACT_SEPARATOR}{fact}");
            if fits(&joined) {
                *last = joined;
                continue;
            }
        }
        let wrapped = wrapped_copy_lines(fact, px, width);
        open = wrapped.len() == 1;
        lines.extend(wrapped);
    }
    lines
}

/// One line of a row's second line.
fn row_detail_line_height() -> f32 {
    18.0_f32.max(16.0 * settings_text_scale())
}

/// `row`, with why its last typed value was not saved under it, wrapped to
/// `text_width`. A screen reader hears the words from the Status over the
/// painted lines, and from the control's own name or description.
fn with_row_error(row: UiNode, key: &str, message: &str, text_width: f32) -> UiNode {
    let (px, _) = crate::native_ui::text_paint_metrics(SemanticRole::Text, StyleRef::Danger);
    let line_height = 18.0_f32.max(16.0 * settings_text_scale());
    let lines = wrapped_copy_lines(message, px, text_width);
    let error_height = lines.len() as f32 * line_height;
    let row_height = fixed_height(&row);
    UiNode::new(
        format!("settings/row-with-error/{key}"),
        UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
    )
    .layout(Layout::column().height(Length::Fixed(row_height + error_height)))
    .children(vec![
        row,
        UiNode::new(
            format!("settings/error/{key}"),
            UiContent::Group(GroupSpec {
                label: Some(message.to_string()),
                role: SemanticRole::Status,
                style: StyleRef::Plain,
            }),
        )
        .layout(Layout::column().height(Length::Fixed(error_height)))
        .children(
            lines
                .into_iter()
                .enumerate()
                .map(|(line, text)| {
                    UiNode::new(
                        format!("settings/error/{key}/line-{line}"),
                        UiContent::Text(TextSpec {
                            text,
                            role: SemanticRole::Text,
                            style: StyleRef::Danger,
                        }),
                    )
                    .layout(Layout::default().height(Length::Fixed(line_height)))
                    .paint_only()
                })
                .collect(),
        ),
    ])
}

/// The DEVELOPER TOOLS card's line height: the MACOS ACCESS card's.
fn devtools_card_line_height() -> f32 {
    24.0_f32.max(20.0 * settings_text_scale())
}

/// The Developer Tools card's heading, as the macOS access card's is set
/// ([`access_card_heading`]), and its height.
fn devtools_card_heading(text_width: f32) -> (UiNode, f32) {
    access_card_heading(
        "settings/macos-access/devtools/heading",
        "DEVELOPER TOOLS",
        text_width,
    )
}

/// The Developer Tools card's one button, set as the block's buttons are
/// ([`macos_access_button_lines`]): its label's width, its words on lines
/// where `text_width` does not hold them on one. Returns it and its height.
fn devtools_open_button(text_width: f32) -> (UiNode, f32) {
    let button = || {
        macos_access_button(
            MACOS_ACCESS_OPEN_DEVTOOLS,
            "Open Developer Tools\u{2026}",
            true,
            false,
        )
    };
    button_line_set(vec![button()], text_width, macos_access_button_lines())
        .pop()
        .and_then(|(mut line, height)| line.pop().map(|button| (button, height)))
        .unwrap_or_else(|| (button(), scaled_control_height()))
}

/// THE CARD'S FLOOR, its least form: the state in a word or two beside the
/// button ([`devtools_floor_state`]) where the row holds both whole, else the
/// state named in its words over the button, each the card's whole column —
/// never the button past the card (a fixed 306pt button in a 118pt card at
/// 2× text in a 22-column window). The group's label carries the whole
/// sentence for assistive technology. Returns the floor and its height, the
/// card's padding not counted.
fn devtools_floor(copy: &DevToolsCardCopy, text_width: f32) -> (UiNode, f32) {
    let (button, button_height) = devtools_open_button(text_width);
    let button_width = match button.layout.width {
        Length::Fixed(width) => width,
        _ => text_width,
    };
    let room = text_width - button_width - 8.0;
    let state = devtools_floor_state(copy.state_short, room);
    let beside = room > 0.0
        && crate::native_ui::fit_native_text_label(&state, room) == state
        && !state.is_empty();
    let group = UiNode::new(
        "settings/macos-access/devtools/actions",
        UiContent::Group(GroupSpec::new(format!("Developer Tools: {}", copy.state))),
    );
    if beside {
        return (
            group
                .layout(
                    Layout::row()
                        .width(Length::Fill)
                        .height(Length::Fixed(button_height))
                        .gap(8.0),
                )
                .children(vec![
                    UiNode::new(
                        "settings/macos-access/devtools/state",
                        UiContent::Text(TextSpec {
                            text: state,
                            role: SemanticRole::Status,
                            style: copy.state_style,
                        }),
                    )
                    .layout(
                        Layout::default()
                            .width(Length::Fill)
                            .height(Length::Fixed(button_height)),
                    ),
                    button,
                ]),
            button_height,
        );
    }
    let (words, words_height) = wrapped_words_node(
        "settings/macos-access/devtools/state",
        &format!("Developer Tools \u{2014} {}", copy.state_short),
        (SemanticRole::Status, copy.state_style),
        text_width,
        devtools_card_line_height(),
    );
    let height = words_height + 8.0 + button_height;
    (
        group
            .layout(
                Layout::column()
                    .width(Length::Fill)
                    .height(Length::Fixed(height))
                    .gap(8.0),
            )
            .children(vec![words, button]),
        height,
    )
}

/// What the Developer Tools card is allowed to be: the column its copy wraps
/// to, and how many visual lines of copy it may draw. The card's sentences are
/// its explanation, so they wrap rather than elide, and the page charges the
/// height they wrap to. The card is held to one screen of the list, less what
/// it keeps in view of the macOS access card under it
/// ([`macos_access_kept_in_view`]), so the first screen shows the card whole
/// and that block beginning: on a short window the card keeps its state line
/// and sheds its other lines by [`devtools_card_priority`], on a tall one it
/// says everything, and with no line to spare at all it is one row (the state
/// beside the button), drawn whatever is left, being the least the card can be.
#[derive(Clone, Copy, Debug, PartialEq)]
struct DevToolsCardFit {
    text_width: f32,
    /// Visual lines of copy under the heading; `0` draws the one-row form.
    line_budget: usize,
}

impl DevToolsCardFit {
    /// The stacked page: the card's column, and what is left of the page's
    /// list's room ([`fields_page_list_room`]: under the heading the page
    /// really pins, and the room kept under the list for a status bar holds no
    /// row) after the gap after the card and what the MACOS ACCESS card keeps
    /// in view ([`macos_access_kept_in_view`]).
    fn stacked(
        state: &SettingsViewState,
        width: SettingsWidth,
        viewport: LogicalRect,
        access: &MacosAccess,
        lead: AccessLead,
    ) -> Self {
        let gap = settings_page_gap(state, width, viewport);
        let text_width = settings_card_text_width(viewport, width);
        Self::within(
            text_width,
            fields_page_list_room(state, width, viewport)
                - gap
                - macos_access_kept_in_view(access, lead, text_width),
        )
    }

    /// The card's own heading, button and padding come out of `height`, and
    /// what is left is counted in whole lines.
    fn within(text_width: f32, height: f32) -> Self {
        let spare = height
            - devtools_card_heading(text_width).1
            - devtools_open_button(text_width).1
            - 2.0 * 12.0;
        Self {
            text_width,
            line_budget: (spare / devtools_card_line_height()).floor().max(0.0) as usize,
        }
    }
}

/// The room the list of a page of settings rows has on its screen: the list's
/// body ([`settings_list_body_height`]) under the heading the page pins
/// ([`pinned_heading`]: its row, or none where the compact toolbar names the
/// page). The page itself seats its list in exactly this
/// ([`settings_fields_page`], with no preview or count over it).
fn fields_page_list_room(
    state: &SettingsViewState,
    width: SettingsWidth,
    viewport: LogicalRect,
) -> f32 {
    let gap = settings_page_gap(state, width, viewport);
    let (_, pinned) = pinned_heading(
        state,
        width,
        viewport,
        gap,
        state.route.label(),
        settings_fields_subtitle(state.route, false, false),
    );
    (settings_list_body_height(state, width, viewport) - pinned).max(0.0)
}

/// THE MACOS ACCESS BLOCK'S VERDICT IS MEASURED AGAINST THE FIRST SCREEN (no
/// window-height cutoff, s-22): the most of it ([`AccessLead`]) that leaves the
/// Security list's first screen holding the DEVELOPER TOOLS card at its least
/// (one row: its state beside its button) and the block down to the end of its
/// actions; where not even the state alone does, the state alone, so *Open
/// Privacy & Security…*, in the first row of buttons, is on that screen
/// wherever the room holds the card's row, the block's heading, its state and
/// one row of buttons ([`macos_access_reach`]).
fn macos_access_lead(
    state: &SettingsViewState,
    width: SettingsWidth,
    viewport: LogicalRect,
    access: &MacosAccess,
) -> AccessLead {
    let gap = settings_page_gap(state, width, viewport);
    let text_width = settings_card_text_width(viewport, width);
    let room = fields_page_list_room(state, width, viewport);
    let devtools_least = devtools_floor(&devtools_card_copy(access), text_width).1 + 2.0 * 12.0;
    AccessLead::ALL
        .into_iter()
        .find(|lead| {
            devtools_least + gap + macos_access_kept_in_view(access, *lead, text_width)
                <= room + 0.01
        })
        .unwrap_or(AccessLead::State)
}

/// Which of the card's lines a short page keeps first, after the state line
/// (which it always keeps): how to add aterm, then the trade the owner makes
/// by doing it, then what the list is not (a person may take it for the
/// "Developer Tools Access" password dialog, so the card says it is not that
/// one before it says more), why aterm asks, where the switch is, which switch
/// matters, the Full Disk Access pointer, the measured cost, the owner's Not
/// now and the last opening. Lower keeps first.
fn devtools_card_priority(key: &str) -> u8 {
    match key {
        "state" => 0,
        "how" => 1,
        "trade" => 2,
        "kind" => 3,
        "why" => 4,
        "route" => 5,
        "only" => 6,
        "unread" => 7,
        "checked" => 8,
        "declined" => 9,
        "opened" => 10,
        _ => 11,
    }
}

/// The card's text in render order: `(key, text, role, style)`. A granted
/// verdict keeps the state line and the trade (what the owner gave, and that
/// it can be taken back); otherwise the whole explanation, the route before
/// the trade whose "there" it is. What of it a short page keeps is the
/// budget's to say ([`DevToolsCardFit`], [`devtools_card_priority`]). The card
/// and its height both read this, so they cannot disagree.
fn devtools_card_lines(
    copy: &DevToolsCardCopy,
) -> Vec<(&'static str, String, SemanticRole, StyleRef)> {
    let mut lines = vec![(
        "state",
        copy.state.clone(),
        SemanticRole::Status,
        copy.state_style,
    )];
    if copy.granted {
        lines.push((
            "trade",
            copy.trade.clone(),
            SemanticRole::Text,
            StyleRef::Quiet,
        ));
        return lines;
    }
    if let Some(unread) = &copy.unread {
        lines.push((
            "unread",
            unread.clone(),
            SemanticRole::Status,
            StyleRef::Primary,
        ));
    }
    lines.push((
        "kind",
        copy.kind.clone(),
        SemanticRole::Text,
        StyleRef::Quiet,
    ));
    lines.push((
        "why",
        copy.why.clone(),
        SemanticRole::Text,
        StyleRef::Primary,
    ));
    if let Some(checked) = &copy.checked {
        lines.push((
            "checked",
            checked.clone(),
            SemanticRole::Status,
            StyleRef::Primary,
        ));
    }
    lines.push((
        "how",
        copy.how.clone(),
        SemanticRole::Text,
        StyleRef::Primary,
    ));
    lines.push((
        "only",
        copy.only.clone(),
        SemanticRole::Text,
        StyleRef::Primary,
    ));
    lines.push((
        "route",
        copy.route.clone(),
        SemanticRole::Text,
        StyleRef::Quiet,
    ));
    lines.push((
        "trade",
        copy.trade.clone(),
        SemanticRole::Text,
        StyleRef::Quiet,
    ));
    if let Some(opened) = &copy.opened {
        lines.push((
            "opened",
            opened.clone(),
            SemanticRole::Status,
            StyleRef::Quiet,
        ));
    }
    if let Some(declined) = &copy.declined {
        lines.push((
            "declined",
            declined.clone(),
            SemanticRole::Status,
            StyleRef::Quiet,
        ));
    }
    lines
}

/// The one-row floor's state words in `room` points: "Developer Tools — off" when
/// that fits whole, else the short words alone, capitalized ("Off"), so the floor
/// never paints a sentence cut short. Pure.
fn devtools_floor_state(short: &str, room: f32) -> String {
    let named = format!("Developer Tools \u{2014} {short}");
    if crate::native_ui::fit_native_text_label(&named, room.max(0.0)) == named {
        return named;
    }
    let mut chars = short.chars();
    chars.next().map_or_else(String::new, |first| {
        first.to_uppercase().chain(chars).collect()
    })
}

/// The state line in the floor's words ([`devtools_floor_state`]), for a card
/// whose budget seats fewer lines than the state sentence wraps to: the
/// sentence's verdict often comes last ("… and did not allow it."), so a sentence
/// cut short can drop exactly the verdict, or read as good news. One line where
/// the column holds them; else they wrap to it, never cut ("Not checked" at 2×
/// text in a 22-column window). The group's label keeps the whole sentence for
/// assistive technology.
fn devtools_state_short_node(
    copy: &DevToolsCardCopy,
    text_width: f32,
    line_height: f32,
) -> (UiNode, f32) {
    let key = "settings/macos-access/devtools/state";
    let (px, face) = crate::native_ui::text_paint_metrics(SemanticRole::Status, copy.state_style);
    let lines = wrap_to_box(
        &devtools_floor_state(copy.state_short, text_width),
        text_width,
        &|line| crate::tray_raster::ui_text_width_for(face, line, px),
    );
    let height = lines.len().max(1) as f32 * line_height;
    (
        UiNode::new(
            key,
            UiContent::Group(GroupSpec {
                label: Some(copy.state.clone()),
                role: SemanticRole::Status,
                style: StyleRef::Plain,
            }),
        )
        .layout(
            Layout::column()
                .width(Length::Fill)
                .height(Length::Fixed(height))
                .gap(0.0),
        )
        .children(
            lines
                .into_iter()
                .enumerate()
                .map(|(index, text)| {
                    UiNode::new(
                        format!("{key}/line-{index}"),
                        UiContent::Text(TextSpec {
                            text,
                            role: SemanticRole::Status,
                            style: copy.state_style,
                        }),
                    )
                    .layout(Layout::default().height(Length::Fixed(line_height)))
                    .paint_only()
                })
                .collect(),
        ),
        height,
    )
}

/// The Developer Tools card, leading the Security page above the macOS access
/// block: whether aterm is on the list, why it asks, how to add it, the trade,
/// when aterm last opened the page, and *Open Developer Tools…*. Its copy wraps
/// to `fit` and keeps what `fit`'s budget seats ([`DevToolsCardFit`]); the node
/// and its exact height come back together, so the page charges the card it
/// paints. Every key under it but its own sits under
/// [`MACOS_ACCESS_GESTURE_PREFIX`], so `act` refuses its button.
fn devtools_card(access: &MacosAccess, fit: DevToolsCardFit) -> (UiNode, f32) {
    let line_height = devtools_card_line_height();
    let copy = devtools_card_copy(access);
    let card = |children: Vec<UiNode>, height: f32| {
        (
            UiNode::new(
                "settings/developer-tools",
                UiContent::Group(GroupSpec::new("Developer Tools").style(StyleRef::Secondary)),
            )
            .layout(
                Layout::column()
                    .height(Length::Fixed(height))
                    .padding(Insets::all(12.0))
                    .gap(0.0)
                    .clipped(),
            )
            .children(children),
            height,
        )
    };
    if fit.line_budget == 0 {
        // The floor: no line to spare under a heading, so the least the card
        // can be ([`devtools_floor`]) — never the sentence cut short.
        let (floor, height) = devtools_floor(&copy, fit.text_width);
        return card(vec![floor], height + 2.0 * 12.0);
    }
    let (open, open_height) = devtools_open_button(fit.text_width);
    let (heading, heading_height) = devtools_card_heading(fit.text_width);
    let mut height = heading_height + open_height + 2.0 * 12.0;
    let mut children = vec![heading];
    // Wrap every line, then keep lines in priority order while the budget
    // seats the next one, and draw them in reading order: a short page shows
    // the state, then how, then the trade… never a later line in place of an
    // earlier one that did not fit. The state line is always kept, and never
    // cut short: whole when the budget seats it, else in the floor's words on
    // one line (`devtools_state_short_node`).
    let mut wrapped = devtools_card_lines(&copy)
        .into_iter()
        .map(|(key, text, role, style)| {
            let (node, lines_height) = wrapped_copy_node(
                &format!("settings/macos-access/devtools/{key}"),
                &text,
                role,
                style,
                fit.text_width,
                line_height,
                None,
            );
            let lines = (lines_height / line_height).round() as usize;
            if key == "state" && lines > fit.line_budget {
                let (node, height) = devtools_state_short_node(&copy, fit.text_width, line_height);
                let lines = (height / line_height).round() as usize;
                return (key, node, height, lines, false);
            }
            (key, node, lines_height, lines, false)
        })
        .collect::<Vec<_>>();
    let mut order = (0..wrapped.len()).collect::<Vec<_>>();
    order.sort_by_key(|&index| devtools_card_priority(wrapped[index].0));
    let mut left = fit.line_budget;
    for index in order {
        let (key, _, _, lines, keep) = &mut wrapped[index];
        if *key != "state" && *lines > left {
            break;
        }
        left = left.saturating_sub(*lines);
        *keep = true;
    }
    for (_, node, lines_height, _, keep) in wrapped {
        if keep {
            height += lines_height;
            children.push(node);
        }
    }
    // The one button, in every form: it only opens System Settings.
    children.push(
        UiNode::new(
            "settings/macos-access/devtools/actions",
            UiContent::Group(GroupSpec::new("Developer Tools actions")),
        )
        .layout(
            Layout::row()
                .width(Length::Fill)
                .height(Length::Fixed(open_height))
                .gap(8.0),
        )
        .children(vec![open]),
    );
    card(children, height)
}

/// The quiet badge on a font row whose aterm.toml value beats the value the
/// saved theme names.
const OVERRIDES_THEME_WORD: &str = "Overrides theme";

/// The quiet Reset after a row's control: it removes the row's key from
/// aterm.toml.
fn setting_reset_button(field: &EditField) -> UiNode {
    setting_reset_button_to(field, None)
}

/// [`setting_reset_button`] for a row whose removal lands on the saved
/// theme's value (`theme`: the value and the theme's label): it reads "Use
/// theme's", and its name says those words and which value it returns to.
fn setting_reset_button_to(field: &EditField, theme: Option<&(String, String)>) -> UiNode {
    let spec = match theme {
        Some((value, label)) => {
            ButtonSpec::new(format!("Use theme's {} ({label}: {value})", field.label))
                .visual_label("Use theme's")
        }
        None => ButtonSpec::new(format!("Reset {}", field.label)).visual_label("Reset"),
    };
    row_trailing_button(
        format!("settings/reset/{}", field.key),
        spec,
        format!("settings/reset/{}", field.key),
    )
}

/// An empty slot of Reset's width after a row's control, for a row without
/// Reset whose neighbours have one: the controls stay in one column. A row
/// that already has Reset, or a slot, is left as it is.
fn reserve_reset_slot(row: &mut UiNode, key: &str) {
    let reset = format!("settings/reset/{key}");
    let slot_key = format!("settings/reset-slot/{key}");
    if ui_node_holds(row, &reset) || ui_node_holds(row, &slot_key) {
        return;
    }
    let slot = UiNode::new(
        slot_key,
        UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
    )
    .layout(
        Layout::default()
            .width(Length::Fixed(72.0 * settings_text_scale().min(1.5)))
            .height(Length::Fill),
    );
    // A stacked row keeps its controls in their own row under the label; a
    // one-line row holds them itself.
    let controls_key = format!("settings/controls/{key}");
    match row
        .children
        .iter_mut()
        .find(|child| child.key.as_str() == controls_key)
    {
        Some(controls) => controls.children.push(slot),
        None => row.children.push(slot),
    }
}

fn row_trailing_button(key: String, spec: ButtonSpec, action: String) -> UiNode {
    UiNode::new(
        key,
        UiContent::Button(
            Control::new(spec, ActionId::new(action))
                .state(ControlState::default())
                .style(StyleRef::Quiet),
        ),
    )
    .layout(
        Layout::default()
            .width(Length::Fixed(reset_slot_width()))
            .height(Length::Fill),
    )
}

/// The place a row keeps for its Reset while it has none: as wide as Reset,
/// painted as nothing, never focused or read out.
fn reset_slot(key: &str) -> UiNode {
    UiNode::new(
        format!("settings/reset-slot/{key}"),
        UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
    )
    .layout(
        Layout::default()
            .width(Length::Fixed(reset_slot_width()))
            .height(Length::Fill),
    )
    .paint_only()
}

/// How wide a row's Reset is, and the place it keeps for one.
fn reset_slot_width() -> f32 {
    72.0 * settings_text_scale().min(1.5)
}

/// What a switch reads with its key absent from aterm.toml. A switch turned
/// to this value removes its key, so "Changed" never lingers on a default.
fn switch_default(key: &str) -> Option<bool> {
    static DEFAULTS: std::sync::OnceLock<Vec<(&'static str, bool)>> = std::sync::OnceLock::new();
    DEFAULTS
        .get_or_init(|| {
            prefs::editable_fields(&crate::app_config::Config::default())
                .into_iter()
                .filter(|field| matches!(field.kind, EditKind::Bool))
                .filter_map(|field| Some((field.key, field.seed?.trim().parse().ok()?)))
                .collect()
        })
        .iter()
        .find(|(candidate, _)| *candidate == key)
        .map(|(_, default)| *default)
}

/// A setting's row: its label, its control, and — on Modified, or wherever
/// its key is written in aterm.toml — a Reset after the control. The Reset's
/// place is kept on every row, so a control never moves or shrinks when its
/// Reset appears. Its visual label is the name and its tags on one line
/// ([`SettingRowParts`]); [`finish_setting_row_sharing`] lays them out for a list.
fn setting_row(
    state: &SettingsViewState,
    index: usize,
    field: &EditField,
    modified_only: bool,
    width: SettingsWidth,
) -> UiNode {
    setting_row_parts(state, index, field, modified_only, width).row
}

/// What form a setting row takes.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum RowForm {
    /// An ordinary list's row: Modified's (`modified_only`: no Changed, the
    /// default it resets to, Reset or Discard on every row) or any other
    /// page's (Changed, and Reset where aterm.toml sets the key). Either way
    /// the row keeps Reset's place, so its control never moves.
    List { modified_only: bool },
    /// Top Settings' DIRECT form: the bare name — no tags, no timing, no
    /// Reset or its place — because Modified owns provenance. Its painted
    /// label and its label's semantics are the one name; the control still
    /// says the setting's facts.
    Direct,
}

/// A setting row and the words its label line holds, kept apart so a list
/// can lay them out: the name, then its short tags (Changed, an unsaved
/// draft, why the row does nothing, the default it resets to), and the
/// plain words for when a saved change takes effect, which always go on the
/// row's second line.
struct SettingRowParts {
    row: UiNode,
    name: String,
    tags: RowTags,
    /// The tags in the row's fullest state, in the same order: Changed (but
    /// on Modified) and every fact its own value can bring. A list lays the
    /// row out for these, so no change to the row moves anything
    /// ([`place_row_tags`]). An unsaved draft is no tag: its field says it
    /// ([`TextFieldSpec::trailing_hint`]).
    worst: RowTags,
    timing: Option<&'static str>,
}

/// The word a changed row's label carries.
const CHANGED_WORD: &str = "Changed";

/// What a field holding an unsaved draft says at its end
/// ([`TextFieldSpec::trailing_hint`]).
const UNSAVED_HINT: &str = "Unsaved";

/// THE VALUE A ROW SHOWS, as its control holds it: the field's value, with
/// the folds a row draws over it — the cursor style and the two keyword toys
/// and Music effects as Serious Mode and the word effects' master leave them
/// (Off while held), except on Modified (`modified_only`), which lists what
/// aterm.toml says. An unset value reads as its default, "(default)" after
/// it. The row, the words a change is named in and `aterm ctl settings`'s
/// answer all read it.
fn row_shown_value(state: &SettingsViewState, field: &EditField, modified_only: bool) -> String {
    if field.key == prefs::EDIT_CURSOR_TRAIL_STYLE {
        if modified_only {
            top_authored_trail_value(state)
        } else {
            // Unset, the row shows the default it draws as every other
            // choice row does ("Block (default)").
            let projected = top_projected_trail_value(state);
            if !state.is_explicit(prefs::EDIT_CURSOR_TRAIL_STYLE)
                && projected.eq_ignore_ascii_case(crate::app_config::default_cursor_trail_style())
            {
                format!("{projected} (default)")
            } else {
                projected
            }
        }
    } else if field.key == SPARKLE_WORDS_KEY || field.key == KEYWORD_KITTIES_KEY {
        if modified_only {
            top_authored_toy_value(state, field.key).to_string()
        } else {
            top_projected_toy_value(state, field.key).to_string()
        }
    } else if field.key == prefs::EDIT_TRAIL_SOUNDS {
        if modified_only {
            top_authored_music_value(state).to_string()
        } else {
            top_projected_music_value(state).to_string()
        }
    } else {
        SettingsState::display_value(field).to_string()
    }
}

/// WHAT A SETTING READS AS NOW, in the words its Settings row's control says
/// and where it comes from: `<words> (default)` where aterm's own default is
/// in force, `<words> (from theme <Name>)` where the theme in use sets it,
/// `<words> (automatic)` where the platform chooses it (the font size). A
/// switch says On or Off; a choice its picker's words, or its segment's
/// where the row draws segments; a slider its readout; a font row the face
/// it draws; a text row the value its empty field stands for, never the
/// input hint after " — ". Words that already name the default ("Default")
/// take no mark. `aterm ctl settings unset` answers it
/// after "now", on the side of a light/dark theme pair `system_dark` shows,
/// naming the automatic font from `font_families` (the list Settings' font
/// pickers were last given) as the font row does. `None` for a key no row
/// edits.
pub(crate) fn effective_value_words(
    snapshot: &crate::native_config_service::ConfigSnapshot,
    key: &str,
    system_dark: bool,
    font_families: Option<Arc<aterm_render::font_catalog::MonospaceFamilies>>,
) -> Option<String> {
    let mut state = SettingsViewState::from_snapshot(snapshot).ok()?;
    if let Some(families) = font_families {
        state.replace_font_families(families);
    }
    state.presented_motion.set(crate::native_app::ViewMotionCx {
        system_dark,
        ..state.presented_motion.get()
    });
    let fields = state.theme_seeded_fields(&snapshot.config, &Arc::clone(&state.assets.themes));
    state.set_fields(fields);
    state.row_value_words(key)
}

impl SettingsViewState {
    /// [`effective_value_words`] for `key` in this view.
    fn row_value_words(&self, key: &str) -> Option<String> {
        let field = self.field_by_key(key)?;
        // A Top effect row Serious Mode or the word effects' master holds Off
        // reads Off, which is not its key's value: the key's own value is
        // said, then what holds the row Off ("On (default); Off while Serious
        // Mode silences sound"), never "Off (default)" for a key whose
        // default is On.
        let held = top_effect_held_off_reason(self, None, key);
        let shown = match held {
            Some(_) if key == prefs::EDIT_CURSOR_TRAIL_STYLE => top_authored_trail_value(self),
            Some(_) => SettingsState::display_value(field).to_string(),
            None => row_shown_value(self, field, false),
        };
        let shown = shown.trim();
        // The value without the note on where it comes from.
        let theme = (!self.is_explicit(key))
            .then(|| self.theme_fallback_for(key))
            .flatten()
            .map(|(_, label)| label);
        let bare = theme
            .as_ref()
            .and_then(|label| shown.strip_suffix(&format!(" (from theme {label})")))
            .or_else(|| shown.strip_suffix(" (default)"))
            .unwrap_or(shown)
            .trim();
        let automatic = bare.ends_with(" (automatic)");
        let bare = bare.strip_suffix(" (automatic)").unwrap_or(bare).trim();
        let words = match field.kind {
            EditKind::Bool => if bare.parse::<bool>().unwrap_or(false) {
                "On"
            } else {
                "Off"
            }
            .to_string(),
            // The face the row names; its theme is said once, below.
            _ if font_picker_key(key) && field.seed.is_none() => {
                let label = font_automatic_label(self, key);
                theme
                    .as_ref()
                    .and_then(|theme| label.strip_suffix(&format!(" (from theme {theme})")))
                    .map_or_else(|| label.clone(), str::to_string)
            }
            EditKind::Enum { .. } => {
                let token = unset_choice_value(field, bare);
                if segmented_choices(field, shown).is_some() {
                    segment_label(key, token)
                } else {
                    setting_choice_label(key, token)
                }
            }
            EditKind::Theme => theme_value_words(&self.assets.themes, field.seed.as_deref()),
            EditKind::Float | EditKind::Integer
                if let Some((numeric, readout)) = numeric_slider_value_for_state(self, field) =>
            {
                slider_readout(key, numeric, readout)
            }
            _ => match field_placeholder(self, field) {
                (_, Some(path)) if field.seed.is_none() => path,
                _ => bare
                    .split_once(" \u{2014} ")
                    .map_or(bare, |(value, _hint)| value)
                    .trim()
                    .to_string(),
            },
        };
        // A key whose unset value has no words of its own (the style kept
        // beside an Off) holds none.
        let words = if words.trim().is_empty() {
            "none".to_string()
        } else {
            words
        };
        // An unset font row that names the face it draws ("Automatic (SF
        // Mono)") already says where its value comes from.
        let sourced = font_picker_key(key) && words.starts_with("Automatic (");
        let value = if self.is_explicit(key) || sourced {
            words
        } else if let Some(label) = theme {
            format!("{words} (from theme {label})")
        } else if automatic {
            format!("{words} (automatic)")
        } else if words.to_ascii_lowercase().ends_with("default") {
            words
        } else {
            format!("{words} (default)")
        };
        Some(match held {
            Some(reason) => format!("{value}; Off while {reason}"),
            None => value,
        })
    }
}

fn setting_row_parts(
    state: &SettingsViewState,
    index: usize,
    field: &EditField,
    modified_only: bool,
    width: SettingsWidth,
) -> SettingRowParts {
    setting_row_parts_in(state, index, field, RowForm::List { modified_only }, width)
}

fn setting_row_parts_in(
    state: &SettingsViewState,
    index: usize,
    field: &EditField,
    form: RowForm,
    width: SettingsWidth,
) -> SettingRowParts {
    let direct = form == RowForm::Direct;
    let modified_only = form
        == RowForm::List {
            modified_only: true,
        };
    let offers_reset = !direct && (modified_only || state.is_explicit(field.key));
    let reserve_reset_slot = !direct;
    let setting_effect = setting_effect_projection(
        state,
        None,
        field.key,
        SettingsAvailability::for_state(state),
        state.presented_motion.get(),
    );
    let value = row_shown_value(state, field, modified_only);
    let first_token_is = |key: &str, word: &str| {
        field.key == key
            && value
                .split_whitespace()
                .next()
                .is_some_and(|token| token.eq_ignore_ascii_case(word))
    };
    // Zero means opposite things on two neighbouring rows; each row's note
    // says which, under the field that shows the 0.
    let unlimited_scrollback = first_token_is(prefs::EDIT_SCROLLBACK, "0");
    let screen_only_search = first_token_is(prefs::EDIT_SEARCH_HISTORY_LINES, "0");
    // `always` is deliberately not offered (it can echo a password); a value
    // written in Manual says so on its row.
    let echo_always = first_token_is(prefs::EDIT_PREDICTIVE_ECHO, "always");
    let retained_input = state.field_inputs.get(field.key);
    let has_draft = retained_input.is_some_and(|input| {
        input.value() != field.seed.as_deref().unwrap_or_default() || input.preedit().is_some()
    });
    let environment_override = state.environment_override(field.key);
    let bounded_numeric_disclosure =
        bounded_numeric_disclosure(state, field, environment_override.is_some());
    // When a save takes effect, in one phrase ([`prefs::ApplicationTiming`]):
    // painted on the row's second line and said in its name, in the same
    // words. A change that applies at once says nothing, and a row that has
    // no effect here takes effect at no time, so it says only that.
    let timing_of = |timing: Option<prefs::ApplicationTiming>| {
        timing
            .filter(|_| !setting_effect.unavailable())
            .map(prefs::ApplicationTiming::words)
    };
    let timing = timing_of(application_timing_in(state, None, field.key));
    // Short facts after the name, in visual and spoken form, and the visual
    // words the row's own value may bring there whether or not it shows them
    // now (its fullest state, [`SettingRowParts::worst`]). The config key is
    // Manual's business, never a control's name or description.
    let mut facts: Vec<(String, String)> = Vec::new();
    let mut own_value_facts: Vec<Option<String>> = Vec::new();
    let mut fact = |visual: String, semantic: String, own: Option<&str>| {
        facts.push((visual, semantic));
        own_value_facts.push(own.map(str::to_string));
    };
    if let Some(disclosure) = bounded_numeric_disclosure.as_ref() {
        fact(disclosure.visual.clone(), disclosure.semantic.clone(), None);
    }
    if let Some(active) = environment_override {
        fact(
            format!("{} active → {}", active.variable, active.effective),
            format!(
                "overridden by {}; effective {}",
                active.variable, active.effective
            ),
            None,
        );
    }
    // A text field's note is paint-only, so its spoken name carries what
    // the 0 means; the note is the one painted statement of it.
    if unlimited_scrollback {
        fact(String::new(), "Unlimited (0)".to_string(), None);
    }
    // An unset size follows the platform; the slider shows that size.
    if field.key == prefs::EDIT_FONT_PX && environment_override.is_none() {
        let (visual, semantic) = if field.seed.is_none() {
            ("Automatic", "automatic")
        } else {
            ("", "")
        };
        fact(visual.to_string(), semantic.to_string(), Some("Automatic"));
    }
    // An unset style row's control names the face its text is drawn from;
    // a synthetic style over that face is a fact after the row's name.
    if !has_draft
        && environment_override.is_none()
        && let Some(modifier) = font_style_modifier(state, field.key)
    {
        fact(modifier.to_string(), modifier.to_lowercase(), None);
    }
    if screen_only_search {
        fact(String::new(), "Screen only (0)".to_string(), None);
    }
    if field.key == prefs::EDIT_PREDICTIVE_ECHO {
        let (visual, semantic) = if echo_always {
            (
                "Can show a password",
                "Always, set in Manual, can show what you type at a password prompt",
            )
        } else {
            ("", "")
        };
        fact(
            visual.to_string(),
            semantic.to_string(),
            Some("Can show a password"),
        );
    }
    for note in &setting_effect.notes {
        fact(note.visual.clone(), note.semantic.clone(), None);
    }
    let facts_after = |timing: Option<&str>| -> String {
        timing
            .into_iter()
            .chain(facts.iter().map(|(_, semantic)| semantic.as_str()))
            .filter(|fact| !fact.is_empty())
            .map(|fact| format!(" · {fact}"))
            .collect()
    };
    let semantic_facts = facts_after(timing);
    let visual_facts: Vec<(String, Option<String>)> = facts
        .iter()
        .map(|(visual, _)| visual.clone())
        .zip(own_value_facts)
        .collect();
    let semantic_field_label = format!("{}{semantic_facts}", field.label);
    let field_error = state.field_errors.get(field.key);
    // A refused draft is never told that Return will save it; a field that
    // takes typing says how to put it right.
    let takes_typing = matches!(
        field.kind,
        EditKind::Text | EditKind::Integer | EditKind::Float | EditKind::Color
    ) && numeric_slider_value(field).is_none();
    let setting_description = field_error
        .map(|error| {
            if takes_typing {
                format!("{error}; correct it and press Return, or use Discard Draft in Modified")
            } else {
                error.clone()
            }
        })
        .into_iter()
        .chain(row_footnote(state, field.key).map(std::borrow::Cow::into_owned))
        .chain((has_draft && field_error.is_none()).then(|| {
            "Unsaved draft; focus and press Return to save, or use Discard Draft in Modified"
                .to_string()
        }))
        .collect::<Vec<_>>()
        .join(FACT_SEPARATOR);
    let editing_input = (state.editing_field.as_deref() == Some(field.key))
        .then_some(retained_input)
        .flatten();
    let action = ActionId::new(format!("settings/set/{}", field.key));
    let focused = state
        .common
        .last_focus
        .as_ref()
        .is_some_and(|key| key.as_str() == format!("settings/control/{}", field.key));
    // A color draft that is not a hex color (nor, for the trail color, the
    // cursor's color by its word) is marked where it is typed.
    let invalid = field.kind == EditKind::Color
        && retained_input.is_some_and(|input| {
            let draft = input.value().trim();
            !draft.is_empty() && !prefs::color_value_is_valid(field.key, draft)
        });
    let control_state = ControlState {
        focused,
        invalid: invalid
            || field_error.is_some()
            || state.font_refusal(field.key).is_some_and(|refusal| {
                refusal.reason == crate::native_font_catalog::FontRefusalReason::NotFound
            }),
        // What it sets does nothing for now — it waits on another setting, or
        // has no effect here: it paints quiet, and still works.
        muted: setting_effect.idle(),
        ..ControlState::default()
    };
    // What a row of segments needs to show every label whole: a one-line
    // row's slot grows to it ([`segmented_choices`]).
    let segment_need =
        segmented_choices(field, &value).map(|(segments, _)| segmented_natural_width(&segments));
    let segmented = segmented_choices(field, &value).map(|(segments, selected)| {
        // Each segment says when choosing it takes effect: Universal
        // Control's Leave as is at once, its Off at the next pass.
        let segment_facts: Vec<String> = segments
            .iter()
            .map(|segment| facts_after(timing_of(segment_timing(state, field.key, &segment.value))))
            .collect();
        segmented_choice_node(
            field,
            &segments,
            selected,
            &value,
            &segment_facts,
            &setting_description,
            control_state,
        )
    });
    // A font row is a list to pick from until "Other…" asks for a name.
    let font_list = font_picker_key(field.key) && !state.font_row_takes_text(field.key);
    // What a choice control says: a theme by the catalog's names (a pair as
    // its two sides), every other choice as its picker row does.
    let choice_words = if field.key == prefs::EDIT_THEME && field.seed.is_some() {
        theme_value_words(&state.assets.themes, Some(&value))
    } else {
        setting_choice_label(field.key, &value)
    };
    let control = match field.kind {
        _ if font_list => {
            let shown = field
                .seed
                .as_deref()
                .map(str::trim)
                .filter(|family| !family.is_empty())
                .map_or_else(|| font_automatic_label(state, field.key), str::to_string);
            UiContent::Button(
                Control::new(
                    ButtonSpec {
                        label: format!("{}: {shown}{semantic_facts}", field.label),
                        visual_label: Some(shown.clone()),
                        visual_icon: None,
                        trailing_icon: Some(ButtonIcon::ChevronDown),
                        description: (!setting_description.is_empty())
                            .then(|| setting_description.clone()),
                        badge: false,
                        swatches: Vec::new(),
                        chip: None,
                        chevron_row: None,
                    },
                    ActionId::new(format!("settings/font-picker/{}", field.key)),
                )
                .value(SemanticValue::Text(shown))
                .state(ControlState {
                    selected: state
                        .choice_picker
                        .as_ref()
                        .is_some_and(|picker| picker.key == field.key),
                    ..control_state
                })
                .style(StyleRef::Setting),
            )
        }
        EditKind::Bool => UiContent::Switch(
            Control::new(
                SwitchSpec {
                    label: semantic_field_label.clone(),
                    description: (!setting_description.is_empty())
                        .then(|| setting_description.clone()),
                },
                action,
            )
            .value(SemanticValue::Bool(value.parse().unwrap_or(false)))
            .state(control_state)
            .style(StyleRef::Setting),
        ),
        EditKind::Enum { .. } | EditKind::Theme => UiContent::Button(
            Control::new(
                ButtonSpec {
                    label: format!("{}: {choice_words}{semantic_facts}", field.label),
                    // A theme pair too long for the control drops its
                    // "follows system" tail on glass; the label says it whole.
                    visual_label: Some(theme_pair_fitted(field.key, &value, &choice_words)),
                    visual_icon: None,
                    // The cursor style's control opens its page; every other
                    // choice opens a picker.
                    trailing_icon: Some(if field.key == prefs::EDIT_CURSOR_TRAIL_STYLE {
                        ButtonIcon::Forward
                    } else {
                        ButtonIcon::ChevronDown
                    }),
                    description: (!setting_description.is_empty())
                        .then(|| setting_description.clone()),
                    badge: false,
                    swatches: Vec::new(),
                    chip: None,
                    chevron_row: None,
                },
                action,
            )
            // The words the control shows, never the config token.
            .value(SemanticValue::Text(choice_words.clone()))
            .state(ControlState {
                selected: state
                    .choice_picker
                    .as_ref()
                    .is_some_and(|picker| picker.key == field.key),
                ..control_state
            })
            .style(StyleRef::Setting),
        ),
        EditKind::Float | EditKind::Integer
            if numeric_slider_value_for_state(state, field).is_some() =>
        {
            let (numeric, display_value) = numeric_slider_value_for_state(state, field)
                .expect("guard checked numeric slider value");
            let range = slider_domain(state, field.key).expect("numeric slider has a range");
            let display_value = slider_readout(field.key, numeric, display_value);
            UiContent::Slider(
                Control::new(
                    SliderSpec {
                        description: (!setting_description.is_empty())
                            .then(|| setting_description.clone()),
                        // The bar draws the useful span; the value's domain
                        // (what its keys and readers reach) is the whole one.
                        track: slider_track(field.key, range, numeric),
                        label: semantic_field_label.clone(),
                        step: range.step,
                        display_value,
                    },
                    action,
                )
                .value(SemanticValue::Number {
                    value: numeric,
                    minimum: range.min,
                    maximum: range.max,
                })
                .state(control_state)
                .style(StyleRef::Setting),
            )
        }
        EditKind::Float | EditKind::Integer | EditKind::Text | EditKind::Color => {
            let field_text = retained_input.map_or_else(
                || field.seed.clone().unwrap_or_default(),
                |input| input.projection().text,
            );
            let semantic_text = if field_text.trim().is_empty() {
                value.clone()
            } else {
                field_text.clone()
            };
            let swatch = matches!(field.kind, EditKind::Color)
                .then(|| {
                    let candidate = if field_text.trim().is_empty() {
                        value.as_str()
                    } else {
                        field_text.as_str()
                    };
                    aterm_types::scheme::parse_hex(candidate)
                        .map(|color| [color.r, color.g, color.b])
                        .or_else(|| {
                            (field_text.trim().is_empty())
                                .then(|| unset_color_swatch(state, field.key))
                                .flatten()
                        })
                })
                .flatten();
            // An unset field says what it stands for; a path's default, by
            // the path (`~/.config/aterm/ai-fleet.toml`), whole in its value.
            let (placeholder, default_path) = field_placeholder(state, field);
            let semantic_text = match default_path {
                Some(path) if field_text.trim().is_empty() => path,
                _ => semantic_text,
            };
            UiContent::TextField(
                Control::new(
                    TextFieldSpec {
                        label: semantic_field_label.clone(),
                        placeholder: Some(placeholder),
                        secret: false,
                        visual_value: Some(field_text),
                        input: editing_input
                            .map(crate::native_text_input::TextInputState::projection),
                        swatch,
                        // The draft is the field's: it says so in the field,
                        // so typing never adds a line to the row.
                        swatch_line: false,
                        trailing_hint: has_draft.then(|| UNSAVED_HINT.to_string()),
                        description: (!setting_description.is_empty())
                            .then(|| setting_description.clone()),
                        end_button: false,
                    },
                    action,
                )
                .value(SemanticValue::Text(semantic_text))
                .state(control_state)
                .style(StyleRef::Setting),
            )
        }
    };
    // Elsewhere a changed row says so; Modified lists only changed rows. The
    // tags follow the name; a list moves those its line has no room for to
    // the row's second line ([`finish_setting_row`]), deciding for the row's
    // fullest state (`worst`), so no change to the row moves anything.
    // A direct row's label is its bare name: its control says the facts.
    let mut tags = RowTags::default();
    let mut worst = RowTags::default();
    if !modified_only && !direct {
        if state.is_explicit(field.key) {
            tags.state.push(CHANGED_WORD.to_string());
        }
        worst.state.push(CHANGED_WORD.to_string());
    }
    // A typography row the config sets while the saved theme names it too:
    // the config wins, and the row says so. Writing the row can bring the
    // tag, so the row keeps its place whether or not it shows.
    let theme_fallback = state.theme_fallback_for(field.key);
    if theme_fallback.is_some() && !direct {
        if state.is_explicit(field.key) {
            tags.state.push(OVERRIDES_THEME_WORD.to_string());
        }
        worst.state.push(OVERRIDES_THEME_WORD.to_string());
    }
    for (fact, own_value) in visual_facts.iter().filter(|_| !direct) {
        if !fact.is_empty() {
            tags.facts.push(fact.clone());
        }
        // A fact the row's own value may bring takes its place whether or
        // not it shows now.
        if let Some(fact) = own_value.as_ref().or((!fact.is_empty()).then_some(fact)) {
            worst.facts.push(fact.clone());
        }
    }
    // Modified says what Reset returns each row to. Last, so a label too long
    // for its row loses the default before it loses why the row is idle.
    if modified_only && let Some(default) = modified_default_words(state, field.key) {
        // The theme's says "Default theme", as a Follow system slot's does:
        // aterm's own theme is named Default, and "Default: Default" reads
        // as if nothing had changed.
        let tag = if field.key == prefs::EDIT_THEME {
            "Default theme"
        } else {
            "Default"
        };
        let default = format!("{tag}: {default}");
        tags.facts.push(default.clone());
        worst.facts.push(default);
    }
    let visual_label = with_tags(field.label, tags.iter());
    let mut label = visual_label.clone();
    // The colour a colour row's default draws, in words, where Modified
    // names the default: the chip after the words is paint only.
    if modified_only && let Some([r, g, b]) = color_picker::default_color_chip(state, field) {
        label.push_str(&format!(", #{r:02X}{g:02X}{b:02X}"));
    }
    if let Some(timing) = timing.filter(|_| !direct) {
        label.push_str(FACT_SEPARATOR);
        label.push_str(timing);
    }
    let label_node = UiNode::new(
        format!("settings/label/{}", field.key),
        UiContent::Group(GroupSpec {
            label: Some(label),
            role: SemanticRole::Text,
            // This wrapper owns the complete, unabridged semantic label; it
            // is not a visual card. The paint-only Text child supplies the
            // visible copy without introducing a panel around every setting.
            style: StyleRef::Plain,
        }),
    )
    .layout(
        Layout::default()
            .width(Length::Fill)
            .height(if width == SettingsWidth::Compact {
                Length::Fixed(22.0_f32.max(20.0 * settings_text_scale()))
            } else {
                Length::Fill
            }),
    )
    .children(vec![row_label_visual(
        &format!("settings/label/{}", field.key),
        vec![visual_label],
    )]);
    let mut control_node = segmented
        .unwrap_or_else(|| UiNode::new(format!("settings/control/{}", field.key), control));
    control_node.layout.width = if width == SettingsWidth::Compact {
        if matches!(field.kind, EditKind::Bool) {
            Length::Fixed(104.0 * settings_text_scale().min(1.4))
        } else {
            Length::Fill
        }
    } else {
        match field.kind {
            EditKind::Bool => Length::Fixed(104.0 * settings_text_scale().min(1.4)),
            EditKind::Enum { .. } | EditKind::Theme => {
                Length::Fixed(regular_choice_control_width().max(segment_need.unwrap_or_default()))
            }
            _ => Length::Fixed(300.0 * settings_text_scale().min(1.25)),
        }
    };
    control_node.layout.height = Length::Fill;
    let mut control_children = vec![control_node];
    let reset = if offers_reset {
        // Modified discards an unsaved draft where the row has one.
        Some(if modified_only && has_draft {
            row_trailing_button(
                format!("settings/draft-discard/{}", field.key),
                ButtonSpec::new("Discard Draft").visual_label("Discard"),
                format!("settings/drafts/discard/{}", field.key),
            )
        } else {
            setting_reset_button_to(field, theme_fallback.as_ref())
        })
    } else if reserve_reset_slot {
        // The Reset's place, kept while the row has none, so the control
        // stays where it is when a change brings Reset up.
        Some(reset_slot(field.key))
    } else {
        None
    };
    let label_node = match reset {
        // A stacked row's Reset (or its place) ends its label line, so the
        // control under it keeps the whole width and never shrinks — but a
        // switch's, which follows the switch on its own line, where the row
        // has room to spare, so the name has the whole width to itself.
        Some(reset) if width == SettingsWidth::Compact && !matches!(field.kind, EditKind::Bool) => {
            let height = 22.0_f32.max(20.0 * settings_text_scale());
            UiNode::new(
                format!("settings/label-line/{}", field.key),
                UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
            )
            .layout(
                Layout::row()
                    .width(Length::Fill)
                    .height(Length::Fixed(height))
                    .gap(6.0),
            )
            .children(vec![label_node, reset])
        }
        Some(reset) => {
            control_children.push(reset);
            label_node
        }
        None => label_node,
    };
    if width == SettingsWidth::Compact && matches!(field.kind, EditKind::Bool) {
        // A fill spacer keeps the compact switch at the trailing edge while
        // the switch itself remains a recognizable 104px control instead of
        // stretching into a full-width bar. The row's 46px control band is
        // also the complete hit target.
        control_children.insert(
            0,
            UiNode::new(
                format!("settings/control-spacer/{}", field.key),
                UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
            )
            .layout(Layout::default().width(Length::Fill).height(Length::Fill)),
        );
    }
    let (layout, children) = if width == SettingsWidth::Compact {
        let controls = UiNode::new(
            format!("settings/controls/{}", field.key),
            UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
        )
        .layout(
            Layout::row()
                .width(Length::Fill)
                .height(Length::Fill)
                .gap(STACKED_CONTROL_GAP),
        )
        .children(control_children);
        (
            Layout::column()
                .height(Length::Fixed(width.row_height()))
                .gap(4.0),
            vec![label_node, controls],
        )
    } else {
        let mut children = vec![label_node];
        children.extend(control_children);
        (
            Layout::row()
                .height(Length::Fixed(width.row_height()))
                .padding(Insets::symmetric(0.0, 4.0))
                .gap(12.0),
            children,
        )
    };
    SettingRowParts {
        row: UiNode::new(
            format!("settings/row/{index}/{}", field.key),
            UiContent::Group(GroupSpec::new(field.label)),
        )
        .layout(layout)
        .children(children),
        name: field.label.to_string(),
        tags,
        worst,
        timing,
    }
}

/// The words an unset text field shows, and, where they are a path, that
/// path whole for its accessible value. The fleet document's default is the
/// file `ai-fleet.toml` beside aterm.toml: by its path where Settings knows
/// where aterm.toml is (the field fits a path keeping its file's name,
/// [`crate::native_ui::path_forms`]), else in those words. It used to say
/// "ai-fleet.toml beside aterm.toml" in every field, which a narrow field
/// could only cut to "ai-fleet.toml…".
fn field_placeholder(state: &SettingsViewState, field: &EditField) -> (String, Option<String>) {
    if field.key == prefs::EDIT_AI_FLEET
        && let Some((path, shown)) = state.config_file.as_ref()
        && let Some(dir) = path.parent()
    {
        // aterm.toml's folder as Settings shows it, its own separator kept
        // (`C:\…\aterm\` on Windows).
        let folder = &shown[..crate::native_ui::path_name_start(shown)];
        let painted = format!("{folder}{}", aterm_agent::ai::config::FLEET_FILE);
        let spoken = dir
            .join(aterm_agent::ai::config::FLEET_FILE)
            .display()
            .to_string();
        return (painted, Some(spoken));
    }
    (field.placeholder.clone(), None)
}

/// A ROW'S BUTTON KEEPS ITS WORDS ON EVERY FORM OF THE ROW: a stacked
/// row's button is fitted to its column ([`fit_row_choice_label`]); a
/// one-line row's (a choice, a font, the wallpaper Modified names) first
/// takes from the name's column the width its whole words need, down to
/// the name's floor ([`one_line_name_floor`], the name wrapping), then
/// runs the same ladder ([`choice_words`]) in the width it has — its words
/// on lines where one line cannot hold them, the row as much taller. Only
/// a stacked row was fitted: a one-line font row at 2× text kept its fixed
/// 375pt control and the painter elided "Automatic (SF Mono Light Italic)"
/// to "Automatic (SF Mono Light…" — the word the row exists to state cut —
/// beside a name column with room to spare, at every window width. A row
/// that grows taller than a short list's screen stacks after all
/// ([`finished_setting_row`]), where its column holds the words on a line.
fn fit_row_button_words(row: &mut UiNode, name: &str, text_width: f32, stacked: bool) {
    if stacked {
        fit_row_choice_label(row, text_width);
        return;
    }
    let spare = (one_line_label_room(row, text_width) - one_line_name_floor(name)).max(0.0);
    let band = fixed_height(row) - row.layout.padding.top - row.layout.padding.bottom;
    let Some(control) = row
        .children
        .get_mut(1)
        .filter(|node| node.key.as_str().starts_with("settings/control/"))
    else {
        return;
    };
    let Length::Fixed(current) = control.layout.width else {
        return;
    };
    let UiContent::Button(button) = &mut control.content else {
        return;
    };
    let complete = button
        .spec
        .visual_label
        .clone()
        .unwrap_or_else(|| button.spec.label.clone());
    // The button's own edges: its lead, its arrow, what its end wears.
    let edges = current - crate::native_ui::text_button_label_room(&button.spec, current);
    let need = crate::native_ui::native_button_label_width(&complete) + edges;
    let width = current + (need - current).clamp(0.0, spare);
    let lines = choice_words(&mut button.spec, &complete, width);
    control.layout.width = Length::Fixed(width);
    let grow = crate::native_ui::native_button_height_for_lines(lines, band) - band;
    if grow > 0.01 {
        grow_row(row, grow);
    }
}

/// Fit a stacked row's choice button label to the row's `max_width` while
/// its semantic label and value stay complete. Doing this before compilation
/// distinguishes deliberate responsive copy from an accidental painter
/// overflow in the exhaustive Settings audit.
fn fit_row_choice_label(row: &mut UiNode, max_width: f32) {
    let Some(controls) = row.children.get_mut(1) else {
        return;
    };
    // Fixed-width siblings (the Theme row's Browse arrow) share the line.
    let siblings: f32 = controls
        .children
        .iter()
        .filter(|node| !node.key.as_str().starts_with("settings/control/"))
        .map(|node| match node.layout.width {
            Length::Fixed(width) => width + 6.0,
            _ => 0.0,
        })
        .sum();
    let max_width = max_width - siblings;
    let Some(control) = controls
        .children
        .iter_mut()
        .find(|node| node.key.as_str().starts_with("settings/control/"))
    else {
        return;
    };
    let UiContent::Button(button) = &mut control.content else {
        return;
    };
    let complete = button
        .spec
        .visual_label
        .clone()
        .unwrap_or_else(|| button.spec.label.clone());
    let lines = choice_words(&mut button.spec, &complete, max_width);
    let single = scaled_control_height();
    let grow = crate::native_ui::native_button_height_for_lines(lines, single) - single;
    if grow > 0.0 {
        grow_row(row, grow);
    }
}

/// THE CHOICE KEEPS ITS WORDS — one measured ladder for a button that shows
/// a choice (`complete`, its words), in the room the painter fits a button
/// `max_width` wide to (its lead, its trailing arrow and whatever its end
/// wears — a colour chip, a badge): the whole choice; else the choice
/// without its "(default)", which the row's absent Reset says; else, the
/// arrow given up (the button still opens what it opens), each of those
/// again; else, where the button wears the colour it names, that colour
/// alone, its chip; else the choice's words on as many lines as the button
/// needs, whole, the arrow kept where they are whole beside it and given up
/// where only that keeps them whole ([`whole_button_words_in`]); and only
/// where a word is wider than the whole button, broken with a hyphen in it,
/// the arrow given up ([`button_words_in`]) — never cut. A stacked colour row
/// at 22 columns painted "Automatic (default)" as "Auto…" beside room for
/// "Automatic"; AI CLIs' "Claude (default)" read "Claude (…" at 2×, a font
/// row "Automatic (S…" at 22 columns and the theme "Def…"; and Home's "More
/// styles…" broke "styl-" / "es…" beside an arrow whose room held it whole.
/// The semantic label and value remain complete. Sets the painted words on
/// `spec` and returns how many lines they take.
fn choice_words(spec: &mut ButtonSpec, complete: &str, max_width: f32) -> usize {
    let fits = |spec: &ButtonSpec, words: &str| {
        crate::native_ui::native_button_label_width(words)
            <= crate::native_ui::text_button_label_room(spec, max_width)
                + crate::native_ui::TEXT_FIT_SLACK
    };
    let bare = complete
        .strip_suffix(" (default)")
        .filter(|bare| !bare.is_empty())
        .map(str::to_string);
    // A value that names a thing and then its facts ("sunset-over-the-
    // bay.png · 1074 × 686") gives up the facts before the name.
    let named = bare
        .as_deref()
        .unwrap_or(complete)
        .split_once(FACT_SEPARATOR)
        .map(|(name, _)| name.to_string())
        .filter(|name| !name.is_empty());
    let forms: Vec<String> = std::iter::once(complete.to_string())
        .chain(bare)
        .chain(named)
        .collect();
    if let Some(words) = forms.iter().find(|words| fits(spec, words)) {
        spec.visual_label = Some(words.clone());
        return 1;
    }
    if spec.trailing_icon.is_some() {
        let mut bare_spec = spec.clone();
        bare_spec.trailing_icon = None;
        if let Some(words) = forms.iter().find(|words| fits(&bare_spec, words)) {
            spec.trailing_icon = None;
            spec.visual_label = Some(words.clone());
            return 1;
        }
    }
    if spec.chip.is_some() {
        spec.visual_label = Some(String::new());
        return 1;
    }
    let short = forms[1..].iter().map(String::as_str).collect::<Vec<_>>();
    if let Some((words, lines)) = whole_button_words_in(spec, complete, &short, max_width) {
        spec.visual_label = Some(words);
        return lines;
    }
    spec.trailing_icon = None;
    let (words, lines) = button_words_in(spec, complete, &short, max_width);
    spec.visual_label = Some(words);
    lines
}

/// `row` (a setting's row, its control line under or beside its name) taller
/// by `grow`: its control line takes it, as the row's other lines keep their
/// heights.
fn grow_row(row: &mut UiNode, grow: f32) {
    if let Length::Fixed(height) = row.layout.height {
        row.layout.height = Length::Fixed(height + grow);
    }
    if let Some(controls) = row.children.get_mut(1)
        && let Length::Fixed(height) = controls.layout.height
    {
        controls.layout.height = Length::Fixed(height + grow);
    }
}

/// A row's text field shows its placeholder fitted to the width the row
/// gives the field ([`field_placeholder_lines`]): its width on a one-line
/// row (grown toward its unset words), else (a stacked row's control line)
/// the column less the fixed controls beside it. At every width and text
/// size every word whole, on one line ("Automatic (default)" reads
/// "Automatic") or on lines of the field, the row as much taller in every
/// state; the semantic value keeps the whole words.
fn fit_row_field_placeholder(
    row: &mut UiNode,
    (name, text_width, stacked): (&str, f32, bool),
    unset: Option<(&str, bool)>,
    held: Option<&str>,
) {
    // A ONE-LINE ROW'S FIELD TAKES THE WIDTH ITS UNSET WORDS NEED from the
    // name's column, down to the name's floor ([`one_line_name_floor`]), as a
    // row's button does ([`fit_row_button_words`]): measured on the words
    // the field shows unset (`unset`), so a value written or typed into it
    // never moves it.
    if !stacked && let Some((unset, chip)) = unset {
        let spare = (one_line_label_room(row, text_width) - one_line_name_floor(name)).max(0.0);
        if let Some(control) = row
            .children
            .get_mut(1)
            .filter(|node| node.key.as_str().starts_with("settings/control/"))
            && let Length::Fixed(current) = control.layout.width
            && matches!(control.content, UiContent::TextField(_))
        {
            let need = crate::native_ui::text_field_width_for(
                &crate::native_ui::plain_placeholder(unset),
                chip,
            );
            control.layout.width = Length::Fixed(current + (need - current).clamp(0.0, spare));
        }
    }
    // How many more lines than one the field keeps for its words.
    fn fit(
        node: &mut UiNode,
        room: f32,
        unset: Option<(&str, bool)>,
        held: Option<&str>,
    ) -> Option<usize> {
        let siblings: f32 = node
            .children
            .iter()
            .filter(|child| !child.key.as_str().starts_with("settings/control/"))
            .map(|child| match child.layout.width {
                Length::Fixed(width) => width + node.layout.gap,
                _ => 0.0,
            })
            .sum();
        for child in &mut node.children {
            if child.key.as_str().starts_with("settings/control/")
                && let UiContent::TextField(field) = &mut child.content
            {
                let width = match child.layout.width {
                    Length::Fixed(width) => width,
                    _ => room - siblings,
                };
                // A chip on a line of its own takes none of the words' width,
                // and a line of the field's height.
                let chip_line = field.spec.swatch_line;
                let swatch = field.spec.swatch.is_some() && !chip_line;
                let empty = field
                    .spec
                    .visual_value
                    .as_deref()
                    .unwrap_or_default()
                    .is_empty()
                    && field
                        .spec
                        .input
                        .as_ref()
                        .is_none_or(|input| input.text.is_empty());
                let placeholder = field.spec.placeholder.clone();
                let painted = placeholder
                    .as_deref()
                    .map(|placeholder| field_placeholder_lines(placeholder, width, swatch));
                // The lines the field keeps whatever it holds: those its
                // unset words take — beside a colour field's chip and
                // without it, which a written colour brings and an unset one
                // may not — so writing, clearing or typing into it never
                // makes its row taller or shorter.
                let kept = unset
                    .map(|(unset, chip)| {
                        [false, chip && !chip_line]
                            .into_iter()
                            .map(|swatch| field_placeholder_lines(unset, width, swatch).1)
                            .max()
                            .unwrap_or(1)
                    })
                    .unwrap_or(1);
                // A VALUE IS WHOLE TOO: the value the key holds keeps the
                // lines it takes whatever the field shows (typing into it
                // never makes the row taller or shorter), and a value shown
                // while the field is not being edited — the saved one, or a
                // draft waiting — is set on the lines it takes
                // ([`field_value_lines`]). Cut on one line, a shell named
                // "nushell-nightly-build" read "nushel…" at 2× text in a
                // 22-column window.
                let words_room = crate::native_ui::text_field_words_room(field, width);
                let kept = held
                    .filter(|held| !held.is_empty())
                    .map_or(kept, |held| kept.max(field_value_lines(held, words_room).1));
                let mut lines = kept;
                if let (Some((words, count)), Some(slot)) =
                    (painted, field.spec.placeholder.as_mut())
                {
                    if empty {
                        lines = lines.max(count);
                    }
                    *slot = words;
                }
                if field.spec.input.is_none()
                    && let Some(value) = field
                        .spec
                        .visual_value
                        .as_mut()
                        .filter(|value| !value.is_empty())
                {
                    let (shown, count) = field_value_lines(value, words_room);
                    lines = lines.max(count);
                    *value = shown;
                }
                return Some(lines.saturating_sub(1) + usize::from(chip_line));
            }
            if let Some(extra) = fit(child, room, unset, held) {
                return Some(extra);
            }
        }
        None
    }
    if let Some(extra) = fit(row, text_width, unset, held).filter(|extra| *extra > 0) {
        grow_row(
            row,
            extra as f32 * crate::native_ui::native_button_line_height(),
        );
    }
}

/// `placeholder` as a text field `width` wide (with or without its colour
/// `swatch`) paints it, and how many lines that takes:
///
/// NO WORD IS DROPPED WHERE THE ROW CAN GROW: one line only where it holds
/// the words whole — all of them, or without the " (default)" the quiet
/// tint says, or without the aside they end in. Else the plain words go on
/// lines of the field, a word wider than it broken with a hyphen
/// ([`wrap_to_box`]), as many as a screen of the list holds the field on
/// ([`word_placeholder_lines`]). A one-line form of the leading words with
/// "…" after them passed as whole: "Theme default" read "Theme…" at 1×
/// text in a 22-column window, "platform default" "platform…" at 2× in 30
/// columns, and "Brighter pale blue" "Brighter" / "pale…".
fn field_placeholder_lines(placeholder: &str, width: f32, swatch: bool) -> (String, usize) {
    let fitted = crate::native_ui::fit_native_field_placeholder(placeholder, width, swatch);
    let plain = crate::native_ui::plain_placeholder(placeholder);
    // A path's ellipsis stands for whole folders
    // ([`crate::native_ui::path_forms`]); only its file's name cut inside
    // itself is a cut.
    let path = crate::native_ui::reads_as_path(placeholder);
    let drops_words = if path {
        fitted.ends_with('\u{2026}')
    } else {
        fitted != placeholder
            && fitted != plain
            && placeholder.strip_suffix(" (default)") != Some(fitted.as_str())
    };
    if !drops_words {
        return (fitted, 1);
    }
    let px = crate::native_ui::native_type_px(crate::type_scale::TypeStep::Secondary).get();
    let room = crate::native_ui::field_placeholder_room(width, swatch);
    let measure = |line: &str| crate::tray_raster::ui_text_width(line, px);
    // A COLOUR FIELD WHOSE WORDS ARE NOT WHOLE BESIDE ITS CHIP, not one of
    // them on a line of its own, shows its colour alone, as a button that
    // wears the colour it names does ([`choice_words`]): the chip is what
    // the row is about, and the row's absent Reset says the colour is the
    // default. Its words went on lines beside the chip and a word wider than
    // what the chip left was broken and cut: "Theme default" painted "The-"
    // / "me…" at 2× text in a 22-column window. The field's value still
    // says the words.
    let words_beside_chip = plain
        .split_whitespace()
        .all(|word| measure(word) <= room + crate::native_ui::TEXT_FIT_SLACK);
    if swatch && !path && !words_beside_chip {
        return (String::new(), 1);
    }
    let lines = if path {
        path_placeholder_lines(placeholder, room, &measure)
    } else {
        word_placeholder_lines(&plain, room, &measure, field_lines_most())
    };
    let count = lines.len().max(1);
    (lines.join("\n"), count)
}

/// A FIELD'S VALUE AS IT SHOWS WHILE IT IS NOT BEING EDITED, in a box
/// `room` wide ([`crate::native_ui::text_field_words_room`]), and how many
/// lines that takes: whole on one line where it fits; else on lines of the
/// field — a path the longest of its forms two lines hold, its file's name
/// whole ([`path_placeholder_lines`]); any other value broken between its
/// words, a word wider than the box broken where the shared rule breaks it
/// ([`wrap_to_box`]), as many lines as a screen of the list holds the field
/// on ([`word_placeholder_lines`]). The field paints the lines as they are
/// ([`crate::native_ui::TextFieldSpec::visual_value`]); its semantic value
/// keeps the value.
fn field_value_lines(value: &str, room: f32) -> (String, usize) {
    let px = crate::native_ui::native_type_px(crate::type_scale::TypeStep::Secondary).get();
    let measure = |line: &str| crate::tray_raster::ui_text_width(line, px);
    // A value that holds its own line breaks is on its lines already.
    if value.contains('\n') {
        return (value.to_string(), value.split('\n').count());
    }
    if measure(value) <= room + crate::native_ui::TEXT_FIT_SLACK {
        return (value.to_string(), 1);
    }
    let lines = if crate::native_ui::reads_as_path(value) {
        path_placeholder_lines(value, room, &measure)
    } else {
        word_placeholder_lines(value, room, &measure, field_lines_most())
    };
    let count = lines.len().max(1);
    (lines.join("\n"), count)
}

/// The words `field`'s text field shows while the key is unset — with its
/// "(default)" — whatever it holds now: what it shows where it is unset,
/// else the words its default reads as ([`modified_default_words`]) as the
/// field would set them ([`field_placeholder`]). `None` where they are not
/// known.
fn unset_field_words(state: &SettingsViewState, field: &EditField) -> Option<String> {
    if field.seed.is_none() {
        return Some(field_placeholder(state, field).0);
    }
    let words = modified_default_words(state, field.key)?;
    let placeholder = if words.contains("(default)") {
        words
    } else {
        format!("{words} (default)")
    };
    let unset = EditField {
        label: field.label,
        key: field.key,
        kind: field.kind,
        seed: None,
        placeholder,
    };
    Some(field_placeholder(state, &unset).0)
}

/// A PATH PLACEHOLDER ON LINES KEEPS ITS FIELD A FIELD: the longest of its
/// forms two lines of `room` hold — the whole path, then whole folders
/// either side of "…" ([`crate::native_ui::path_forms`]) — broken at its
/// folders ([`wrap_to_box`]); else "…" and its file's name, on the lines
/// that takes. Its every folder on lines made the fleet document's field
/// 691pt tall in a 268pt list at 2× text in a 22-column window, whole on no
/// screen, for a config folder with a long path. The field's value still
/// says the whole path.
fn path_placeholder_lines(path: &str, room: f32, measure: &dyn Fn(&str) -> f32) -> Vec<String> {
    let start = crate::native_ui::path_name_start(path);
    let tail = format!(
        "{}{}",
        crate::native_ui::TEXT_FIELD_ELLIPSIS,
        &path[start.saturating_sub(1)..]
    );
    std::iter::once(path.to_string())
        .chain(
            crate::native_ui::path_forms(path)
                .into_iter()
                .map(|(form, _, _)| form),
        )
        .map(|form| wrap_to_box(&form, room, measure))
        .find(|lines| lines.len() <= 2)
        .unwrap_or_else(|| wrap_to_box(&tail, room, measure))
}

/// WORDS ON LINES, EVERY ONE OF THEM, WHILE THE FIELD STAYS A FIELD: the
/// words whole on the lines `room` gives them where no more than `most`
/// hold them — the lines a screen of the page's list holds the field on
/// ([`field_lines_most`]) — else the most leading whole words `most` lines
/// hold with "…" saying more follows. Capped at two or three lines
/// whatever the room, "Brighter pale blue" read "Brighter" / "pale…" in a
/// list with room for every word; the cap was for the fleet document's
/// "ai-fleet.toml beside aterm.toml", which at 2× text in a 22-column
/// window took more lines than a screen holds. The field's semantic value
/// keeps every word.
fn word_placeholder_lines(
    plain: &str,
    room: f32,
    measure: &dyn Fn(&str) -> f32,
    most: usize,
) -> Vec<String> {
    let most = most.max(1);
    let whole = wrap_to_box(plain, room, measure);
    if whole.len() <= most {
        return whole;
    }
    let words: Vec<&str> = plain.split_whitespace().collect();
    (1..words.len())
        .rev()
        .find_map(|n| {
            let lines = wrap_to_box(
                &format!(
                    "{}{}",
                    words[..n].join(" "),
                    crate::native_ui::TEXT_FIELD_ELLIPSIS
                ),
                room,
                measure,
            );
            (lines.len() <= most).then_some(lines)
        })
        .unwrap_or(whole)
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct BoundedNumericDisclosure {
    semantic: String,
    visual: String,
}

/// Project a bounded authored numeric onto the runtime-admitted slider domain.
///
/// The configured token remains untouched in `EditField::seed`, Modified, and
/// Manual. An off-step but in-range token is also left byte-for-byte intact:
/// step is an interaction increment, not a second validity constraint. Legacy
/// finite values outside the runtime range still get the native slider rather
/// than silently degrading to an unbounded text box. Its thumb shows the value
/// the runtime will use, while [`bounded_numeric_disclosure`] names both facts.
fn numeric_slider_value(field: &EditField) -> Option<(f64, String)> {
    let range = prefs::range_of(field.key)?;
    let raw = SettingsState::display_value(field);
    let token = raw.split_whitespace().next().unwrap_or(raw);
    let configured = token.parse::<f64>().ok()?;
    if !configured.is_finite() {
        let (effective, _) = bounded_numeric_nonfinite_effective(field.key)?;
        return Some((effective, compact_f64(effective)));
    }
    if (range.min..=range.max).contains(&configured) {
        // The number as aterm spells one (`prefs::written_number`): a
        // placeholder's "1.0" and a saved "1" read the same.
        return Some((configured, compact_f64(configured)));
    }

    // Font size is the one bounded numeric whose resolver rejects a bad config
    // source and falls through to FONT_PX; every other range mirrors a clamp in
    // its shipping consumer (the additional top-padding pair cap is disclosed
    // independently by `constrained_window_top_padding`).
    let effective = if field.key == prefs::EDIT_FONT_PX {
        f64::from(crate::FONT_PX)
    } else {
        configured.clamp(range.min, range.max)
    };
    Some((effective, compact_f64(effective)))
}

/// Effective value of a valid-TOML non-finite authored float. These are the
/// shipping resolvers' actual fail-safe outcomes, not the ordinary finite
/// range clamp. Every bounded native `EditKind::Float` is exhaustively pinned
/// by `bounded_native_float_non_finite_values_keep_sliders_and_disclose`.
fn bounded_numeric_nonfinite_effective(key: &str) -> Option<(f64, &'static str)> {
    Some(match key {
        prefs::EDIT_FONT_PX => (f64::from(crate::FONT_PX), "default"),
        prefs::EDIT_LINE_HEIGHT => (
            f32_as_shown(crate::app_config::DEFAULT_LINE_HEIGHT),
            "default",
        ),
        prefs::EDIT_FONT_SIZE_SCALE => (1.0, "default"),
        prefs::EDIT_MINIMUM_CONTRAST => (1.0, "default"),
        prefs::EDIT_FAINT_OPACITY => (f64::from(aterm_types::DIM_FACTOR), "default"),
        prefs::EDIT_STEM_GAMMA => (1.0, "identity default"),
        prefs::EDIT_CURSOR_TRAIL_INTENSITY
        | prefs::EDIT_CURSOR_TRAIL_RADIUS
        | prefs::EDIT_CURSOR_TRAIL_BLOOM_STRENGTH
        | prefs::EDIT_CURSOR_GLOW_SDR_BOOST
        | prefs::EDIT_FONT_WEIGHT_DARK_NUDGE
        | "sparkle_words.profanity.intensity"
        | "sparkle_words.feline.intensity"
        | "sparkle_words.ink.strength" => (0.0, "off"),
        // The default-style value; the state-aware callers substitute the
        // selected style's own (`preview_bloom_radius_style_default`).
        prefs::EDIT_CURSOR_TRAIL_BLOOM_RADIUS => (
            f32_as_shown(Config::CURSOR_TRAIL_BLOOM_RADIUS_DEFAULT),
            "style default",
        ),
        prefs::EDIT_TRAIL_SOUND_VOLUME => (0.0, "muted"),
        prefs::EDIT_BACKGROUND_OPACITY => (1.0, "solid default"),
        // `wallpaper_dim_or_default`: a non-finite dim reads the 0.3 default.
        prefs::EDIT_WALLPAPER_DIM => (0.3, "default"),
        prefs::EDIT_WINDOW_PADDING => (f64::from(crate::PAD_LOGICAL_PX), "default"),
        prefs::EDIT_WINDOW_PADDING_TOP => (f64::from(crate::PAD_TOP_LOGICAL_PX), "default"),
        _ => return None,
    })
}

/// An `f32` constant as its shortest decimal (`1.8`, not `1.7999999523…`).
fn f32_as_shown(value: f32) -> f64 {
    value.to_string().parse().unwrap_or(f64::from(value))
}

/// The unset bloom radius for the trail style Settings currently shows.
fn preview_bloom_radius_style_default(state: &SettingsViewState) -> f32 {
    let style = field_text(
        state,
        prefs::EDIT_CURSOR_TRAIL_STYLE,
        crate::app_config::default_cursor_trail_style(),
    );
    Config::bloom_radius_style_default(crate::app_config::resolve_trail_style(&style))
}

fn numeric_slider_value_for_state(
    state: &SettingsViewState,
    field: &EditField,
) -> Option<(f64, String)> {
    let projected = numeric_slider_value(field)?;
    // A finite configured value is its own slider value; an unset or
    // non-finite one shows what the runtime uses, so the row stays a slider
    // whether or not it was ever set.
    let configured = field
        .seed
        .as_deref()
        .and_then(|seed| seed.parse::<f64>().ok());
    if field.key == prefs::EDIT_CURSOR_TRAIL_BLOOM_RADIUS {
        if configured.is_some_and(f64::is_finite) {
            return Some(projected);
        }
        // Unset or not a number: the saved style's own default.
        let effective = f32_as_shown(preview_bloom_radius_style_default(state));
        return Some((effective, compact_f64(effective)));
    }
    if field.key != prefs::EDIT_WINDOW_PADDING_TOP {
        return Some(projected);
    }
    // The top's slider ends at the sides' value, and its thumb sits at the
    // top the window draws, also for a hand-written one above that.
    let base = f64::from(window_padding_sides(state));
    let effective = configured
        .filter(|value| value.is_finite())
        .unwrap_or(f64::from(crate::PAD_TOP_LOGICAL_PX))
        .min(base);
    Some((effective, compact_f64(effective)))
}

fn bounded_numeric_disclosure(
    state: &SettingsViewState,
    field: &EditField,
    environment_override: bool,
) -> Option<BoundedNumericDisclosure> {
    let range = prefs::range_of(field.key)?;
    let raw = field.seed.as_deref()?;
    let token = raw.split_whitespace().next().unwrap_or(raw);
    let configured = token.parse::<f64>().ok()?;
    if !configured.is_finite() {
        let (mut effective, outcome) = bounded_numeric_nonfinite_effective(field.key)?;
        if field.key == prefs::EDIT_WINDOW_PADDING_TOP
            || field.key == prefs::EDIT_CURSOR_TRAIL_BLOOM_RADIUS
        {
            effective = numeric_slider_value_for_state(state, field)?.0;
        }
        let effective = compact_f64(effective);
        let qualifier = if environment_override {
            "; a higher-priority environment value remains active"
        } else {
            ""
        };
        return Some(BoundedNumericDisclosure {
            semantic: format!(
                "configured {token} is non-finite; runtime uses {effective} ({outcome}){qualifier}"
            ),
            visual: format!("Configured {token} → Effective {effective} ({outcome})"),
        });
    }
    if (range.min..=range.max).contains(&configured) {
        return None;
    }

    // Every number read as the row's slider reads it, with its unit.
    let read = |value: f64| slider_readout(field.key, value, compact_f64(value));
    let configured = read(configured);
    let bounds = format!("{}–{}", read(range.min), read(range.max));
    if field.key == prefs::EDIT_FONT_PX {
        let fallback = read(f64::from(crate::FONT_PX));
        let qualifier = if environment_override {
            "; a higher-priority environment value remains active"
        } else {
            ""
        };
        return Some(BoundedNumericDisclosure {
            semantic: format!(
                "configured {configured} is outside {bounds} and is ignored; config resolution falls through to the {fallback} default{qualifier}"
            ),
            visual: format!("Configured {configured} → Default {fallback}"),
        });
    }

    let effective = read(
        token
            .parse::<f64>()
            .expect("finite numeric token was parsed above")
            .clamp(range.min, range.max),
    );
    let runtime = if environment_override {
        "the config source clamps"
    } else {
        "runtime clamps"
    };
    Some(BoundedNumericDisclosure {
        semantic: format!(
            "configured {configured}; {runtime} it to {effective} (allowed {bounds})"
        ),
        visual: format!("Configured {configured} → Effective {effective}"),
    })
}

/// A numeric row's value as its slider shows it — and the status line, Undo
/// and Reset with it: with its unit ([`prefs::numeric_reading`]), a 0–1
/// fraction as a whole percent, anything else as `shown`. The stored value
/// stays the number.
fn slider_readout(key: &str, numeric: f64, shown: String) -> String {
    prefs::numeric_reading(key, numeric, &shown).unwrap_or(shown)
}

/// THE VALUES A NUMERIC ROW MAY HOLD, the one domain its keys, its drag,
/// automation and a screen reader all reach: its registered range, the top
/// padding capped at the sides' (the window ignores a top past them).
fn slider_domain(state: &SettingsViewState, key: &str) -> Option<prefs::Range> {
    let range = prefs::range_of(key)?;
    if key == prefs::EDIT_WINDOW_PADDING_TOP {
        return Some(prefs::Range {
            max: f64::from(window_padding_sides(state)).max(range.min),
            ..range
        });
    }
    Some(range)
}

/// THE TRACK a numeric row's slider draws, where it is not its whole domain
/// ([`crate::native_ui::SliderSpec::track`]): Font size draws the sizes
/// people read at, 8–36 px, widened to hold a size set beyond them and never
/// past its domain, while its keys and its readers reach every size the
/// terminal takes. `None`: the track is the domain.
fn slider_track(key: &str, domain: prefs::Range, value: f64) -> Option<(f64, f64)> {
    if key != prefs::EDIT_FONT_PX {
        return None;
    }
    let value = if value.is_finite() {
        value
    } else {
        f64::from(crate::FONT_PX)
    };
    Some((
        FONT_SIZE_SLIDER_SPAN.0.min(value.floor()).max(domain.min),
        FONT_SIZE_SLIDER_SPAN.1.max(value.ceil()).min(domain.max),
    ))
}

/// [`slider_track`]'s font sizes, in pixels.
const FONT_SIZE_SLIDER_SPAN: (f64, f64) = (8.0, 36.0);

fn bounded_numeric_submission_error(field: &EditField, raw: Option<&str>) -> Option<String> {
    let range = prefs::range_of(field.key)?;
    let raw = raw?.trim();
    if raw.is_empty() {
        return None;
    }
    // Read as the slider reads them, with their unit; the refused value as
    // typed, since it was not taken.
    let read = |value: f64| slider_readout(field.key, value, compact_f64(value));
    let (min, max) = (read(range.min), read(range.max));
    let Some(value) = raw.parse::<f64>().ok().filter(|value| value.is_finite()) else {
        return Some(format!(
            "{} must be a number from {min} to {max}; {raw:?} was not saved",
            field.label
        ));
    };
    (!(range.min..=range.max).contains(&value)).then(|| {
        format!(
            "{} must be between {min} and {max}; {} was not saved",
            field.label,
            read(value)
        )
    })
}

/// A typed top above the sides is refused like any value out of range: the
/// window would draw it at the sides' value.
fn window_top_submission_error(
    view: &SettingsViewState,
    field: &EditField,
    raw: Option<&str>,
) -> Option<String> {
    if field.key != prefs::EDIT_WINDOW_PADDING_TOP {
        return None;
    }
    let value = raw?.trim().parse::<f32>().ok()?;
    let sides = window_padding_sides(view);
    let read = |px: f32| slider_readout(field.key, f64::from(px), compact_number(px));
    (value > sides + f32::EPSILON).then(|| {
        format!(
            "{} can't be more than Sides and bottom ({}); {} was not saved",
            field.label,
            read(sides),
            read(value)
        )
    })
}

/// A color row's draft that is not a hex color stays in its field with this
/// reason, as a rejected number does, instead of reaching the config file.
fn color_submission_error(field: &EditField, raw: Option<&str>) -> Option<String> {
    let raw = raw?.trim();
    (field.kind == EditKind::Color
        && !raw.is_empty()
        && !prefs::color_value_is_valid(field.key, raw))
    .then(|| {
        let takes = if field.key == prefs::EDIT_CURSOR_TRAIL_COLOR {
            format!(
                "a hex color like #D0D0D0, or {} for the cursor's color",
                prefs::TRAIL_COLOR_CURSOR
            )
        } else {
            "a hex color like #D0D0D0".to_string()
        };
        format!("{} needs {takes}; {raw:?} was not saved", field.label)
    })
}

/// Why `raw` cannot be saved to `field`, in its row's words and never its
/// config key; `None` when it can. A refused value writes nothing, and its
/// text stays in the field to correct.
fn submission_error(field: &EditField, raw: Option<&str>) -> Option<String> {
    if let Some(message) =
        bounded_numeric_submission_error(field, raw).or_else(|| color_submission_error(field, raw))
    {
        return Some(message);
    }
    let raw = raw?.trim();
    if raw.is_empty() {
        return None;
    }
    let error = prefs::check_edit_value(field.key, raw).err()?;
    let label = field.label;
    Some(match (field.kind, error) {
        // The writer's own words for what it takes, so the row and
        // `settings set` agree.
        (EditKind::Integer, _) => format!(
            "{label} must be {}; {raw:?} was not saved",
            prefs::integer_requirement(field.key, raw)
        ),
        (EditKind::Float, prefs::PrefsEditError::OutOfRange { range, .. }) => {
            let range = range.replace("..=", " to ");
            format!("{label} must be from {range}; {raw:?} was not saved")
        }
        (EditKind::Float, _) => format!("{label} must be a number; {raw:?} was not saved"),
        (EditKind::Color, _) => {
            format!("{label} must be a color such as #1e1e2e; {raw:?} was not saved")
        }
        _ => format!("{label} can't be {raw:?}; it was not saved"),
    })
}

fn compact_f64(value: f64) -> String {
    if value.fract().abs() <= f64::EPSILON {
        format!("{value:.0}")
    } else {
        value.to_string()
    }
}

/// The edits a slider's new value makes: its own key (removed at its default
/// when it is written, [`SettingsApp::submit_config`], as a switch turned to
/// its default is, so "Changed" and Modified mean "differs from the default";
/// every slider write goes through here: a drag, a click, an arrow key, a
/// typed value) and the top padding that follows the sides down
/// ([`window_top_follows_sides`]).
fn slider_edits(view: &SettingsViewState, key: &str, value: String) -> Vec<ConfigEdit> {
    let value = Some(value);
    let mut edits = vec![ConfigEdit {
        key: key.to_string(),
        expected: ExpectedConfigValue::Exact(view.raw_value(key)),
        value: value.clone(),
    }];
    edits.extend(window_top_follows_sides(view, key, value.as_deref()));
    edits
}

fn normalize_slider_value(value: f64, range: prefs::Range) -> Option<String> {
    if !value.is_finite() || !range.step.is_finite() || range.step <= 0.0 {
        return None;
    }
    Some(compact_f64(crate::native_ui::snap_slider_value(
        value, range.min, range.max, range.step,
    )))
}

fn about_page(
    state: &SettingsViewState,
    messages: &MessagesState,
    width: SettingsWidth,
    viewport: LogicalRect,
) -> Vec<UiNode> {
    let (viewport_width, viewport_height) = (viewport.width, viewport.height);
    let about = &state.about;
    let text_scale = settings_text_scale();
    let viewport = LogicalRect::new(0.0, 0.0, viewport_width, viewport_height);
    let gap = settings_page_gap(state, width, viewport);
    let (heading, heading_height) = pinned_heading(state, width, viewport, gap, "About", "");
    // The room the page's list has under its heading: every section is
    // authored to fit it whole.
    let room = (settings_list_body_height(state, width, viewport) - heading_height)
        .max(scaled_control_height());
    let value = |wanted: &str, fallback: &str| {
        about
            .semantic_rows()
            .iter()
            .find(|(key, _)| *key == wanted)
            .map_or_else(|| fallback.to_string(), |(_, value)| value.clone())
    };
    // EVERY WORDING IN THE HERO IS CHOSEN BY MEASURING THE COLUMN IT IS PAINTED
    // IN (s-3): the hero's column is About's page content at its own maximum,
    // less the hero's padding pair; the short hero's text column is that less
    // the wordmark beside it and their gap. A width-class guess (a narrow
    // large-type window) used to drop the tagline, start the byline at the
    // author and shorten the buttons and the card's heading where all of them
    // fit, and keep them where they did not.
    let content =
        settings_page_content_width(viewport_width, width, PageLayout::Form.maximum(width));
    let hero_inner = (content - 48.0).max(0.0);
    // The short hero's wordmark at its own measure, in the face it paints in.
    let short_wordmark_width = {
        let (px, face) = crate::native_ui::wordmark_typography("aterm", f32::INFINITY);
        (crate::tray_raster::ui_text_width_for(face, "aterm", px.get()) + 8.0).ceil()
    };
    // The two buttons at their own widths, side by side where the hero holds
    // both, else one under the other; never a full-width bar. Each paints its
    // words by the one rule every page button keeps ([`button_words`]): its
    // whole label where it is one line of the hero's column, else its short
    // form, else its words on as many lines as the column needs — never cut
    // ("Cop…" and "Ope…" at 2× text on a phone-width page). A short form's
    // words are in the button's name (label in name): "Copy Build" is in "Copy
    // Build Information"; "Open Site" is not in "Open Project Site", so a
    // short site button is named by its painted words.
    let (copy_visual, copy_lines) =
        button_words("Copy Build Information", &["Copy Build"], hero_inner);
    let (site_visual, site_lines) = button_words("Open Project Site", &["Open Site"], hero_inner);
    let site_label = if painted_words(&site_visual) == "Open Site" {
        "Open Site"
    } else {
        "Open Project Site"
    };
    let button_width = |visual: &str, lines: usize| {
        if lines > 1 {
            hero_inner
        } else {
            page_button_width(visual, hero_inner)
        }
    };
    let copy_width = button_width(&copy_visual, copy_lines);
    let site_width = button_width(&site_visual, site_lines);
    let actions_in_row =
        copy_lines == 1 && site_lines == 1 && copy_width + 8.0 + site_width <= hero_inner;
    let row_actions_height = 40.0_f32.max(32.0 * text_scale);
    let copy_height =
        crate::native_ui::native_button_height_for_lines(copy_lines, scaled_control_height());
    let site_height =
        crate::native_ui::native_button_height_for_lines(site_lines, scaled_control_height());
    let compact_actions_height = if actions_in_row {
        row_actions_height
    } else {
        copy_height + site_height + 8.0
    };
    let hero_actions = UiNode::new(
        "about/actions",
        UiContent::Group(GroupSpec::new("About actions")),
    )
    .layout(if actions_in_row {
        Layout::row()
            .height(Length::Fixed(row_actions_height))
            .gap(8.0)
    } else {
        Layout::column()
            .height(Length::Fixed(compact_actions_height))
            .gap(8.0)
    })
    .children(vec![
        UiNode::new(
            "about/copy-build-info",
            UiContent::Button(
                Control::new(
                    ButtonSpec::new("Copy Build Information").visual_label(copy_visual),
                    ActionId::new("about/copy-build-info"),
                )
                .style(StyleRef::Primary),
            ),
        )
        .layout(Layout::default().width(Length::Fixed(copy_width)).height(
            if actions_in_row {
                Length::Fill
            } else {
                Length::Fixed(copy_height)
            },
        )),
        UiNode::new(
            "about/open-site",
            UiContent::Button(
                Control::new(
                    ButtonSpec::new(site_label).visual_label(site_visual),
                    ActionId::new("about/open-site"),
                )
                .state(ControlState {
                    enabled: crate::about::site_url(about).is_some(),
                    ..ControlState::default()
                })
                .style(StyleRef::Secondary),
            ),
        )
        .layout(Layout::default().width(Length::Fixed(site_width)).height(
            if actions_in_row {
                Length::Fill
            } else {
                Length::Fixed(site_height)
            },
        )),
    ]);
    // THE WORDMARK IS WHOLE AT EVERY SIZE: in the hero's type, made smaller
    // where the hero's column cannot hold it ([`native_ui::wordmark_typography`]),
    // its line as much shorter.
    let wordmark_base_height = 38.0_f32.max(30.0 * text_scale);
    let wordmark_fit = {
        let natural = crate::native_ui::wordmark_typography("aterm", f32::INFINITY).0;
        crate::native_ui::wordmark_typography("aterm", hero_inner)
            .0
            .get()
            / natural.get()
    };
    let wordmark_height = (wordmark_base_height * wordmark_fit).ceil();
    let status_height = 20.0_f32.max(18.0 * text_scale);
    let capability_height = 22.0_f32.max(18.0 * text_scale);
    let wordmark = UiNode::new(
        "about/wordmark",
        UiContent::Custom(AuditedCustomNode {
            audit_id: crate::native_ui::WORDMARK_AUDIT,
            role: SemanticRole::Heading,
            label: "aterm".to_string(),
            value: None,
            action: None,
            focusable: false,
            focused: false,
            focus_visible: false,
        }),
    )
    .layout(Layout::default().height(Length::Fixed(wordmark_height)));
    // One sentence at every width: the build info's `tagline` row, the words
    // Copy Build Information copies. It WRAPS to its column at whole words
    // rather than being dropped or cut; only a column too narrow for one of its
    // words (where the wrapper would break inside the word) paints none, and
    // the Build Information card then lists it.
    let tagline_text = value("tagline", crate::build_info::TAGLINE);
    let tagline_in = |column: f32| {
        let (px, _) = crate::native_ui::text_paint_metrics(SemanticRole::Text, StyleRef::Plain);
        tagline_text
            .split_whitespace()
            .all(|word| crate::tray_raster::ui_text_width(word, px) <= column)
            .then(|| {
                wrapped_copy_node(
                    "about/tagline",
                    &tagline_text,
                    SemanticRole::Text,
                    StyleRef::Plain,
                    column,
                    26.0_f32.max(20.0 * text_scale),
                    None,
                )
            })
    };
    // The version alone (the build number is a build-information row),
    // wrapped to its column where one line cannot hold it, never cut.
    let version_text = format!("Version {}", value("version", "development"));
    let version_in = |column: f32| {
        wrapped_words_node(
            "about/version-summary",
            &version_text,
            (SemanticRole::Status, StyleRef::Quiet),
            column,
            status_height,
        )
    };
    // The byline says WHO and WHERE FROM: author · company · site
    // (`alab.systems`, the `site` row — owner, 2026-09-14) wherever that whole
    // line fits, then author · company, then the author, then the author's short
    // form. Fit is MEASURED, never guessed from the width class: the line paints
    // at the Body step (13pt × text scale) in the UI face, in the column the
    // renderer really gives it — the full hero's, or the short hero's beside the
    // wordmark (`text_column`). A 286.5pt phone column at 1× is 206.5pt against
    // the full line's ~223pt, which is exactly where the site used to clip.
    //
    // EVERY RUNG IS MEASURED, THE LAST ONE INCLUDED, AND A LINE THAT DOES NOT
    // FIT IS NOT PAINTED (owner's decision, 2026-09-17). A ladder whose floor is
    // asserted rather than measured is not a ladder: `Andrew Yates` is 164.6pt
    // at 2× against the 164.0pt column a 240pt host gives, so the floor rung
    // itself painted `Andrew Yat…`. The other half of the same defect was the
    // column: it used to be clamped UP to 48pt so the arithmetic could not go
    // degenerate, and a clamp is a guess — at a 100pt host the real box is 24pt
    // while the clamp claimed 48, so every rung "fit" a column that was not
    // there. A zero-width column is a true answer, and when no rung fits one the
    // hero authors no byline at all: an elided name is a worse attribution than
    // none, and none loses a fact: whatever the painted line does not name
    // (`author`, `company`, `site`) is a row of the Build Information card.
    let site = value("site", "");
    let byline_in = |column: f32| {
        let px = 13.0 * text_scale;
        let fits = |line: &str| crate::tray_raster::ui_text_width(line, px) <= column;
        let author_company = crate::build_info::AUTHOR_COMPANY_BYLINE;
        // A build with no `site` row authors no full rung, rather than a line
        // ending in a dangling separator.
        let full = (!site.is_empty()).then(|| format!("{author_company} \u{00b7} {site}"));
        let ladder = [
            full.as_deref().unwrap_or_default(),
            author_company,
            aterm_types::identity::AUTHOR,
            crate::build_info::AUTHOR_SHORT,
        ];
        ladder
            .iter()
            .position(|form| !form.is_empty() && fits(form))
            .map(|rung| (rung, ladder[rung].to_string()))
    };
    let hero_vertical_padding = if width == SettingsWidth::Compact {
        12.0
    } else {
        20.0
    };
    // THE SHORT HERO IS MEASURED, not taken below a fixed height: the full hero
    // — the wordmark over the purpose, the version and the byline, its buttons
    // inside it — wherever it fits the list's room whole; else, on a compact
    // page, the short hero, one row (the wordmark beside the rest), which saves
    // the height of the lines it sets beside the wordmark — wherever the column
    // beside the wordmark holds the version whole. A phone at the largest text
    // has no such column, and keeps the full hero, its buttons the stop after
    // it.
    let full_hero_height = {
        let tagline = tagline_in(hero_inner).map_or(0.0, |(_, height)| height);
        let byline = byline_in(hero_inner).map_or(0.0, |_| capability_height);
        let children = 2 + usize::from(tagline > 0.0) + usize::from(byline > 0.0);
        wordmark_height
            + tagline
            + version_in(hero_inner).1
            + byline
            + hero_vertical_padding * 2.0
            + (children - 1) as f32 * 6.0
            + 6.0
            + compact_actions_height
    };
    let short_column = (content - 24.0 - short_wordmark_width - 8.0).max(0.0);
    let version_fits_short = {
        let (px, face) =
            crate::native_ui::text_paint_metrics(SemanticRole::Status, StyleRef::Quiet);
        crate::tray_raster::ui_text_width_for(
            face,
            &format!("Version {}", value("version", "development")),
            px,
        ) <= short_column
    };
    // The short hero's row, wordmark beside its words, is one stop the
    // list cannot cut between them: it is taken only where it fits the room
    // whole. Taller (its words beside the wordmark on five lines at 2× text
    // in a 102x12 window, 126pt in a 100pt list), it was cut on every
    // screen; the full hero is listed a row at a time and split where it
    // outgrows the room ([`scroll::SplitCard`]).
    let short_fits = {
        let tagline = tagline_in(short_column).map_or(0.0, |(_, height)| height);
        let byline = byline_in(short_column).map_or(0.0, |_| capability_height);
        let lines = usize::from(tagline > 0.0) + 1 + usize::from(byline > 0.0);
        let words =
            tagline + version_in(short_column).1 + byline + lines.saturating_sub(1) as f32 * 4.0;
        wordmark_base_height.max(words) + hero_vertical_padding * 2.0 <= room + 0.01
    };
    let short_compact = width == SettingsWidth::Compact
        && full_hero_height > room + 0.01
        && version_fits_short
        && short_fits;
    let text_column = if short_compact {
        short_column
    } else {
        hero_inner
    };
    let (version_summary, status_height) = version_in(text_column);
    let tagline = tagline_in(text_column);
    let tagline_height = tagline.as_ref().map_or(0.0, |(_, height)| *height);
    let tagline = tagline.map(|(node, _)| node);
    let byline = byline_in(text_column);
    // The provenance facts the painted byline names, which the card then does
    // not repeat: rung 0 names the author, the company and the site, rung 1 the
    // author and the company, rungs 2 and 3 the author.
    let byline_names: &[&str] = match byline.as_ref().map(|(rung, _)| *rung) {
        Some(0) => &["author", "company", "site"],
        Some(1) => &["author", "company"],
        Some(_) => &["author"],
        None => &[],
    };
    let byline = byline.map(|(_, text)| text);
    let capability_height = if byline.is_some() {
        capability_height
    } else {
        0.0
    };
    // Quiet text: it names, it does not link (Open Project Site is the link).
    let capabilities = byline.map(|text| {
        UiNode::new(
            "about/byline",
            UiContent::Text(TextSpec {
                text,
                role: SemanticRole::Text,
                style: StyleRef::Quiet,
            }),
        )
        .layout(Layout::default().height(Length::Fixed(capability_height)))
    });
    // A short window's hero is one row: the wordmark beside the purpose, the
    // exact version and the byline — the attribution is painted wherever a rung
    // of it fits the column beside the wordmark, as in the full hero.
    let (mut hero_children, identity_height) = if short_compact {
        // Beside the words, at its own measure: whole at the hero's size.
        let wordmark_height = wordmark_base_height;
        let mut wordmark = wordmark;
        wordmark.layout.width = Length::Fixed(short_wordmark_width);
        wordmark.layout.height = Length::Fixed(wordmark_height);
        let lines = usize::from(tagline.is_some()) + 1 + usize::from(capabilities.is_some());
        let detail_height = tagline_height
            + status_height
            + capability_height
            + lines.saturating_sub(1) as f32 * 4.0;
        let details = UiNode::new(
            "about/compact-identity",
            UiContent::Group(GroupSpec::new("About summary")),
        )
        .layout(
            Layout::column()
                .width(Length::Fill)
                .height(Length::Fixed(detail_height))
                .gap(4.0),
        )
        .children(
            tagline
                .into_iter()
                .chain([version_summary])
                .chain(capabilities)
                .collect(),
        );
        let height = wordmark_height.max(detail_height);
        (
            vec![
                UiNode::new(
                    "about/identity-row",
                    UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
                )
                .layout(Layout::row().height(Length::Fixed(height)).gap(8.0))
                .children(vec![wordmark, details]),
            ],
            height,
        )
    } else {
        (
            [Some(wordmark), tagline, Some(version_summary)]
                .into_iter()
                .flatten()
                .chain(capabilities)
                .collect::<Vec<_>>(),
            wordmark_height + tagline_height + status_height + capability_height,
        )
    };
    // The hero is exactly its content: no floor that pads it with empty card.
    let identity_block = identity_height
        + hero_vertical_padding * 2.0
        + hero_children.len().saturating_sub(1) as f32 * 6.0;
    // The two buttons ride in the hero wherever the hero, buttons and all,
    // fits the list's room, so they never float outside their card; only a
    // window too short for that lists them as the stop after it.
    let split_compact_actions =
        width == SettingsWidth::Compact && identity_block + 6.0 + compact_actions_height > room;
    let hero_height = if split_compact_actions {
        identity_block
    } else {
        hero_children.push(hero_actions.clone());
        identity_block + 6.0 + compact_actions_height
    };
    let hero = UiNode::new(
        "about/hero",
        UiContent::Group(GroupSpec::new("About aterm").style(StyleRef::Primary)),
    )
    .layout(
        Layout::column()
            .height(Length::Fixed(hero_height))
            .padding(Insets::symmetric(
                if short_compact { 12.0 } else { 24.0 },
                hero_vertical_padding,
            ))
            .gap(6.0),
    )
    .children(hero_children);

    // The card lists every fact the hero does not paint: the tagline where the
    // hero has no column for it, and whatever the byline does not name.
    let tagline_painted = tagline_height > 0.0;
    let build_rows = about
        .semantic_rows()
        .iter()
        .filter(|(key, _)| !((*key == "tagline" && tagline_painted) || byline_names.contains(key)))
        .map(|(key, value)| ((*key).to_string(), about_fact_value(key, value, messages)))
        .collect::<Vec<_>>();
    // One card, the page's width: painted LINES, not facts — a long non-code
    // value (the compiler line) wraps, and the card buys that height; its
    // caption is its whole name where that is one line of the card's text
    // column, else its short one, else the whole name on two. The hero names
    // the site and links it, so no second card repeats it.
    let (build, card_height) = metadata_card(
        "about/provenance",
        caption_words("BUILD INFORMATION", "BUILD INFO", card_text_width(content)),
        &build_rows,
        content,
        about_metadata_label_width(),
    );
    let mut sections = vec![ListItem::of(hero, hero_height)];
    if split_compact_actions {
        sections.push(ListItem::of(hero_actions, compact_actions_height));
    }
    // Listed fact by fact, so a card taller than the room scrolls between its
    // facts and never squeezes a row.
    sections.push(ListItem::of(build, card_height));
    // Who made the display faces Text & Fonts offers by look, and under
    // which licence: credits belong here, not on the settings card.
    let credit_rows = aterm_render::DISPLAY_FACES
        .iter()
        .map(|face| (face.label.to_string(), face.face.to_string()))
        .collect::<Vec<_>>();
    let (credits, credits_height) = metadata_card(
        "about/font-credits",
        "FONT CREDITS",
        &credit_rows,
        content,
        about_metadata_label_width(),
    );
    sections.push(ListItem::of(credits, credits_height));
    let mut out = heading;
    out.push(scroll::list_page_peeking(
        state,
        "about/list",
        "About aterm",
        sections,
        room,
        gap,
        settings_list_overhang(state, width, viewport),
    ));
    out
}

const ABOUT_METADATA_CARD_PADDING: f32 = 18.0;

/// THE SIDE PADDING OF A CARD OF FACTS OR ROWS (About's, Harness's, AI CLIs'
/// and Tab Control's cards): [`ABOUT_METADATA_CARD_PADDING`], or 12pt where
/// the card is narrow for its words — where that padding would leave its text
/// column under 16 ems of body text at the live text size (a phone-width
/// window at large text: 110pt for 26px words at 22 columns, 122pt at 12pt,
/// which still keeps a landed row's block [`harness_page::ROW_INSET`] round its words).
/// The words get the room the padding would have taken; over and under them
/// the card keeps its padding. One measure for the card and the rows laid
/// out in it ([`card_text_width`]).
fn card_side_padding(card_width: f32) -> f32 {
    let em = 13.0 * settings_text_scale();
    if card_width - 2.0 * ABOUT_METADATA_CARD_PADDING >= 16.0 * em {
        ABOUT_METADATA_CARD_PADDING
    } else {
        NARROW_CARD_PADDING
    }
}

/// A narrow card's side padding ([`card_side_padding`]).
const NARROW_CARD_PADDING: f32 = 12.0;

/// The text column of a card `card_width` wide: the card less its side
/// padding each side ([`card_side_padding`]).
fn card_text_width(card_width: f32) -> f32 {
    (card_width - 2.0 * card_side_padding(card_width)).max(0.0)
}

const ABOUT_METADATA_LABEL_WIDTH: f32 = 104.0;
const ABOUT_METADATA_ROW_GAP: f32 = 10.0;
const ABOUT_METADATA_TEXT_SAFETY: f32 = 4.0;

fn about_metadata_label_width() -> f32 {
    ABOUT_METADATA_LABEL_WIDTH * settings_text_scale().min(1.2)
}

/// A FACT CARD'S LABEL COLUMN (Settings ▸ Harness's STATUS, EFFECT OF EACH
/// AUTOPILOT and WHAT THE HARNESS DID, Tab Control's summary, AI's WHO
/// REVIEWS and WHAT IS HELD): as wide as the widest of ITS OWN `rows`'
/// labels in the type the card paints them at the text scale now, never
/// narrower than About's column — so at 2× text `Supervision`, `Waited at
/// limits` and `System Vitals` are whole — as far as it leaves the value
/// column its widest word ([`metadata_value_lines`] wraps a value between
/// its words, so a word is what the column must hold whole). At 1× every
/// label fits About's column, which it keeps. Each card its own column: one
/// shared with another card's longer labels would take a value's room for
/// a label it does not draw. About's own cards keep About's column
/// ([`about_metadata_label_width`]).
fn fact_label_width(rows: &[(String, String)], inner: f32) -> f32 {
    let px = 13.0 * crate::native_appearance::text_scale();
    let label = rows
        .iter()
        .map(|(label, _)| metadata_value_text_width(about_fact_label(label), px, false))
        .fold(0.0_f32, f32::max)
        + ABOUT_METADATA_TEXT_SAFETY;
    let word = rows
        .iter()
        .filter(|(label, _)| !metadata_value_is_code(label))
        .flat_map(|(_, value)| value_words(value))
        .map(|word| metadata_value_text_width(word, px, false))
        .fold(0.0_f32, f32::max)
        + ABOUT_METADATA_TEXT_SAFETY;
    about_metadata_label_width().max(label.min(inner - ABOUT_METADATA_ROW_GAP - word))
}

/// The least parts [`metadata_value_lines`] can break `value` into: its
/// words, and a path's pieces after each `/`.
fn value_words(value: &str) -> impl Iterator<Item = &str> {
    value
        .split(FACT_SEPARATOR)
        .flat_map(|segment| segment.split(' '))
        .flat_map(|word| word.split_inclusive('/'))
}

/// A card caption's words for a text column `width` wide: the whole caption
/// where it is one line there, else its short form where that is, else the
/// whole caption, which then wraps to the column ([`caption_node`]) — never
/// cut.
fn caption_words<'a>(full: &'a str, short: &'a str, width: f32) -> &'a str {
    let (px, face) = crate::native_ui::text_paint_metrics(SemanticRole::Heading, StyleRef::Quiet);
    let one_line = |text: &str| {
        crate::tray_raster::ui_text_width_for(face, text, px)
            <= width + crate::native_ui::TEXT_FIT_SLACK
    };
    if one_line(full) || !one_line(short) {
        full
    } else {
        short
    }
}

/// A build fact's name as the page shows it; the row's key, and the copied
/// build information, keep the raw name.
fn about_fact_label(key: &str) -> &str {
    match key {
        "version" => "Version",
        "build" => "Build",
        "commit" => "Commit",
        "built" => "Built",
        "arch" => "Architecture",
        "compiler" => "Compiler",
        "signature" => "Signature",
        "running" => "Running from",
        "another copy" => "Other copy",
        // The hero's words, listed where the hero cannot paint them.
        "tagline" => "About",
        "author" => "Author",
        "company" => "Company",
        "site" => "Website",
        other => other,
    }
}

/// A build fact's value as the page shows it: the build time on the reader's
/// clock, in the words Messages uses (`Today 3:53:20 PM`); UTC, and saying
/// so, before the host has published a clock. Copy Build Information keeps
/// the ISO stamp.
fn about_fact_value(key: &str, value: &str, clock: &MessagesState) -> String {
    if key != "built" {
        return value.to_string();
    }
    let Some(built) = aterm_types::rfc3339::parse_utc(value.trim()) else {
        return value.to_string();
    };
    let built_ms = u64::try_from(built).unwrap_or(0).saturating_mul(1000);
    if clock.now_unix_ms == 0 {
        let (date, time) = value
            .trim()
            .trim_end_matches('Z')
            .split_once('T')
            .unwrap_or_default();
        return format!("{date} {} UTC", time.get(..5).unwrap_or(time));
    }
    aterm_messages::words::local_words(clock.now_unix_ms, built_ms, clock.utc_offset_s)
}

fn metadata_value_is_code(label: &str) -> bool {
    label.eq_ignore_ascii_case("commit") || label.eq_ignore_ascii_case("build")
}

fn metadata_value_text_width(text: &str, px: f32, code: bool) -> f32 {
    if code {
        crate::tray_raster::measure_text(text, px, crate::widget::TextWeight::Regular)
    } else {
        crate::tray_raster::ui_text_width(text, px)
    }
}

/// The most painted lines one fact's value takes: a pathological value cannot
/// stretch its card without limit (its last kept line then ends in an
/// ellipsis that fits, saying it ran out of room). Every value aterm states is
/// whole inside it at the narrowest column a 2× page gives — the running path
/// of a development build in its build cache included, which took more than
/// the 16 lines this was and lost its end ("96b519…") at 22 columns. A fact
/// taller than a screen is listed a part at a time by the page's list.
const MAX_METADATA_VALUE_LINES: usize = 64;

/// THE PIECES A LINE OF WORDS BREAKS BETWEEN, `(joiner, piece)` each, at
/// every place a line of it may break ([`aterm_grapheme::pieces`], the one
/// cut every wrap of aterm's chrome lays its lines from): its words (joined
/// by a space); between CJK characters, kinsoku kept (joined by nothing);
/// inside a word of prose after a `-` or a `/` (`built-` / `in`); and inside
/// a path before each folder's `/` (a path wraps at its folders instead of
/// losing its end, and no line ends in a separator), as a setting's name
/// breaks ([`row_name_lines`]). A fact separator (` · `) stays with the
/// piece before it, so no line starts with one.
fn line_pieces(text: &str) -> Vec<(&str, &str)> {
    let separator = FACT_SEPARATOR.trim();
    let mut pieces: Vec<(&str, &str)> = Vec::new();
    // Where the last piece starts, so a separator can join it.
    let mut last = 0;
    for piece in aterm_grapheme::pieces(text, |_| true) {
        if piece.text == separator
            && let Some(joined) = pieces.last_mut()
        {
            joined.1 = &text[last..piece.at + piece.text.len()];
            continue;
        }
        pieces.push((if piece.spaced { " " } else { "" }, piece.text));
        last = piece.at;
    }
    pieces
}

/// `text`'s lines in a box `width` wide, each as full as the box holds,
/// measured by `measure` (the face and size the lines paint in): broken
/// between its pieces ([`line_pieces`]), and inside a piece only where the
/// piece alone is wider than the box, where a typesetter would break it
/// ([`aterm_grapheme::break_inside`]) — a word at its syllables, each line
/// it breaks ending in a hyphen that says the word goes on ("Archi-" /
/// "tecture"); an identifier (a path's folder, a host, a version, a hash)
/// at its own joints with no mark (`alab` / `.systems`); and only where
/// neither fits at a character (a word with its hyphen, an identifier with
/// none) — so no line paints past the box. Nothing is cut and nothing is
/// dropped.
pub(crate) fn wrap_to_box(text: &str, width: f32, measure: &dyn Fn(&str) -> f32) -> Vec<String> {
    wrap_to_box_marked(text, width, measure, "-")
}

/// [`wrap_to_box`] whose syllable breaks end in `mark` — none for code (a
/// commit, a build, an aterm.toml key), which breaks as an identifier
/// wherever it is broken, even where a part of it reads as a word.
fn wrap_to_box_marked(
    text: &str,
    width: f32,
    measure: &dyn Fn(&str) -> f32,
    mark: &str,
) -> Vec<String> {
    wrap_to_box_from(text, width, measure, mark)
        .into_iter()
        .map(|(_, line)| line)
        .collect()
}

/// [`wrap_to_box_marked`]'s lines, each with the byte of `text` it starts
/// at: what a caller that keeps some lines and says the rest another way
/// takes the rest from (a CJK line goes on with no space between).
fn wrap_to_box_from(
    text: &str,
    width: f32,
    measure: &dyn Fn(&str) -> f32,
    mark: &str,
) -> Vec<(usize, String)> {
    let fits = |line: &str| measure(line) <= width + crate::native_ui::TEXT_FIT_SLACK;
    // Every piece is a slice of `text`: where it starts.
    let at = |piece: &str| piece.as_ptr() as usize - text.as_ptr() as usize;
    let mut lines: Vec<(usize, String)> = Vec::new();
    let mut line = String::new();
    let mut line_at = 0;
    for (joiner, piece) in line_pieces(text) {
        let candidate = if line.is_empty() {
            piece.to_string()
        } else {
            format!("{line}{joiner}{piece}")
        };
        if fits(&candidate) {
            if line.is_empty() {
                line_at = at(piece);
            }
            line = candidate;
            continue;
        }
        let mut start = at(piece);
        let end = start + piece.len();
        if !line.is_empty() {
            // A piece no whole line holds fills this line first where a
            // typesetter would ([`aterm_grapheme::break_into_line`]): a
            // word with the syllables that fit there ("a trans-" /
            // "lucent", where on a line of its own it left "a" alone before
            // it), an identifier at a joint where its rest is then whole.
            // So does a word of prose after A LINE OF ONE LETTER, which
            // holds a syllable of it: a note at 2× text in a 22-column card
            // painted "A" alone on a line, "A program's" too wide for one
            // ("A pro-" / "gram's colors").
            let after_a_lone_letter = is_a_lone_letter(&line)
                && aterm_grapheme::token_kind(piece.split_whitespace().next().unwrap_or(piece))
                    == aterm_grapheme::TokenKind::Word;
            if (!fits(piece) || after_a_lone_letter)
                && let Some((rest, part)) = aterm_grapheme::break_into_line(
                    text,
                    start..end,
                    mark,
                    &|part| fits(&format!("{line}{joiner}{part}")),
                    &fits,
                )
            {
                line.push_str(joiner);
                line.push_str(&part);
                start = rest;
            }
            lines.push((line_at, std::mem::take(&mut line)));
        }
        if fits(&text[start..end]) {
            line = text[start..end].to_string();
            line_at = start;
            continue;
        }
        // A piece wider than the whole box breaks inside itself where a
        // typesetter would ([`aterm_grapheme::break_inside`]): a word at its
        // syllables, with the mark; an identifier (a path's folder, a host,
        // a version, a hash) at its own joints, with none; and only where
        // neither fits at a character, never a lone letter. Broken wherever
        // the box ended it read "Brightn-" / "ess", "alab.syst-" / "ems"
        // and "0.11.0+g205-" / "65c325".
        let mut broken = aterm_grapheme::break_inside(text, start..end, mark, &fits);
        let (tail_at, tail) = broken.pop().unwrap_or((start, String::new()));
        lines.extend(broken);
        line_at = tail_at;
        line = tail;
    }
    if !line.is_empty() || lines.is_empty() {
        lines.push((line_at, line));
    }
    lines
}

/// Whether `line` is one letter alone ("A", "I"), a hole in a paragraph a
/// typesetter fills with a syllable of the word after it ([`wrap_to_box`]).
/// East Asian text, whose every character is a word, has no such line.
fn is_a_lone_letter(line: &str) -> bool {
    let mut graphemes = line.trim().graphemes();
    matches!(
        (graphemes.next(), graphemes.next()),
        (Some(one), None) if one.chars().all(|c| {
            c.is_alphabetic() && !crate::tray_raster::is_east_asian(c)
        })
    )
}

/// Whether every piece of `text` ([`line_pieces`]) is whole in a box `width`
/// wide, so its wrap there never breaks inside one.
fn pieces_fit(text: &str, width: f32, measure: &dyn Fn(&str) -> f32) -> bool {
    line_pieces(text)
        .iter()
        .all(|(_, piece)| measure(piece) <= width + crate::native_ui::TEXT_FIT_SLACK)
}

/// How wide a fact's name paints: quiet Body copy in the UI face.
fn fact_name_width(text: &str) -> f32 {
    let (px, face) = crate::native_ui::text_paint_metrics(SemanticRole::Text, StyleRef::Quiet);
    crate::tray_raster::ui_text_width_for(face, text, px)
}

/// HOW A CARD OF FACTS SETS THEM — one measured rule, the setting rows'
/// (a name wraps to the box it is drawn in; a control goes under its label
/// where the row cannot hold both): each fact's name in a column beside its
/// value wherever every fact's words sit in those columns whole — each piece
/// of a name in the name column, each piece of a value in the value column,
/// a code value whole in it — so no line there breaks inside a word; else
/// every name over its value, each the card's whole text width. Decided for
/// the card, so its facts line up.
///
/// The name column used to be a fixed 104pt (×1.2 at most) whatever its
/// words, and the names were elided into it ("Architec…", "Supervi…" at 2×
/// text; at a phone width it was wider than the card itself); the value
/// column was what that left, a 35pt column at 2× that painted every value
/// as "…".
#[derive(Clone, Copy, Debug, PartialEq)]
struct FactColumns {
    /// The name column, or the whole text width where names stand over values.
    label: f32,
    /// The value column, or the whole text width.
    value: f32,
    stacked: bool,
}

impl FactColumns {
    /// The columns `rows` take in a card `inner` wide whose name column is
    /// `label_width` where its facts sit beside each other — or as wide as
    /// the widest piece of a name, where that is wider, up to two fifths of
    /// the card (a wide card at 2× text holds "Unsupervised" beside its
    /// value, as a phone-width one cannot).
    fn measure(rows: &[(String, String)], inner: f32, label_width: f32) -> Self {
        let inner = inner.max(0.0);
        let widest = rows
            .iter()
            .flat_map(|(name, _)| line_pieces(about_fact_label(name)))
            .map(|(_, piece)| fact_name_width(piece))
            .fold(0.0_f32, f32::max);
        let label = label_width.max(widest.min(inner * 0.4)).min(inner);
        let value = (inner - label - ABOUT_METADATA_ROW_GAP).max(0.0);
        let px = 13.0 * crate::native_appearance::text_scale();
        let beside = rows.iter().all(|(name, text)| {
            let code = metadata_value_is_code(name);
            pieces_fit(about_fact_label(name), label, &fact_name_width)
                && if code {
                    metadata_value_text_width(text, px, true)
                        <= value + crate::native_ui::TEXT_FIT_SLACK
                } else {
                    pieces_fit(text, value, &|piece| {
                        metadata_value_text_width(piece, px, false)
                    })
                }
        });
        if beside {
            Self {
                label,
                value,
                stacked: false,
            }
        } else {
            Self {
                label: inner,
                value: inner,
                stacked: true,
            }
        }
    }
}

/// One fact's value as the lines it paints in its column `value_width`
/// wide, never cut: whole where it fits; a non-code value wrapped at its own
/// " · " separators where each part it joins is whole on a line, else at its
/// pieces ([`wrap_to_box`]) — the About compiler row once painted "release ·
/// tr…", chopping `trust_verify` in half (2026-08 settings audit) — its
/// identifiers (a version, a host, a path, a signature) broken at their own
/// joints with no hyphen put in them, whatever the fact's name
/// ([`aterm_grapheme::break_inside`] reads the text: "0.11.0" /
/// "+g20565c325", "alab" / ".systems", where a hyphen made "alab.syst-" /
/// "ems"); a code identifier (a commit, a build, in the code face) on as
/// many lines as its characters take, with no hyphen to read as one of
/// them. A code value used to keep its two
/// ends and lose its middle, and a phone-width column at 2× text painted
/// the build number "179…328" and the commit "6e8…73a".
fn metadata_value_lines(label: &str, value: &str, value_width: f32) -> Vec<String> {
    let budget = value_width.max(0.0);
    let code = metadata_value_is_code(label);
    let px = 13.0 * crate::native_appearance::text_scale();
    let measure = |line: &str| metadata_value_text_width(line, px, code);
    let fits = |line: &str| measure(line) <= budget + crate::native_ui::TEXT_FIT_SLACK;
    if fits(value) {
        return vec![value.to_string()];
    }
    if code {
        return wrap_to_box_marked(value, budget, &measure, "");
    }
    // Whole parts, as many to a line as it holds, a line break standing for
    // the separator it falls on; a part too wide for a line takes lines of
    // its own, wrapped between its pieces ([`wrap_to_box`]: its words, a
    // path after its `/`s), and the part after it begins the next — so a
    // fact the value lists is never broken after another's end or before
    // another's start (`held 0%` / `at its prompt 98%, finished` / `83%`).
    let mut lines: Vec<String> = Vec::new();
    let mut after_wrap = false;
    for part in value.split(FACT_SEPARATOR) {
        if !fits(part) {
            lines.extend(wrap_to_box(part, budget, &measure));
            after_wrap = true;
            continue;
        }
        match lines.last_mut() {
            Some(line) if !after_wrap && fits(&format!("{line}{FACT_SEPARATOR}{part}")) => {
                line.push_str(FACT_SEPARATOR);
                line.push_str(part);
            }
            _ => lines.push(part.to_string()),
        }
        after_wrap = false;
    }
    if lines.len() > MAX_METADATA_VALUE_LINES {
        lines.truncate(MAX_METADATA_VALUE_LINES);
        if let Some(last) = lines.pop() {
            lines.push(elide_wrapped_copy_tail(
                &last,
                px,
                crate::widget::TextFace::Ui,
                budget,
            ));
        }
    }
    lines
}

/// One fact's painted lines in `columns`: its name's, then its value's
/// ([`metadata_value_lines`]).
fn fact_card_lines(label: &str, value: &str, columns: FactColumns) -> (Vec<String>, Vec<String>) {
    (
        wrap_to_box(about_fact_label(label), columns.label, &fact_name_width),
        metadata_value_lines(label, value, columns.value),
    )
}

/// One line of a fact card's caption: a card's caption in small capitals,
/// the Heading role's Quiet step.
fn caption_line_height() -> f32 {
    22.0_f32.max(16.0 * settings_text_scale())
}

/// A CARD'S CAPTION WRAPS TO ITS CARD, never cut: `text` on as many lines as
/// the card's text column `width` needs, each as tall as one caption line
/// ([`wrapped_words_node`]). Returns the node, keyed `key`, and its height.
fn caption_node(key: &str, text: &str, width: f32) -> (UiNode, f32) {
    wrapped_words_node(
        key,
        text,
        (SemanticRole::Heading, StyleRef::Quiet),
        width,
        caption_line_height(),
    )
}

/// WORDS THAT WRAP TO THEIR BOX: `text` in `(role, style)` type on as many
/// lines of a box `width` wide as it needs ([`wrap_to_box`], measured in the
/// face and size it paints in), each `line_height` tall. One line is a plain
/// text node keyed `key`; more are a group of that key, in that role, that
/// says the whole text, its lines paint-only under it. Returns the node and
/// its height.
///
/// THE GROUP PAINTS NOTHING OF ITS OWN: its lines carry the type's style,
/// and the group is [`StyleRef::Plain`]. It used to wear the lines' style,
/// and a group in a card's style is painted as a card: every wrapped line
/// of Primary words (Packages' "No package activity recorded yet." at 2×)
/// stood in an accent-ringed box of its own, its words against the ring,
/// and a box per piece where a screen took it a part at a time.
fn wrapped_words_node(
    key: &str,
    text: &str,
    (role, style): (SemanticRole, StyleRef),
    width: f32,
    line_height: f32,
) -> (UiNode, f32) {
    let (px, face) = crate::native_ui::text_paint_metrics(role, style);
    let lines = wrap_to_box(text, width, &|line| {
        if face == crate::widget::TextFace::Mono {
            crate::tray_raster::measure_text(line, px, crate::widget::TextWeight::Regular)
        } else {
            crate::tray_raster::ui_text_width_for(face, line, px)
        }
    });
    let height = lines.len().max(1) as f32 * line_height;
    let line_node = |key: String, text: String| {
        UiNode::new(key, UiContent::Text(TextSpec { text, role, style }))
            .layout(Layout::default().height(Length::Fixed(line_height)))
    };
    if lines.len() <= 1 {
        return (line_node(key.to_string(), text.to_string()), height);
    }
    (
        UiNode::new(
            key,
            UiContent::Group(GroupSpec {
                label: Some(text.to_string()),
                role,
                style: StyleRef::Plain,
            }),
        )
        .layout(Layout::column().height(Length::Fixed(height)))
        .children(
            lines
                .into_iter()
                .enumerate()
                .map(|(index, line)| line_node(format!("{key}/line-{index}"), line).paint_only())
                .collect(),
        ),
        height,
    )
}

/// A CARD OF FACTS, `(name, value)` each, under its caption, `card_width`
/// wide: its text column the card less its side padding
/// ([`card_text_width`]), its name column `label_width` wide where the facts
/// sit beside each other ([`FactColumns`]). Each fact is ONE block of the
/// card, its lines inside it: the block owns the fact's whole accessible
/// text, and a list that lays the card out a fact at a time never parts a
/// fact from its own continuation. Returns the card and its height.
fn metadata_card(
    key: &str,
    caption: &str,
    rows: &[(String, String)],
    card_width: f32,
    label_width: f32,
) -> (UiNode, f32) {
    let inner = card_text_width(card_width);
    let side = card_side_padding(card_width);
    let columns = FactColumns::measure(rows, inner, label_width);
    let row_height = 28.0_f32.max(18.0 * settings_text_scale());
    let (heading, heading_height) = caption_node(&format!("{key}/heading"), caption, inner);
    let mut children = vec![heading];
    let mut height = 2.0 * ABOUT_METADATA_CARD_PADDING + heading_height;
    children.extend(rows.iter().map(|(label, value)| {
        let fragment = key_fragment(label);
        let code = metadata_value_is_code(label);
        let shown_label = about_fact_label(label);
        let value_style = if code {
            StyleRef::Code
        } else {
            StyleRef::Primary
        };
        let cell = |key: String, text: String, style: StyleRef, width: Length| {
            UiNode::new(
                key,
                UiContent::Text(TextSpec {
                    text,
                    role: SemanticRole::Text,
                    style,
                }),
            )
            .layout(Layout::default().width(width).height(Length::Fill))
            .paint_only()
        };
        let suffix = |index: usize| {
            if index == 0 {
                String::new()
            } else {
                format!("/line-{index}")
            }
        };
        let label_cell = |index: usize, text: String, width: Length| {
            cell(
                format!("{key}/label/{fragment}{}", suffix(index)),
                text,
                StyleRef::Quiet,
                width,
            )
        };
        let value_cell = |index: usize, text: String| {
            cell(
                format!("{key}/value/{fragment}{}", suffix(index)),
                text,
                value_style,
                Length::Fill,
            )
        };
        let (names, values) = fact_card_lines(label, value, columns);
        // Each painted line of the block: beside each other, a line of the
        // name's column and of the value's; stacked, the name's lines, then
        // the value's.
        let lines: Vec<Vec<UiNode>> = if columns.stacked {
            let name_lines = names
                .into_iter()
                .enumerate()
                .map(|(index, text)| vec![label_cell(index, text, Length::Fill)]);
            let value_lines = values
                .into_iter()
                .enumerate()
                .map(|(index, text)| vec![value_cell(index, text)]);
            name_lines.chain(value_lines).collect()
        } else {
            let count = names.len().max(values.len());
            (0..count)
                .map(|index| {
                    vec![
                        label_cell(
                            index,
                            names.get(index).cloned().unwrap_or_default(),
                            Length::Fixed(columns.label),
                        ),
                        value_cell(index, values.get(index).cloned().unwrap_or_default()),
                    ]
                })
                .collect()
        };
        let count = lines.len();
        let block_height = count as f32 * row_height + count.saturating_sub(1) as f32 * 4.0;
        height += block_height + 4.0;
        let line_rows = lines
            .into_iter()
            .enumerate()
            .map(|(index, cells)| {
                UiNode::new(
                    format!("{key}/row/{fragment}/line-{index}"),
                    UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
                )
                .layout(
                    Layout::row()
                        .height(Length::Fixed(row_height))
                        .gap(ABOUT_METADATA_ROW_GAP),
                )
                .children(cells)
                .paint_only()
            })
            .collect::<Vec<_>>();
        UiNode::new(
            format!("{key}/row/{fragment}"),
            UiContent::Group(GroupSpec::new(format!("{shown_label}: {value}"))),
        )
        .layout(
            Layout::column()
                .height(Length::Fixed(block_height))
                .gap(4.0),
        )
        .children(line_rows)
    }));
    (
        UiNode::new(
            key,
            UiContent::Group(GroupSpec::new(caption).style(StyleRef::Secondary)),
        )
        .layout(
            Layout::column()
                .width(Length::Fill)
                .height(Length::Fixed(height))
                .padding(Insets::symmetric(side, ABOUT_METADATA_CARD_PADDING))
                .gap(4.0)
                .clipped(),
        )
        .children(children),
        height,
    )
}

fn update_release_notes_padding() -> f32 {
    if settings_text_scale() > 1.25 {
        14.0
    } else {
        16.0
    }
}

fn update_release_notes_line_height() -> f32 {
    // RichText uses the native Body step (13 logical px) at 1.45 line height.
    // Keep the page capacity derived from that exact painter contract.
    (13.0 * crate::native_appearance::text_scale() * 1.45).max(16.0)
}

fn wrap_native_lines(lines: &[String], max_width: f32, px: f32) -> Vec<String> {
    let max_width = max_width.max(48.0);
    let mut wrapped = Vec::new();
    for source in lines {
        if source.is_empty() {
            wrapped.push(String::new());
            continue;
        }
        // Each line without its trailing space, a word wider than the box
        // broken as a label's is ([`copy_paragraph_lines`]).
        wrapped.extend(copy_paragraph_lines(source, px, max_width));
    }
    wrapped
}

fn wrap_release_note_lines(lines: &[String], max_width: f32) -> Vec<String> {
    wrap_native_lines(
        lines,
        max_width,
        13.0 * crate::native_appearance::text_scale(),
    )
}

/// THE RELEASE NOTES ARE ONE CARD, read paragraph by paragraph as stops of the
/// page's one scrolling list (s-25): a heading, then each paragraph of
/// [`update_notes_lines`] as a row of its own wrapped lines, at the height those
/// lines take — never fixed-height chunks headed "RELEASE NOTES · N OF M", the last
/// a room-tall card around a few lines, each carrying the whole changelog as its
/// spoken text, so a screen reader read the notes once per chunk. A paragraph
/// taller than the list's `room` is split at its line boundaries; each row says
/// exactly the words it paints.
fn update_release_notes_card(update: &UpdateProjection, room: f32, text_width: f32) -> UiNode {
    let line_height = update_release_notes_line_height();
    // Its caption wraps to the card's column, never cut ("RELEASE…" at 2×
    // on a phone-width page).
    let (heading, heading_height) =
        caption_node("updates/release-notes-heading", "RELEASE NOTES", text_width);
    let padding = update_release_notes_padding();
    let gap = 8.0;
    let capacity =
        (((room - padding * 2.0 - heading_height - gap) / line_height).floor() as usize).max(1);
    let mut rows: Vec<(UiNode, f32)> = Vec::new();
    for source in update_notes_lines(update)
        .iter()
        .filter(|line| !line.trim().is_empty())
    {
        let lines = wrap_release_note_lines(std::slice::from_ref(source), text_width);
        let whole = lines.len() <= capacity;
        for chunk in lines.chunks(capacity) {
            let index = rows.len();
            let key = if index == 0 {
                "updates/release-notes".to_string()
            } else {
                format!("updates/release-notes/{index}")
            };
            let height = (chunk.len() as f32 * line_height).ceil();
            rows.push((
                UiNode::new(
                    key,
                    UiContent::RichText(RichTextSpec {
                        semantic_text: if whole {
                            source.clone()
                        } else {
                            chunk.join(" ")
                        },
                        text: chunk.join("\n"),
                        selectable: true,
                    }),
                )
                .layout(
                    Layout::default()
                        .height(Length::Fixed(height))
                        .width(Length::Fill),
                ),
                height,
            ));
        }
    }
    let height =
        padding * 2.0 + heading_height + rows.iter().map(|(_, height)| height + gap).sum::<f32>();
    let mut children = vec![heading];
    children.extend(rows.into_iter().map(|(node, _)| node));
    UiNode::new(
        "updates/release-notes-card",
        UiContent::Group(GroupSpec::new("Release notes").style(StyleRef::Secondary)),
    )
    .layout(
        Layout::column()
            .height(Length::Fixed(height))
            .padding(Insets::all(padding))
            .gap(gap)
            .clipped(),
    )
    .children(children)
}

/// The engine tried this stage and it did not work: the state no compact rung of
/// the page may call "Ready".
///
/// Two carriers, both required. [`UpdateProjection::apply_trouble`] is precise (it
/// names the artifact, the count and the cause) from the first failure.
/// `apply_is_failing` is the escalation streak, which cannot name an artifact and
/// so survives a ledger this build cannot pin to the stage on offer (one from
/// before `apply_failure_build`). Keying on the precise one alone would read a
/// failing lane as ready on those machines.
fn not_applying(update: &UpdateProjection) -> bool {
    update.apply_trouble.is_some() || (update.staged.is_some() && update.apply_is_failing)
}

pub(crate) fn compact_update_headline(update: &UpdateProjection) -> String {
    if update.checking || update.installable == UpdateInstallability::Unobserved {
        // Unobserved: the full headline's "Checking this copy…".
        "Checking".to_string()
    } else if update.linux_host {
        if update.installable.cannot_install() {
            "Unavailable"
        } else if !update.enabled {
            "Off"
        } else if update.linux_attention {
            "Needs attention"
        } else if update
            .linux
            .as_ref()
            .is_some_and(|status| status.staged_build.is_some())
        {
            "Downloaded"
        } else if update
            .linux
            .as_ref()
            .is_some_and(|status| status.trial_phase.is_some() && !status.trial_healthy)
        {
            "Awaiting startup"
        } else if update
            .linux
            .as_ref()
            .is_some_and(|status| status.installed_build > update.current_build)
        {
            "Installed"
        } else if !update.automatic_checks {
            // The full ladder's idle arm (`UpdateState::headline`): below every disk,
            // enrollment and trouble fact, above "None staged".
            "Checks off"
        } else {
            "None staged"
        }
        .to_string()
    } else if update.staged_on_hold {
        // The full headline's "Update on hold" (`UpdateState::headline`),
        // failed tries or not: never "Ready".
        "On hold".to_string()
    } else if not_applying(update) {
        "Not installing".to_string()
    } else if update.staged.is_some() {
        "Ready".to_string()
    } else if update.failing_persistent {
        "Failing".to_string()
    } else if update.dev_build {
        // Left alone on purpose: the headline says where it stands.
        "Dev build".to_string()
    } else if update.installable.cannot_install() {
        // Not "Current": nothing was compared, and this copy could not take a newer
        // build if one existed.
        "Can\u{2019}t update".to_string()
    } else if update.channel_unreadable {
        // Not "Current": the channel cannot be read, so no comparison ran and none
        // will until an operator acts.
        "Can\u{2019}t check".to_string()
    } else if !update.enabled {
        "No updater".to_string()
    } else if !update.automatic_checks {
        // Not "Current": nothing in this process checks by itself (the full
        // headline's "Automatic checks are off."). Every trouble arm above outranks it.
        "Checks off".to_string()
    } else {
        "Current".to_string()
    }
}

pub(crate) fn compact_update_detail(update: &UpdateProjection) -> String {
    if update.checking {
        "Contacting service…".to_string()
    } else if update.installable == UpdateInstallability::Unobserved {
        "Reading this copy\u{2026}".to_string()
    } else if update.linux_host {
        update
            .detail
            .clone()
            .unwrap_or_else(|| "Run `aterm update status`.".to_string())
    } else if let Some(trouble) = update.apply_trouble.as_ref() {
        // The count and the cause survive the squeeze to a phone column; the whole
        // sentence stays the card's semantic value for assistive tech.
        trouble.compact()
    } else if update.staged_on_hold {
        format!(
            "On hold \u{b7} {}.",
            crate::update_words::NEWER_RELEASE_REPLACES
        )
    } else if not_applying(update) {
        // Escalated, but the ledger cannot pin the streak to this artifact (see
        // `UpdateState::apply_failure_build`): no count or cause, yet not "Ready".
        "Downloaded, but it keeps failing to install.".to_string()
    } else if update.staged.is_some() && update.failing_persistent {
        "Ready to install; update checks are failing.".to_string()
    } else if update.staged.is_some() {
        "Ready to install.".to_string()
    } else if update.failing_persistent {
        "Updates are failing.".to_string()
    } else if update.dev_build {
        "A dev build is left alone.".to_string()
    } else if update.installable.cannot_install() {
        "Install aterm to get updates.".to_string()
    } else if update.channel_unreadable {
        "The release channel can\u{2019}t be read.".to_string()
    } else if update.enabled {
        update_checked_sentence(update)
    } else {
        "Checks unavailable.".to_string()
    }
}

/// The tersest truthful rung for each [`compact_update_detail`] state: a
/// phone-width status card at 2× native text gives the line ~16 characters,
/// where even "Checked 12 min ago." runs past the box. The complete sentence
/// stays the card's semantic value; this is only what paints.
pub(crate) fn compact_update_detail_minimum(update: &UpdateProjection) -> String {
    if update.linux_host && !update.checking {
        // The page's one step, where it has one (`UpdateState::detail`'s Linux
        // direction); every other Linux state is the compact headline's to say.
        let downloaded = update
            .linux
            .as_ref()
            .is_some_and(|status| status.staged_build.is_some());
        return if update.installable.is_installable() && downloaded {
            "aterm update apply"
        } else {
            ""
        }
        .to_string();
    }
    if let Some(trouble) = update.apply_trouble.as_ref().filter(|_| !update.checking) {
        // The tersest rung keeps the count ("2 tries failed"): the one fact that
        // separates this from a stage waiting its turn.
        return trouble.micro();
    }
    if update.checking {
        "Contacting…"
    } else if update.installable == UpdateInstallability::Unobserved {
        "Reading\u{2026}"
    } else if update.staged_on_hold {
        "On hold."
    } else if not_applying(update) {
        "Install failing."
    } else if update.staged.is_some() && update.failing_persistent {
        "Checks failing."
    } else if update.staged.is_some() {
        "Ready."
    } else if update.failing_persistent {
        "Checks failing."
    } else if update.dev_build {
        "Dev build."
    } else if update.installable.cannot_install() {
        "Needs install."
    } else if update.channel_unreadable {
        "Channel unread."
    } else if !update.enabled {
        "Unavailable."
    } else if !update.automatic_checks {
        // Beside "Checks off": what still checks (the button, the terminal verb).
        "Manual checks."
    } else {
        "Up to date."
    }
    .to_string()
}

fn fit_native_bold_label(value: &str, max_width: f32, px: f32) -> String {
    let fits = |candidate: &str| {
        crate::tray_raster::ui_text_width_for(crate::widget::TextFace::UiBold, candidate, px)
            <= max_width.max(0.0) + 0.5
    };
    if fits(value) {
        return value.to_string();
    }

    let graphemes = value.graphemes().collect::<Vec<_>>();
    for retained in (0..graphemes.len()).rev() {
        let candidate = format!("{}…", graphemes[..retained].concat());
        if fits(&candidate) {
            return candidate;
        }
    }
    String::new()
}

fn compact_update_summary_detail(update: &UpdateProjection) -> &'static str {
    if update.checking {
        "Checking…"
    } else if update.installable == UpdateInstallability::Unobserved {
        "Reading this copy\u{2026}"
    } else if update.linux_host {
        "See terminal status"
    } else if update.staged_on_hold {
        "On hold"
    } else if not_applying(update) {
        "Not installing"
    } else if update.staged.is_some() && update.failing_persistent {
        "Ready · checks failing"
    } else if update.staged.is_some() {
        "Ready"
    } else if update.failing_persistent {
        // Beside the Danger "Failing" headline; "None staged" would contradict it.
        "Checks failing"
    } else if update.dev_build {
        // Beside the "Dev build" headline: why nothing moves it, not the same words.
        "Not auto-updated"
    } else if update.installable.cannot_install() {
        "Needs an installed copy"
    } else if update.channel_unreadable {
        // Beside "Can't check"; "Up to date" would claim a comparison that never ran.
        "Channel unreadable"
    } else if !update.enabled {
        "Unavailable"
    } else if !update.automatic_checks {
        // Beside "Checks off".
        "Manual checks"
    } else {
        "Up to date"
    }
}

/// The compact page's short status summary: two elided text columns in one row,
/// the headline beside the version and the detail's short form.
///
/// The page draws it where it lets more switches share the first screen with
/// the status than the full card does, or where the full card is not whole on
/// that screen, and only where each column holds its words whole (the third
/// value) ([`update_page`]); the detail sentence it shortens is painted whole
/// under it on the same card ([`compact_update_summary_card`]). The owning
/// Status node carries the complete headline and version.
fn compact_update_summary(
    update: &UpdateProjection,
    available_width: f32,
    titled: bool,
) -> (UiNode, f32, bool) {
    let scale = settings_text_scale();
    let title_height = 20.0_f32.max(16.0 * scale);
    let headline_height = 42.0_f32.max(30.0 * scale);
    let current_height = 22.0_f32.max(18.0 * scale);
    let detail_height = 24.0_f32.max(20.0 * scale);
    // This summary is a short landscape list's whole-width stop. Derive the
    // exact two text-column widths from that row instead of relying on the
    // compiler's emergency ellipsis. The owning Status below retains every
    // complete authored value as one non-duplicated accessibility stop.
    let inner_width = (available_width - 8.0 * 2.0 - 8.0).max(0.0);
    let identity_width = inner_width * 0.42;
    let detail_width = (inner_width - identity_width).max(0.0);
    // EVERY WORDING IN THE SUMMARY IS MEASURED in the column it is painted in,
    // never chosen by the text size: the whole form where it fits, else its
    // shorter honest one.
    // Named only where nothing else names the page, as the full card is.
    let caption_px = 11.0 * crate::native_appearance::text_scale();
    let caption_fits = |text: &str| {
        crate::tray_raster::ui_text_width_for(crate::widget::TextFace::UiBold, text, caption_px)
            <= identity_width + 0.5
    };
    let title_words = if caption_fits("SOFTWARE UPDATE") {
        "SOFTWARE UPDATE"
    } else {
        "UPDATE"
    };
    let title = titled.then(|| fit_native_bold_label(title_words, identity_width, caption_px));
    // A STAGE THE ENGINE HAS ALREADY FAILED TO APPLY IS NOT A CELEBRATION. The
    // accent is the same argument the wording makes: `failing_persistent` is the
    // ESCALATION verdict and stays quiet through the first two attempts, so "Not
    // applying" rendered in the identical Hero accent as "You're up to date."
    // The verdict at its own step where it fits the column, else at the Body
    // step in bold, a warning in the warning's colour still, as the full
    // card's headline steps down ([`update_headline_fit`]).
    let headline_words = compact_update_headline(update);
    let headline_px =
        |style: StyleRef| crate::native_ui::text_paint_metrics(SemanticRole::Heading, style).0;
    let preferred_style = update_headline_style(update);
    let headline_style = if crate::tray_raster::ui_text_width_for(
        crate::widget::TextFace::UiBold,
        &headline_words,
        headline_px(preferred_style),
    ) <= identity_width + 0.5
    {
        preferred_style
    } else {
        compact_heading_style(preferred_style)
    };
    let headline =
        fit_native_bold_label(&headline_words, identity_width, headline_px(headline_style));
    // The version a person knows; the build number is About's: "aterm 0.1.0"
    // where it fits the column, else "v0.1.0".
    let current_semantic = format!("aterm {}", update.current_version);
    let current_preferred =
        if crate::native_ui::fit_native_status_label(&current_semantic, detail_width)
            == current_semantic
        {
            current_semantic.clone()
        } else {
            format!("v{}", update.current_version)
        };
    let current = crate::native_ui::fit_native_status_label(&current_preferred, detail_width);
    let detail = crate::native_ui::fit_native_text_label(
        compact_update_summary_detail(update),
        detail_width,
    );
    // Whether every column holds its words whole: a summary that elides its
    // caption, its headline or its state says less than the full card, whose
    // caption wraps, so the page does not take it ([`update_page`]). The
    // caption was left out, and where a face's bold "UPDATE" is wider than the
    // identity column (Cantarell at 2× in a 30-column window) the summary
    // painted "UPD…".
    let whole = title.as_deref().is_none_or(|title| title == title_words)
        && headline == headline_words
        && current == current_preferred
        && detail == compact_update_summary_detail(update);
    // The detail sentence is the card's line under this row
    // ([`compact_update_detail_line`]), so the summary does not say it twice.
    let summary_semantic = format!("Software Update\n{}\n{}", update.headline, current_semantic);
    let left_height = if title.is_some() {
        title_height + 4.0
    } else {
        0.0
    } + headline_height;
    let right_height = current_height + detail_height + 4.0;
    let height = left_height.max(right_height) + 16.0;
    (
        UiNode::new(
            "updates/hero",
            UiContent::Group(GroupSpec {
                label: Some(summary_semantic),
                role: SemanticRole::Status,
                style: StyleRef::Primary,
            }),
        )
        .layout(
            Layout::row()
                .height(Length::Fixed(height))
                .padding(Insets::all(8.0))
                .gap(8.0)
                .clipped(),
        )
        .children(vec![
            UiNode::new(
                "updates/summary/identity",
                UiContent::Group(GroupSpec::new("Software Update")),
            )
            .layout(
                Layout::column()
                    .width(Length::Fraction(0.42))
                    .height(Length::Fixed(left_height))
                    .gap(4.0),
            )
            .children(
                title
                    .map(|title| {
                        UiNode::new(
                            "updates/title",
                            UiContent::Text(TextSpec {
                                text: title,
                                role: SemanticRole::Heading,
                                style: StyleRef::Quiet,
                            }),
                        )
                        .layout(Layout::default().height(Length::Fixed(title_height)))
                        .paint_only()
                    })
                    .into_iter()
                    .chain([UiNode::new(
                        "updates/headline",
                        UiContent::Text(TextSpec {
                            text: headline,
                            role: SemanticRole::Heading,
                            style: headline_style,
                        }),
                    )
                    .layout(Layout::default().height(Length::Fixed(headline_height)))
                    .paint_only()])
                    .collect(),
            )
            .paint_only(),
            UiNode::new(
                "updates/summary/detail",
                UiContent::Group(GroupSpec::new("Current update state")),
            )
            .layout(
                Layout::column()
                    .width(Length::Fill)
                    .height(Length::Fixed(right_height))
                    .gap(4.0),
            )
            .children(vec![
                UiNode::new(
                    "updates/current",
                    UiContent::Text(TextSpec {
                        text: current,
                        role: SemanticRole::Status,
                        style: StyleRef::Quiet,
                    }),
                )
                .layout(Layout::default().height(Length::Fixed(current_height)))
                .paint_only(),
                UiNode::new(
                    "updates/summary/state",
                    UiContent::Text(TextSpec {
                        text: detail,
                        role: SemanticRole::Text,
                        style: StyleRef::Quiet,
                    }),
                )
                .layout(Layout::default().height(Length::Fixed(detail_height)))
                .paint_only(),
            ])
            .paint_only(),
        ]),
        height,
        whole,
    )
}

/// The compact page's status card around the two-column summary
/// ([`compact_update_summary`]): the summary, the detail sentence its second
/// column shortens painted whole under it, and, where the card holds them, the
/// `actions` row under that. The detail is part of the status, so wherever the
/// summary is drawn the cause and the remedy are on the same card — on the same
/// screen — as the headline they explain; the buttons never float under the card
/// on the backdrop. The card keeps the summary's identity and semantics.
fn compact_update_summary_card(
    mut summary: UiNode,
    summary_height: f32,
    detail: Option<(UiNode, f32)>,
    actions: Option<(UiNode, f32)>,
) -> (UiNode, f32) {
    let spec = match &summary.content {
        UiContent::Group(spec) => spec.clone(),
        _ => GroupSpec::new("Software Update").style(StyleRef::Primary),
    };
    let inner_height = summary_height - 16.0;
    summary.key = UiKey::new("updates/summary");
    summary.content = UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group));
    summary.layout.padding = Insets::default();
    summary.layout.height = Length::Fixed(inner_height);
    let mut height = summary_height;
    let mut children = vec![summary];
    for (node, node_height) in detail.into_iter().chain(actions) {
        height += 8.0 + node_height;
        children.push(node);
    }
    (
        UiNode::new("updates/hero", UiContent::Group(spec))
            .layout(
                Layout::column()
                    .height(Length::Fixed(height))
                    .padding(Insets::all(8.0))
                    .gap(8.0)
                    .clipped(),
            )
            .children(children),
        height,
    )
}

/// The compact Software Update page with its full status card: the card, the
/// action split out of it where the card with it does not fit the list's room
/// (`split_action`), the link to Settings ▸ Messages beside the action where
/// the card (or the action's own row) holds both and as the stop after them
/// where it does not, the switches' card, and the release notes.
fn compact_update_full_items(
    status: UiNode,
    split_action: Option<UiNode>,
    automatic: Vec<(UiNode, f32)>,
    notes: Vec<UiNode>,
    notes_width: f32,
    action_height: f32,
) -> Vec<(UiNode, f32)> {
    let split = split_action.is_some();
    let mut sections = vec![status];
    if let Some(action) = split_action {
        let action_width = match action.layout.width {
            Length::Fixed(width) => width,
            _ => notes_width,
        };
        let row_height = fixed_height(&action).max(action_height);
        let mut row = vec![action];
        // The link rides beside the split-out action wherever the row
        // holds both, as it does inside the card.
        if action_width + 8.0 + messages_link_width() <= notes_width {
            row.push(messages_link_button(
                "updates/messages",
                messages_link_width(),
                action_height,
            ));
        }
        sections.push(
            UiNode::new(
                "updates/actions",
                UiContent::Group(GroupSpec::new("Update actions")),
            )
            .layout(Layout::row().height(Length::Fixed(row_height)).gap(8.0))
            .children(row),
        );
    }
    sections.extend(automatic.into_iter().map(|(node, _)| node));
    if !sections
        .iter()
        .take(1 + usize::from(split))
        .any(|section| ui_node_holds(section, "updates/messages"))
    {
        sections.insert(
            1 + usize::from(split),
            messages_link_button(
                "updates/messages",
                messages_link_width().min(notes_width),
                action_height,
            ),
        );
    }
    sections.extend(notes);
    with_heights(sections)
}

/// Where [`compact_update_summary_items`] lays the summary out: the card's
/// width, whether it names the page (no page heading over it), the list's
/// room, and the action's height.
struct SummaryPlace {
    notes_width: f32,
    card_titled: bool,
    room: f32,
    action_height: f32,
}

/// The compact Software Update page with the two-column summary
/// ([`compact_update_summary`]): one status card holding the summary, the
/// detail sentence it shortens painted whole ([`compact_update_detail_line`]),
/// and the action and the link to Settings ▸ Messages where the card holds them
/// (else each a stop after it); the switches' card; the last outcome where it
/// says something the detail does not; and the notes. `None` where a column of
/// the summary would elide its words.
fn compact_update_summary_items(
    update: &UpdateProjection,
    mut action: UiNode,
    automatic: Vec<(UiNode, f32)>,
    notes: Vec<UiNode>,
    place: SummaryPlace,
) -> Option<Vec<(UiNode, f32)>> {
    let SummaryPlace {
        notes_width,
        card_titled,
        room,
        action_height,
    } = place;
    let (summary, summary_height, whole) = compact_update_summary(update, notes_width, card_titled);
    if !whole {
        return None;
    }
    action.layout.height = Length::Fixed(fixed_height(&action).max(action_height));
    let link = messages_link_button(
        "updates/messages",
        messages_link_width().min(notes_width),
        action_height,
    );
    let action_width = match action.layout.width {
        Length::Fixed(width) => width,
        _ => notes_width,
    };
    // The card's text column: its width less its 8pt padding pair.
    let detail = compact_update_detail_line(update, (notes_width - 16.0).max(0.0));
    let detail_height = detail.as_ref().map_or(0.0, |(_, height)| 8.0 + height);
    // The action and the Messages link side by side, inside the card,
    // wherever the card holds them and the list's room the card.
    let side_by_side = action_width + 8.0 + messages_link_width() <= notes_width - 16.0;
    let with_actions = summary_height + detail_height + 8.0 + action_height;
    let mut items = Vec::new();
    if side_by_side && with_actions <= room {
        items.push(compact_update_summary_card(
            summary,
            summary_height,
            detail,
            Some((
                UiNode::new(
                    "updates/actions",
                    UiContent::Group(GroupSpec::new("Update actions")),
                )
                .layout(Layout::row().height(Length::Fixed(action_height)).gap(8.0))
                .children(vec![action, link]),
                action_height,
            )),
        ));
    } else {
        items.push(compact_update_summary_card(
            summary,
            summary_height,
            detail,
            None,
        ));
        let height = fixed_height(&action);
        items.push((action, height));
        items.push((link, action_height));
    }
    items.extend(automatic);
    // The CARD width, not the notes card's text measure: the outcome card
    // subtracts its own inset so the wrap and the paint share one box.
    items.extend(compact_update_outcome(update, notes_width));
    items.extend(with_heights(notes));
    Some(items)
}

/// The status card's detail sentence — the cause, the remedy, or when the last
/// check ran — under the two-column summary, whose second column says only its
/// short form ("Needs an installed copy"): painted whole wherever the summary is
/// (s-3), wrapped to the card's text column `width`, never cut to a line budget.
/// Its lines are paint-only; the sentence is the one semantic node, keyed
/// `updates/detail` as the full card's is, so the summary's own label does not
/// repeat it. `None` for a state with no sentence.
fn compact_update_detail_line(update: &UpdateProjection, width: f32) -> Option<(UiNode, f32)> {
    let sentence = update_status_detail(update, SettingsWidth::Compact);
    (!sentence.trim().is_empty()).then(|| {
        wrapped_copy_node(
            "updates/detail",
            &sentence,
            SemanticRole::Text,
            StyleRef::Quiet,
            width,
            24.0_f32.max(20.0 * settings_text_scale()),
            None,
        )
    })
}

/// How many wrapped lines of the last updater outcome the status card shows.
/// Enough for a real message, bounded so a pathological ledger string cannot
/// push the two controls off the page again.
const MAX_UPDATE_OUTCOME_LINES: usize = 3;

/// Bound wrapped outcome prose to [`MAX_UPDATE_OUTCOME_LINES`], eliding the last kept
/// line so the appended ellipsis still fits the wrap measure.
fn bound_outcome_lines(lines: &mut Vec<String>, max_width: f32) {
    bound_update_lines(lines, max_width, MAX_UPDATE_OUTCOME_LINES);
}

/// [`bound_outcome_lines`] at any bound: the status card's detail takes a tighter one
/// where a short phone pairs it with the check switch ([`update_page`]).
fn bound_update_lines(lines: &mut Vec<String>, max_width: f32, max_lines: usize) {
    if lines.len() <= max_lines {
        return;
    }
    lines.truncate(max_lines);
    let Some(last) = lines.pop() else {
        return;
    };
    let px = 13.0 * crate::native_appearance::text_scale();
    let measure = |candidate: &str| {
        crate::tray_raster::ui_text_width_for(crate::widget::TextFace::Ui, candidate, px)
    };
    let mut graphemes = last.graphemes().collect::<Vec<_>>();
    loop {
        let retained = graphemes.concat();
        let candidate = format!("{}\u{2026}", retained.trim_end());
        if measure(&candidate) <= max_width || graphemes.is_empty() {
            lines.push(candidate);
            return;
        }
        graphemes.pop();
    }
}

/// The outcome card's own padding, written once and read by both the card's layout
/// and the measure its prose wraps to, so a wrapped line cannot exceed its box (not
/// [`update_release_notes_padding`], which narrows above 1.25× text).
const COMPACT_UPDATE_OUTCOME_PADDING: f32 = 16.0;

/// The text measure this card's own box leaves, derived from the card width the
/// caller lays it out at. Measure and paint agree because they are the same
/// subtraction.
fn compact_update_outcome_text_width(card_width: f32) -> f32 {
    (card_width - COMPACT_UPDATE_OUTCOME_PADDING * 2.0).max(0.0)
}

/// The last updater outcome as a stop of its own, for the short-landscape host
/// only, where the status card collapses to [`compact_update_summary`] with no
/// room for a result line.
///
/// Takes the card width, not a text measure: the padding it wraps to must be the
/// padding it paints with.
fn compact_update_outcome(update: &UpdateProjection, card_width: f32) -> Option<(UiNode, f32)> {
    let display = update_outcome_line(update)?;
    let scale = settings_text_scale();
    let line_height = 24.0_f32.max(20.0 * scale);
    let text_width = compact_update_outcome_text_width(card_width);
    let mut lines = wrap_native_lines(
        std::slice::from_ref(&display),
        text_width,
        13.0 * crate::native_appearance::text_scale(),
    );
    bound_outcome_lines(&mut lines, text_width);
    let height = 32.0 + lines.len() as f32 * line_height;
    Some((
        UiNode::new(
            "updates/outcome",
            UiContent::Group(GroupSpec {
                label: Some(update.outcome.clone()),
                role: SemanticRole::Status,
                style: StyleRef::Secondary,
            }),
        )
        .layout(
            Layout::column()
                .width(Length::Fill)
                .height(Length::Fixed(height))
                .padding(Insets::all(COMPACT_UPDATE_OUTCOME_PADDING))
                .clipped(),
        )
        .children(
            lines
                .iter()
                .enumerate()
                .map(|(index, line)| {
                    UiNode::new(
                        format!("updates/outcome/line-{index}"),
                        UiContent::Text(TextSpec {
                            text: line.clone(),
                            role: SemanticRole::Text,
                            style: StyleRef::Quiet,
                        }),
                    )
                    .layout(Layout::default().height(Length::Fixed(line_height)))
                    .paint_only()
                })
                .collect(),
        ),
        height,
    ))
}

/// The one action the page offers, as a verb rather than a state machine.
///
/// There used to be three buttons — Check for Updates, Install & Relaunch and
/// Install When Safe — which asked the user to know which stage the updater was
/// in and to pick a policy for it. They only ever wanted the newest build, so
/// this is that: check when nothing is staged, install when something is.
/// Its whole label wherever the button with it fits `room`, measured; else
/// "Update", which its accessible name contains.
fn update_action_label(room: f32) -> &'static str {
    const WHOLE: &str = "Update to Latest Now";
    if crate::native_ui::native_button_label_width(WHOLE) + 28.0 <= room + 0.01 {
        WHOLE
    } else {
        "Update"
    }
}

/// The update action's painted words in a column `room` wide, by the one rule
/// page buttons keep ([`whole_button_words`]): one line, "Update to Latest
/// Now" where it fits, else "Update" — or `None` where not even that is whole
/// there, and the action is a stop of its own under the card, the list's
/// width (a 22-column page at 2× text painted "Upd…" inside the card).
fn update_action_words(update: &UpdateProjection, room: f32) -> Option<String> {
    let (full, short): (&str, &[&str]) = if update.linux_host {
        ("Install in a terminal", &[])
    } else {
        (update_action_label(room), &["Update"])
    };
    whole_button_words(full, short, room).map(|(words, _)| words)
}

/// Why the update action is unavailable on a copy that cannot replace itself:
/// its accessible description, beside the status card's own cause line.
const UPDATE_CANT_INSTALL: &str = "This copy of aterm can\u{2019}t install updates.";

/// Why the update action waits on a copy nothing has read yet: its accessible
/// description, and what a press (the palette's Updates: Check) says.
const UPDATE_UNOBSERVED_FEEDBACK: &str =
    "Still checking whether this copy of aterm can update itself.";

fn update_action_node(update: &UpdateProjection, height: f32, room: f32) -> UiNode {
    // A copy that can't replace itself never starts a check: the button is
    // greyed and says why, never a live primary that does nothing. One nothing
    // has read yet waits, greyed, for the read.
    let installable = update.installable.is_installable() || update.linux_host;
    let semantic_label = if update.linux_host {
        "Install in a terminal: run aterm update apply"
    } else {
        "Update to Latest Now"
    };
    let (visual_label, lines) = if update.linux_host {
        button_words("Install in a terminal", &[], room)
    } else {
        button_words(update_action_label(room), &["Update"], room)
    };
    let visual_label = visual_label.as_str();
    let unobserved = update.installable == UpdateInstallability::Unobserved && !update.linux_host;
    let mut spec = ButtonSpec::new(semantic_label).visual_label(visual_label);
    if unobserved {
        spec.description = Some(UPDATE_UNOBSERVED_FEEDBACK.to_string());
    } else if !installable {
        spec.description = Some(UPDATE_CANT_INSTALL.to_string());
    }
    UiNode::new(
        "updates/install-now",
        UiContent::Button(
            Control::new(spec, ActionId::new("updates/install-now"))
                .state(ControlState {
                    enabled: update.enabled
                        && installable
                        && !update.checking
                        && !update.linux_host,
                    busy: update.checking || unobserved,
                    ..ControlState::default()
                })
                .style(if installable || unobserved {
                    StyleRef::Primary
                } else {
                    StyleRef::Secondary
                }),
        ),
    )
    .layout(
        Layout::default()
            .width(Length::Fixed(if lines > 1 {
                room
            } else {
                page_button_width(visual_label, room)
            }))
            .height(Length::Fixed(
                crate::native_ui::native_button_height_for_lines(lines, height),
            )),
    )
}

/// A BUTTON'S WORDS FOR ITS BOX — one rule for the system pages' buttons:
/// its whole label `full` on one line where a text button `width` wide holds
/// it, else the first of its `short` forms that is one line there, else its
/// whole label on two lines or more at its words, else a short form so
/// ([`native_ui::native_button_label_lines`]) — never cut, its painted words
/// one phrase of its name. Only where not even the shortest form's longest
/// word fits the box is that word broken, with a hyphen.
/// Returns the painted label (`\n` between its lines) and its line count, the
/// height a button takes for them being
/// [`native_ui::native_button_height_for_lines`]'s.
fn button_words(full: &str, short: &[&str], width: f32) -> (String, usize) {
    button_words_in(&ButtonSpec::new(full), full, short, width)
}

/// The words a button's painted label says, its lines joined again: a line a
/// word broke at ends in the hyphen the break added, which joins it.
fn painted_words(visual: &str) -> String {
    visual
        .replace("-\n", "")
        .split_whitespace()
        .collect::<Vec<_>>()
        .join(" ")
}

/// [`button_words`] for a button that wears what `spec` does beside its
/// words (a trailing arrow, a chip, a badge), whose room it takes. Where no
/// form is whole, each form WITHOUT ITS TRAILING "…", whole, before a word
/// of one is broken: the ellipsis only says the button asks for more (its
/// name says what it does), and glued to the word before it, it made that
/// word too wide — a 22-column window at 2× text broke a word that fits
/// whole, Choose… painting "Choo-" / "se…" where "Choose" fits.
fn button_words_in(spec: &ButtonSpec, full: &str, short: &[&str], width: f32) -> (String, usize) {
    fn bare(form: &str) -> Option<&str> {
        form.strip_suffix('\u{2026}')
            .map(str::trim_end)
            .filter(|bare| !bare.is_empty())
    }
    let bare_short: Vec<&str> = short.iter().filter_map(|form| bare(form)).collect();
    let without_ellipsis = || {
        let (full, short) = match bare(full) {
            Some(full) => (full, &bare_short[..]),
            None => bare_short
                .split_first()
                .map(|(first, rest)| (*first, rest))?,
        };
        whole_button_words_in(spec, full, short, width)
    };
    whole_button_words_in(spec, full, short, width)
        .or_else(without_ellipsis)
        .unwrap_or_else(|| {
            // A word of every form wider than the button: the shortest form with
            // that word broken by a hyphen ([`wrap_to_box`]), never cut.
            let shortest = short.last().copied().unwrap_or(full);
            let room = crate::native_ui::text_button_label_room(spec, width);
            let lines = wrap_to_box(shortest, room, &crate::native_ui::native_button_label_width);
            (lines.join("\n"), lines.len())
        })
}

/// [`button_words`], or `None` where no form of the label is whole in a
/// button `width` wide on any number of lines (a word of each wider than the
/// button): a caller with somewhere wider to put the button puts it there.
fn whole_button_words(full: &str, short: &[&str], width: f32) -> Option<(String, usize)> {
    whole_button_words_in(&ButtonSpec::new(full), full, short, width)
}

/// [`whole_button_words`] for a button that wears what `spec` does.
fn whole_button_words_in(
    spec: &ButtonSpec,
    full: &str,
    short: &[&str],
    width: f32,
) -> Option<(String, usize)> {
    let room = crate::native_ui::text_button_label_room(spec, width);
    let one_line = |label: &str| {
        crate::native_ui::native_button_label_width(label)
            <= room + crate::native_ui::TEXT_FIT_SLACK
    };
    let forms = std::iter::once(full).chain(short.iter().copied());
    if let Some(form) = forms.clone().find(|form| one_line(form)) {
        return Some((form.to_string(), 1));
    }
    forms
        .clone()
        .find_map(|form| crate::native_ui::native_button_label_lines(form, room))
        .map(|lines| (lines.join("\n"), lines.len()))
}

/// A page action button's width: its label and the painter's padding, at
/// every width. A button that fills its row reads as a text field.
fn page_button_width(label: &str, room: f32) -> f32 {
    (crate::native_ui::native_button_label_width(label) + 28.0)
        .max(72.0)
        .min(room.max(0.0))
}

/// What the release-notes panel shows: a staged build's notes, else one line, since
/// the panel is a permanent section and an empty card reads as a rendering fault.
fn update_notes_lines(update: &UpdateProjection) -> Vec<String> {
    if update.linux_host {
        return vec!["No release notes on Linux.".to_string()];
    }
    if !update.changelog.is_empty() {
        return update.changelog.clone();
    }
    vec![if update.checking {
        "Checking for a newer version\u{2026}".to_string()
    } else if let Some((_, version)) = update.staged.as_ref() {
        // A staged build without notes (activating a bundle already on disk, or a
        // manifest that omits a changelog) is still staged.
        let state = if update.staged_on_hold {
            "is on hold"
        } else {
            "is ready to install"
        };
        format!("Version {version} {state}; its release notes aren\u{2019}t available here.")
    } else if update.failing_persistent || update.dev_build || !update.installable.is_installable()
    {
        // NEVER "is the latest build" on the same page whose headline says this Mac
        // cannot update (2026-08-19 round-5 audit), is a dev build left alone on
        // purpose (gap #30), or is a copy that can never replace itself and never
        // fetched a release list (round-6 audit). The status card above names the
        // cause; this card does not repeat it.
        "Release notes appear here when an update is ready.".to_string()
    } else if update.enabled && (update.channel_unreadable || update.checked_at.is_none()) {
        // Never "is the newest version" without a comparison behind it: a stranded
        // machine records no ledger failures, so the arm above misses it, and before
        // any check the status card says "Not checked yet."
        "Release notes appear here when an update is ready.".to_string()
    } else if update.enabled {
        format!(
            "aterm {} is the newest version. Notes for the next one appear here when it\u{2019}s ready.",
            update.current_version
        )
    } else {
        "Update checks are unavailable for this installation, so no release notes can be shown."
            .to_string()
    }]
}

/// How many wrapped lines the status card paints of its detail and of its outcome —
/// [`MAX_UPDATE_OUTCOME_LINES`] each, but fewer where the card must fit a section: a short
/// phone keeping a switch beside it, a desktop card windowed into its section. Each
/// sentence stays whole as its node's semantic value whatever paints.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct StatusLineBudget {
    detail: usize,
    outcome: usize,
}

impl StatusLineBudget {
    const FULL: Self = Self {
        detail: MAX_UPDATE_OUTCOME_LINES,
        outcome: MAX_UPDATE_OUTCOME_LINES,
    };

    /// The desktop ladder, longest first: the outcome steps down to one line, then the
    /// detail does. The outcome goes first because the detail is the headline's own
    /// sentence, while one line of "check failed (network)…" still names the
    /// cause (its whole text stays the node's semantic value). Neither goes below one.
    fn desktop_ladder() -> impl Iterator<Item = Self> {
        let outcome = (1..=MAX_UPDATE_OUTCOME_LINES).rev().map(|outcome| Self {
            detail: MAX_UPDATE_OUTCOME_LINES,
            outcome,
        });
        let detail = (1..MAX_UPDATE_OUTCOME_LINES)
            .rev()
            .map(|detail| Self { detail, outcome: 1 });
        outcome.chain(detail)
    }
}

/// How the status card fits its window.
#[derive(Clone, Copy, Debug)]
struct StatusCardShape {
    /// Nothing else names the page ([`page_named`]: no heading row, no
    /// toolbar title), so the card names it itself.
    titled: bool,
}

/// The status card's headline style: a persistent failure is a warning, not a
/// hero — the same treatment the configuration-reload warning gets, so it cannot
/// be mistaken for the accent "You're up to date" line it replaces. A stage that
/// has already failed to apply gets it too, from the FIRST failure — the headline
/// says "Update didn't install" and it must not be painted in the colour of good
/// news.
fn update_headline_style(update: &UpdateProjection) -> StyleRef {
    if update.failing_persistent || update.linux_attention || not_applying(update) {
        StyleRef::Danger
    } else {
        StyleRef::Hero
    }
}

/// THE STATUS CARD'S HEADLINE IS MEASURED in the card's text column
/// (`text_width`), never guessed from the window's width class: the whole
/// sentence where it fits its line in its style ([`update_headline_style`]);
/// else the compact verdict there ([`compact_update_headline`]: "Can't
/// update"), the same state in fewer words; else that verdict at the Body
/// step in bold, as a compact page's heading takes at large text (a phone
/// column at the platform maximum Dynamic Type) — A WARNING STAYS A WARNING
/// AS IT GIVES UP ITS SIZE ([`compact_heading_style`]: colour isn't size);
/// and where not even that is one line, that verdict on as many lines as the
/// column needs, never cut. The complete sentence stays the card's semantic
/// label.
fn update_headline_fit(update: &UpdateProjection, text_width: f32) -> (String, StyleRef) {
    let style = update_headline_style(update);
    let width = |text: &str, style: StyleRef| {
        let (px, face) = crate::native_ui::text_paint_metrics(SemanticRole::Heading, style);
        crate::tray_raster::ui_text_width_for(face, text, px)
    };
    let compact = compact_update_headline(update);
    if width(&update.headline, style) <= text_width + 0.01 {
        (update.headline.clone(), style)
    } else if width(&compact, style) <= text_width + 0.01 {
        (compact, style)
    } else {
        (compact, compact_heading_style(style))
    }
}

/// A heading's style at the compact heading step, the Body step in bold: a
/// warning's ([`StyleRef::DangerCompact`]) keeps the warning's colour; any
/// other is [`StyleRef::Plain`]'s. The fallback used to be Plain for a
/// warning too, so where Software Update's verdict had to step down it lost
/// its red and read as a routine headline.
fn compact_heading_style(style: StyleRef) -> StyleRef {
    if matches!(style, StyleRef::Danger | StyleRef::DangerCompact) {
        StyleRef::DangerCompact
    } else {
        StyleRef::Plain
    }
}

/// A CARD'S HEADLINE WHOLE IN ITS COLUMN, measured: `text` in its heading
/// `style` on one line `height` tall where the column `width` holds it; else
/// at the compact heading step ([`compact_heading_style`]) on one line; else
/// at that step on as many lines as the column needs, never cut. Returns the
/// node, keyed `key`, and its height.
fn fitted_headline_node(
    key: &str,
    text: &str,
    style: StyleRef,
    width: f32,
    height: f32,
) -> (UiNode, f32) {
    let one_line = |style: StyleRef| {
        let (px, face) = crate::native_ui::text_paint_metrics(SemanticRole::Heading, style);
        crate::tray_raster::ui_text_width_for(face, text, px)
            <= width + crate::native_ui::TEXT_FIT_SLACK
    };
    let style = if one_line(style) {
        style
    } else {
        compact_heading_style(style)
    };
    let (mut node, lines_height) = wrapped_words_node(
        key,
        text,
        (SemanticRole::Heading, style),
        width,
        26.0_f32.max(22.0 * settings_text_scale()),
    );
    let height = if matches!(node.content, UiContent::Text(_)) {
        height
    } else {
        lines_height
    };
    node.layout.height = Length::Fixed(height);
    (node, height)
}

/// THE STATUS CARD'S DETAIL IS MEASURED too: the whole sentence (`full`) where
/// it wraps within the card's line budget (`max_lines`) in its text column;
/// else the compact sentence ([`compact_update_detail`]), then the tersest
/// truthful one ([`compact_update_detail_minimum`]), each only where it is
/// whole there; and where none is, the whole sentence, its last line cut with
/// an ellipsis by the card's bound. The complete sentence stays the detail's
/// semantic value whatever paints.
fn update_detail_fit(
    update: &UpdateProjection,
    full: &str,
    text_width: f32,
    max_lines: usize,
) -> String {
    let px = 13.0 * crate::native_appearance::text_scale();
    // Whole: every word on a line of its own measure (the wrapper breaks a
    // word wider than the column inside it), in no more lines than the budget.
    let whole = |text: &str| {
        !text.trim().is_empty()
            && text
                .split_whitespace()
                .all(|word| crate::tray_raster::ui_text_width(word, px) <= text_width + 0.01)
            && wrap_to_box(text, text_width, &|line| {
                crate::tray_raster::ui_text_width(line, px)
            })
            .len()
                <= max_lines.max(1)
    };
    let forms = [
        full.to_string(),
        compact_update_detail(update),
        compact_update_detail_minimum(update),
    ];
    // Where no form is whole word by word (a word wider than a phone-width
    // column at 2× text), the first that fits the budget with that word
    // broken by a hyphen ([`wrap_to_box`]) — rather than the whole sentence
    // cut by the budget ("… this / copy…").
    let measure = |line: &str| crate::tray_raster::ui_text_width(line, px);
    forms
        .iter()
        .find(|text| whole(text))
        .or_else(|| {
            forms.iter().find(|text| {
                !text.trim().is_empty()
                    && wrap_to_box(text, text_width, &measure).len() <= max_lines.max(1)
            })
        })
        .cloned()
        .unwrap_or_else(|| full.to_string())
}

/// Status: what is running, what is available, and the single action. Also the
/// last updater outcome when there is one — one quiet line, where a paginated
/// "LAST UPDATE RESULT" section used to be.
///
/// `lines` bounds the painted detail and outcome ([`StatusLineBudget`]); the complete
/// sentences stay their semantic values either way.
fn update_status_card(
    update: &UpdateProjection,
    width: SettingsWidth,
    shape: StatusCardShape,
    text_width: f32,
    action: Option<UiNode>,
    action_height: f32,
    lines: StatusLineBudget,
) -> (UiNode, f32) {
    let StatusCardShape { titled } = shape;
    let text_scale = settings_text_scale();
    let headline_height = 42.0_f32.max(30.0 * text_scale);
    let current_height = 22.0_f32.max(18.0 * text_scale);
    let detail_height = 24.0_f32.max(20.0 * text_scale);
    let full_detail = update_status_detail(update, width);
    let (visual_headline, headline_style) = update_headline_fit(update, text_width);
    let visual_detail = update_detail_fit(update, &full_detail, text_width, lines.detail);
    // THE DETAIL IS AUTHORED PROSE NOW TOO, and it grew: "Version 0.5.15 · build
    // 830 · every attempt to start it has failed; see aterm.log" was ~80 characters
    // and the apply-trouble sentence is half as long again. It was painted as ONE
    // fixed-height, non-wrapping node, so the clipped tail was "It will try again by
    // itself." — the half that decides whether the reader has to do anything. Same
    // treatment as the `updates/outcome` node below, which has wrapped and bounded
    // for exactly this reason since it was authored.
    let detail_lines = {
        let px = 13.0 * crate::native_appearance::text_scale();
        let mut wrapped = wrap_to_box(&visual_detail, text_width, &|line| {
            crate::tray_raster::ui_text_width(line, px)
        });
        bound_update_lines(&mut wrapped, text_width, lines.detail.max(1));
        // A measure too small to fit anything still owes the card one row; an empty
        // vector would collapse the node and silently drop the line.
        if wrapped.is_empty() {
            wrapped.push(visual_detail.clone());
        }
        wrapped
    };
    // On Linux the detail line already carries the outcome verbatim, so this card
    // skips it; the short-landscape list's summary paints no detail, so its outcome
    // stop ([`compact_update_outcome`]) is where the cause paints there.
    let outcome = update_outcome_line(update).filter(|_| !update.linux_host);
    // The outcome is authored prose of unknown length. Wrap it to the card's
    // real measure, bounded, instead of painting one line off the edge — the
    // complete text stays available from `aterm update status`.
    let outcome_lines = outcome
        .as_ref()
        .map(|outcome| {
            let mut wrapped = wrap_native_lines(
                std::slice::from_ref(outcome),
                text_width,
                13.0 * crate::native_appearance::text_scale(),
            );
            bound_update_lines(&mut wrapped, text_width, lines.outcome.max(1));
            wrapped
        })
        .unwrap_or_default();
    // The card names itself only where nothing else names the page
    // ([`page_named`]): under the heading that was "Software Update" twice,
    // eight points apart. In caption case, as every card caption is.
    let mut children = Vec::new();
    // The caption, the headline and the version each wrap to the card's
    // column where one line cannot hold them, never cut ("SOFTWARE UPD…",
    // "aterm 0.…" at 2× on a phone-width page): a one-line headline keeps its
    // headline band, a wrapped one takes its lines.
    let (title_node, title_height) = caption_node(
        "updates/title",
        caption_words("SOFTWARE UPDATE", "UPDATE", text_width),
        text_width,
    );
    let title_height = if titled { title_height } else { 0.0 };
    if titled {
        children.push(title_node);
    }
    let (mut headline, wrapped_headline_height) = wrapped_words_node(
        "updates/headline",
        &visual_headline,
        (SemanticRole::Heading, headline_style),
        text_width,
        26.0_f32.max(22.0 * text_scale),
    );
    let headline_height = if matches!(headline.content, UiContent::Text(_)) {
        headline_height
    } else {
        wrapped_headline_height
    };
    headline.layout.height = Length::Fixed(headline_height);
    let (current, current_height) = wrapped_words_node(
        "updates/current",
        // The version a person knows; the build number is About's.
        &format!("aterm {}", update.current_version),
        (SemanticRole::Status, StyleRef::Quiet),
        text_width,
        current_height,
    );
    children.extend([
        headline,
        current,
        UiNode::new(
            "updates/detail",
            UiContent::Group(GroupSpec {
                // The COMPLETE sentence stays the semantic value — assistive tech and
                // `controls update` read it whole however narrow the card paints.
                label: Some(full_detail.clone()),
                role: SemanticRole::Text,
                style: StyleRef::Quiet,
            }),
        )
        .layout(Layout::column().height(Length::Fixed(detail_lines.len() as f32 * detail_height)))
        .children(
            detail_lines
                .iter()
                .enumerate()
                .map(|(index, line)| {
                    UiNode::new(
                        format!("updates/detail/line-{index}"),
                        UiContent::Text(TextSpec {
                            text: line.clone(),
                            role: SemanticRole::Text,
                            style: StyleRef::Quiet,
                        }),
                    )
                    .layout(Layout::default().height(Length::Fixed(detail_height)))
                    .paint_only()
                })
                .collect(),
        ),
    ]);
    if outcome.is_some() {
        children.push(
            UiNode::new(
                "updates/outcome",
                UiContent::Group(GroupSpec {
                    // The exact ledger string: assistive technology and `controls
                    // update` read the real outcome; the paint is the bounded summary.
                    label: Some(update.outcome.clone()),
                    role: SemanticRole::Status,
                    style: StyleRef::Quiet,
                }),
            )
            .layout(
                Layout::column().height(Length::Fixed(outcome_lines.len() as f32 * detail_height)),
            )
            .children(
                outcome_lines
                    .iter()
                    .enumerate()
                    .map(|(index, line)| {
                        UiNode::new(
                            format!("updates/outcome/line-{index}"),
                            UiContent::Text(TextSpec {
                                text: line.clone(),
                                role: SemanticRole::Text,
                                style: StyleRef::Quiet,
                            }),
                        )
                        .layout(Layout::default().height(Length::Fixed(detail_height)))
                        .paint_only()
                    })
                    .collect(),
            ),
        );
    }
    let has_action = action.is_some();
    // The link to Settings ▸ Messages (every update's record) rides beside the action
    // where the card's measure holds both, else on its own row; a compact page lists
    // it after the card (`update_page`).
    let compact = width == SettingsWidth::Compact;
    let link = messages_link_button("updates/messages", messages_link_width(), action_height);
    let action_width = action
        .as_ref()
        .map_or(0.0, |action| match action.layout.width {
            Length::Fixed(width) => width,
            _ => text_width,
        });
    let link_inline = has_action && action_width + 8.0 + messages_link_width() <= text_width;
    if let Some(action) = action {
        let mut row = vec![action];
        if link_inline {
            row.push(link.clone());
        }
        children.push(
            UiNode::new(
                "updates/actions",
                UiContent::Group(GroupSpec::new("Update actions")),
            )
            .layout(Layout::row().height(Length::Fixed(action_height)).gap(8.0))
            .children(row),
        );
    }
    let link_row = !compact && !link_inline;
    if link_row {
        children.push(link);
    }
    let height = if titled { title_height } else { 0.0 }
        + headline_height
        + current_height
        + detail_lines.len() as f32 * detail_height
        + outcome_lines.len() as f32 * detail_height
        + if has_action { action_height } else { 0.0 }
        + if link_row { action_height } else { 0.0 }
        + 40.0
        + children.len().saturating_sub(1) as f32 * 8.0;
    (
        UiNode::new(
            "updates/hero",
            UiContent::Group(
                GroupSpec::new(format!(
                    "Software Update status: {}. {full_detail}{}",
                    update
                        .headline
                        .trim_end_matches(['.', '\u{2026}', '?', '!']),
                    outcome.map_or_else(String::new, |outcome| format!(" {outcome}"))
                ))
                .style(StyleRef::Primary),
            ),
        )
        .layout(
            Layout::column()
                .height(Length::Fixed(height))
                .padding(Insets::symmetric(22.0, 20.0))
                .gap(8.0),
        )
        .children(children),
        height,
    )
}

/// The status card's detail: the projection's own detail when it has one; otherwise
/// when the last check ran, then, where automatic checks are not simply on, what that
/// means for this process (`UpdateProjection::automatic_checks_note`). The last check
/// comes first: it is short, so no line budget can cut it.
fn update_status_detail(update: &UpdateProjection, width: SettingsWidth) -> String {
    if let Some(detail) = &update.detail {
        return detail.clone();
    }
    let status = if update.checking {
        "Contacting the update service\u{2026}".to_string()
    } else if update.enabled {
        update_checked_sentence(update)
    } else if width == SettingsWidth::Compact {
        "Update checks are unavailable.".to_string()
    } else {
        "Update checks are unavailable for this installation.".to_string()
    };
    match &update.automatic_checks_note {
        Some(note) => format!("{status} {note}"),
        None => status,
    }
}

/// A healthy page's status line: when the last check completed, relative and local
/// (`Checked 12 min ago.`), or that none has yet.
fn update_checked_sentence(update: &UpdateProjection) -> String {
    let now = aterm_time::unix_secs().map_or(0, |s| i64::try_from(s).unwrap_or(i64::MAX));
    update
        .checked_line(now)
        .map_or_else(|| "Not checked yet.".to_string(), |line| format!("{line}."))
}

/// The last updater outcome as one line, only where it says something the page does
/// not: never a healthy decision (the headline and "Checked …" line say those), never
/// a check the updater retries by itself (its record is on Settings ▸ Messages), and
/// never a cause the detail line already carries.
///
/// A Linux page's full status card skips it (its detail carries it), but that is
/// [`update_status_card`]'s decision: the short-landscape summary paints no detail,
/// so its outcome stop is where the cause paints.
fn update_outcome_line(update: &UpdateProjection) -> Option<String> {
    let outcome = update.outcome.trim();
    let routine = outcome.is_empty()
        || outcome.eq_ignore_ascii_case("ok")
        || outcome.eq_ignore_ascii_case("Checking for updates")
        || outcome.starts_with("up to date")
        || outcome.starts_with("staged ")
        || outcome.contains("ready to apply")
        || outcome.starts_with("a verified stage already covers")
        || outcome.starts_with("update check deferred");
    let said_above = update.failing_persistent
        || update.channel_unreadable
        || update.apply_trouble.is_some()
        || !update.installable.is_installable();
    if routine || said_above {
        return None;
    }
    // The ledger stores authored prose that may span lines; the status line
    // takes the whole of it as one bounded sentence. No "Last check:" label: the
    // apply lane and the reducer write this field too, and each sentence names its subject.
    Some(outcome.split('\n').collect::<Vec<_>>().join(" "))
}

/// The one platform-true sentence for a build whose in-app updater lane does
/// not exist: every such copy (Windows, and any host with neither the macOS nor the
/// Linux updater) is built by its owner from an aterm checkout, so pulling, rebuilding
/// and reinstalling it IS the update. It names no file or command: which scripts or
/// build line a checkout has differs between a development checkout and the public
/// snapshot, and only `aterm update status` and `aterm help update` (from
/// `aterm_cli::WINDOWS_UPDATE_LANE`, which knows which one this build came from)
/// spell them out. Shown as the status card's detail line under the
/// unavailable-updater headline, so the pair reads as one honest statement, on one
/// line in the narrowest status card (the Medium workbench's).
const PLATFORM_UPDATE_LANE: &str = "Pull, rebuild and reinstall from your aterm checkout.";

/// What the automatic-updates card explains, beyond the switches' own labels, for the
/// updater this host has. `macos_updater` is [`SettingsAvailability::macos`];
/// `linux_updater` is [`UpdateProjection::linux_host`], or Linux's updater running
/// here off macOS ([`native_updater_here`]). Both native updaters read
/// `[update] enabled` once per process (`aterm_update::automatic`, through
/// `aterm_update_core::settings`) to decide whether the BACKGROUND checker starts —
/// a person's check never consults it (Check for Updates on macOS, `aterm update check`
/// on either) — so on both the caption says automatic checks start or stop next
/// launch. What installing means differs: macOS hands the live sessions to the new
/// build; Linux replaces the executable on disk and existing terminals keep running,
/// and with the switch off it downloads only. Only where there is NO native updater
/// (neither macOS nor Linux) must the caption not describe the switches as doing
/// anything — the SAME honest copy `setting_effect_projection` authors for both
/// `[update]` keys ("Updater unavailable: no effect here"), which the page's direct
/// visual labels otherwise strip.
fn update_automatic_caption(
    width: SettingsWidth,
    macos_updater: bool,
    linux_updater: bool,
    installable: UpdateInstallability,
) -> String {
    let compact = width == SettingsWidth::Compact;
    let install = prefs::UPDATE_INSTALL_LABEL;
    if macos_updater && installable.cannot_install() {
        // A copy that can't replace itself checks and installs nothing; the
        // switches are saved for an installed copy, and say only that.
        "These switches take effect in an installed copy of aterm.".to_string()
    } else if linux_updater {
        if compact {
            "Automatic checks start or stop next launch; without automatic installs, aterm \
             downloads only (then `aterm update apply`)."
                .to_string()
        } else {
            // That terminals keep running rides in the page subtitle at every width
            // this caption shows at.
            format!(
                "Automatic checks start or stop next launch. Installing replaces aterm on \
                 disk; with {install} off, aterm downloads only \u{2014} then run \
                 `aterm update apply`."
            )
        }
    } else if macos_updater {
        if compact {
            "Automatic checks start or stop next launch; installing keeps your sessions."
                .to_string()
        } else {
            // Main's plain words for what installing does (e0f26104a: "installs updates by
            // itself, within a minute, and keeps your sessions running"). The install
            // switch is NAMED by its one name: after a plural "Updates", a bare "it" could
            // only mean the check switch — which stops background checks and never makes
            // installing manual (2026-09-24 post-push review).
            format!(
                "Automatic checks start or stop next launch. Updates install within a minute \
                 and keep your sessions running; turn {install} off to install only when \
                 you press the button."
            )
        }
    } else if compact {
        "Updater unavailable \u{b7} no effect here.".to_string()
    } else {
        "These switches do nothing here.".to_string()
    }
}

/// Whether the card's switches lay out one line each, label beside switch, in
/// `text_width`: measured for the WORST case — a written switch, its Changed tag
/// and its Reset — on the registry names the card paints, so turning a switch never
/// changes the card's layout or words.
fn update_switches_fit_inline(state: &SettingsViewState, text_width: f32) -> bool {
    let room = inline_row_label_width(&EditKind::Bool, text_width, true);
    let worst = update_switch_tags(true);
    [prefs::EDIT_UPDATE_ENABLED, "update.auto_apply"]
        .iter()
        .filter_map(|key| state.field_by_key(key))
        .all(|field| {
            row_name_lines(field.label, room).len() == 1
                && row_tag_fit(field.label, &worst, room).state
        })
}

/// An Automatic updates switch's tags: Changed where it is written. The
/// facts after a registry row's name are the card caption's to say once.
fn update_switch_tags(changed: bool) -> RowTags {
    RowTags {
        state: changed
            .then(|| CHANGED_WORD.to_string())
            .into_iter()
            .collect(),
        facts: Vec::new(),
    }
}

/// The card's two switches — `[update] enabled` and `[update] auto_apply`, each
/// painted by its registry name — bound to the SAME config
/// leaves the Settings editor writes, through the same row builder every other boolean
/// setting uses — so they inherit the switch control, the pending/busy state, the
/// application-timing disclosure (`[update] enabled`: "Applies next launch") and the
/// accessibility semantics, and cannot drift from the values the updater reads.
/// Live wherever a native updater reads them (macOS, and Linux's `linux_updater`,
/// where enrollment is a separate status fact, not this policy) and disabled, never
/// hidden, everywhere else. One card under its heading: each row on one line where
/// the worst case fits beside the switch, else the label over the switch, as a
/// narrow page lays any row out. A written switch says Changed and offers Reset, and
/// an unwritten one keeps an empty slot of Reset's width, so the two switches stay
/// in one column that turning either never moves. Within `height_budget` (the room
/// the page's section gets) its caption steps down to the compact sentence, then
/// goes, so the card fits in any UI face.
fn update_automatic_cards(
    state: &SettingsViewState,
    linux_updater: bool,
    availability: SettingsAvailability,
    width: SettingsWidth,
    text_width: f32,
    height_budget: Option<f32>,
) -> Vec<(UiNode, f32)> {
    // Each switch is named by its registry name — its painted label, the
    // switch, its Reset and its row say the one name — with Changed where
    // the switch is written; the notes after a registry row's name are the
    // caption's to say once for both switches ("These switches take effect
    // in an installed copy of aterm.").
    let keys = [prefs::EDIT_UPDATE_ENABLED, "update.auto_apply"];
    let fits_inline = update_switches_fit_inline(state, text_width)
        && (width != SettingsWidth::Compact
            || compact_row_inline(&EditKind::Bool, text_width, true));
    let compact_inline = fits_inline && width == SettingsWidth::Compact;
    let row_width = if !fits_inline {
        SettingsWidth::Compact
    } else if compact_inline {
        SettingsWidth::Medium
    } else {
        width
    };
    let label_room = if fits_inline {
        inline_row_label_width(&EditKind::Bool, text_width, true)
    } else {
        text_width
    };
    let mut rows = Vec::with_capacity(2);
    for key in keys {
        let Some(index) = state.field_index_of(key) else {
            return Vec::new();
        };
        let wording = state.legacy.fields[index].label;
        let mut row = setting_row(state, index, &state.legacy.fields[index], false, row_width);
        if compact_inline {
            row.layout.height = Length::Fixed(compact_inline_row_height());
        }
        // Reset's slot on every row, whether or not it is written: the
        // switches share one column, and turning one never moves it.
        if !state.is_explicit(key) {
            reserve_reset_slot(&mut row, key);
        }
        // The label's real room beside the switch and Reset's place; a
        // stacked row seats its Reset as every stacked switch row does
        // ([`seat_stacked_reset`]) and its name has what that leaves.
        let label_room = if row_width == SettingsWidth::Compact {
            seat_stacked_reset(&mut row, wording, text_width);
            row_label_room(&row, true, text_width)
        } else {
            label_room.min(one_line_label_room(&row, text_width))
        };
        // The wording wraps, never cut, Changed after it where it fits
        // written or not, else on the line under it ([`place_row_tags`]).
        let placement = lay_out_row_label(
            &mut row,
            wording,
            &update_switch_tags(state.is_explicit(key)),
            &update_switch_tags(true),
            label_room,
            row_width == SettingsWidth::Compact,
            false,
        );
        let detail = row_second_line(&placement, None, None, text_width);
        let mut row = with_row_detail(row, key, &detail, row_width == SettingsWidth::Compact);
        // A LANE THAT DOES NOT EXIST CANNOT LOOK OPERABLE. Both native updaters — macOS
        // and Linux — read these keys (Linux's enrollment is a separate status fact, not
        // this policy); with neither (`aterm_update::enabled()` is false) each switch is
        // DISABLED — not hidden: the config leaves are real, portable, and the greyed
        // control plus the caption say exactly why it does nothing here. Hiding them
        // would make the page shape diverge per platform and turn "where did my setting
        // go" into a support question; a live switch was worse — it flipped a value
        // nothing reads and looked like a working feature (the 2026-08 Windows audit's
        // L4). The row's semantic label already carries the registry's "Native updater
        // unavailable on this platform; saved for portability" disclosure, so assistive
        // tech hears the same truth the caption paints.
        if !native_updater_here(availability) && !linux_updater {
            // Desktop rows hold the switch directly at children[1]; compact rows
            // wrap it in a controls group (spacer first, switch LAST). Rather than
            // mirror that layout knowledge here, find the row's one Switch.
            fn disable_switch(node: &mut UiNode) -> bool {
                if let UiContent::Switch(switch) = &mut node.content {
                    switch.state.enabled = false;
                    return true;
                }
                node.children.iter_mut().any(disable_switch)
            }
            let disabled = disable_switch(&mut row);
            debug_assert!(disabled, "each [update] row carries exactly one switch");
        }
        rows.push(row);
    }
    let text_scale = settings_text_scale();
    let caption_line_height = 24.0_f32.max(20.0 * text_scale);
    let row_height = if compact_inline {
        compact_inline_row_height()
    } else {
        row_width.row_height()
    };
    let compact = width == SettingsWidth::Compact;
    let title_height = 20.0_f32.max(16.0 * text_scale);
    // The card's caption, where its measure holds it whole (a phone-width card
    // at the largest text sizes does not, and its rows then say enough).
    const TITLE: &str = "AUTOMATIC UPDATES";
    let (title_px, title_face) =
        crate::native_ui::text_paint_metrics(SemanticRole::Heading, StyleRef::Quiet);
    let titled = crate::tray_raster::ui_text_width_for(title_face, TITLE, title_px) <= text_width;
    let title_block = if titled { title_height + 8.0 } else { 0.0 };
    // The rows as laid out: a wording that wraps, or a Changed that moved
    // under it, makes its row taller, the same in every state.
    let rows_height = rows
        .iter()
        .map(fixed_height)
        .sum::<f32>()
        .max(2.0 * row_height)
        + 8.0;
    // The caption is prose of the UI face's measure, so how many lines it takes is the
    // face's to decide: the medium workbench's column held the Linux sentence in five
    // lines of Helvetica Neue and seven of Noto Sans, and the seventh ran the card —
    // and the status card beside it — 13pt past the section (2026-09-24 review). A desktop
    // card therefore tries its own sentence, then the compact one, within the budget.
    let room =
        height_budget.map(|budget| (budget - (40.0 + title_block + rows_height + 8.0)).max(0.0));
    // The updater the caption speaks for is the platform's: macOS's, or Linux's
    // wherever Linux's updater runs (`native_updater_here` off macOS) as well as
    // where a status names Linux's lane (`linux_updater`). Never macOS's sentence
    // off macOS, and never "do nothing" where an updater reads both switches.
    let linux_caption = linux_updater || (!availability.macos && native_updater_here(availability));
    // Nothing has read this copy yet (no installability, and no Linux status,
    // which is a read too): the caption would claim what the switches do here
    // before anything knows, so it waits.
    let unread = (availability.macos || (native_updater_here(availability) && !linux_updater))
        && availability.update_installable == UpdateInstallability::Unobserved;
    let mut rungs = vec![update_automatic_caption(
        width,
        availability.macos,
        linux_caption,
        availability.update_installable,
    )];
    if unread {
        rungs.clear();
    } else if !compact {
        rungs.push(update_automatic_caption(
            SettingsWidth::Compact,
            availability.macos,
            linux_caption,
            availability.update_installable,
        ));
    }
    // Where no rung fits, keep the controls and drop the caption whole: each row's
    // semantic label carries the full policy, and half a sentence is worse than none.
    let (caption_text, caption) = rungs
        .into_iter()
        .map(|text| {
            let lines = wrap_native_lines(
                std::slice::from_ref(&text),
                text_width,
                13.0 * crate::native_appearance::text_scale(),
            );
            (text, lines)
        })
        .find(|(_, lines)| room.is_none_or(|room| lines.len() as f32 * caption_line_height <= room))
        .unwrap_or_default();
    let caption_height = caption.len() as f32 * caption_line_height;
    let caption_node = (!caption.is_empty()).then(|| {
        UiNode::new(
            "updates/automatic/caption",
            UiContent::Group(GroupSpec {
                label: Some(caption_text),
                role: SemanticRole::Text,
                style: StyleRef::Quiet,
            }),
        )
        .layout(Layout::column().height(Length::Fixed(caption_height)))
        .children(
            caption
                .iter()
                .enumerate()
                .map(|(index, line)| {
                    UiNode::new(
                        format!("updates/automatic/caption/line-{index}"),
                        UiContent::Text(TextSpec {
                            text: line.clone(),
                            role: SemanticRole::Text,
                            style: StyleRef::Quiet,
                        }),
                    )
                    .layout(Layout::default().height(Length::Fixed(caption_line_height)))
                    .paint_only()
                })
                .collect(),
        )
    });
    let caption_block = if caption.is_empty() {
        0.0
    } else {
        caption_height + 8.0
    };
    let card = |key: &str, label: &str, children: Vec<UiNode>, height: f32| {
        (
            UiNode::new(
                key,
                UiContent::Group(GroupSpec::new(label).style(StyleRef::Secondary)),
            )
            .layout(
                Layout::column()
                    .width(Length::Fill)
                    .height(Length::Fixed(height))
                    .padding(Insets::all(20.0))
                    .gap(8.0)
                    .clipped(),
            )
            .children(children),
            height,
        )
    };
    // The card's caption, in the case every card caption is painted in: it says
    // what the two switches' words leave out — that both are automatic.
    let title = titled.then(|| {
        UiNode::new(
            "updates/automatic/title",
            UiContent::Text(TextSpec {
                text: TITLE.to_string(),
                role: SemanticRole::Heading,
                style: StyleRef::Quiet,
            }),
        )
        .layout(Layout::default().height(Length::Fixed(title_height)))
    });
    let install = rows.pop().expect("two rows");
    let check = rows.pop().expect("two rows");
    let mut children: Vec<UiNode> = title.into_iter().collect();
    children.extend([check, install]);
    children.extend(caption_node);
    vec![card(
        "updates/automatic",
        "Automatic updates",
        children,
        40.0 + title_block + rows_height + caption_block,
    )]
}

/// The Software Update page: what you are running, one button that takes you to the
/// newest build, the two automatic-update switches, and the release notes.
fn update_page(
    state: &SettingsViewState,
    update: &UpdateProjection,
    availability: SettingsAvailability,
    width: SettingsWidth,
    viewport_width: f32,
    viewport_height: f32,
) -> (Vec<UiNode>, PageLayout) {
    // Unsupported hosts name their real reinstall lane. Linux keeps its typed
    // per-copy status even when unenrolled; macOS keeps its existing projection.
    // Enabled projection fixtures retain their staged/checking layout shapes.
    let honest;
    let update = if native_updater_here(availability) || update.enabled || update.linux_host {
        update
    } else {
        honest = UpdateProjection {
            // Hero-sized, so short enough for one line in the Medium workbench's
            // ~320pt; the platform limitation rides in the page subtitle and the
            // switch caption.
            headline: "No in-app updater here.".to_string(),
            // The platform sentence REPLACES any authored detail: with the
            // updater lane absent, every macOS-shaped detail ("Move aterm.app
            // to your Applications folder…") is a worse lie than the vague
            // line it decorates.
            detail: Some(PLATFORM_UPDATE_LANE.to_string()),
            ..update.clone()
        };
        &honest
    };
    let text_scale = settings_text_scale();
    let compact = width == SettingsWidth::Compact;
    let viewport = LogicalRect::new(0.0, 0.0, viewport_width, viewport_height);
    let gap = settings_page_gap(state, width, viewport);
    let subtitle = if update.linux_host {
        "Updating keeps open terminals running."
    } else {
        update_page_subtitle(native_updater_here(availability))
    };
    let (heading, heading_height) =
        pinned_heading(state, width, viewport, gap, "Software Update", subtitle);
    // The status card names the page only where nothing else does (a window
    // too short for the heading row whose toolbar cannot hold the title):
    // under the heading, or the toolbar's title, it would say it twice.
    let card_titled = !page_named(width, viewport);
    // The room the page's list has under its heading: every section is
    // authored to fit it whole.
    let room = (settings_list_body_height(state, width, viewport) - heading_height)
        .max(scaled_control_height());
    let overhang = settings_list_overhang(state, width, viewport);
    let compact_section_height = room;

    // The two cards are measured for the side-by-side layout's measure; where
    // they stack, the page is a form ([`PageLayout`]) and every card takes
    // the form's measure, as on every other single-column page.
    let columns_width =
        settings_page_content_width(viewport_width, width, PageLayout::Columns.maximum(width));
    // Prose inside the two cards wraps to the measure each card really gets —
    // the BOX ITS WORDS ARE DRAWN IN, no narrower and no wider: full width when
    // the page stacks, and the workbench fractions when the desktop layout sets
    // them side by side. The fractions share the row less its gap: measured
    // against the whole row, the gap's share painted a caption line 0.1pt over
    // (2026-09-23). A 6pt "wrap slack" under every measure used to absorb that
    // error, and with it wrapped every switch name and sentence on the page 6pt
    // short of its box; the painter's own fit slack ([`native_ui::TEXT_FIT_SLACK`])
    // is what f32 rounding costs. No floor either: a 48pt floor claimed a column
    // a phone-width card at large text does not have.
    const WORKBENCH_GAP: f32 = 16.0;
    let shared = columns_width - WORKBENCH_GAP;
    let side_text_width = |status_share: f32| (shared * (1.0 - status_share) - 40.0).max(0.0);
    // The two cards sit side by side only where the switches' card holds each
    // switch on one line in its worst case (written: Changed and Reset beside
    // it) and the status card still holds its one-line headline whole — at the
    // status card's usual share of the row, else half of it; anywhere narrower
    // the status card and the switches' card stack, each the page's width,
    // rather than cut either card's words.
    let (headline_px, headline_face) =
        crate::native_ui::text_paint_metrics(SemanticRole::Heading, StyleRef::Hero);
    let headline_width =
        crate::tray_raster::ui_text_width_for(headline_face, &update.headline, headline_px);
    let action_height = 36.0_f32.max(32.0 * text_scale);
    // AND ONLY WHERE THE PAIR FITS THE LIST'S ROOM, side by side one stop
    // (its tersest status rung, as the page builds it): taller than any
    // screen (218pt in the 72pt list of a 220x12 window), the workbench was
    // cut on every screen and its switches were on none; stacked, each card
    // is listed row by row and split where it outgrows the room
    // ([`scroll::SplitCard`]).
    let side_by_side_fits = |share: f32| {
        let status_width = (shared * share - 44.0).max(0.0);
        let action = update_action_node(update, action_height, status_width);
        let status = std::iter::once(StatusLineBudget::FULL)
            .chain(StatusLineBudget::desktop_ladder().skip(1))
            .map(|lines| {
                update_status_card(
                    update,
                    width,
                    StatusCardShape {
                        titled: card_titled,
                    },
                    status_width,
                    Some(action.clone()),
                    action_height,
                    lines,
                )
                .1
            })
            .fold(f32::INFINITY, f32::min);
        let automatic = update_automatic_cards(
            state,
            update.linux_host,
            availability,
            width,
            side_text_width(share),
            Some(room),
        )
        .into_iter()
        .map(|(_, height)| height)
        .fold(0.0, f32::max);
        status.max(automatic) <= room + 0.01
    };
    let status_share = (!compact)
        .then(|| {
            [0.62_f32, 0.5].into_iter().find(|share| {
                update_switches_fit_inline(state, side_text_width(*share))
                    && headline_width <= shared * share - 44.0
                    && side_by_side_fits(*share)
            })
        })
        .flatten();
    let layout = if status_share.is_some() {
        PageLayout::Columns
    } else {
        PageLayout::Form
    };
    let notes_width = settings_page_content_width(viewport_width, width, layout.maximum(width));
    let notes_text_width = (notes_width - update_release_notes_padding() * 2.0).max(48.0);
    let (status_text_width, automatic_text_width) = match status_share {
        Some(share) => ((shared * share - 44.0).max(0.0), side_text_width(share)),
        None => ((notes_width - 44.0).max(0.0), (notes_width - 40.0).max(0.0)),
    };
    let action = update_action_node(update, action_height, status_text_width);
    // The action rides inside the status card, the Messages link beside it where
    // the card's measure holds both, wherever the card with them fits the list's
    // room and its words are one line of the card's column — measured, not a
    // fixed height nor the text size — and is a stop of its own after the card,
    // the list's width, on a compact page where it does not.
    let action_in_card =
        update_action_words(update, status_text_width).is_some_and(|words| !words.contains('\n'));
    let list_action = update_action_node(update, action_height, notes_width);
    let split_action = compact
        && (!action_in_card || {
            let (_, with_action) = update_status_card(
                update,
                width,
                StatusCardShape {
                    titled: card_titled,
                },
                status_text_width,
                Some(action.clone()),
                action_height,
                StatusLineBudget::FULL,
            );
            with_action > room
        });
    // A copy that can't replace itself has no release notes coming; the status
    // card already says why, so the page carries no empty notes card for it.
    // The notes are one card the list reads paragraph by paragraph
    // ([`update_release_notes_card`]).
    let notes_cards = |room: f32| {
        if update.installable.is_installable() || update.linux_host {
            vec![update_release_notes_card(update, room, notes_text_width)]
        } else {
            Vec::new()
        }
    };

    // The most one section of a desktop page gets: the list's whole room.
    let noncompact_section_room = (!compact).then_some(room);
    let build = |lines: StatusLineBudget| {
        let (status, status_height) = update_status_card(
            update,
            width,
            StatusCardShape {
                titled: card_titled,
            },
            status_text_width,
            (!split_action).then(|| action.clone()),
            action_height,
            lines,
        );
        let automatic = update_automatic_cards(
            state,
            update.linux_host,
            availability,
            width,
            automatic_text_width,
            Some(noncompact_section_room.unwrap_or(compact_section_height)),
        );
        (status, status_height, automatic)
    };
    let mut built = build(StatusLineBudget::FULL);
    // A desktop status card fits the section it is windowed into, as the automatic
    // card's caption steps down within the same budget: the outcome steps down first,
    // then the detail ([`StatusLineBudget::desktop_ladder`]); where no rung fits, the
    // tersest one paints.
    if let Some(room) = noncompact_section_room
        && built.1 > room
    {
        for lines in StatusLineBudget::desktop_ladder().skip(1) {
            built = build(lines);
            if built.1 <= room {
                break;
            }
        }
    }
    let (status, status_height, automatic) = built;

    if compact {
        // THE FORM IS MEASURED, NOT GUESSED FROM THE WINDOW'S SHAPE (s-1, s-3): the
        // page takes the form whose first screen shows the status card whole with
        // the most switches beside it, asking the plan the list draws. Both forms'
        // status cards say the whole status — the headline, and the detail
        // sentence with its cause or remedy — so no form trades the remedy for a
        // switch. On a tie the full card, whose headline is whole, wins over the
        // two-column summary. A form whose status card is not whole on the first
        // screen (the full card in a short landscape list at the platform maximum
        // Dynamic Type, listed row by row) ranks under every form whose card is.
        let switches = [
            UiKey::new(format!("settings/control/{}", prefs::EDIT_UPDATE_ENABLED)),
            UiKey::new("settings/control/update.auto_apply"),
        ];
        let rank = |items: &[(UiNode, f32)]| {
            let listed = items
                .iter()
                .map(|(node, height)| ListItem::of(node.clone(), *height))
                .collect::<Vec<_>>();
            scroll::first_screen_holds(&listed, gap, room, overhang, &switches)
                .map_or(-1, |shown| shown as i32)
        };
        let full = compact_update_full_items(
            status,
            split_action.then(|| list_action.clone()),
            automatic.clone(),
            notes_cards(compact_section_height),
            notes_width,
            action_height,
        );
        let summary = compact_update_summary_items(
            update,
            if action_in_card {
                action.clone()
            } else {
                list_action.clone()
            },
            automatic.clone(),
            notes_cards(compact_section_height),
            SummaryPlace {
                notes_width,
                card_titled,
                room,
                action_height,
            },
        );
        let mut best = (rank(&full), full);
        if let Some(form) = summary {
            let ranked = rank(&form);
            if ranked > best.0 {
                best = (ranked, form);
            }
        }
        return (
            update_list(state, heading, best.1, room, gap, overhang),
            layout,
        );
    }

    let notes = notes_cards(room);
    // Desktop widths put the two cards side by side where the switches fit
    // beside the status, else one over the other; the notes beneath.
    debug_assert!(automatic.len() <= 1);
    let Some(status_share) = status_share else {
        let mut sections = vec![(status, status_height)];
        sections.extend(automatic);
        sections.extend(with_heights(notes));
        return (
            update_list(state, heading, sections, room, gap, overhang),
            layout,
        );
    };
    let workbench = match automatic.into_iter().next() {
        Some((mut automatic, automatic_height)) => {
            let height = status_height.max(automatic_height);
            // Both cards own the full row height so the pair reads as one band
            // rather than two cards of different depth.
            automatic.layout.height = Length::Fill;
            UiNode::new(
                "updates/workbench",
                UiContent::Group(GroupSpec::new("Update status and automatic updates")),
            )
            .layout(
                Layout::row()
                    .height(Length::Fixed(height))
                    .gap(WORKBENCH_GAP)
                    .clipped(),
            )
            .children(vec![
                status.layout(
                    Layout::column()
                        .width(Length::Fraction(status_share))
                        .height(Length::Fill)
                        .padding(Insets::symmetric(22.0, 20.0))
                        .gap(8.0),
                ),
                automatic,
            ])
        }
        None => status,
    };
    let mut sections = vec![workbench];
    sections.extend(notes);
    (
        update_list(state, heading, with_heights(sections), room, gap, overhang),
        layout,
    )
}

/// Software Update's sections, with their heights, as one scrolling list
/// under its `heading` whose screens draw their peek; a list that fits whole
/// in its `room` and the `overhang` kept under it for a status bar
/// ([`settings_list_overhang`]) takes both ([`scroll::list_page_peeking`]).
fn update_list(
    state: &SettingsViewState,
    mut heading: Vec<UiNode>,
    sections: Vec<(UiNode, f32)>,
    room: f32,
    gap: f32,
    overhang: scroll::Overhang,
) -> Vec<UiNode> {
    heading.push(scroll::list_page_peeking(
        state,
        "updates/list",
        "Software Update",
        sections
            .into_iter()
            .map(|(node, height)| ListItem::of(node, height))
            .collect(),
        room,
        gap,
        overhang,
    ));
    heading
}

/// Sections authored at a fixed height, with it.
fn with_heights(sections: Vec<UiNode>) -> Vec<(UiNode, f32)> {
    sections
        .into_iter()
        .map(|node| {
            let height = fixed_height(&node);
            (node, height)
        })
        .collect()
}

/// Bounded program rows: 16 holds the whole shipped index with room to grow; past
/// it, the overflow line says how many are elided.
const MAX_PACKAGE_PROGRAM_ROWS: usize = 16;

/// The budget one program-row line gets before it wraps, per layout, in the wrap's
/// units — average lowercase glyphs (`packages_screen::glyph_advance`, 2026-09-15; from
/// the 2026-09-14 incident — a ~700-character refusal ellipsized to one line, its `fix:`
/// clause the part cut). The rows paint at the Caption step (11px × text scale,
/// `SemanticRole::Status`), and `SettingsWidth` is chosen on the scale-divided viewport,
/// so one budget per width holds at every text scale. The page is a form
/// ([`PageLayout::Form`]) at every width, so its rows paint at 402pt (the 474pt
/// compact test viewport) or ≈680pt (the form measure less the card's padding), and a
/// unit of the advance table is at most 0.35pt at 1× on the incident's own lines — so
/// 402/0.35/20 ≈ 57 and 680/0.35/20 ≈ 97, each taken a little under. The painter's
/// ellipsis stays the last resort for a pathological line, never the layout; the paint
/// audit in the tests measures the claim.
fn packages_reason_wrap_chars(width: SettingsWidth) -> usize {
    match width {
        SettingsWidth::Compact => 56,
        SettingsWidth::Medium | SettingsWidth::Wide => 96,
    }
}

/// One line of the Packages program list: a program row (its canonical state verbatim),
/// one of its wrapped reason/facts/detail lines, or the overflow/empty/loading line.
#[derive(Clone, Debug, PartialEq, Eq)]
struct ProgramLine {
    key: String,
    text: String,
    /// A wrapped continuation of the row above it: one line of a long reason
    /// (`packages_screen::reason_lines`). Text only, full width; the compact page
    /// gives it neither a label nor a control.
    continuation: bool,
    /// A row's detail line (updated, latest known), painted quiet under the row's own
    /// words.
    quiet: bool,
    /// atpkg's canonical state line, verbatim, on a program row whose words say it
    /// plainly instead: the row's accessible value (its semantic label's second
    /// line), so assistive tech and `controls` introspection read what `status.toml`,
    /// `doctor` and the log say.
    state: Option<String>,
}

/// The program list (an agent program's row with its vendor · license · size). Pure:
/// the wide page, the compact page and the row counts all read this one derivation.
/// `width` sets the budget a long reason wraps to (`packages_reason_wrap_chars`); a
/// state that fits rides inline.
fn packages_program_lines(packages: &PackagesProjection, width: SettingsWidth) -> Vec<ProgramLine> {
    let plain = |key: &str, text: String| ProgramLine {
        key: key.to_string(),
        text,
        continuation: false,
        quiet: false,
        state: None,
    };
    if !packages.observed {
        return vec![plain(
            "packages/programs/loading",
            "Reading package status…".to_string(),
        )];
    }
    if packages.programs.is_empty() {
        return vec![plain(
            "packages/programs/empty",
            "No managed programs installed.".to_string(),
        )];
    }
    let mut lines = Vec::new();
    let mut shown = 0usize;
    for row in &packages.programs {
        if shown >= MAX_PACKAGE_PROGRAM_ROWS {
            break;
        }
        shown += 1;
        let wrap = packages_reason_wrap_chars(width);
        let mut text = package_program_display_name(&row.name);
        // An installed program is named by its facts in plain words: its version (a
        // vendor build's, never its store id; an index build's number) and what its
        // state says (`up to date`, `latest from Anthropic`, `you pinned it`), with
        // when it was updated and any newer build on the detail line. A row with no
        // installed build says its state in words too. A state with no plain words (a
        // fault, anything this page does not parse) rides the row verbatim. Either
        // way the canonical line is the row's accessible value.
        let plain = crate::packages_screen::plain_state(&row.kind, &row.state);
        let show_state = match row.words.as_ref() {
            Some(words) => {
                text.push_str(FACT_SEPARATOR);
                text.push_str(&words.summary);
                plain.is_none()
            }
            None => {
                if let Some(build) = row.installed_build {
                    text.push_str(FACT_SEPARATOR);
                    text.push_str(&atpkg::vendor_direct::build_words(build));
                }
                if let Some(plain) = plain.as_deref() {
                    text.push_str(FACT_SEPARATOR);
                    text.push_str(plain);
                }
                plain.is_none()
            }
        };
        // What follows the row's own words: the product facts, the upstream an ALab
        // build is based on and a dev-link annotation.
        let mut tail = String::new();
        if let Some(facts) = row.facts.as_ref() {
            tail.push_str(FACT_SEPARATOR);
            tail.push_str(&facts.line());
        }
        if let Some(upstream) = row.upstream.as_deref() {
            tail.push_str(FACT_SEPARATOR);
            tail.push_str(upstream);
        }
        if let Some(annotation) = row.annotation.as_deref() {
            tail.push_str(FACT_SEPARATOR);
            tail.push_str(annotation);
        }
        // A state that fits the row rides inline verbatim (the canonical spellings,
        // byte-for-byte); one that does not (a long refusal, or a short state beside a
        // row's facts) moves below its row as continuation lines, fix first, so none
        // of it meets the painter's ellipsis.
        let state_lines = if show_state && !row.state.is_empty() {
            crate::packages_screen::reason_lines(&row.state, wrap)
        } else {
            Vec::new()
        };
        let inline_state = state_lines.len() == 1
            && crate::packages_screen::fits_one_line(
                &format!("{text}{FACT_SEPARATOR}{}{tail}", row.state),
                wrap,
            );
        if inline_state {
            text.push_str(FACT_SEPARATOR);
            text.push_str(&row.state);
        }
        let below = if inline_state {
            Vec::new()
        } else {
            state_lines
        };
        // The detail (why a kept row is not current, when it was updated, the latest
        // build known) rides inline after the row's own words when the whole line fits
        // and nothing else goes below; else under the row, quiet, wrapped between its
        // parts.
        let detail = row.words.as_ref().and_then(|w| w.detail.clone());
        let detail_lines = match detail {
            Some(detail)
                if below.is_empty()
                    && crate::packages_screen::fits_one_line(
                        &format!("{text}{FACT_SEPARATOR}{detail}{tail}"),
                        wrap,
                    ) =>
            {
                text.push_str(FACT_SEPARATOR);
                text.push_str(&detail);
                Vec::new()
            }
            Some(detail) => packages_detail_lines(&detail, wrap),
            None => Vec::new(),
        };
        // The facts that follow ride the row when they fit; else they move under it
        // (after a state that went below — the fix comes first), wrapped between their
        // parts, so the row's own words are never the part the painter's ellipsis eats.
        let tail_lines = if tail.is_empty()
            || crate::packages_screen::fits_one_line(&format!("{text}{tail}"), wrap)
        {
            text.push_str(&tail);
            Vec::new()
        } else {
            packages_detail_lines(tail.trim_start_matches(FACT_SEPARATOR), wrap)
        };
        lines.push(ProgramLine {
            key: format!("packages/programs/{}", row.name),
            text,
            continuation: false,
            quiet: false,
            state: (!show_state && !row.state.is_empty()).then(|| row.state.clone()),
        });
        lines.extend(
            below
                .into_iter()
                .enumerate()
                .map(|(index, text)| ProgramLine {
                    key: format!("packages/programs/{}/reason/{}", row.name, index + 1),
                    text,
                    continuation: true,
                    quiet: false,
                    state: None,
                }),
        );
        let facts = tail_lines.len() > 1;
        lines.extend(
            tail_lines
                .into_iter()
                .enumerate()
                .map(|(index, text)| ProgramLine {
                    key: if facts {
                        format!("packages/programs/{}/facts/{}", row.name, index + 1)
                    } else {
                        format!("packages/programs/{}/facts", row.name)
                    },
                    text,
                    continuation: true,
                    quiet: false,
                    state: None,
                }),
        );
        let many = detail_lines.len() > 1;
        lines.extend(
            detail_lines
                .into_iter()
                .enumerate()
                .map(|(index, text)| ProgramLine {
                    key: if many {
                        format!("packages/programs/{}/detail/{}", row.name, index + 1)
                    } else {
                        format!("packages/programs/{}/detail", row.name)
                    },
                    text,
                    continuation: true,
                    quiet: true,
                    state: None,
                }),
        );
    }
    let total = packages.programs.len();
    if total > shown {
        lines.push(plain(
            "packages/programs/more",
            format!(
                "… and {} more (aterm pkg list shows them all)",
                total - shown
            ),
        ));
    }
    lines
}

/// The node for one program line: its status text, keyed `packages/programs/<name>`.
fn packages_program_line_node(line: &ProgramLine, row_height: f32) -> UiNode {
    let painted = UiContent::Text(TextSpec {
        text: line.text.clone(),
        role: SemanticRole::Status,
        style: if line.quiet {
            StyleRef::Quiet
        } else {
            StyleRef::Primary
        },
    });
    let text = match line.state.as_deref() {
        Some(state) => program_state_node(line.key.clone(), painted, &line.text, state),
        None => UiNode::new(line.key.clone(), painted),
    };
    text.layout(Layout::default().height(Length::Fixed(row_height)))
}

/// A row whose words replace atpkg's state keeps that state as its accessible value:
/// one semantic node (the words, then the canonical line `status.toml`, `doctor` and
/// the log say) over the painted words.
fn program_state_node(key: String, painted: UiContent, words: &str, state: &str) -> UiNode {
    UiNode::new(
        key.clone(),
        UiContent::Group(GroupSpec {
            label: Some(format!("{words}\n{state}")),
            role: SemanticRole::Status,
            style: StyleRef::Plain,
        }),
    )
    .children(vec![
        UiNode::new(format!("{key}/text"), painted)
            .layout(Layout::default().height(Length::Fill))
            .paint_only(),
    ])
}

/// A row's detail as lines of at most `wrap` (the reason wrap's measure), broken only
/// between its ` · ` parts, in order; a part longer than a line is a line of its own.
fn packages_detail_lines(detail: &str, wrap: usize) -> Vec<String> {
    let mut lines: Vec<String> = Vec::new();
    for part in detail.split(FACT_SEPARATOR) {
        match lines.last_mut() {
            Some(line)
                if crate::packages_screen::fits_one_line(
                    &format!("{line}{FACT_SEPARATOR}{part}"),
                    wrap,
                ) =>
            {
                line.push_str(FACT_SEPARATOR);
                line.push_str(part);
            }
            _ => lines.push(part.to_string()),
        }
    }
    lines
}

/// Where the signed builds come from, said only when there is a package tool
/// to fetch them and a source to name.
fn packages_has_service_line(packages: &PackagesProjection) -> bool {
    packages.observed
        && packages.available
        && packages.manager_enabled
        && !packages.index_source.is_empty()
}

// Settings ▸ Messages (design §4).

/// Every action the Messages page authors starts here; the reducer routes
/// the family in one arm (`SettingsApp::reduce_messages_action`).
const MESSAGES_ACTION_PREFIX: &str = "settings/messages/";

/// The deep link's action (design §4.5): `settings/messages/select` with
/// `SemanticInput::Text("<id>")`, text rather than `Number(f64)`, which is inexact
/// above 2^53. The host dispatches it after `open_settings_tab_in_window`
/// (`App::open_messages_entry`).
pub(crate) const MESSAGES_SELECT: &str = "settings/messages/select";

/// Settings ▸ Messages with a tag chip down: `settings/messages/show/<tag>` —
/// the chip a press on it would set, after the navigation that clears the
/// filter. Software Update's "View Messages" link is the update chip.
pub(crate) const MESSAGES_SHOW_UPDATE: &str = "settings/messages/show/update";

/// The most lines the Messages filters take as chips on a wider page; past it the
/// tags go in the pop-up.
const MESSAGES_FILTER_LINES_MAX: usize = 2;

/// How long the Messages page's status line stands at least, once a projection has
/// seen it. The host arms the publish that clears it (`App::messages_publish_due_at`),
/// so it stands about this long, not until the next minute tick.
pub(crate) const MESSAGES_FEEDBACK_MS: u64 = 5_000;

/// Whether `node` or anything under it is keyed `key`.
fn ui_node_holds(node: &UiNode, key: &str) -> bool {
    node.key.as_str() == key || node.children.iter().any(|child| ui_node_holds(child, key))
}

/// The entry a Settings ▸ Messages key belongs to: its title or one of its
/// own buttons (`settings/messages/row/<id>/…`).
fn messages_row_of(key: &str) -> Option<u64> {
    key.strip_prefix("settings/messages/row/")?
        .split('/')
        .next()?
        .parse()
        .ok()
}

/// The first control under `node` a person can focus, in authoring order.
fn first_focusable_key(node: &UiNode) -> Option<UiKey> {
    let focusable = matches!(
        node.content,
        UiContent::Button(_)
            | UiContent::Switch(_)
            | UiContent::Slider(_)
            | UiContent::TextField(_)
    );
    if focusable && !node.paint_only {
        return Some(node.key.clone());
    }
    node.children.iter().find_map(first_focusable_key)
}

/// The link Settings ▸ Software Update carries to its record: Settings ▸ Messages with
/// the update chip down ([`MESSAGES_SHOW_UPDATE`], the chip a press on it would set) —
/// every update's download, install and landing, and why one did not install.
fn messages_link_button(key: &str, width: f32, height: f32) -> UiNode {
    // In a button narrower than its word and its arrow (a phone-width page at
    // large text) the word keeps the room and the arrow goes: "Messa…" read as
    // a cut word, where the button still goes to the same page without it.
    let mut spec = messages_link_spec();
    if crate::native_ui::native_button_label_width("Messages")
        > crate::native_ui::text_button_label_room(&spec, width) + crate::native_ui::TEXT_FIT_SLACK
    {
        spec.trailing_icon = None;
    }
    UiNode::new(
        key,
        UiContent::Button(
            Control::new(spec, ActionId::new(MESSAGES_SHOW_UPDATE)).style(StyleRef::Secondary),
        ),
    )
    .layout(
        Layout::default()
            .width(Length::Fixed(width))
            .height(Length::Fixed(height)),
    )
}

fn messages_link_spec() -> ButtonSpec {
    ButtonSpec::new("Open Settings \u{25b8} Messages")
        .visual_label("Messages")
        .trailing_icon(ButtonIcon::Forward)
}

/// The width of [`messages_link_button`]: its label MEASURED at the live text
/// size, with the lead and the arrow's slot the painter keeps around it
/// ([`crate::native_ui::text_button_label_room`]), at least a touch target
/// wide — never a fixed width that is too wide at 1× and capped at 1.5×.
fn messages_link_width() -> f32 {
    let spec = messages_link_spec();
    // What the painter keeps beside the label in a button of any width.
    let probe = 1_000.0;
    let reserve = probe - crate::native_ui::text_button_label_room(&spec, probe);
    (crate::native_ui::native_button_label_width("Messages") + reserve)
        .ceil()
        .max(72.0)
}

// The filter (`MessagesFilter`), the chip identity (`messages_same_chip`), the
// not-saved note, the count line's words, the day clock (`MessagesClock`) and
// an entry's spoken description are the page MODEL's: `aterm_messages::page`
// (design ruling 382), imported under these names at the top of this file.
// So are the page's CHROME words (ruling 395): the heading, the subtitle, the
// segments', chips' and pop-up's words, Copy and Copy All and what Copy All
// copies, a footer button's `Open …`, the meta line, `Technical details` and
// the empty log's `Nothing yet.` (`MESSAGES_EMPTY`). The macOS page's own
// affordance keeps its words here: `Open Log Folder`.

/// Copy All's action: the shown entries, newest first, and the build
/// information on top.
const MESSAGES_COPY_ALL: &str = "settings/messages/copy-all";
/// Show All's action, where the filters admit nothing: both filters lift.
const MESSAGES_SHOW_ALL: &str = "settings/messages/show-all";
/// Open Log Folder's action: the host opens the log directory itself.
const MESSAGES_OPEN_FOLDER: &str = "settings/messages/open-folder";
/// The compact page's tag pop-up (`Tag: All ▾`): opens the tag list in place.
const MESSAGES_TAG_MENU: &str = "settings/messages/tag-menu";
/// The tag list's first chip: every tag.
const MESSAGES_TAGS_ALL: &str = "settings/messages/filter/tags-all";
/// What every chip of the tag list begins with: `…/filter/tags-all` and each
/// `…/filter/tag/<tag>`.
const MESSAGES_TAG_CHIPS: &str = "settings/messages/filter/tag";

/// A collapsed entry: one line, 30·s pt.
fn messages_row_height() -> f32 {
    30.0 * settings_text_scale()
}

/// A day header over a day's entries: 26·s pt, its caption low, near the rows it
/// names.
fn messages_day_height() -> f32 {
    26.0 * settings_text_scale()
}

/// One meta or sentence line of an expanded entry: 22·s pt.
fn messages_line_height() -> f32 {
    22.0 * settings_text_scale()
}

/// One technical-details line: the caption step's monospace, 18·s pt.
fn messages_code_line_height() -> f32 {
    18.0 * settings_text_scale()
}

/// A small secondary button (an entry's footer, Copy All, Open Log Folder):
/// a pointer target, never a slab.
fn messages_small_button_height() -> f32 {
    28.0_f32.max(26.0 * settings_text_scale().min(1.6))
}

/// The gap between the items of a compact page's section.
const MESSAGES_ROW_GAP: f32 = 6.0;

/// The gap between an expanded entry's text and its buttons.
const MESSAGES_FOOTER_GAP: f32 = 12.0;

/// The list container's inner padding, top and bottom.
const MESSAGES_LIST_PAD: f32 = 4.0;

/// The entries the filters admit, newest first (the projection's order).
fn messages_visible<'a>(
    messages: &'a MessagesState,
    filter: &MessagesFilter,
) -> Vec<&'a MessageView> {
    messages
        .entries
        .iter()
        .filter(|entry| filter.admits(entry))
        .collect()
}

/// The page's subtitle, the engine's (`MessagesState::subtitle`, ruling 395):
/// what the log is (design §10.11), and that the open items lead it while one
/// does. One line at every width (it fits the 286.5 pt phone page).
fn messages_page_subtitle(messages: &MessagesState) -> &'static str {
    messages.subtitle()
}

/// A status-sized line whose whole text is the semantic node's label and whose painted
/// child is fitted to `width` (the pager's pattern), so a narrow page at large type
/// paints `12 of 4…` rather than overflowing its box.
fn messages_fitted_status(key: &str, words: String, width: Length, fit_width: f32) -> UiNode {
    let visual = crate::native_ui::fit_native_status_label(&words, (fit_width - 4.0).max(24.0));
    UiNode::new(
        key.to_string(),
        UiContent::Group(GroupSpec {
            label: Some(words),
            role: SemanticRole::Status,
            style: StyleRef::Quiet,
        }),
    )
    .layout(Layout::default().width(width).height(Length::Fill))
    .children(vec![
        UiNode::new(
            format!("{key}/visual"),
            UiContent::Text(TextSpec {
                text: visual,
                role: SemanticRole::Status,
                style: StyleRef::Quiet,
            }),
        )
        .layout(Layout::default().width(Length::Fill).height(Length::Fill))
        .paint_only(),
    ])
}

/// THE COUNT LINE'S WORDS (`words`: the count, and the page's note after
/// it), its lines in a column `fit_width` wide: the count on as many lines as
/// it needs, whole ("40 messa…" at 2× on a phone-width page); the note on
/// the count's last line, fitted to what that line leaves — where the count
/// decides the line's place (round 17 review, V4), a five-second note never
/// moves the buttons under it by a line of its own. The group's name says
/// both whole. Returns the node and its line count.
fn messages_count_status(
    words: String,
    count: Option<&str>,
    note: Option<&str>,
    fit_width: f32,
) -> (UiNode, usize) {
    let key = "settings/messages/status";
    let room = (fit_width - 4.0).max(24.0);
    let (px, face) = crate::native_ui::text_paint_metrics(SemanticRole::Status, StyleRef::Quiet);
    let mut lines = count.map_or_else(Vec::new, |count| {
        wrap_to_box(count, room, &|line| {
            crate::tray_raster::ui_text_width_for(face, line, px)
        })
    });
    if let Some(note) = note {
        let last = lines.pop().map_or_else(
            || note.to_string(),
            |last| format!("{last} \u{00b7} {note}"),
        );
        lines.push(crate::native_ui::fit_native_status_label(&last, room));
    }
    let count = lines.len().max(1);
    let line = |key: String, text: String, height: Length| {
        UiNode::new(
            key,
            UiContent::Text(TextSpec {
                text,
                role: SemanticRole::Status,
                style: StyleRef::Quiet,
            }),
        )
        .layout(Layout::default().width(Length::Fill).height(height))
        .paint_only()
    };
    let children = if count == 1 {
        vec![line(
            format!("{key}/visual"),
            lines.pop().unwrap_or_default(),
            Length::Fill,
        )]
    } else {
        let height = Length::Fixed(messages_line_height());
        lines
            .into_iter()
            .enumerate()
            .map(|(index, text)| line(format!("{key}/visual/line-{index}"), text, height))
            .collect()
    };
    (
        UiNode::new(
            key,
            UiContent::Group(GroupSpec {
                label: Some(words),
                role: SemanticRole::Status,
                style: StyleRef::Quiet,
            }),
        )
        .layout(Layout::column().width(Length::Fill).height(Length::Fill))
        .children(children),
        count,
    )
}

/// A small secondary button: `label` painted, `semantic` its name, measured
/// to its label (never full-width, ruling 262).
fn messages_small_button(key: &str, label: &str, semantic: &str, enabled: bool) -> (UiNode, f32) {
    let px = crate::native_ui::native_type_px(crate::type_scale::TypeStep::Secondary).get();
    let width =
        crate::tray_raster::ui_text_width_for(crate::widget::TextFace::Ui, label, px) + 24.0;
    let node = UiNode::new(
        key.to_string(),
        UiContent::Button(
            Control::new(
                ButtonSpec::new(semantic).visual_label(label),
                ActionId::new(key.to_string()),
            )
            .state(ControlState {
                enabled,
                ..ControlState::default()
            })
            .style(StyleRef::Secondary),
        ),
    )
    .layout(
        Layout::default()
            .width(Length::Fixed(width))
            .height(Length::Fixed(messages_small_button_height())),
    );
    (node, width)
}

/// The count line: the count on the left, Copy All and Open Log Folder small on the
/// right. An empty log has no count, and nothing to copy.
fn messages_count_line(
    words: Option<String>,
    note: Option<&str>,
    content_width: f32,
    can_copy: bool,
) -> (UiNode, f32) {
    let (spx, sface) = crate::native_ui::text_paint_metrics(SemanticRole::Status, StyleRef::Quiet);
    // Where the buttons go is the count's decision alone: a note joining it (`The log
    // folder is <path>`) must not push the buttons under the count and move the one
    // just pressed. The note is fitted into the status width left.
    let words_w = words.as_deref().map_or(0.0, |w| {
        crate::tray_raster::ui_text_width_for(sface, w, spx) + 8.0
    });
    // The page's own confirmation rides the count (ruling 270).
    let count = words.clone();
    let words = match (words, note) {
        (Some(words), Some(note)) => Some(format!("{words} \u{00b7} {note}")),
        (None, Some(note)) => Some(note.to_string()),
        (words, None) => words,
    };
    let (copy, copy_w) = messages_small_button(
        MESSAGES_COPY_ALL,
        aterm_messages::page::COPY_ALL,
        aterm_messages::page::COPY_ALL_NAME,
        can_copy,
    );
    let (folder, folder_w) = messages_small_button(
        MESSAGES_OPEN_FOLDER,
        "Open Log Folder",
        "Open Log Folder",
        true,
    );
    let button_h = messages_small_button_height();
    // A button wider than the whole column (a phone-width page at 2× text)
    // keeps its words on as many lines as the column needs ([`button_words`]),
    // never past the page's edge ("Open Log Folder" ran 87pt off it).
    let fit = |(mut node, width): (UiNode, f32), label: &str| -> (UiNode, f32, f32) {
        if width <= content_width + crate::native_ui::TEXT_FIT_SLACK {
            return (node, width, button_h);
        }
        let (words, lines) = button_words(label, &[], content_width);
        if let UiContent::Button(button) = &mut node.content {
            button.spec.visual_label = Some(words);
        }
        let height = crate::native_ui::native_button_height_for_lines(lines, button_h);
        node.layout.width = Length::Fixed(content_width);
        node.layout.height = Length::Fixed(height);
        (node, content_width, height)
    };
    let (copy, copy_w, copy_h) = fit((copy, copy_w), aterm_messages::page::COPY_ALL);
    let (folder, folder_w, folder_h) = fit((folder, folder_w), "Open Log Folder");
    // The buttons beside the count where both fit; else under it, right-aligned.
    let beside = words_w + copy_w + folder_w + 16.0 <= content_width;
    let status_w = if beside {
        (content_width - copy_w - folder_w - 16.0).max(24.0)
    } else {
        content_width
    };
    let (status, status_lines) = match words {
        Some(words) => messages_count_status(words, count.as_deref(), note, status_w),
        None => (
            UiNode::new(
                "settings/messages/status-spacer",
                UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
            )
            .layout(Layout::default().width(Length::Fill).height(Length::Fill)),
            1,
        ),
    };
    let row = |key: &str, children: Vec<UiNode>, height: f32| {
        UiNode::new(
            key.to_string(),
            UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
        )
        .layout(
            Layout::row()
                .width(Length::Fill)
                .height(Length::Fixed(height))
                .gap(8.0),
        )
        .children(children)
    };
    if beside {
        return (
            row(
                "settings/messages/header",
                vec![status, copy, folder],
                button_h,
            ),
            button_h,
        );
    }
    let spacer = |key: &str| {
        UiNode::new(
            key.to_string(),
            UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
        )
        .layout(Layout::default().width(Length::Fill).height(Length::Fill))
    };
    // Under the count: both buttons on one row where they fit, else one each.
    let button_rows = if copy_w + folder_w + 8.0 <= content_width {
        vec![row(
            "settings/messages/report",
            vec![spacer("settings/messages/report/spacer"), copy, folder],
            copy_h.max(folder_h),
        )]
    } else {
        vec![
            row(
                "settings/messages/report",
                vec![spacer("settings/messages/report/spacer"), copy],
                copy_h,
            ),
            row(
                "settings/messages/report/folder",
                vec![spacer("settings/messages/report/folder-spacer"), folder],
                folder_h,
            ),
        ]
    };
    let line_h = messages_line_height();
    let mut status = status;
    status.layout.height = Length::Fixed(status_lines as f32 * line_h);
    let height = status_lines as f32 * line_h
        + button_rows
            .iter()
            .map(|row| 6.0 + fixed_height(row))
            .sum::<f32>();
    let mut children = vec![status];
    children.extend(button_rows);
    (
        UiNode::new(
            "settings/messages/header",
            UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
        )
        .layout(
            Layout::column()
                .width(Length::Fill)
                .height(Length::Fixed(height))
                .gap(6.0),
        )
        .children(children),
        height,
    )
}

/// The severity filter: `All · 42 | Problems · 23`, a segmented control whose counts
/// are what a press would show under the tag that is down, combined with the tag.
/// "Problems" is the warnings and errors together, the same word painted and spoken.
fn messages_severity_segments(
    messages: &MessagesState,
    filter: &MessagesFilter,
    content_width: f32,
    height: f32,
) -> (UiNode, f32) {
    let px = crate::native_ui::native_type_px(crate::type_scale::TypeStep::Secondary).get();
    let measure = |label: &str| {
        crate::tray_raster::ui_text_width_for(crate::widget::TextFace::UiBold, label, px) + 28.0
    };
    // The counts and their words are the engine's: the web page's `all=`/`problems=`
    // and `all_words=`/`problems_words=` are the same calls.
    let (all, alarms) = messages.severity_counts(filter.tag.as_deref());
    let (all_words, problems_words) = aterm_messages::page::severity_segment_words(all, alarms);
    let segments = [
        ("settings/messages/filter/all", all_words, !filter.warn_only),
        (
            "settings/messages/filter/warn",
            problems_words,
            filter.warn_only,
        ),
    ];
    let widths: Vec<f32> = segments.iter().map(|(_, l, _)| measure(l)).collect();
    let total: f32 = widths.iter().sum::<f32>() + 6.0;
    // One row of two chips where both fit; stacked, each its own width, where
    // not. "Problems" is short enough to need no short form (ruling 264). The
    // chips stand on the filters' card as the tag chips do, spaced, not in a
    // track of their own: a card in a card.
    let stacked = total > content_width;
    let mut stacked_h = 2.0 + 6.0;
    let children = segments
        .into_iter()
        .zip(widths)
        .map(|((key, label, selected), width)| {
            let width = width.min(content_width);
            let mut chip = messages_filter_chip(key, &label, selected, width);
            if stacked {
                let chip_h = messages_chip_height(&label, width, height - 6.0);
                chip.layout.height = Length::Fixed(chip_h);
                stacked_h += chip_h;
            }
            chip
        })
        .collect();
    let (layout, node_h) = if stacked {
        (
            Layout::column()
                .width(Length::Fill)
                .gap(2.0)
                .padding(Insets::symmetric(0.0, 3.0)),
            stacked_h,
        )
    } else {
        (
            Layout::row()
                .width(Length::Fixed(total))
                .padding(Insets::symmetric(0.0, 3.0))
                .gap(6.0),
            height,
        )
    };
    (
        UiNode::new(
            "settings/messages/severity",
            UiContent::Group(GroupSpec {
                label: Some("Severity".to_string()),
                role: SemanticRole::Group,
                style: StyleRef::Plain,
            }),
        )
        .layout(layout.height(Length::Fixed(node_h)))
        .children(children)
        // THE SEVERITY SEGMENTS ARE ONE CONTROL (ruling 267), the same
        // segmented control as every Settings row's ([`UiNode::segmented`]).
        .segmented(),
        node_h,
    )
}

/// ONE FILTER CHIP, severity and tag alike (system-15): a [`StyleRef::Chip`]
/// button in a measured slot, its label centred, `selected` while its filter is
/// down — a solid accent fill, where a resting chip is the card's fill in a 3:1
/// control edge. The two kinds used to be two half-styles: a selected chip a 13%
/// accent wash within 1.06:1 of a resting one (selection carried by hue alone,
/// reading as disabled in greyscale) and a resting one's 1.4:1 hairline rim.
fn messages_filter_chip(key: &str, label: &str, selected: bool, width: f32) -> UiNode {
    let (words, _) = messages_chip_words(label, width);
    UiNode::new(
        key.to_string(),
        UiContent::Button(
            Control::new(
                ButtonSpec::new(label).visual_label(words),
                ActionId::new(key.to_string()),
            )
            .state(ControlState {
                selected,
                ..ControlState::default()
            })
            .style(StyleRef::Chip),
        ),
    )
    .layout(
        Layout::default()
            .width(Length::Fixed(width))
            .height(Length::Fill),
    )
}

/// A filter chip's painted words in a chip `width` wide, and their line
/// count: the label on one line where it fits the room a centred chip keeps
/// clear of its edges, else on as many lines as it needs (never "Proble…"),
/// measured in the wider of the faces a resting and a selected chip paint.
fn messages_chip_words(label: &str, width: f32) -> (String, usize) {
    let px = crate::native_ui::native_type_px(crate::type_scale::TypeStep::Secondary).get();
    let measure = |line: &str| {
        crate::tray_raster::ui_text_width_for(crate::widget::TextFace::UiBold, line, px).max(
            crate::tray_raster::ui_text_width_for(crate::widget::TextFace::Ui, line, px),
        )
    };
    let lines = wrap_to_box(label, (width - 20.0).max(0.0), &measure);
    let count = lines.len();
    (lines.join("\n"), count)
}

/// A filter chip's height in a chip `width` wide whose one line is `single`.
fn messages_chip_height(label: &str, width: f32, single: f32) -> f32 {
    crate::native_ui::native_button_height_for_lines(messages_chip_words(label, width).1, single)
}

/// The TAG chips (ruling 262): `All tags`, then one chip per chip-name present
/// — `fabric` and `harness` under Agents, `toolchain` and `packages` under ALab
/// tools, a script's own tag verbatim — each with its count under the severity
/// that is down, in as few rows as `content_width` needs. A resting chip wears
/// a faint outline so it reads as a button. Returns the rows.
///
/// THE CHIPS ARE ONE BLOCK (design ruling 312; round 21 at 1200 pt: the tags
/// filled the line beside the severity segments, then ran on from the page's
/// left edge under them, a ragged second line that read as a new group). Where
/// the segments lead the first row, every row of chips starts at the x the
/// first chip does; and the rows are BALANCED — each as close to the others'
/// width as the chips allow, never one full line over a stub — so a wrap reads
/// as a deliberate two-line block, aligned on its left edge.
fn messages_tag_chip_rows(
    messages: &MessagesState,
    filter: &MessagesFilter,
    content_width: f32,
    chip_h: f32,
    first: Option<(UiNode, f32)>,
) -> Vec<UiNode> {
    let px = crate::native_ui::native_type_px(crate::type_scale::TypeStep::Secondary).get();
    let measure = |label: &str| {
        crate::tray_raster::ui_text_width_for(crate::widget::TextFace::UiBold, label, px).max(
            crate::tray_raster::ui_text_width_for(crate::widget::TextFace::Ui, label, px),
        ) + 26.0
    };
    // One chip per chip name, keyed by the first tag that shows under it: the
    // engine's chips and words (the web page's `chip` lines and `all_tags=`).
    let mut chips: Vec<(String, String, bool)> = vec![(
        MESSAGES_TAGS_ALL.to_string(),
        aterm_messages::page::ALL_TAGS.to_string(),
        filter.tag.is_none(),
    )];
    chips.extend(messages.chips(filter.warn_only).into_iter().map(|chip| {
        (
            format!("settings/messages/filter/tag/{}", chip.tag),
            chip.label(),
            filter
                .tag
                .as_deref()
                .is_some_and(|t| messages_same_chip(t, &chip.tag)),
        )
    }));
    // The severity segments lead the first row where the page seats them there (the
    // wider pages, filters in at most two rows), and the chips' block starts where
    // they end.
    let indent = first.as_ref().map_or(0.0, |(_, width)| width + 6.0);
    let room = (content_width - indent).max(48.0);
    let widths: Vec<f32> = chips
        .iter()
        .map(|(_, label, _)| measure(label).min(room))
        .collect();
    let mut chips = chips.into_iter().zip(widths.iter().copied());
    let lead_h = first
        .as_ref()
        .map_or(chip_h, |(node, _)| fixed_height(node).max(chip_h));
    let mut lead = first.map(|(node, _)| node);
    messages_chip_row_lengths(&widths, 6.0, room)
        .into_iter()
        .enumerate()
        .map(|(index, len)| {
            let mut children: Vec<UiNode> = lead.take().into_iter().collect();
            // As tall as its tallest chip's words (one wider than the row
            // keeps them on lines).
            let mut row_h = if index == 0 { lead_h } else { chip_h };
            children.extend(
                chips
                    .by_ref()
                    .take(len)
                    .map(|((key, label, selected), width)| {
                        row_h = row_h.max(messages_chip_height(&label, width, chip_h));
                        let mut chip = messages_filter_chip(&key, &label, selected, width);
                        chip.layout.height = Length::Fill;
                        chip
                    }),
            );
            UiNode::new(
                format!("settings/messages/filters/row/{index}"),
                UiContent::Group(GroupSpec::new("Tags")),
            )
            .layout(
                Layout::row()
                    .width(Length::Fill)
                    .height(Length::Fixed(row_h + 6.0))
                    .padding(Insets {
                        top: 3.0,
                        right: 0.0,
                        bottom: 3.0,
                        left: if index == 0 { 0.0 } else { indent },
                    })
                    .gap(6.0),
            )
            .children(children)
        })
        .collect()
}

/// How many chips each row of the tag block holds: as few rows as `room` allows,
/// balanced (the narrowest width that still packs the chips into that many rows, so
/// no row is a full line over a stub). A chip is never split; one wider than `room`
/// has a row of its own.
fn messages_chip_row_lengths(widths: &[f32], gap: f32, room: f32) -> Vec<usize> {
    let pack = |cap: f32| {
        let mut rows: Vec<usize> = Vec::new();
        let mut used = 0.0_f32;
        for &width in widths {
            match rows.last_mut() {
                Some(len) if used + gap + width <= cap => {
                    *len += 1;
                    used += gap + width;
                }
                _ => {
                    rows.push(1);
                    used = width;
                }
            }
        }
        rows
    };
    let fewest = pack(room).len();
    let (mut lo, mut hi) = (widths.iter().copied().fold(0.0_f32, f32::max), room);
    if hi <= lo {
        return pack(room);
    }
    for _ in 0..24 {
        let mid = f32::midpoint(lo, hi);
        if pack(mid).len() <= fewest {
            hi = mid;
        } else {
            lo = mid;
        }
    }
    pack(hi)
}

/// The compact page's TAG POP-UP (ruling 262): one `Tag: All ▾` control; open,
/// the tag chips are listed under it and a press on one closes it. Its words
/// are the engine's (ruling 395).
fn messages_tag_popup(filter: &MessagesFilter, open: bool, width: f32, height: f32) -> UiNode {
    let tag = filter.tag.as_deref();
    // Its words whole beside its chevron, on lines where the pop-up is
    // narrower than them ("Tag:…" at 2× on a phone-width page).
    let spec = ButtonSpec::new(aterm_messages::page::tag_menu_name(tag))
        .trailing_icon(ButtonIcon::ChevronDown);
    let label = aterm_messages::page::tag_menu_label(tag);
    let (words, lines) = button_words_in(&spec, &label, &[], width);
    let height = crate::native_ui::native_button_height_for_lines(lines, height);
    UiNode::new(
        MESSAGES_TAG_MENU,
        UiContent::Button(
            Control::new(spec.visual_label(words), ActionId::new(MESSAGES_TAG_MENU))
                .state(ControlState {
                    expanded: Some(open),
                    ..ControlState::default()
                })
                .style(StyleRef::Secondary),
        ),
    )
    .layout(
        Layout::default()
            .width(Length::Fixed(width))
            .height(Length::Fixed(height)),
    )
}

/// A fixed-height blank.
fn messages_spacer(key: &str, height: f32) -> UiNode {
    UiNode::new(
        key.to_string(),
        UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
    )
    .layout(
        Layout::default()
            .width(Length::Fill)
            .height(Length::Fixed(height)),
    )
}

/// A 1 pt hairline ([`crate::native_ui::MESSAGES_RULE_AUDIT`]): decoration only.
fn messages_rule(key: &str) -> UiNode {
    UiNode::new(
        key.to_string(),
        UiContent::Custom(crate::native_ui::AuditedCustomNode {
            audit_id: crate::native_ui::MESSAGES_RULE_AUDIT,
            role: SemanticRole::Group,
            label: String::new(),
            value: None,
            action: None,
            focusable: false,
            focused: false,
            focus_visible: false,
        }),
    )
    .layout(
        Layout::default()
            .width(Length::Fill)
            .height(Length::Fixed(1.0)),
    )
    .paint_only()
}

/// The lead column: the severity mark, when, and the tag's chip name, one fixed width
/// for every row so every title begins at the same x. `when` is the widest the
/// relative words take (measured); `tag` the longest chip name the log holds, capped
/// (about twelve ems, seven compact) and ellipsized past it. Measured over the whole
/// log, never the filtered list, so titles do not move as the filter changes.
#[derive(Clone, Copy, Debug, PartialEq)]
struct MessagesLead {
    mark: f32,
    when: f32,
    tag: f32,
    gap: f32,
    /// The head stacks: its mark and `when` on its first line, its title on
    /// a line of its own under them across the row ([`messages_head_height`])
    /// — where even the narrowed lead leaves the title less than two fifths
    /// of the row (a phone-width window, where the title had 24pt: "C…").
    stacked: bool,
    /// On a stacked head, the lines `when` takes under the mark where the
    /// log's widest own `when` is wider than the room beside it (0: beside
    /// it). The most any of the log's words take, so every head of the page
    /// is as tall (the list is virtual, ruling 264: its rows' heights are
    /// known without measuring every entry).
    when_lines: usize,
    /// On a stacked head, the lines its title takes across the row: as many
    /// as the log's longest title needs there ([`messages_plan`] holds the
    /// head inside the list), one height for every head. On one line,
    /// ruling 262's one line.
    title_lines: usize,
}

impl MessagesLead {
    fn measure(
        visible: &[&MessageView],
        clock: MessagesClock,
        compact: bool,
        content_width: f32,
    ) -> Self {
        let scale = settings_text_scale();
        let (px, face) = crate::native_ui::text_paint_metrics(SemanticRole::Text, StyleRef::Quiet);
        let width = |s: &str| crate::tray_raster::ui_text_width_for(face, s, px);
        // Each distinct word is measured once: a full ring holds only a few dozen
        // distinct times and a handful of tags.
        let whens: std::collections::BTreeSet<String> =
            visible.iter().map(|e| clock.when(e.at_unix_ms)).collect();
        let when = [
            "yesterday",
            "2026-09-22",
            "59 min ago",
            "23 h ago",
            "12:59 PM",
        ]
        .into_iter()
        .chain(whens.iter().map(String::as_str))
        .map(width)
        .fold(0.0_f32, f32::max)
            + 4.0;
        let cap = if compact { 7.0 } else { 12.0 } * px;
        let tags: std::collections::BTreeSet<&str> =
            visible.iter().map(|e| e.tag.as_str()).collect();
        let tag = tags
            .into_iter()
            .map(|t| width(&crate::messages_host::tag_words(t)))
            .fold(0.0_f32, f32::max)
            .min(cap)
            + 4.0;
        let mut lead = Self {
            mark: 28.0 * scale,
            when,
            tag,
            gap: 8.0,
            stacked: false,
            when_lines: 0,
            title_lines: 1,
        };
        // A title keeps at least two fifths of the row, the chevron's end not
        // counted as its (at 30 columns it had a quarter, "Claud…"): where
        // the column would take more, the tag column goes first (the row's
        // name says it), then
        // the time column narrows to its own words (the log's own, not the
        // longest it may say later); and where not even that leaves the title
        // its two fifths, the head stacks.
        if lead.title_x() + MESSAGES_CHEVRON_END > content_width * 0.6 {
            lead.tag = 0.0;
        }
        if lead.title_x() + MESSAGES_CHEVRON_END > content_width * 0.6 {
            let own = whens.iter().map(|when| width(when)).fold(0.0_f32, f32::max) + 4.0;
            lead.when = lead.when.min(own);
        }
        lead.stacked = lead.title_x() + MESSAGES_CHEVRON_END > content_width * 0.6;
        if lead.stacked {
            let beside = content_width - lead.mark - lead.gap - MESSAGES_CHEVRON_END;
            let under = messages_stacked_width(content_width, lead);
            if whens.iter().any(|when| width(when) > beside + 0.01) {
                lead.when_lines = whens
                    .iter()
                    .map(|when| wrap_to_box(when, under, &width).len())
                    .max()
                    .unwrap_or(1)
                    .max(1);
            }
            // The title across the row, whole: its lines the most any of the
            // log's titles takes there, each distinct title measured once.
            let (ppx, pface) =
                crate::native_ui::text_paint_metrics(SemanticRole::Text, StyleRef::Primary);
            let primary = |line: &str| crate::tray_raster::ui_text_width_for(pface, line, ppx);
            let titles: std::collections::BTreeSet<&str> =
                visible.iter().map(|entry| entry.title.as_str()).collect();
            lead.title_lines = titles
                .into_iter()
                .map(|title| wrap_to_box(title, under, &primary).len())
                .max()
                .unwrap_or(1)
                .max(1);
        }
        lead
    }

    /// Where every title begins, from the row's left edge.
    fn title_x(self) -> f32 {
        let columns = if self.tag > 0.0 { 3.0 } else { 2.0 };
        self.mark + self.when + self.tag + columns * self.gap
    }
}

// Test-only work census: the entry rows `messages_head_node` has built on this
// thread. The list is virtual, so a render builds only the rows its view shows; the
// ring-cap test counts that instead of timing it.
#[cfg(test)]
thread_local! {
    static MESSAGES_ROWS_BUILT: std::cell::Cell<usize> = const { std::cell::Cell::new(0) };
}

/// The room a head keeps clear at its end for the disclosure's chevron.
const MESSAGES_CHEVRON_END: f32 = 36.0;

/// The end a stacked head's lines under its first row keep, as the open
/// entry's body keeps it.
const MESSAGES_STACKED_END: f32 = 12.0;

/// HOW WIDE A STACKED HEAD'S LINES UNDER ITS FIRST ROW ARE (its title, and
/// its `when` where that is too wide beside the mark): the row from the gap
/// they start after to its 12pt end. The chevron stands on the first row,
/// beside the mark and `when` ([`crate::native_ui::ButtonSpec::chevron_row`]),
/// so these lines run past where it is. Keeping its 36pt end on every line
/// (the chevron drawn once, at the head's middle) cost "Antigravity" its
/// line in a 22-column window at 2× text: "Antigrav-" / "ity CLI is" /
/// "not…", the title cut to the head's lines.
fn messages_stacked_width(content_width: f32, lead: MessagesLead) -> f32 {
    (content_width - lead.gap - MESSAGES_STACKED_END).max(24.0)
}

/// AN ENTRY'S TITLE AS ITS HEAD PAINTS IT, and whether that cut it: on one
/// line, fitted to the title's column (ruling 262); stacked, on the head's
/// title lines across the row, the last cut only where the title needs more
/// than the list lets a head have. The open entry's body says a title its
/// head cut whole ([`MessagesBody::name`]).
fn messages_head_title(
    entry: &MessageView,
    lead: MessagesLead,
    content_width: f32,
) -> (Vec<String>, bool) {
    if !lead.stacked {
        let title_w = (content_width - lead.title_x() - MESSAGES_CHEVRON_END).max(24.0);
        let shown = crate::native_ui::fit_native_text_label(&entry.title, title_w);
        let cut = shown != entry.title;
        return (vec![shown], cut);
    }
    let under = messages_stacked_width(content_width, lead);
    let (px, face) = crate::native_ui::text_paint_metrics(SemanticRole::Text, StyleRef::Primary);
    let mut lines = wrap_to_box_from(
        &entry.title,
        under,
        &|line| crate::tray_raster::ui_text_width_for(face, line, px),
        "-",
    );
    if lines.len() <= lead.title_lines {
        return (lines.into_iter().map(|(_, line)| line).collect(), false);
    }
    // The title from the last line it keeps on, as it is written: a CJK
    // title goes on with no space where its lines broke.
    let rest = lines
        .split_off(lead.title_lines - 1)
        .first()
        .map_or("", |(at, _)| &entry.title[*at..]);
    let mut lines: Vec<String> = lines.into_iter().map(|(_, line)| line).collect();
    lines.push(crate::native_ui::fit_native_text_label(rest, under));
    (lines, true)
}

/// A HEAD'S HEIGHT ([`messages_head_node`]): a row on one line (ruling 262);
/// stacked ([`MessagesLead::stacked`]), the mark's row, the lines `when`
/// takes under it where it does not fit beside it, and the title's line. One
/// height for every entry of the page, so the virtual list (ruling 264)
/// knows every row's without measuring a word.
fn messages_head_height(lead: MessagesLead) -> f32 {
    let row_h = messages_row_height();
    if !lead.stacked {
        return row_h;
    }
    let line_h = messages_line_height();
    row_h + (lead.when_lines + lead.title_lines) as f32 * line_h + (row_h - line_h) / 2.0
}

/// One entry's head (ruling 262): a flush DISCLOSURE control the whole row
/// wide — its name the title, its description the plain words, expanded or
/// collapsed — under the painted lead column and title, every word whole
/// on one line or stacked ([`messages_head_height`]). Hover, press and open
/// paint a quiet wash; the
/// chevron says which way it opens.
fn messages_head_node(
    entry: &MessageView,
    expanded: bool,
    lead: MessagesLead,
    content_width: f32,
    clock: MessagesClock,
) -> UiNode {
    #[cfg(test)]
    MESSAGES_ROWS_BUILT.with(|rows| rows.set(rows.get() + 1));
    let now_unix_ms = clock.now_unix_ms;
    let key = format!("settings/messages/row/{}", entry.id);
    let row_h = messages_row_height();
    let title_key = format!("{key}/title");
    let button = UiNode::new(
        title_key.clone(),
        UiContent::Button(
            Control::new(
                ButtonSpec {
                    description: Some(messages_description(entry, now_unix_ms)),
                    // A stacked head's chevron on its first row, beside the
                    // mark and `when`: the title's lines under it run to the
                    // row's end ([`messages_stacked_width`]).
                    chevron_row: lead.stacked.then(|| row_h.round() as u16),
                    ..ButtonSpec::new(entry.title.clone()).visual_label(String::new())
                },
                ActionId::new(title_key),
            )
            .state(ControlState {
                expanded: Some(expanded),
                ..ControlState::default()
            })
            .style(StyleRef::Plain),
        ),
    )
    .layout(Layout::default().width(Length::Fill).height(Length::Fill));
    let text = |key: String, text: String, style: StyleRef, width: Length, height: f32| {
        UiNode::new(
            key,
            UiContent::Text(TextSpec {
                text,
                role: SemanticRole::Text,
                style,
            }),
        )
        .layout(Layout::default().width(width).height(Length::Fixed(height)))
        .paint_only()
    };
    let (quiet_px, quiet_face) =
        crate::native_ui::text_paint_metrics(SemanticRole::Text, StyleRef::Quiet);
    let fit = |s: &str, w: f32| {
        let s = s.to_string();
        if crate::tray_raster::ui_text_width_for(quiet_face, &s, quiet_px) <= w - 2.0 {
            s
        } else {
            crate::native_ui::fit_native_text_label(&s, (w - 2.0).max(8.0))
        }
    };
    let mark = UiNode::new(
        format!("{key}/severity"),
        UiContent::Custom(crate::native_ui::AuditedCustomNode {
            audit_id: crate::native_ui::MESSAGES_SEVERITY_AUDIT,
            role: SemanticRole::Group,
            label: String::new(),
            // `severity:glyph` — the icon is the row's own glyph's, as the
            // band draws it; the colour and the rail are the severity's.
            value: Some(format!("{}:{}", entry.severity, entry.glyph)),
            action: None,
            focusable: false,
            focused: false,
            focus_visible: false,
        }),
    )
    .layout(
        Layout::default()
            .width(Length::Fixed(lead.mark))
            .height(Length::Fixed(row_h)),
    )
    .paint_only();
    let when = clock.when(entry.at_unix_ms);
    let visual = if lead.stacked {
        // The mark and `when` over the title, which has the row to its end
        // (the chevron stands on the first row): `when` beside the mark
        // where the log's words fit there, else on its own lines under it,
        // whole.
        let line_h = messages_line_height();
        let under = messages_stacked_width(content_width, lead);
        let pad = Insets {
            top: 0.0,
            right: 0.0,
            bottom: 0.0,
            left: lead.gap,
        };
        let mut first = vec![mark];
        let mut children = Vec::new();
        if lead.when_lines == 0 {
            first.push(text(
                format!("{key}/when"),
                when.clone(),
                StyleRef::Quiet,
                Length::Fill,
                row_h,
            ));
        }
        children.push(
            UiNode::new(
                format!("{key}/lead/first"),
                UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
            )
            .layout(
                Layout::row()
                    .width(Length::Fill)
                    .height(Length::Fixed(row_h))
                    .gap(lead.gap),
            )
            .paint_only()
            .children(first),
        );
        if lead.when_lines > 0 {
            let (px, face) =
                crate::native_ui::text_paint_metrics(SemanticRole::Text, StyleRef::Quiet);
            let lines = wrap_to_box(&when, under, &|line| {
                crate::tray_raster::ui_text_width_for(face, line, px)
            });
            children.push(
                UiNode::new(
                    format!("{key}/when"),
                    UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
                )
                .layout(
                    // The box its lines were measured for: clear of the
                    // chevron, centred on the head's lines beside them.
                    Layout::column()
                        .width(Length::Fixed(under + lead.gap))
                        .height(Length::Fixed(lead.when_lines as f32 * line_h))
                        .padding(pad),
                )
                .paint_only()
                .children(
                    lines
                        .into_iter()
                        .enumerate()
                        .map(|(index, line)| {
                            text(
                                format!("{key}/when/line-{index}"),
                                line,
                                StyleRef::Quiet,
                                Length::Fill,
                                line_h,
                            )
                        })
                        .collect(),
                ),
            );
        }
        // The title across the row, on its lines: whole where the head's
        // lines hold it (they hold the log's longest wherever the list has
        // the room), else its last line cut.
        let (lines, _) = messages_head_title(entry, lead, content_width);
        let title = if let [line] = lines.as_slice() {
            let mut title = text(
                format!("{key}/label"),
                line.clone(),
                StyleRef::Primary,
                Length::Fixed(under + lead.gap),
                line_h,
            );
            title.layout.padding = pad;
            title
        } else {
            UiNode::new(
                format!("{key}/label"),
                UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
            )
            .layout(
                Layout::column()
                    .width(Length::Fixed(under + lead.gap))
                    .height(Length::Fixed(lead.title_lines as f32 * line_h))
                    .padding(pad),
            )
            .paint_only()
            .children(
                lines
                    .into_iter()
                    .enumerate()
                    .map(|(index, line)| {
                        text(
                            format!("{key}/label/line-{index}"),
                            line,
                            StyleRef::Primary,
                            Length::Fill,
                            line_h,
                        )
                    })
                    .collect(),
            )
        };
        children.push(title);
        UiNode::new(
            format!("{key}/lead"),
            UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
        )
        .layout(Layout::column().width(Length::Fill).height(Length::Fill))
        .paint_only()
        .children(children)
    } else {
        let title_w = (content_width - lead.title_x() - MESSAGES_CHEVRON_END).max(24.0);
        let mut children = vec![
            mark,
            text(
                format!("{key}/when"),
                when,
                StyleRef::Quiet,
                Length::Fixed(lead.when),
                row_h,
            ),
        ];
        if lead.tag > 0.0 {
            children.push(text(
                format!("{key}/tag"),
                fit(&crate::messages_host::tag_words(&entry.tag), lead.tag),
                StyleRef::Quiet,
                Length::Fixed(lead.tag),
                row_h,
            ));
        }
        let (title, _) = messages_head_title(entry, lead, content_width);
        children.push(text(
            format!("{key}/label"),
            title.concat(),
            StyleRef::Primary,
            Length::Fixed(title_w),
            row_h,
        ));
        UiNode::new(
            format!("{key}/lead"),
            UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
        )
        .layout(
            Layout::row()
                .width(Length::Fill)
                .height(Length::Fill)
                .gap(lead.gap),
        )
        .paint_only()
        .children(children)
    };
    UiNode::new(
        format!("{key}/head"),
        UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
    )
    .layout(
        Layout::default()
            .width(Length::Fill)
            .height(Length::Fixed(messages_head_height(lead))),
    )
    .children(vec![button, visual])
}

/// An expanded entry's body, laid out: the meta line (the local time, and the state
/// where it says something), the plain sentence (the cause and the next step,
/// `detail[0]`), the buttons in a footer, and the technical details in small
/// monospace last.
#[derive(Clone, Debug, PartialEq)]
struct MessagesBody {
    /// The entry's title whole, on the body's lines, where its head cut it
    /// ([`messages_head_title`]): opened, an entry says all of its name.
    name: Vec<String>,
    meta: Vec<String>,
    sentence: Vec<String>,
    technical: Vec<String>,
    /// The footer's buttons, row by row (one row where they fit).
    footer: Vec<Vec<MessagesButton>>,
}

/// One button of an expanded entry's footer.
#[derive(Clone, Debug, PartialEq)]
struct MessagesButton {
    key: String,
    label: String,
    /// The words it paints: its label, on lines where the body is narrower
    /// than it ([`button_words`]; "Ope…" at 1.5× on a phone-width page).
    visual: String,
    lines: usize,
    primary: bool,
    enabled: bool,
    width: f32,
}

impl MessagesButton {
    /// Its height: a small button's, as tall as its lines need.
    fn height(&self) -> f32 {
        crate::native_ui::native_button_height_for_lines(self.lines, messages_small_button_height())
    }
}

/// A footer row's height: its tallest button's.
fn messages_footer_row_height(row: &[MessagesButton]) -> f32 {
    row.iter()
        .map(MessagesButton::height)
        .fold(messages_small_button_height(), f32::max)
}

impl MessagesBody {
    /// The body of `entry` at `text_width`; [`Self::fit`] bounds it to a height.
    fn of(entry: &MessageView, text_width: f32, utc_offset_s: i64, now_unix_ms: u64) -> Self {
        let (qpx, _) = crate::native_ui::text_paint_metrics(SemanticRole::Text, StyleRef::Quiet);
        let (ppx, _) = crate::native_ui::text_paint_metrics(SemanticRole::Text, StyleRef::Primary);
        // The meta line's words are the engine's (the web page's `meta=`); the wrap
        // is the layout's.
        let meta = entry.meta_words(now_unix_ms, utc_offset_s);
        // The split is the engine's (the web page's `sentence=` and `technical=`): a
        // diagram (a caret under a column) is technical whole; else the entry's
        // leading `sentences` lines are the sentence and the rest the details; the
        // `shown for` line is the meta line's. Each sentence line wraps to at most
        // three lines.
        let (sentence, technical) = entry.sentence_and_technical();
        let diagram = entry.is_diagram();
        // Every line of it, whole: an entry taller than the room is read a
        // part at a time ([`MessagesTall`]); it was cut to three lines.
        let sentence = sentence
            .into_iter()
            .flat_map(|first| wrapped_copy_lines(first, ppx, text_width))
            .collect();
        // A diagram's rows are cut (a column stays a column); a prose line in the
        // monospace face wraps at its spaces.
        let technical = technical
            .into_iter()
            .flat_map(|line| {
                if diagram {
                    messages_cut_code(line, text_width)
                } else {
                    messages_wrap_code(line, text_width)
                }
            })
            .collect();
        // The buttons, packed right to left into as few rows as the measure
        // needs — never full-width.
        let key = format!("settings/messages/row/{}", entry.id);
        let px = crate::native_ui::native_type_px(crate::type_scale::TypeStep::Secondary).get();
        let measure = |label: &str| {
            crate::tray_raster::ui_text_width_for(crate::widget::TextFace::Ui, label, px) + 24.0
        };
        // A footer row is a spacer and its buttons, 8pt apart: the buttons
        // have the body less the gap after the spacer.
        let room = (text_width - 8.0).max(48.0);
        // Its words and its width: one line where the row holds it, else the
        // row's width and the words on its lines.
        let words = |label: &str| {
            if measure(label) <= room + crate::native_ui::TEXT_FIT_SLACK {
                (label.to_string(), 1, measure(label))
            } else {
                let (words, lines) = button_words(label, &[], room);
                (words, lines, room)
            }
        };
        // The Primary is the engine's (ruling 407; the lines carry it as
        // `primary=`): the FIRST button offered while a press can still
        // perform it (ruling 265); past a dead one — which stays, plain and
        // disabled (day ten, D2; ruling 401) — the first later intent a press
        // can perform that is not a decline (ruling 403); none such, none
        // leads. A POSITION in the offered intents, not an `ActionIndex`
        // (ruling 408): `k`, never `action.index`.
        let lead = aterm_messages::page::primary_index(&entry.actions);
        let mut buttons: Vec<MessagesButton> = entry
            .actions
            .iter()
            .enumerate()
            .map(|(k, action)| {
                let label = aterm_messages::page::button_label(action.label);
                let (visual, lines, width) = words(&label);
                MessagesButton {
                    key: format!("{key}/action/{}", action.index),
                    width,
                    label,
                    visual,
                    lines,
                    primary: Some(k) == lead,
                    enabled: action.still_actionable,
                }
            })
            .collect();
        let (visual, lines, width) = words(aterm_messages::page::COPY);
        buttons.push(MessagesButton {
            key: format!("{key}/copy"),
            label: aterm_messages::page::COPY.to_string(),
            visual,
            lines,
            primary: false,
            enabled: true,
            width,
        });
        let mut footer: Vec<Vec<MessagesButton>> = vec![Vec::new()];
        let mut used = 0.0_f32;
        for button in buttons {
            if used + 8.0 + button.width > room && !footer.last().is_some_and(Vec::is_empty) {
                footer.push(Vec::new());
                used = 0.0;
            }
            used += if used > 0.0 { 8.0 } else { 0.0 } + button.width;
            footer.last_mut().expect("a row").push(button);
        }
        Self {
            name: Vec::new(),
            meta: wrapped_copy_lines(&meta, qpx, text_width),
            sentence,
            technical,
            footer,
        }
    }

    /// The technical lines bounded to `lines`: the last kept line says how many more
    /// there are, with at least one real line above it (a bound of one keeps two
    /// rows, since a bare `… (2 more lines)` says nothing), and [`Self::fit`] drops
    /// the block when even that does not fit. Two lines are never one line and a
    /// marker. Copy keeps them all.
    fn bound(&mut self, lines: usize) {
        let keep = lines.saturating_sub(1).max(1);
        if self.technical.len() > keep + 1 {
            let hidden = self.technical.len() - keep;
            self.technical.truncate(keep);
            self.technical
                .push(format!("\u{2026} ({hidden} more lines)"));
        }
    }

    /// The body's height below the head with `actions` buttons.
    fn height(&self) -> f32 {
        let line = messages_line_height();
        let tech = if self.technical.is_empty() {
            0.0
        } else {
            8.0 + line + self.technical.len() as f32 * messages_code_line_height()
        };
        let rows = self.footer.len().max(1) as f32;
        let footer = if self.footer.is_empty() {
            messages_small_button_height()
        } else {
            self.footer
                .iter()
                .map(|row| messages_footer_row_height(row))
                .sum()
        };
        (self.name.len() + self.meta.len() + self.sentence.len()) as f32 * line
            + MESSAGES_FOOTER_GAP
            + footer
            + (rows - 1.0) * 6.0
            + tech
            + 10.0
    }

    /// Fit the body into `avail` points by its technical lines alone (to
    /// one, then the block — Copy keeps every line); the meta line, the
    /// sentence and the footer stay whole, and what is still taller than the
    /// room is read a part at a time ([`MessagesTall`]).
    fn fit(&mut self, avail: f32) {
        let code_h = messages_code_line_height();
        if self.height() > avail && !self.technical.is_empty() {
            let over = self.height() - avail;
            let drop = (over / code_h).ceil() as usize;
            if self.technical.len() > drop {
                self.bound(self.technical.len() - drop);
            }
            // One real line and its marker, or nothing (Copy keeps them all).
            if self.height() > avail {
                self.technical.clear();
            }
        }
        // The meta line and the sentence stay whole: an entry taller than
        // the room is read a part at a time ([`MessagesTall`]). They were
        // dropped a line at a time here, the cause and its next step the
        // first to go.
    }
}

/// One technical line cut to the measure in the monospace face it paints in (a column
/// stays a column: never reflowed), one grapheme at a time.
fn messages_cut_code(line: &str, available_width: f32) -> Vec<String> {
    let (px, face) = crate::native_ui::text_paint_metrics(SemanticRole::Status, StyleRef::Code);
    let advance = |grapheme: &str| {
        if face == crate::widget::TextFace::Mono {
            crate::tray_raster::measure_text(grapheme, px, crate::widget::TextWeight::Regular)
        } else {
            crate::tray_raster::ui_text_width_for(face, grapheme, px)
        }
    };
    let available_width = available_width.max(48.0);
    let mut rows = Vec::new();
    let mut row = String::new();
    let mut width = 0.0_f32;
    for grapheme in line.graphemes() {
        let step = advance(grapheme);
        if !row.is_empty() && width + step > available_width {
            rows.push(std::mem::take(&mut row));
            width = 0.0;
        }
        row.push_str(grapheme);
        width += step;
    }
    rows.push(row);
    rows
}

/// One technical line wrapped at its spaces to the measure in the monospace face it
/// paints in; a word longer than the measure is cut.
fn messages_wrap_code(line: &str, available_width: f32) -> Vec<String> {
    let (px, _) = crate::native_ui::text_paint_metrics(SemanticRole::Status, StyleRef::Code);
    let width =
        |s: &str| crate::tray_raster::measure_text(s, px, crate::widget::TextWeight::Regular);
    let available_width = available_width.max(48.0);
    let mut rows: Vec<String> = Vec::new();
    let mut row = String::new();
    for word in line.split(' ') {
        let candidate = if row.is_empty() {
            word.to_string()
        } else {
            format!("{row} {word}")
        };
        if width(&candidate) <= available_width {
            row = candidate;
            continue;
        }
        if !row.is_empty() {
            rows.push(std::mem::take(&mut row));
        }
        if width(word) <= available_width {
            row = word.to_string();
        } else {
            let mut pieces = messages_cut_code(word, available_width);
            row = pieces.pop().unwrap_or_default();
            rows.extend(pieces);
        }
    }
    rows.push(row);
    rows
}

/// An expanded entry's body node, inside the log's card, indented to `indent`.
fn messages_body_node(
    entry: &MessageView,
    body: &MessagesBody,
    indent: f32,
    body_width: f32,
    note: Option<&str>,
) -> UiNode {
    let key = format!("settings/messages/row/{}", entry.id);
    let line_h = messages_line_height();
    let line = |key: String, text: String, role: SemanticRole, style: StyleRef, height: f32| {
        UiNode::new(key, UiContent::Text(TextSpec { text, role, style })).layout(
            Layout::default()
                .width(Length::Fill)
                .height(Length::Fixed(height)),
        )
    };
    let mut children: Vec<UiNode> = Vec::new();
    for (index, words) in body.name.iter().enumerate() {
        children.push(line(
            format!("{key}/name/{index}"),
            words.clone(),
            SemanticRole::Text,
            StyleRef::Primary,
            line_h,
        ));
    }
    for (index, words) in body.meta.iter().enumerate() {
        children.push(line(
            format!("{key}/meta/{index}"),
            words.clone(),
            SemanticRole::Text,
            StyleRef::Quiet,
            line_h,
        ));
    }
    for (index, words) in body.sentence.iter().enumerate() {
        children.push(line(
            format!("{key}/detail/{index}"),
            words.clone(),
            SemanticRole::Text,
            StyleRef::Primary,
            line_h,
        ));
    }
    children.push(messages_spacer(
        &format!("{key}/footer-gap"),
        MESSAGES_FOOTER_GAP,
    ));
    // The footer: the buttons right-aligned, never full-width.
    let rows = body.footer.len().max(1);
    let footer_rows: Vec<UiNode> = body
        .footer
        .iter()
        .enumerate()
        .map(|(r, row)| {
            // The page's transient line, where this entry's button set it and
            // the count line is off screen (s-13): beside the buttons, in the
            // row's room, never a row of its own.
            let lead = match note.filter(|_| r == 0) {
                Some(text) => {
                    let buttons: f32 = row.iter().map(|b| b.width + 8.0).sum();
                    messages_fitted_status(
                        &format!("{key}/status"),
                        text.to_string(),
                        Length::Fill,
                        (body_width - buttons).max(24.0),
                    )
                }
                None => UiNode::new(
                    format!("{key}/footer-spacer/{r}"),
                    UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
                )
                .layout(Layout::default().width(Length::Fill).height(Length::Fill)),
            };
            let mut buttons: Vec<UiNode> = vec![lead];
            let row_h = messages_footer_row_height(row);
            for b in row {
                buttons.push(
                    UiNode::new(
                        b.key.clone(),
                        UiContent::Button(
                            Control::new(
                                ButtonSpec::new(b.label.clone()).visual_label(b.visual.clone()),
                                ActionId::new(b.key.clone()),
                            )
                            .state(ControlState {
                                enabled: b.enabled,
                                ..ControlState::default()
                            })
                            .style(if b.primary {
                                StyleRef::Primary
                            } else {
                                StyleRef::Secondary
                            }),
                        ),
                    )
                    .layout(
                        Layout::default()
                            .width(Length::Fixed(b.width))
                            .height(Length::Fixed(b.height())),
                    ),
                );
            }
            UiNode::new(
                format!("{key}/actions/{r}"),
                UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
            )
            .layout(
                Layout::row()
                    .width(Length::Fill)
                    .height(Length::Fixed(row_h))
                    .gap(8.0),
            )
            .children(buttons)
        })
        .collect();
    let footer_h = footer_rows
        .iter()
        .map(fixed_height)
        .sum::<f32>()
        .max(messages_small_button_height());
    children.push(
        UiNode::new(
            format!("{key}/actions"),
            UiContent::Group(GroupSpec::new("Message actions")),
        )
        .layout(
            Layout::column()
                .width(Length::Fill)
                .height(Length::Fixed(footer_h + (rows - 1) as f32 * 6.0))
                .gap(6.0),
        )
        .children(footer_rows),
    );
    if !body.technical.is_empty() {
        children.push(messages_spacer(&format!("{key}/tech-gap"), 8.0));
        children.push(line(
            format!("{key}/technical"),
            aterm_messages::page::TECHNICAL.to_string(),
            SemanticRole::Text,
            StyleRef::Quiet,
            line_h,
        ));
        let code_h = messages_code_line_height();
        for (index, words) in body.technical.iter().enumerate() {
            children.push(line(
                format!("{key}/code/{index}"),
                words.clone(),
                SemanticRole::Status,
                StyleRef::Code,
                code_h,
            ));
        }
    }
    UiNode::new(
        format!("{key}/body"),
        UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
    )
    .layout(
        Layout::column()
            .width(Length::Fill)
            .height(Length::Fixed(body.height()))
            .padding(Insets {
                top: 0.0,
                right: 12.0,
                bottom: 10.0,
                left: indent,
            })
            .clipped(),
    )
    .children(children)
}

/// A day header's words: whole where they fit the card from the time column
/// on, else the date's weekday and month abbreviated (`Fri, 12 Sep` — a
/// phone at twice the text size), else cut to the room.
fn messages_day_words(plan: &MessagesPlan, day: i64) -> String {
    let (px, face) = crate::native_ui::text_paint_metrics(SemanticRole::Heading, StyleRef::Quiet);
    let room = plan.content_width - plan.lead.mark - plan.lead.gap - 12.0 - 2.0;
    let fits = |s: &str| crate::tray_raster::ui_text_width_for(face, s, px) <= room;
    let whole = aterm_messages::words::day_heading(plan.clock.today, day, false);
    if fits(&whole) {
        return whole;
    }
    let short = aterm_messages::words::day_heading(plan.clock.today, day, true);
    if fits(&short) {
        short
    } else {
        crate::native_ui::elide_text_label(&short, room.max(8.0), px, face)
    }
}

/// A day header: the day's name (`Today`, `Yesterday`, `Thursday`, `Friday, 18
/// September`) in the caption heading, from the lead column's time x so it stands over
/// the times it dates. A heading for a screen reader, never a control: the keyboard
/// steps past it and it takes no scroll stop; the list's top entry always carries its
/// day's header.
fn messages_day_node(day: i64, plan: &MessagesPlan) -> UiNode {
    let key = format!("settings/messages/day/{day}");
    UiNode::new(
        format!("{key}/group"),
        UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
    )
    .layout(
        Layout::column()
            .width(Length::Fill)
            .height(Length::Fixed(plan.day_h))
            .padding(Insets {
                top: 6.0 * settings_text_scale(),
                right: 12.0,
                bottom: 0.0,
                left: plan.lead.mark + plan.lead.gap,
            }),
    )
    .children(vec![
        UiNode::new(
            key,
            UiContent::Text(TextSpec {
                text: messages_day_words(plan, day),
                role: SemanticRole::Heading,
                style: StyleRef::Quiet,
            }),
        )
        .layout(Layout::default().width(Length::Fill).height(Length::Fill)),
    ])
}

/// The log's card: the entries the view shows, one line each with hairlines between,
/// the open one with its body under it (already fitted by the plan that seated it,
/// [`messages_plan`]), so the card is exactly as tall as the plan measured. The card
/// is the screen reader's scrolling list ([`SemanticRole::List`]).
fn messages_list_node(
    rows: &[&MessageView],
    (first, part): (usize, Option<usize>),
    plan: &MessagesPlan,
    selected: Option<u64>,
    note: Option<(u64, &str)>,
) -> (UiNode, f32) {
    let indent = plan.indent();
    let mut children: Vec<UiNode> = vec![messages_spacer(
        "settings/messages/list/top",
        MESSAGES_LIST_PAD,
    )];
    let mut height = 2.0 * MESSAGES_LIST_PAD;
    for (k, entry) in rows.iter().enumerate() {
        if k > 0 {
            children.push(messages_rule(&format!(
                "settings/messages/row/{}/rule",
                entry.id
            )));
            height += 1.0;
        }
        if let Some(day) = plan.day_before(first + k, first) {
            children.push(messages_day_node(day, plan));
            height += plan.day_h;
        }
        let expanded = selected == Some(entry.id);
        let head = messages_head_node(entry, expanded, plan.lead, plan.content_width, plan.clock);
        let row_h = fixed_height(&head);
        let key = format!("settings/messages/row/{}", entry.id);
        match plan
            .body
            .as_ref()
            .filter(|(id, _)| expanded && *id == entry.id)
        {
            Some((_, b)) => {
                let mut body = messages_body_node(
                    entry,
                    b,
                    indent,
                    (plan.content_width - indent - 16.0).max(48.0),
                    note.filter(|(id, _)| *id == entry.id).map(|(_, text)| text),
                );
                // A tall entry's part: its blocks alone, the body's
                // padding with them ([`MessagesTall`]).
                let shown = part
                    .filter(|_| k == 0)
                    .zip(plan.tall.as_ref().filter(|tall| tall.entry == first));
                let (key, row, h) = match shown {
                    Some((part, tall)) => {
                        let blocks = tall.parts[part].clone();
                        let last = body.children.len();
                        let body_blocks = blocks.start.max(1) - 1..blocks.end - 1;
                        body.layout.padding.bottom = if blocks.end - 1 == last {
                            body.layout.padding.bottom
                        } else {
                            0.0
                        };
                        let kept: Vec<UiNode> = std::mem::take(&mut body.children)
                            .into_iter()
                            .enumerate()
                            .filter(|(index, _)| body_blocks.contains(index))
                            .map(|(_, child)| child)
                            .collect();
                        let body_h =
                            kept.iter().map(fixed_height).sum::<f32>() + body.layout.padding.bottom;
                        body.layout.height = Length::Fixed(body_h);
                        body.children = kept;
                        let mut row = Vec::new();
                        if blocks.start == 0 {
                            row.push(head);
                        }
                        if !body.children.is_empty() {
                            row.push(body);
                        }
                        let key = if part == 0 {
                            key
                        } else {
                            format!("{key}/part-{part}")
                        };
                        (key, row, tall.heights[part])
                    }
                    None => (key, vec![head, body], row_h + b.height()),
                };
                children.push(
                    UiNode::new(key, UiContent::Group(GroupSpec::new(entry.title.clone())))
                        .layout(
                            Layout::column()
                                .width(Length::Fill)
                                .height(Length::Fixed(h))
                                .clipped(),
                        )
                        .children(row),
                );
                height += h;
            }
            None => {
                children.push(
                    UiNode::new(key, UiContent::Group(GroupSpec::new(entry.title.clone())))
                        .layout(
                            Layout::column()
                                .width(Length::Fill)
                                .height(Length::Fixed(row_h)),
                        )
                        .children(vec![head]),
                );
                height += row_h;
            }
        }
    }
    children.push(messages_spacer(
        "settings/messages/list/bottom",
        MESSAGES_LIST_PAD,
    ));
    let node = UiNode::new(
        "settings/messages/list",
        UiContent::Group(GroupSpec {
            label: Some(aterm_messages::page::HEADING.to_string()),
            role: SemanticRole::List,
            style: StyleRef::Secondary,
        }),
    )
    .layout(
        Layout::column()
            .width(Length::Fill)
            .height(Length::Fixed(height))
            .clipped(),
    )
    .children(children);
    (node, height)
}

/// The card with its scroll indicator laid over it: where the view shows only some
/// of the `total` entries, a thin thumb down the card's trailing edge says the list
/// scrolls and where the view is ([`crate::native_ui::MESSAGES_SCROLL_AUDIT`],
/// paint-only); where it shows them all, the card alone.
fn messages_scroll_node(
    card: UiNode,
    height: f32,
    rows: std::ops::Range<usize>,
    total: usize,
) -> UiNode {
    if rows.start == 0 && rows.end >= total {
        return card;
    }
    let thumb = UiNode::new(
        "settings/messages/scroll/thumb",
        UiContent::Custom(crate::native_ui::AuditedCustomNode {
            audit_id: crate::native_ui::MESSAGES_SCROLL_AUDIT,
            role: SemanticRole::Group,
            label: String::new(),
            value: Some(format!("{},{},{total}", rows.start, rows.len())),
            action: None,
            focusable: false,
            focused: false,
            focus_visible: false,
        }),
    )
    .layout(Layout::default().width(Length::Fill).height(Length::Fill))
    .paint_only();
    UiNode::new(
        "settings/messages/scroll",
        UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
    )
    .layout(
        Layout::default()
            .width(Length::Fill)
            .height(Length::Fixed(height)),
    )
    .children(vec![card, thumb])
}

/// The filters and the count, top to bottom, with their heights: the severity
/// segments; the tag chips (wide), or the `Tag: …` pop-up and, open, its chips
/// (compact); and the count line. An empty log has neither filters nor count, only
/// the report buttons.
fn messages_filter_items(
    state: &SettingsViewState,
    messages: &MessagesState,
    visible: usize,
    page_width: f32,
    (compact, room): (bool, Option<f32>),
    tag_menu: bool,
) -> Vec<(UiNode, f32)> {
    // THE FILTERS AND THE COUNT SIT ON ONE CARD (system-15): they were the only
    // Settings controls with no card under them, so the chips, the count and
    // the report buttons — their resting fills tuned for a card behind them —
    // landed on the wallpaper (a chip's fill at 1.06:1 against GitHub Light's
    // wash). Everything here is laid out against the card's inner width.
    let content_width = (page_width - 2.0 * MESSAGES_FILTERS_PAD_X).max(48.0);
    let filter = &state.messages_filter;
    let total = messages.entries.len();
    let mut items = Vec::new();
    let chip_h = 30.0_f32.max(26.0 * settings_text_scale());
    if total > 0 {
        let (segments, segments_h) =
            messages_severity_segments(messages, filter, content_width, chip_h + 6.0);
        // The filters stay in two lines: a wider page lays its tags out as chips only
        // while segments and chips fit in two; past that (a script can name any tag)
        // it takes the compact page's `Tag: …` pop-up, which holds any number. The
        // chips' block sits beside the segments where it fits in two rows there, else
        // on full lines under them.
        let segments_lead = segments_h <= chip_h + 6.0;
        let lead_width = match segments.layout.width {
            Length::Fixed(width) => width,
            _ => content_width,
        };
        let beside = !compact
            && segments_lead
            && messages_tag_chip_rows(
                messages,
                filter,
                content_width,
                chip_h,
                Some((segments.clone(), lead_width)),
            )
            .len()
                <= MESSAGES_FILTER_LINES_MAX;
        // Under the segments: their own line, and the chips' rows after it.
        let under = !compact
            && !beside
            && messages_tag_chip_rows(messages, filter, content_width, chip_h, None).len()
                < MESSAGES_FILTER_LINES_MAX;
        let popup_form = !(beside || under);
        let tag_rows = if popup_form {
            // The pop-up measured to its words and its chevron; beside the
            // severity segments where both fit on one line.
            let px = crate::native_ui::native_type_px(crate::type_scale::TypeStep::Secondary).get();
            let popup_w = (crate::tray_raster::ui_text_width_for(
                crate::widget::TextFace::Ui,
                &aterm_messages::page::tag_menu_label(filter.tag.as_deref()),
                px,
            ) + 56.0)
                .min(content_width);
            let popup = messages_tag_popup(filter, tag_menu, popup_w, chip_h);
            let segments_w = match segments.layout.width {
                Length::Fixed(width) => width,
                _ => content_width,
            };
            if segments_h <= chip_h + 6.0 && segments_w + 8.0 + popup_w <= content_width {
                let mut popup = popup;
                popup.layout.height = Length::Fixed(chip_h);
                items.push((
                    UiNode::new(
                        "settings/messages/filters/line",
                        UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
                    )
                    .layout(
                        Layout::row()
                            .width(Length::Fill)
                            .height(Length::Fixed(chip_h + 6.0))
                            .gap(8.0),
                    )
                    .children(vec![
                        segments,
                        UiNode::new(
                            "settings/messages/filters/popup",
                            UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
                        )
                        .layout(
                            Layout::column()
                                .width(Length::Fixed(popup_w))
                                .height(Length::Fill)
                                .padding(Insets {
                                    top: 3.0,
                                    right: 0.0,
                                    bottom: 3.0,
                                    left: 0.0,
                                }),
                        )
                        .children(vec![popup]),
                    ]),
                    chip_h + 6.0,
                ));
            } else {
                let popup_h = fixed_height(&popup);
                items.push((segments, segments_h));
                items.push((popup, popup_h));
            }
            if tag_menu {
                messages_tag_chip_rows(messages, filter, content_width, chip_h, None)
            } else {
                Vec::new()
            }
        } else if beside {
            // The segments lead the tag chips' first row.
            let width = lead_width;
            let mut segments = segments;
            segments.layout.height = Length::Fill;
            segments.layout.padding = Insets::default();
            messages_tag_chip_rows(
                messages,
                filter,
                content_width,
                chip_h,
                Some((segments, width)),
            )
        } else {
            items.push((segments, segments_h));
            messages_tag_chip_rows(messages, filter, content_width, chip_h, None)
        };
        items.extend(tag_rows.into_iter().map(|row| {
            let height = fixed_height(&row);
            (row, height)
        }));
    }
    let words = (total > 0).then(|| messages_status_words(total, visible, filter.is_all()));
    let note = state
        .feedback
        .as_deref()
        .filter(|_| messages_feedback_inline(state));
    // Copy All copies what the list shows, so with nothing shown there is
    // nothing to copy.
    items.push(messages_count_line(words, note, content_width, visible > 0));
    // A log the filters admit none of says so on the same card, with the one
    // press that lifts both filters.
    if total > 0 && visible == 0 {
        items.push(messages_no_match_node(content_width));
    }
    let gap = 8.0;
    let card_height = |items: &[(UiNode, f32)]| {
        items.iter().map(|(_, h)| *h).sum::<f32>()
            + items.len().saturating_sub(1) as f32 * gap
            + 2.0 * MESSAGES_FILTERS_PAD_Y
    };
    // A CARD NO TALLER THAN THE LIST (a compact page's, which scrolls it as
    // stops): where the card is taller than the room, it is listed a part at
    // a time by the one rule every list keeps ([`scroll::row_parts`]: a part
    // an item alone where one is), so every control is whole on some screen,
    // and its parts read as the one card they are, open where they meet.
    // At 2× on a 22 × 24 window the one card was 405pt in a 268pt list,
    // Copy All half under its edge and Open Log Folder on no screen at all.
    let height = card_height(&items);
    let card = UiNode::new(
        "settings/messages/filters",
        UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group).style(StyleRef::Secondary)),
    )
    .layout(
        Layout::column()
            .width(Length::Fill)
            .height(Length::Fixed(height))
            .padding(Insets::symmetric(
                MESSAGES_FILTERS_PAD_X,
                MESSAGES_FILTERS_PAD_Y,
            ))
            .gap(gap),
    )
    .children(items.into_iter().map(|(node, _)| node).collect());
    match room {
        Some(room) => scroll::row_parts((card, height), room, room, MESSAGES_ROW_GAP),
        None => vec![(card, height)],
    }
}

/// The filters card's own padding ([`messages_filter_items`]): the one place
/// it is written, read by its layout and by the measure its rows are laid out
/// against.
const MESSAGES_FILTERS_PAD_X: f32 = 12.0;
const MESSAGES_FILTERS_PAD_Y: f32 = 10.0;

/// What the list says where the log has messages but the filters admit none:
/// that, and the one press that lifts both filters.
fn messages_no_match_node(text_width: f32) -> (UiNode, f32) {
    let (button, button_width) = messages_small_button(
        MESSAGES_SHOW_ALL,
        MESSAGES_SHOW_ALL_WORDS,
        "Show all messages",
        true,
    );
    let button_height = messages_small_button_height();
    let (spx, sface) = crate::native_ui::text_paint_metrics(SemanticRole::Text, StyleRef::Quiet);
    let text_w = crate::tray_raster::ui_text_width_for(sface, MESSAGES_NO_MATCH, spx);
    let beside = text_w + 8.0 + button_width <= text_width;
    let words = UiNode::new(
        "settings/messages/no-match/words",
        UiContent::Text(TextSpec {
            text: MESSAGES_NO_MATCH.to_string(),
            role: SemanticRole::Text,
            style: StyleRef::Quiet,
        }),
    );
    let (layout, words, height) = if beside {
        (
            Layout::row()
                .width(Length::Fill)
                .height(Length::Fixed(button_height))
                .gap(8.0),
            words.layout(
                Layout::default()
                    .width(Length::Fixed(text_w + 4.0))
                    .height(Length::Fill),
            ),
            button_height,
        )
    } else {
        let line = messages_line_height();
        (
            Layout::column()
                .width(Length::Fill)
                .height(Length::Fixed(line + 6.0 + button_height))
                .gap(6.0),
            words.layout(Layout::default().height(Length::Fixed(line))),
            line + 6.0 + button_height,
        )
    };
    (
        UiNode::new(
            "settings/messages/no-match",
            UiContent::Group(GroupSpec::new(MESSAGES_NO_MATCH)),
        )
        .layout(layout)
        .children(vec![words, button]),
        height,
    )
}

/// THE LOG IS ONE SCROLLING LIST (design ruling 264 — a default the
/// supervisor took; the owner can overrule it): no pages and no pager. The
/// list scrolls by STOP — one per entry, and on a compact page one per header
/// item before them, because there the filters scroll away with the log —
/// and `page_scroll` is the stop at the top of the view. On the wider pages
/// the heading and the header stay; the card under them scrolls — unless the
/// open entry's body does not fit whole under them, when the header scrolls
/// away with the list as on a compact page, so the entry is read through its
/// last line (the review of the owner's notices, 2026-10-20: a lost login's
/// `what to expect` line was dropped under the pinned filters at 864×462,
/// which no scroll could bring back). What a
/// Messages render seats before it builds a node: the header items, the room
/// the list has, the lead column, and every admitted entry's height in the
/// card, the open one with its body fitted to the room. One
/// function for the renderer and the reducer — a reveal that drops a chip or
/// opens an entry measures the list it leaves, never the last render's
/// (ruling 263).
struct MessagesPlan {
    compact: bool,
    /// The header scrolls away with the list, one stop an item: a compact
    /// page's always; a wider page's while the open entry's body does not
    /// fit whole under the pinned header.
    scrolls: bool,
    content_width: f32,
    /// The header items, top to bottom, with their heights.
    header: Vec<(UiNode, f32)>,
    item_gap: f32,
    /// The gap between the header and the log's card.
    gap: f32,
    /// The height the scrolling region has: the whole section where the
    /// header scrolls, the room under the pinned heading and header on the
    /// wider pages else.
    room: f32,
    lead: MessagesLead,
    /// Each admitted entry's height in the card, newest first.
    heights: Vec<f32>,
    /// The open entry and its body, fitted to the room.
    body: Option<(u64, MessagesBody)>,
    /// The reader's calendar.
    clock: MessagesClock,
    /// Each admitted entry's section day when the list carries day headers
    /// ([`MessagesClock::sections`]); `None` for a log of one day.
    sections: Option<Vec<i64>>,
    /// A day header's height.
    day_h: f32,
    /// The open entry where it is taller than the list's room, listed a
    /// part at a time ([`MessagesTall`]).
    tall: Option<MessagesTall>,
}

/// AN OPEN ENTRY TALLER THAN THE LIST, READ A PART AT A TIME: its head and
/// its body's lines, footer and details gathered into parts no taller than
/// the room (a part a block alone where one is), each a stop of the list
/// whose screen shows that part whole — never a line cut by the room's edge.
/// Seated whole or not at all, an entry taller than the room was seated at
/// the top and cut by the edge, or had its sentence dropped a line at a time
/// to fit; at 2× text on a 24-row window its buttons were on no screen.
#[derive(Clone, Debug, PartialEq)]
struct MessagesTall {
    entry: usize,
    /// Each part's blocks: block 0 the head, block `i` the body's child
    /// `i - 1` ([`messages_body_node`]).
    parts: Vec<std::ops::Range<usize>>,
    /// Each part's height, its share of the body's padding with it.
    heights: Vec<f32>,
    /// The keys each part draws: the head's title, the body's lines and
    /// buttons — what the keyboard can be on while that part is the view.
    keys: Vec<std::collections::BTreeSet<String>>,
}

/// Every key under `node`, its own included.
fn ui_node_keys(node: &UiNode, into: &mut std::collections::BTreeSet<String>) {
    into.insert(node.key.as_str().to_string());
    for child in &node.children {
        ui_node_keys(child, into);
    }
}

/// The blocks of an open entry — its head (`head`) and its body's children
/// — packed into parts no taller than `room`, and each part's height: a
/// part's body blocks carry the body's bottom padding where they end it.
fn messages_tall_parts(
    head: f32,
    body: &UiNode,
    room: f32,
) -> (Vec<std::ops::Range<usize>>, Vec<f32>) {
    let pad = body.layout.padding.bottom;
    let blocks: Vec<f32> = std::iter::once(head)
        .chain(body.children.iter().map(fixed_height))
        .collect();
    let last = blocks.len() - 1;
    let mut parts: Vec<std::ops::Range<usize>> = Vec::new();
    let mut heights: Vec<f32> = Vec::new();
    let mut start = 0;
    let mut used = 0.0_f32;
    for (index, height) in blocks.iter().copied().enumerate() {
        let end_pad = if index == last { pad } else { 0.0 };
        if index > start && used + height + end_pad > room + 0.01 {
            parts.push(start..index);
            heights.push(used);
            start = index;
            used = 0.0;
        }
        used += height + end_pad;
    }
    parts.push(start..blocks.len());
    heights.push(used);
    (parts, heights)
}

/// What the list shows with one stop at its top: the header items it seats
/// (a compact page's; the wider pages' header is always there), the
/// entries, by index among those the filters admit, and — where the first
/// is a tall open entry ([`MessagesTall`]) — which of its parts it shows.
#[derive(Clone, Debug, PartialEq, Eq)]
struct MessagesView {
    header: std::ops::Range<usize>,
    rows: std::ops::Range<usize>,
    part: Option<usize>,
}

/// Where a scrolled Messages list stood when it was last drawn: the stop at
/// its top, the entry there, the entries drawn under it in order, and the
/// filter it was drawn under ([`SettingsViewState::messages_anchor`]).
#[derive(Clone, Debug, PartialEq, Eq)]
struct MessagesAnchor {
    stop: usize,
    id: u64,
    below: Vec<u64>,
    filter: MessagesFilter,
}

impl MessagesPlan {
    /// The stops before the entries: the header items, where they scroll
    /// with the list ([`Self::scrolls`]).
    fn lead_stops(&self) -> usize {
        if self.scrolls { self.header.len() } else { 0 }
    }

    /// Every stop the list has: a tall open entry's every part one.
    fn stops(&self) -> usize {
        self.lead_stops() + self.heights.len() + self.extra()
    }

    /// The stops a tall open entry adds after its first.
    fn extra(&self) -> usize {
        self.tall.as_ref().map_or(0, |tall| tall.parts.len() - 1)
    }

    /// The stop entry `index` stands at the top of.
    fn entry_stop(&self, index: usize) -> usize {
        self.lead_stops()
            + index
            + if self.tall.as_ref().is_some_and(|tall| index > tall.entry) {
                self.extra()
            } else {
                0
            }
    }

    /// The entry at the top of entry stop `j` (a stop less the header's),
    /// and which of a tall entry's parts it shows there.
    fn stop_entry(&self, j: usize) -> (usize, Option<usize>) {
        let extra = self.extra();
        match &self.tall {
            Some(tall) if j >= tall.entry && j <= tall.entry + extra => {
                (tall.entry, Some(j - tall.entry))
            }
            Some(tall) if j > tall.entry + extra => (j - extra, None),
            _ => (j, None),
        }
    }

    /// The stop holding the filters card's count line, which carries the
    /// page's transient line, where the header scrolls (`None` where it
    /// stays): the card, or the part of it that holds the line where a short
    /// list lists the card a part at a time.
    fn filters_stop(&self) -> Option<usize> {
        self.scrolls
            .then(|| {
                self.header
                    .iter()
                    .position(|(node, _)| ui_node_holds(node, "settings/messages/header"))
            })
            .flatten()
    }

    /// Where every row's body text begins, from the card's left edge.
    fn indent(&self) -> f32 {
        if self.lead.stacked {
            // Under a stacked head the body has the row, as its title does.
            self.lead.gap
        } else if self.compact {
            self.lead.mark + self.lead.gap
        } else {
            self.lead.title_x()
        }
    }

    /// The card's height holding `rows`: its padding, the rows, a hairline between
    /// each two, and the day headers among them.
    fn card_height(&self, rows: std::ops::Range<usize>) -> f32 {
        if rows.is_empty() {
            return 0.0;
        }
        let hairlines = rows.len() - 1;
        let days = rows
            .clone()
            .filter(|&k| self.day_before(k, rows.start).is_some())
            .count();
        2.0 * MESSAGES_LIST_PAD
            + self.heights[rows].iter().sum::<f32>()
            + hairlines as f32
            + days as f32 * self.day_h
    }

    /// The day whose header stands above entry `k` in a view whose first entry is
    /// `first`: where the section's day changes, and over the view's first entry
    /// whatever its place in its day. `None` in a list of one day.
    fn day_before(&self, k: usize, first: usize) -> Option<i64> {
        let sections = self.sections.as_ref()?;
        let day = *sections.get(k)?;
        (k == first || k == 0 || sections.get(k - 1) != Some(&day)).then_some(day)
    }

    /// What the list shows with stop `top` at its top: on a compact page the
    /// header items from there that fit (at least one), then — once every
    /// header item is seated — the entries that fit under them; else the
    /// entries from `top`, at least one. An entry is seated whole or not at
    /// all.
    fn view(&self, top: usize) -> MessagesView {
        let lead = self.lead_stops();
        let n = self.heights.len();
        let top = top.min(self.stops().saturating_sub(1));
        let (header, first, part, room) = if top < lead {
            let (mut end, mut used) = (top, 0.0_f32);
            for k in top..lead {
                let h = self.header[k].1 + if k > top { self.item_gap } else { 0.0 };
                if k > top && used + h > self.room + 0.01 {
                    break;
                }
                used += h;
                end = k + 1;
            }
            let room = if end == lead {
                self.room - used - self.gap
            } else {
                f32::NEG_INFINITY
            };
            (top..end, 0, None, room)
        } else {
            let (first, part) = self.stop_entry(top - lead);
            (0..0, first, part, self.room)
        };
        // A view that starts on a tall entry's part shows that part, and
        // after its last part the entries that fit under it.
        if let (Some(part), Some(tall)) = (part, self.tall.as_ref()) {
            let mut end = first + 1;
            if part + 1 == tall.parts.len() {
                let mut used = self.part_card_height(first, part);
                while end < n {
                    let more = 1.0 + self.heights[end];
                    if used + more > room + 0.01 {
                        break;
                    }
                    used += more;
                    end += 1;
                }
            }
            return MessagesView {
                header,
                rows: first..end,
                part: Some(part),
            };
        }
        let mut end = first;
        while end < n {
            // A tall entry is seated only from its first part's own stop.
            if self.tall.as_ref().is_some_and(|tall| tall.entry == end) {
                break;
            }
            let fits = self.card_height(first..end + 1) <= room + 0.01;
            // The list's top entry is shown whatever its height.
            let heads = end == first && header.is_empty();
            if !(fits || heads) {
                break;
            }
            end += 1;
        }
        MessagesView {
            header,
            rows: first..end,
            part: None,
        }
    }

    /// The card's height showing part `part` of the tall entry `entry`
    /// alone: its padding, the entry's day header where it carries one, and
    /// the part.
    fn part_card_height(&self, entry: usize, part: usize) -> f32 {
        let day = if self.sections.is_some() {
            self.day_h
        } else {
            0.0
        };
        let height = self
            .tall
            .as_ref()
            .and_then(|tall| (tall.entry == entry).then(|| tall.heights[part]))
            .unwrap_or_default();
        2.0 * MESSAGES_LIST_PAD + day + height
    }

    /// Whether the view from `top` reaches the list's end: its last entry,
    /// a tall one's last part.
    fn reaches_end(&self, top: usize) -> bool {
        let view = self.view(top);
        if self.heights.is_empty() {
            view.header.end == self.lead_stops()
        } else {
            view.rows.end == self.heights.len()
                && view.part.is_none_or(|part| {
                    self.tall
                        .as_ref()
                        .is_none_or(|tall| part + 1 == tall.parts.len())
                })
        }
    }

    /// The last stop the list scrolls to: the least whose view reaches the
    /// end, so the list never scrolls past its last entry.
    fn limit(&self) -> usize {
        let mut top = self.stops().saturating_sub(1);
        while top > 0 && self.reaches_end(top - 1) {
            top -= 1;
        }
        top
    }

    /// The least scroll from `top` that shows entry `index` whole: `top`
    /// itself where it does; up to the entry where it is above; else down,
    /// stop by stop, to the first view that holds it.
    fn reveal(&self, index: usize, top: usize) -> usize {
        let limit = self.limit();
        let top = top.min(limit);
        let view = self.view(top);
        if view.rows.contains(&index) {
            return top;
        }
        let stop = self.entry_stop(index);
        if index < view.rows.start {
            return stop.min(limit);
        }
        let mut next = top + 1;
        while next < stop && !self.view(next).rows.contains(&index) {
            next += 1;
        }
        next.min(limit)
    }

    /// A deep link's landing: where the view from `top` already shows entry `index`
    /// whole, there; else the entry at the top of the list, as far as it scrolls.
    fn land(&self, index: usize, top: usize) -> usize {
        let limit = self.limit();
        let top = top.min(limit);
        if self.view(top).rows.contains(&index) {
            top
        } else {
            self.entry_stop(index).min(limit)
        }
    }
}

/// [`MessagesPlan`] for the `visible` entries under `state`'s filter, the
/// entry `state` has open fitted to the room.
fn messages_plan(
    state: &SettingsViewState,
    messages: &MessagesState,
    visible: &[&MessageView],
    width: SettingsWidth,
    viewport: LogicalRect,
) -> MessagesPlan {
    messages_plan_opening(
        state,
        messages,
        visible,
        width,
        viewport,
        state.messages_selected,
        state.messages_tag_menu,
    )
}

/// [`messages_plan`] with entry `open` open (`None`: every entry closed),
/// and the Tag pop-up in `tag_menu`'s state, including the last render's
/// state when a resize reconstructs the list that `page_scroll` counted.
fn messages_plan_opening(
    state: &SettingsViewState,
    messages: &MessagesState,
    visible: &[&MessageView],
    width: SettingsWidth,
    viewport: LogicalRect,
    open: Option<u64>,
    tag_menu: bool,
) -> MessagesPlan {
    let compact = width == SettingsWidth::Compact;
    let maximum = PageLayout::Form.maximum(width);
    let content_width = settings_page_content_width(viewport.width, width, maximum);
    let total = messages.entries.len();
    // The not-saved note and the empty log's words are the controls column's
    // own children, the page's whole content width, so they wrap to it.
    let text_width = content_width;
    let item_gap = 8.0;
    // The header items: the not-saved note, the filters with the count line
    // and the report buttons, then the no-match line or the invitation of an
    // empty log.
    let mut header: Vec<(UiNode, f32)> = Vec::new();
    if !messages.saved {
        header.push(wrapped_copy_node(
            "settings/messages/not-saved",
            MESSAGES_NOT_SAVED,
            SemanticRole::Text,
            StyleRef::Quiet,
            text_width,
            messages_line_height(),
            None,
        ));
    }
    // A compact page's list room, which its header items scroll in: under
    // the page's pinned heading, which every route keeps.
    let compact_room = compact.then(|| {
        let (_, heading) = pinned_heading(
            state,
            width,
            viewport,
            settings_page_gap(state, width, viewport),
            aterm_messages::page::HEADING,
            "",
        );
        compact_page_budget(state, viewport).content_height - heading
    });
    header.extend(messages_filter_items(
        state,
        messages,
        visible.len(),
        content_width,
        (compact, compact_room),
        tag_menu,
    ));
    if total == 0 {
        header.push(wrapped_copy_node(
            "settings/messages/empty",
            MESSAGES_EMPTY,
            SemanticRole::Text,
            StyleRef::Quiet,
            text_width,
            messages_line_height(),
            None,
        ));
    }
    // The room the list has: a compact page's whole section (its items
    // `MESSAGES_ROW_GAP` apart); on the wider pages the page's column under
    // the heading and the header, each its own gap apart — or, where the
    // header scrolls, the whole column under the heading (`whole`).
    let mut whole = 0.0_f32;
    let (mut room, gap) = if let Some(room) = compact_room {
        (room, MESSAGES_ROW_GAP)
    } else {
        let gap = responsive_page_gap(width, viewport.height);
        let header_h: f32 = header.iter().map(|(_, h)| *h).sum::<f32>()
            + header.len().saturating_sub(1) as f32 * item_gap;
        // Its heading and subtitle under the page's chrome ([`PageChrome`]).
        let (_, heading_h) = pinned_heading(
            state,
            width,
            viewport,
            gap,
            aterm_messages::page::HEADING,
            messages_page_subtitle(messages),
        );
        whole =
            noncompact_page_content_height(state, width, viewport.width, viewport.height, maximum)
                - heading_h;
        (whole - header_h - gap, gap)
    };
    let clock = MessagesClock::of(visible, messages.now_unix_ms, messages.utc_offset_s);
    // The lead column is the log's, whatever the filter admits: the whole log's words
    // under its own calendar are every word a filtered list can say.
    let all: Vec<&MessageView> = messages.entries.iter().collect();
    let log_clock = MessagesClock::of(&all, messages.now_unix_ms, messages.utc_offset_s);
    let mut lead = MessagesLead::measure(&all, log_clock, compact, content_width);
    // A stacked head stays inside the list: its title gives up lines (its
    // last cut) only where the log's longest would make it taller than the
    // room under its day header.
    if lead.stacked {
        let day = if clock.sections(visible).is_some() {
            messages_day_height()
        } else {
            0.0
        };
        while lead.title_lines > 1
            && messages_head_height(lead) > room - 2.0 * MESSAGES_LIST_PAD - day + 0.01
        {
            lead.title_lines -= 1;
        }
    }
    let mut plan = MessagesPlan {
        compact,
        scrolls: compact,
        content_width,
        header,
        item_gap,
        gap,
        room,
        lead,
        heights: Vec::new(),
        body: None,
        clock,
        sections: clock.sections(visible),
        day_h: messages_day_height(),
        tall: None,
    };
    // The open entry's body at the card's measure, bounded to what the card
    // has with the entry alone in it: it is read whole wherever the list
    // shows it. A body taller than the room under a wider page's pinned
    // header takes the header's room too: the header scrolls away with the
    // list, as on a compact page, before a line of the body is dropped.
    let body_width = (content_width - plan.indent() - 16.0).max(48.0);
    // An entry at the list's top carries its day's header too.
    let day_h = if plan.sections.is_some() {
        plan.day_h
    } else {
        0.0
    };
    plan.body = open
        .and_then(|id| visible.iter().find(|entry| entry.id == id))
        .map(|entry| {
            let mut body = MessagesBody::of(
                entry,
                body_width,
                messages.utc_offset_s,
                messages.now_unix_ms,
            );
            if messages_head_title(entry, plan.lead, content_width).1 {
                let (px, face) =
                    crate::native_ui::text_paint_metrics(SemanticRole::Text, StyleRef::Primary);
                body.name = wrap_to_box(&entry.title, body_width, &|line| {
                    crate::tray_raster::ui_text_width_for(face, line, px)
                });
            }
            let card = messages_head_height(plan.lead) + day_h + 2.0 * MESSAGES_LIST_PAD;
            if !compact && body.height() > room - card {
                plan.scrolls = true;
                room = whole;
                plan.room = room;
            }
            body.fit(room - card);
            (entry.id, body)
        });
    let head = messages_head_height(plan.lead);
    plan.heights = visible
        .iter()
        .map(|entry| match &plan.body {
            Some((id, body)) if *id == entry.id => head + body.height(),
            _ => head,
        })
        .collect();
    // NOR DOES A WIDER PAGE'S PINNED HEADER LEAVE NO ENTRY WHOLE: where the
    // room under it is shorter than the newest entry closed, the header
    // scrolls away with the list, as on a compact page — and the first
    // screen, holding no entry then, sheds the page's chrome where that
    // brings one under the header ([`PageChrome`]). At 220x12 at 1× text
    // the filters and count line left the list 12pt under the page's full
    // insets, its 30pt entries clipped on every screen.
    if !compact
        && !plan.scrolls
        && !visible.is_empty()
        && head + day_h + 2.0 * MESSAGES_LIST_PAD > room + 0.01
    {
        plan.scrolls = true;
        plan.room = whole;
    }
    // The open entry, where even fitted it is taller than the room, is read
    // a part at a time ([`MessagesTall`]), each part whole on its screen.
    plan.tall = plan
        .body
        .as_ref()
        .and_then(|(id, body)| {
            let index = visible.iter().position(|entry| entry.id == *id)?;
            Some((index, body))
        })
        .and_then(|(entry, body)| {
            let room = plan.room
                - 2.0 * MESSAGES_LIST_PAD
                - if plan.sections.is_some() {
                    plan.day_h
                } else {
                    0.0
                };
            (plan.card_height(entry..entry + 1) > plan.room + 0.01).then(|| {
                let node = messages_body_node(
                    visible[entry],
                    body,
                    plan.indent(),
                    (plan.content_width - plan.indent() - 16.0).max(48.0),
                    None,
                );
                let (parts, heights) = messages_tall_parts(head, &node, room);
                let title = format!("settings/messages/row/{}/title", visible[entry].id);
                let keys = parts
                    .iter()
                    .map(|blocks| {
                        let mut keys = std::collections::BTreeSet::new();
                        for block in blocks.clone() {
                            match block.checked_sub(1) {
                                None => {
                                    keys.insert(title.clone());
                                }
                                Some(child) => ui_node_keys(&node.children[child], &mut keys),
                            }
                        }
                        keys
                    })
                    .collect();
                MessagesTall {
                    entry,
                    parts,
                    heights,
                    keys,
                }
            })
        });
    plan
}

/// SETTINGS ▸ MESSAGES (design §4; rulings 262 and 264): the filters, the
/// count line with the report buttons, and the log — ONE dense scrolling
/// list, newest first, in one card of one-line entries with hairlines between
/// them; the filters narrow it and there is no pager. On the wider pages the
/// heading and the header stay and the card scrolls under them; on a compact
/// page, and under an open entry too tall for the room the pinned header
/// leaves, the header scrolls away with the list. An open entry grows its
/// card in place. What the render measured is recorded for the reducer: the limit
/// the list scrolls to, the stop it drew (re-seated across a resize,
/// [`messages_seated_top`]), and the geometry it laid out in.
fn messages_page(
    state: &SettingsViewState,
    messages: &MessagesState,
    width: SettingsWidth,
    viewport: LogicalRect,
) -> Vec<UiNode> {
    let visible = messages_visible(messages, &state.messages_filter);
    let plan = messages_plan(state, messages, &visible, width, viewport);
    let limit = plan.limit();
    state.record_result_page_limit(limit);
    let last = state
        .messages_page_geometry
        .replace(Some((width, viewport)));
    let selected = state
        .messages_selected
        .filter(|id| visible.iter().any(|entry| entry.id == *id));
    let open = selected.and_then(|id| visible.iter().position(|entry| entry.id == id));
    // A deep link that came before any render lands here, once.
    let top = match open {
        Some(index) if state.messages_reveal => {
            state.messages_reseat.set(None);
            plan.land(index, state.page_scroll)
        }
        _ => messages_seated_top(
            state,
            messages,
            &visible,
            &plan,
            last.filter(|&geometry| geometry != (width, viewport)),
            open,
        ),
    };
    state.messages_drawn.set(Some(top));
    state
        .messages_drawn_menu
        .set(Some((state.messages_tag_menu, plan.lead_stops())));
    let view = plan.view(top);
    state
        .messages_anchor
        .replace((view.rows.start > 0 && !view.rows.is_empty()).then(|| {
            MessagesAnchor {
                stop: top,
                id: visible[view.rows.start].id,
                below: visible[view.rows.start + 1..view.rows.end]
                    .iter()
                    .map(|entry| entry.id)
                    .collect(),
                filter: state.messages_filter.clone(),
            }
        }));
    let shown: Vec<&MessageView> = visible[view.rows.clone()].to_vec();
    // Where the page's transient line is said (s-13): on the count line where
    // that is on screen; else in the footer of the open entry whose button set
    // it (`SettingsApp::seat_messages_note` keeps one of the two on screen).
    let count_seated = plan
        .filters_stop()
        .is_none_or(|card| view.header.contains(&card));
    let entry_note = (!count_seated && state.status_clock().is_some())
        .then_some(state.messages_note_entry)
        .flatten()
        .filter(|id| selected == Some(*id))
        .zip(state.feedback.as_deref());
    let list = (!shown.is_empty()).then(|| {
        let (card, height) = messages_list_node(
            &shown,
            (view.rows.start, view.part),
            &plan,
            selected,
            entry_note,
        );
        messages_scroll_node(card, height, view.rows.clone(), visible.len())
    });
    let MessagesPlan {
        compact,
        scrolls,
        header,
        item_gap,
        gap,
        room,
        ..
    } = plan;
    // The header items this view seats: every one where the header stays;
    // where it scrolls, the ones the list has not scrolled past.
    let header: Vec<(UiNode, f32)> = header
        .into_iter()
        .enumerate()
        .filter(|(k, _)| !scrolls || view.header.contains(k))
        .map(|(_, item)| item)
        .collect();
    let controls = (!header.is_empty()).then(|| {
        let height = header.iter().map(|(_, h)| *h).sum::<f32>()
            + header.len().saturating_sub(1) as f32 * item_gap;
        UiNode::new(
            "settings/messages/controls",
            UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
        )
        .layout(
            Layout::column()
                .width(Length::Fill)
                .height(Length::Fixed(height))
                .gap(item_gap),
        )
        .children(header.into_iter().map(|(node, _)| node).collect())
    });
    if scrolls {
        // The header and the list in one clipped section under the heading:
        // a compact page's pinned one, a wider page's with its subtitle.
        let mut children: Vec<UiNode> = controls.into_iter().collect();
        children.extend(list);
        // A compact page's pinned heading; a wider page's with its subtitle,
        // both under the page's chrome ([`PageChrome`]).
        let (mut out, _) = pinned_heading(
            state,
            width,
            viewport,
            settings_page_gap(state, width, viewport),
            aterm_messages::page::HEADING,
            if compact {
                ""
            } else {
                messages_page_subtitle(messages)
            },
        );
        out.push(
            UiNode::new(
                "settings/messages/section",
                UiContent::Group(GroupSpec::new(aterm_messages::page::HEADING)),
            )
            .layout(
                Layout::column()
                    .width(Length::Fill)
                    .height(Length::Fixed(room.max(messages_row_height())))
                    .gap(gap)
                    .clipped(),
            )
            .children(children),
        );
        return out;
    }
    let (mut out, _) = pinned_heading(
        state,
        width,
        viewport,
        responsive_page_gap(width, viewport.height),
        aterm_messages::page::HEADING,
        messages_page_subtitle(messages),
    );
    out.extend(controls);
    out.extend(list);
    out
}

/// Stop `top` of a list whose header took `from` stops, as a stop of the
/// same list whose header takes `to` ([`MessagesPlan::lead_stops`]): an
/// entry's stop is that entry's; the list's top is its top (the header
/// whole above the first entry, in either form); a header item's, where the
/// header no longer scrolls, the top.
fn messages_restop(top: usize, from: usize, to: usize) -> usize {
    if top == 0 {
        0
    } else if top >= from {
        top - from + to
    } else {
        top.min(to)
    }
}

/// THE LIST KEEPS ITS PLACE ACROSS A RESIZE. The stop a Messages render draws
/// at the top of its list: `page_scroll`, or the stop the last render
/// re-seated it at that no event has adopted yet
/// ([`SettingsViewState::messages_reseat`]) — counted for the page as it was
/// laid out at `resized_from`, the last render's geometry where this one's
/// differs. A window resized across the switch, or across the compact
/// breakpoint, takes the header into the list or out of it
/// ([`MessagesPlan::scrolls`]), and the same stop then names another entry:
/// grown at 864×462 from a landing on a tall usage-limit entry, the open
/// entry went above the view. Where the header's stops changed, the list is
/// drawn from the same place ([`messages_restop`]) and an open entry (`open`,
/// its index) the reader had in view is kept in view
/// ([`MessagesPlan::reveal`]), and the next event adopts the stop drawn.
///
/// THE LIST KEEPS ITS PLACE ACROSS THE TAG POP-UP, however it closed (r4g-7).
/// Its chips grow the filters card, which can take a wider page's header into
/// the list; a pop-up opened or closed since the last render by a path that
/// did not re-count the stop (focusing Search closes it, by a click, a
/// reader's focus or the Search action) is re-counted here from the stops
/// that render counted ([`SettingsViewState::messages_drawn_menu`]).
fn messages_seated_top(
    state: &SettingsViewState,
    messages: &MessagesState,
    visible: &[&MessageView],
    plan: &MessagesPlan,
    resized_from: Option<(SettingsWidth, LogicalRect)>,
    open: Option<usize>,
) -> usize {
    let pending = state.messages_reseat.get();
    let from = pending.unwrap_or(state.page_scroll);
    // Reconstruct the geometry with the menu that counted the stop. Search
    // can close it without re-counting the stop, then a resize can arrive
    // before the next render; the current menu would measure the wrong old list.
    let drawn_menu = state
        .messages_drawn_menu
        .get()
        .map_or(state.messages_tag_menu, |(open, _)| open);
    let before = resized_from
        .map(|(width, viewport)| {
            messages_plan_opening(
                state,
                messages,
                visible,
                width,
                viewport,
                state.messages_selected,
                drawn_menu,
            )
        })
        .filter(|before| before.lead_stops() != plan.lead_stops());
    let menu_lead = state
        .messages_drawn_menu
        .get()
        .filter(|&(open, lead)| {
            resized_from.is_none() && open != state.messages_tag_menu && lead != plan.lead_stops()
        })
        .map(|(_, lead)| lead);
    let top = match (&before, menu_lead) {
        (Some(before), _) => {
            let was = from.min(before.limit());
            let top = messages_restop(was, before.lead_stops(), plan.lead_stops());
            match open {
                Some(index) if before.view(was).rows.contains(&index) => plan.reveal(index, top),
                _ => top.min(plan.limit()),
            }
        }
        (None, Some(lead)) => messages_restop(from, lead, plan.lead_stops()).min(plan.limit()),
        (None, None) => from.min(plan.limit()),
    };
    state
        .messages_reseat
        .set((pending.is_some() || before.is_some() || menu_lead.is_some()).then_some(top));
    top
}

/// One wrapped line of the Packages page's own sentences — a program row's height, at the
/// Caption step the reason wrap's budgets are measured for.
fn packages_wrapped_line_height() -> f32 {
    24.0_f32.max(20.0 * settings_text_scale())
}

/// THE BACKGROUND SERVICE LINE: its label, then what the loop runs, as plain text like
/// every other status line on the page — not a box, which read as a text field — with
/// the label at its own width and the value WRAPPED in the rest of `text_width`, the
/// card's measure. A one-line row cut every state of it short of its end at the medium
/// and compact widths — "Update Now still works", the last full check, and a retired
/// `auto_update`'s way out were the parts the ellipsis took (review of the Phase 4
/// merge, 2026-09-23). The value stays ONE semantic node carrying the whole sentence;
/// the painted lines are paint-only. A sentence that fits paints on one line, at the
/// control's height.
fn packages_service_status_row(packages: &PackagesProjection, text_width: f32) -> (UiNode, f32) {
    let key = "packages/loop-status";
    let label = "Background service";
    // ONE RULE FOR A FACT ([`FactColumns`]): the label beside its value where
    // both are whole there — the label's column its own width — else the label
    // over the value, each the card's width. The value's column was what a
    // fixed-width label left, floored at 48pt: at 2× text a phone-width card
    // painted the label past the card and the value's lines into 2pt.
    let rows = [(label.to_string(), packages.loop_status.clone())];
    let columns = FactColumns::measure(&rows, text_width, fact_name_width(label).ceil());
    let (_, values) = fact_card_lines(label, &packages.loop_status, columns);
    let line_height = packages_wrapped_line_height();
    let (label_node, label_height) = wrapped_words_node(
        &format!("{key}/label"),
        label,
        (SemanticRole::Text, StyleRef::Quiet),
        columns.label,
        line_height,
    );
    let count = values.len().max(1);
    let value_height = count as f32 * line_height;
    let value = UiNode::new(
        format!("{key}/value"),
        UiContent::Group(GroupSpec {
            label: Some(packages.loop_status.clone()),
            role: SemanticRole::Status,
            style: StyleRef::Plain,
        }),
    )
    .layout(
        Layout::column()
            .width(Length::Fill)
            .height(Length::Fixed(value_height)),
    )
    .children(
        values
            .into_iter()
            .enumerate()
            .map(|(index, text)| {
                UiNode::new(
                    format!("{key}/value/line/{}", index + 1),
                    UiContent::Text(TextSpec {
                        text,
                        role: SemanticRole::Status,
                        style: StyleRef::Primary,
                    }),
                )
                .layout(Layout::default().height(Length::Fixed(line_height)))
                .paint_only()
            })
            .collect(),
    );
    let (layout, content, gap) = if columns.stacked {
        (Layout::column(), label_height + 4.0 + value_height, 4.0)
    } else {
        // The gap the columns were measured with ([`FactColumns::measure`]):
        // 12pt here left the value 2pt short of the column its words were
        // wrapped for ("Unavailabl…" at 36 columns).
        (
            Layout::row(),
            label_height.max(value_height),
            ABOUT_METADATA_ROW_GAP,
        )
    };
    let mut label_node = label_node;
    if !columns.stacked {
        label_node.layout.width = Length::Fixed(columns.label);
    }
    // A sentence that fits paints on one line, at the control's height.
    let height = scaled_control_height().max(content + 8.0);
    (
        UiNode::new(
            key,
            UiContent::Group(GroupSpec::new(label).style(StyleRef::Plain)),
        )
        .layout(
            layout
                .height(Length::Fixed(height))
                .padding(Insets::symmetric(0.0, 4.0))
                .gap(gap),
        )
        .children(vec![label_node, value]),
        height,
    )
}

/// A RETIRED `[packages] auto_update = false` HOLDING AUTOMATIC UPDATES OFF: atpkg's own
/// sentence for it (`atpkg::config::auto_update_note` — doctor's and the config editor's
/// words, which never advise the rename that would write `enabled` twice), quiet and
/// WRAPPED to the card's measure under the switch it explains, every line kept. It rode
/// the hero's one-line detail until the review of the Phase 4 merge (2026-09-23), where its
/// remedy — the words it ends with — was the part the ellipsis took at every width. One
/// semantic node with the whole sentence; the lines are paint-only. ITS LINES ARE THE
/// CARD'S MEASURED COLUMN's, `text_width`, in the quiet type they paint in
/// ([`wrap_to_box`]): they were budgeted in characters per width class (56 on a compact
/// page whatever the text size), which a phone-width card at 2× text cut a line of to an
/// ellipsis, losing the remedy again.
fn packages_retired_switch_note(
    packages: &PackagesProjection,
    text_width: f32,
) -> Option<(UiNode, f32)> {
    let note = packages.retired_switch_note.as_deref()?;
    let (px, face) = crate::native_ui::text_paint_metrics(SemanticRole::Status, StyleRef::Quiet);
    let lines = wrap_to_box(note, text_width, &|line| {
        crate::tray_raster::ui_text_width_for(face, line, px)
    });
    let line_height = packages_wrapped_line_height();
    let height = lines.len() as f32 * line_height;
    Some((
        UiNode::new(
            "packages/retired-note",
            UiContent::Group(GroupSpec {
                label: Some(note.to_string()),
                role: SemanticRole::Text,
                style: StyleRef::Quiet,
            }),
        )
        .layout(Layout::column().height(Length::Fixed(height)))
        .children(
            lines
                .into_iter()
                .enumerate()
                .map(|(index, text)| {
                    UiNode::new(
                        format!("packages/retired-note/line/{}", index + 1),
                        UiContent::Text(TextSpec {
                            text,
                            role: SemanticRole::Status,
                            style: StyleRef::Quiet,
                        }),
                    )
                    .layout(Layout::default().height(Length::Fixed(line_height)))
                    .paint_only()
                })
                .collect(),
        ),
        height,
    ))
}

fn packages_page_subtitle() -> &'static str {
    "ALab tools and coding agents."
}

/// One registry-backed Switch row for the Packages page. The control uses the same
/// `settings/set/<key>` action, focus key, pending gate and semantic value shape as an
/// ordinary [`setting_row`] Bool, so OCC saves, Undo and accessibility behave
/// identically; only the placement is special. Returns the row and its height:
/// `row_height`, and a line or two more where the row's note goes under its name.
fn packages_switch_row(
    state: &SettingsViewState,
    key: &str,
    width: SettingsWidth,
    row_height: f32,
    text_width: f32,
) -> Option<(UiNode, f32)> {
    registry_switch_row(
        state,
        key,
        width,
        row_height,
        text_width,
        format!("packages/switch-row/{key}"),
        "packages",
    )
}

/// One registry-backed Switch row on a SPECIAL page, its row node keyed
/// `row_key` and its compact wrappers under `prefix`: the Packages page's
/// switches ([`packages_switch_row`]).
/// The control is the ordinary `settings/control/<key>` / `settings/set/<key>`
/// pair either way. The row's note follows its name on the label line where
/// the line holds both in `text_width`, and is a quiet line under the name
/// where it does not — wrapped, never cut off.
fn registry_switch_row(
    state: &SettingsViewState,
    key: &str,
    width: SettingsWidth,
    row_height: f32,
    text_width: f32,
    row_key: String,
    prefix: &str,
) -> Option<(UiNode, f32)> {
    let field = state.field_by_key(key)?;
    let availability = SettingsAvailability::for_state(state);
    let effect =
        setting_effect_projection(state, None, key, availability, state.presented_motion.get());
    // The row shows the resolved value its field was seeded with: for "Keep ALab
    // tools up to date" that is `Config::packages_enabled`, the retired `auto_update`
    // folded in, so a machine that key turned off reads Off, and writing the switch
    // drops the retired key (`prefs::RETIRED_PACKAGES_SPELLINGS`): one reader, one
    // writer.
    let value = SettingsState::display_value(field)
        .parse::<bool>()
        .unwrap_or(false);
    let focused = state
        .common
        .last_focus
        .as_ref()
        .is_some_and(|focus| focus.as_str() == format!("settings/control/{key}"));
    // When a save takes effect: said in its name, and painted on its second
    // line, in the same words ([`prefs::ApplicationTiming`]).
    let timing = application_timing_in(state, None, key)
        .filter(|_| !effect.unavailable())
        .map(prefs::ApplicationTiming::words);
    let mut semantic_label = timing.map_or_else(
        || field.label.to_string(),
        |timing| format!("{}{FACT_SEPARATOR}{timing}", field.label),
    );
    // The row's note, then why it is held back; never the config key.
    let mut description = row_footnote(state, key)
        .map(std::borrow::Cow::into_owned)
        .unwrap_or_default();
    for note in &effect.notes {
        semantic_label.push_str(FACT_SEPARATOR);
        semantic_label.push_str(&note.semantic);
        if !description.is_empty() {
            description.push_str(FACT_SEPARATOR);
        }
        description.push_str(&note.semantic);
    }
    let changed = state.is_explicit(key);
    if changed {
        semantic_label.push_str(FACT_SEPARATOR);
        semantic_label.push_str(CHANGED_WORD);
    }
    // The page's status card says once why package settings do nothing in
    // this copy ("Package tool missing"), so no row repeats it; each control's
    // semantic label and description still carry it.
    let page_says_why = prefix == "packages" && availability.packages != PackageAdmission::Ready;
    let note = effect
        .notes
        .iter()
        .find(|note| !(page_says_why && note.kind == EffectNoteKind::Unavailable))
        .map(|note| note.visual.clone());
    let stacked = width == SettingsWidth::Compact;
    // Reset, or the place it keeps, so the switch never moves when it comes.
    let reset = if changed {
        setting_reset_button(field)
    } else {
        reset_slot(key)
    };
    // The name wraps, never cut; Changed and the note after it where they
    // fit in the row's fullest state, else on its second line, whole
    // ([`place_row_tags`]).
    let mut tags = RowTags::default();
    let mut worst = RowTags::default();
    if changed {
        tags.state.push(CHANGED_WORD.to_string());
    }
    worst.state.push(CHANGED_WORD.to_string());
    tags.facts.extend(note.clone());
    worst.facts.extend(note);
    let label_key = format!("settings/label/{key}");
    let label = UiNode::new(
        label_key.clone(),
        UiContent::Group(GroupSpec {
            label: Some(with_tags(field.label, tags.iter())),
            role: SemanticRole::Text,
            style: StyleRef::Plain,
        }),
    )
    .layout(Layout::default().width(Length::Fill).height(if stacked {
        Length::Fixed(22.0_f32.max(20.0 * settings_text_scale()))
    } else {
        Length::Fill
    }))
    .children(vec![row_label_visual(
        &label_key,
        vec![field.label.to_string()],
    )]);
    let control = UiNode::new(
        format!("settings/control/{key}"),
        UiContent::Switch(
            Control::new(
                SwitchSpec {
                    label: semantic_label,
                    description: (!description.is_empty()).then_some(description),
                },
                ActionId::new(format!("settings/set/{key}")),
            )
            .value(SemanticValue::Bool(value))
            .state(ControlState {
                focused,
                ..ControlState::default()
            })
            .style(StyleRef::Setting),
        ),
    )
    .layout(
        Layout::default()
            .width(Length::Fixed(switch_control_width(text_width)))
            .height(Length::Fill),
    );
    // The tags that did not fit, under the name, at the card's measure.
    let detail = |placement: &RowTagPlacement| {
        let second_line = row_second_line(placement, timing, None, text_width);
        (!second_line.is_empty()).then(|| {
            let line_height = row_detail_line_height();
            let height = second_line.len() as f32 * line_height;
            (
                UiNode::new(
                    format!("{prefix}/detail/{key}"),
                    UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
                )
                .layout(
                    Layout::column()
                        .width(Length::Fill)
                        .height(Length::Fixed(height)),
                )
                .children(
                    second_line
                        .into_iter()
                        .enumerate()
                        .map(|(line, text)| {
                            reserved_or_detail_line(
                                format!("{prefix}/detail/{key}/line-{line}"),
                                text,
                                line_height,
                            )
                        })
                        .collect(),
                ),
                height,
            )
        })
    };
    if stacked {
        // Under the name, over the switch, as every stacked switch row: its
        // Reset after the switch where their line holds both, else at the
        // end of the label line, else on a line of its own under the switch
        // ([`seat_stacked_reset`]); the name has what that leaves.
        let controls = UiNode::new(
            format!("{prefix}/controls/{key}"),
            UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
        )
        .layout(Layout::row().height(Length::Fill).gap(STACKED_CONTROL_GAP))
        .children(vec![
            UiNode::new(
                format!("{prefix}/control-spacer/{key}"),
                UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
            )
            .layout(Layout::default().width(Length::Fill).height(Length::Fill)),
            control,
            reset,
        ]);
        let mut row = UiNode::new(row_key, UiContent::Group(GroupSpec::new(field.label)))
            .layout(Layout::column().height(Length::Fixed(row_height)).gap(4.0))
            .children(vec![label, controls]);
        seat_stacked_reset(&mut row, field.label, text_width);
        let label_width = row_label_room(&row, true, text_width);
        let placement = place_row_tags(field.label, &tags, &worst, label_width, false);
        let detail = detail(&placement);
        set_row_label_lines(&mut row, placement.lines, true);
        if let Some((detail, detail_height)) = detail {
            row.children.insert(1, detail);
            row.layout.height = Length::Fixed(fixed_height(&row) + detail_height + 4.0);
        }
        let height = fixed_height(&row);
        return Some((row, height));
    }
    // Measured beside the switch AND Reset's place: every inline row keeps
    // that place (`reset_slot`) whether or not Reset is drawn, so an unwritten
    // row's label gets no more room than a Changed one's.
    let label_width = inline_row_label_width(&EditKind::Bool, text_width, true);
    let placement = place_row_tags(field.label, &tags, &worst, label_width, false);
    let detail = detail(&placement);
    let row = UiNode::new(
        row_key.clone(),
        UiContent::Group(GroupSpec::new(field.label)),
    )
    .layout(
        Layout::row()
            .height(Length::Fixed(row_height))
            .padding(Insets::symmetric(0.0, 4.0))
            .gap(12.0),
    )
    .children(vec![label, control, reset]);
    let mut row = row;
    set_row_label_lines(&mut row, placement.lines, false);
    let row_height = fixed_height(&row);
    Some(match detail {
        None => (row, row_height),
        Some((detail, detail_height)) => {
            let height = row_height + detail_height;
            (
                UiNode::new(
                    format!("{row_key}/with-note"),
                    UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
                )
                .layout(Layout::column().height(Length::Fixed(height)))
                .children(vec![row, detail]),
                height,
            )
        }
    })
}

/// The switches the Packages page carries: "Keep ALab tools up to date" — `[packages] enabled`,
/// THE switch, with the retired `auto_update` folded in (2026-09-23), applied LIVE by the
/// window's package loop (Phase 4) — the one install consent (`auto_install`, the retired
/// `seed_install` folded in), and the reroute's announcement (`[reroute] announce`, the
/// setting that replaced `$ATERM_REROUTE_QUIET`). The retired keys are no rows at all: they
/// are read through the two switches, and when a retired `auto_update = false` is what
/// holds updates off the service line names it and atpkg's sentence for it is a wrapped
/// note under the first switch ([`packages_retired_switch_note`], not a row: no control,
/// and the compact count adds it). A row more pushes the consent card past the
/// compact page's height budget, at which point the page decomposes. The visible way out
/// of tools you do not want is the "Remove ALab Tools" action beside these
/// switches, which is durable (`atpkg uninstall --all` writes a `declined` marker).
const PACKAGES_PAGE_SWITCHES: [&str; 3] = [
    prefs::EDIT_PACKAGES_ENABLED,
    prefs::EDIT_PACKAGES_AUTO_INSTALL,
    prefs::EDIT_REROUTE_ANNOUNCE,
];

/// The Activity card's heading row: the heading and the "Open Log" button, which opens
/// `packages.log` through the host (NSWorkspace — no shell, no Terminal).
fn packages_activity_heading(
    packages: &PackagesProjection,
    height: f32,
    width: f32,
) -> (UiNode, f32) {
    // The caption and Open Log side by side where the card's column holds the
    // caption whole beside the button's words; else the caption over the
    // button, each the column's ("ACTI…" beside a button run past the card
    // at 2× text on a phone-width page).
    let (caption_px, caption_face) =
        crate::native_ui::text_paint_metrics(SemanticRole::Heading, StyleRef::Quiet);
    let caption_width = crate::tray_raster::ui_text_width_for(caption_face, "ACTIVITY", caption_px);
    let button_width =
        (112.0 * settings_text_scale().min(1.5)).max(page_button_width("Open Log", f32::INFINITY));
    let beside = caption_width + 8.0 + button_width <= width + crate::native_ui::TEXT_FIT_SLACK;
    let (visual, lines) = button_words("Open Log", &[], button_width.min(width));
    let button_height = crate::native_ui::native_button_height_for_lines(lines, height);
    let button = UiNode::new(
        "packages/activity/open-log",
        UiContent::Button(
            Control::new(
                ButtonSpec::new("Open Log")
                    .visual_label(visual)
                    .description("Opens the package log"),
                ActionId::new("packages/activity/open-log"),
            )
            .state(ControlState {
                enabled: packages.log_path.is_some() && !packages.activity.is_empty(),
                ..ControlState::default()
            })
            .style(StyleRef::Secondary),
        ),
    )
    .layout(
        Layout::default()
            .width(Length::Fixed(button_width.min(width)))
            .height(if beside {
                Length::Fill
            } else {
                Length::Fixed(button_height)
            }),
    );
    if beside {
        let caption = UiNode::new(
            "packages/activity/heading",
            UiContent::Text(TextSpec {
                text: "ACTIVITY".to_string(),
                role: SemanticRole::Heading,
                style: StyleRef::Quiet,
            }),
        )
        .layout(Layout::default().width(Length::Fill).height(Length::Fill));
        return (
            UiNode::new(
                "packages/activity/header",
                UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
            )
            .layout(Layout::row().height(Length::Fixed(height)).gap(8.0))
            .children(vec![caption, button]),
            height,
        );
    }
    let (caption, caption_height) = caption_node("packages/activity/heading", "ACTIVITY", width);
    let total = caption_height + 8.0 + button_height;
    (
        UiNode::new(
            "packages/activity/header",
            UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
        )
        .layout(Layout::column().height(Length::Fixed(total)).gap(8.0))
        .children(vec![caption, button]),
        total,
    )
}

/// One painted line of the Activity card: an event's first line (`packages/activity/<n>`),
/// or a wrapped continuation of it (`packages/activity/<n>/more/<i>`) — a long reason is
/// never left to the painter's ellipsis ([`crate::packages_screen::activity_text_lines`]).
/// `trouble` rides every line of a failure or a refusal.
#[derive(Clone, Debug, PartialEq, Eq)]
struct ActivityRow {
    key: String,
    text: String,
    trouble: bool,
    continuation: bool,
}

/// The Activity lines: every event the log's tail holds (at most
/// [`atpkg::packages_log::ACTIVITY_EVENTS`]) as `when · what`, wrapped to `width`'s
/// measure ([`packages_reason_wrap_chars`], the program rows' own), and where the tail is
/// full, one quiet line that says Open Log has the rest; or the one line that says
/// nothing is recorded yet. Each line is a stop of the page's one scrolling list (s-25):
/// the card has no pager of its own, whose last page shrank the card and jumped the page
/// under the reader and stranded focus on its disabled Older.
fn packages_activity_rows(packages: &PackagesProjection, width: SettingsWidth) -> Vec<ActivityRow> {
    let single = |key: &str, text: &str| {
        vec![ActivityRow {
            key: key.to_string(),
            text: text.to_string(),
            trouble: false,
            continuation: false,
        }]
    };
    if !packages.observed {
        return single("packages/activity/loading", "Reading the package log…");
    }
    if packages.activity.is_empty() {
        return single(
            "packages/activity/empty",
            "No package activity recorded yet.",
        );
    }
    let wrap = packages_reason_wrap_chars(width);
    let mut rows = Vec::new();
    for (i, line) in packages.activity.iter().enumerate() {
        let key = format!("packages/activity/{i}");
        let text = format!("{}{FACT_SEPARATOR}{}", line.when, line.text);
        for (n, text) in crate::packages_screen::activity_text_lines(&text, wrap)
            .into_iter()
            .enumerate()
        {
            rows.push(ActivityRow {
                key: if n == 0 {
                    key.clone()
                } else {
                    format!("{key}/more/{n}")
                },
                text,
                trouble: line.trouble,
                continuation: n > 0,
            });
        }
    }
    if packages.activity_capped {
        rows.push(ActivityRow {
            key: "packages/activity/more".to_string(),
            text: format!(
                "The newest {} events. Open Log has the whole log.",
                packages.activity.len()
            ),
            trouble: false,
            continuation: false,
        });
    }
    rows
}

/// One Activity line's node: body text, a failure or a refusal in the danger colour (a
/// `Status` role would paint any style but Primary as a quiet caption — the opposite of
/// what a person scanning for trouble needs).
fn packages_activity_row(
    key: String,
    text: &str,
    trouble: bool,
    height: f32,
    width: f32,
) -> (UiNode, f32) {
    // Its lines were budgeted in average glyphs per width class
    // ([`packages_reason_wrap_chars`]); each is wrapped again to the card's
    // MEASURED column, so a narrow card at large text breaks a line it cannot
    // hold instead of the painter cutting it ("No package act…").
    wrapped_words_node(
        &key,
        text,
        (
            SemanticRole::Text,
            if trouble {
                StyleRef::Danger
            } else {
                StyleRef::Primary
            },
        ),
        width,
        height,
    )
}

/// One program line as the Programs card's row: the line's node where it is
/// one line of the card's MEASURED column `width`, else its words over as
/// many lines as that needs ([`wrapped_words_node`]), its accessible text —
/// and a state line's canonical state — whole on the row. The lines are
/// budgeted in average glyphs per width class first
/// ([`packages_reason_wrap_chars`]); this is what keeps the painter from
/// cutting one a narrow card at large text cannot hold ("Readin…").
fn packages_program_line_row(line: &ProgramLine, row_height: f32, width: f32) -> (UiNode, f32) {
    let style = if line.quiet {
        StyleRef::Quiet
    } else {
        StyleRef::Primary
    };
    let (wrapped, height) = wrapped_words_node(
        &line.key,
        &line.text,
        (SemanticRole::Status, style),
        width,
        row_height,
    );
    if matches!(wrapped.content, UiContent::Text(_)) {
        return (packages_program_line_node(line, row_height), row_height);
    }
    let mut wrapped = wrapped;
    if let (Some(state), UiContent::Group(group)) = (line.state.as_deref(), &mut wrapped.content) {
        group.label = Some(format!("{}\n{state}", line.text));
    }
    (wrapped, height)
}

/// A Packages verb button's width in a row, the gap between two, and the hero card's
/// horizontal padding: the row's measure.
const PACKAGES_ACTION_WIDTH: f32 = 196.0;
const PACKAGES_ACTION_GAP: f32 = 8.0;
const PACKAGES_HERO_PAD_X: f32 = 22.0;

/// The Automatic maintenance card's note: what the switches do, the default
/// install and its way out, and the download it may start.
const PACKAGE_CONSENT_NOTE: &str = "Keeping ALab tools up to date covers ALab tools and the coding agents aterm manages, and takes effect at once; Check & Update Now works either way. aterm installs ALab tools by default; Remove ALab Tools undoes that. Installing ALab tools lets aterm download them \u{2014} several GB \u{2014} at the next check, and new ones as they join.";
const PACKAGE_CONSENT_LINES: [&str; 2] = [
    "Changes take effect at once; Check & Update Now always works.",
    "aterm may download several GB of tools at the next check.",
];
/// The note where this copy can't install packages: nothing here runs, so it
/// says what the switches do in a copy that can.
const PACKAGE_CONSENT_NOTE_INERT: &str = "Saved for a copy of aterm that can install packages. There, keeping ALab tools up to date covers ALab tools and the coding agents aterm manages, and installing ALab tools lets aterm download them \u{2014} several GB \u{2014} at the next check, and new ones as they join.";
const PACKAGE_CONSENT_LINES_INERT: [&str; 2] = [
    "Saved for a copy of aterm that can install packages.",
    "There, aterm may download several GB of tools at the next check.",
];
/// The note in a copy without its package tool, where none of this runs.
const PACKAGE_CONSENT_UNAVAILABLE: &str = "Saved for a copy of aterm that has its package tool.";

fn packages_page(
    state: &SettingsViewState,
    packages: &PackagesProjection,
    width: SettingsWidth,
    viewport_width: f32,
    viewport_height: f32,
) -> Vec<UiNode> {
    let text_scale = settings_text_scale();
    let title_height = 20.0_f32.max(16.0 * text_scale);
    let headline_height = 42.0_f32.max(30.0 * text_scale);
    let detail_height = 24.0_f32.max(20.0 * text_scale);
    let action_control_height = 36.0_f32.max(32.0 * text_scale);
    // The three verbs sit in a row wherever the hero card holds them whole —
    // at the row's even width where that fits (ruling 270), else each at its
    // own label's width (day three: at 100 columns the Medium page cut the
    // third to `Remove ALab T…` at the card's edge) — and stack only where even
    // that does not fit.
    let hero_inner =
        settings_page_content_width(viewport_width, width, PageLayout::Form.maximum(width))
            - 2.0 * PACKAGES_HERO_PAD_X;
    let action_labels = [
        "Check & Update Now",
        "Install ALab Tools Now",
        "Remove ALab Tools",
    ];
    // Even only where each label is whole in the even width, measured: at 2×
    // text a wide hero held three 196pt buttons and cut every label in them
    // ("Check & Up…").
    let even_actions = hero_inner >= 3.0 * PACKAGES_ACTION_WIDTH + 2.0 * PACKAGES_ACTION_GAP
        && action_labels
            .iter()
            .all(|label| page_button_width(label, f32::INFINITY) <= PACKAGES_ACTION_WIDTH);
    let natural_actions = action_labels
        .iter()
        .map(|label| page_button_width(label, hero_inner))
        .sum::<f32>()
        + 2.0 * PACKAGES_ACTION_GAP
        <= hero_inner;
    let stack_actions = !even_actions && !natural_actions;

    // Action row: the two verbs through the host executor (co-located atpkg,
    // off the UI thread). Disabled with an honest reason whenever the manager
    // cannot act; the busy one paints as busy while its worker runs. A copy
    // whose manager can never act paints no primary at all.
    let can_act = !packages.tool_observed || (packages.available && packages.manager_enabled);
    // Each verb's words by the one rule page buttons keep ([`button_words`]):
    // its whole label, else its short form ("Check & Update", "Install ALab
    // Tools"), else on as many lines as the stacked button needs, never cut
    // ("Check & Up…" at 22 columns).
    let words = |label: &str| {
        let short: &[&str] = match label {
            "Check & Update Now" => &["Check & Update"],
            "Install ALab Tools Now" => &["Install ALab Tools"],
            _ => &[],
        };
        button_words(label, short, hero_inner)
    };
    let action_button = |key: &str, label: &str, busy: PackagesBusy, primary: bool| {
        let (visual, lines) = words(label);
        UiNode::new(
            key,
            UiContent::Button(
                Control::new(
                    ButtonSpec::new(label).visual_label(&visual),
                    ActionId::new(key),
                )
                .state(ControlState {
                    enabled: packages.actions_enabled,
                    busy: packages.busy == Some(busy),
                    ..ControlState::default()
                })
                .style(if primary && can_act {
                    StyleRef::Primary
                } else {
                    StyleRef::Secondary
                }),
            ),
        )
        .layout(
            Layout::default()
                .width(Length::Fixed(if even_actions {
                    PACKAGES_ACTION_WIDTH
                } else if lines > 1 {
                    hero_inner
                } else {
                    page_button_width(&visual, hero_inner)
                }))
                .height(if stack_actions {
                    Length::Fixed(crate::native_ui::native_button_height_for_lines(
                        lines,
                        action_control_height,
                    ))
                } else {
                    Length::Fill
                }),
        )
    };
    let [check_label, install_label, remove_label] = action_labels;
    let actions = vec![
        action_button("packages/check", check_label, PackagesBusy::Check, true),
        action_button(
            "packages/install-default",
            install_label,
            PackagesBusy::Install,
            false,
        ),
        // The exit beside the entrance: a first launch downloads multiple GB without
        // a prompt (`packages.auto_install`), and trashing aterm.app orphans them under
        // Application Support, so removal must not be a CLI verb the user has to
        // discover.
        action_button(
            "packages/uninstall-all",
            remove_label,
            PackagesBusy::Uninstall,
            false,
        ),
    ];
    // One row of the hero either way, so the list keeps the buttons together
    // with the status they act on wherever the card fits a screen, and never
    // leaves a button alone on a screen of its own.
    let action_rows: Vec<(UiNode, f32)> = if stack_actions {
        let height = actions.iter().map(fixed_height).sum::<f32>() + 2.0 * PACKAGES_ACTION_GAP;
        vec![(
            UiNode::new(
                "packages/actions",
                UiContent::Group(GroupSpec::new("Package actions")),
            )
            .layout(
                Layout::column()
                    .height(Length::Fixed(height))
                    .gap(PACKAGES_ACTION_GAP),
            )
            .children(actions),
            height,
        )]
    } else {
        vec![(
            UiNode::new(
                "packages/actions",
                UiContent::Group(GroupSpec::new("Package actions")),
            )
            .layout(
                Layout::row()
                    .height(Length::Fixed(action_control_height))
                    .gap(PACKAGES_ACTION_GAP),
            )
            .children(actions),
            action_control_height,
        )]
    };

    // Status hero: headline and detail from the shared projection (one derivation in
    // packages_screen serves screen and introspection). Where the signed builds come
    // from is said once; the pinned key's fingerprint is `aterm pkg doctor`'s.
    let service_line = if packages_has_service_line(packages) {
        format!("Signed updates from {}", packages.index_source)
    } else {
        String::new()
    };
    // The source wraps to the hero's measure, as the detail does: one line
    // ran 43pt past the hero's column at 2× text in a 60x20 window.
    let service = (!service_line.is_empty()).then(|| {
        wrapped_words_node(
            "packages/service-line",
            &service_line,
            (SemanticRole::Status, StyleRef::Quiet),
            hero_inner,
            22.0_f32.max(18.0 * text_scale),
        )
    });
    let service_height = service.as_ref().map_or(0.0, |(_, height)| *height);
    // The detail wraps to the hero's measure: a remedy cut by an ellipsis
    // loses exactly the part that says what to do.
    // The whole sentence, at the hero's own measure: the hero is listed row
    // by row, so a long remedy takes lines, never an ellipsis ("package
    // tool.…" at three lines).
    let (detail, detail_height) = wrapped_words_node(
        "packages/detail",
        packages.detail.as_deref().unwrap_or_default(),
        (SemanticRole::Text, StyleRef::Quiet),
        hero_inner,
        detail_height,
    );
    let (headline, headline_height) = fitted_headline_node(
        "packages/headline",
        &packages.headline,
        StyleRef::Hero,
        hero_inner,
        headline_height,
    );
    let mut status_lines = vec![
        UiNode::new(
            "packages/title",
            UiContent::Text(TextSpec {
                // Not "Packages": the page heading says that just above. In
                // caption case, as "AUTOMATIC MAINTENANCE" under it.
                text: "STATUS".to_string(),
                role: SemanticRole::Heading,
                style: StyleRef::Quiet,
            }),
        )
        .layout(Layout::default().height(Length::Fixed(title_height))),
        headline,
        detail,
    ];
    if let Some((line, _)) = service {
        status_lines.push(line);
    }
    let status_height = title_height
        + headline_height
        + detail_height
        + service_height
        + status_lines.len().saturating_sub(1) as f32 * 8.0;
    let mut hero_rows = vec![(
        UiNode::new(
            "packages/status",
            UiContent::Group(GroupSpec::unlabeled(SemanticRole::Group)),
        )
        .layout(
            Layout::column()
                .height(Length::Fixed(status_height))
                .gap(8.0),
        )
        .children(status_lines),
        status_height,
    )];
    hero_rows.extend(action_rows);
    let hero = SplitCard {
        key: "packages/hero".to_string(),
        spec: GroupSpec::new("Package status").style(StyleRef::Primary),
        padding: Insets::symmetric(PACKAGES_HERO_PAD_X, 20.0),
        gap: 8.0,
        head: Vec::new(),
        rows: hero_rows,
    };

    // Consent switches: registry-backed dotted keys through the ordinary
    // ConfigPatch/OCC path; flipping auto_install here is the §11 consent.
    // A compact card lays a switch out on one line wherever its label has
    // the room, as the field pages do.
    let consent_text_width = hero_inner + 2.0 * PACKAGES_HERO_PAD_X - 40.0;
    let switch_inline = width == SettingsWidth::Compact
        && compact_row_inline(&EditKind::Bool, consent_text_width, true);
    let switch_width = if switch_inline {
        SettingsWidth::Medium
    } else {
        width
    };
    let switch_height = if switch_inline {
        compact_inline_row_height()
    } else {
        width.row_height()
    };
    let consent_line_height = 21.0_f32.max(18.0 * text_scale);
    // TELL THE TRUTH ABOUT THE DEFAULT. aterm installs and maintains the ALab
    // toolset by default — that is what the app is for — so copy implying the
    // toolchain only arrives if you enable Auto-install described a product that
    // does not exist, while multi-GB installs happened anyway. `auto_install` now
    // means only what its name says: may atpkg pull the set over the NETWORK onto a
    // machine that has none. "Remove ALab Tools" is the durable way out, and it is
    // named here because a default this large must state its off switch.
    // ONE SWITCH FOR UPDATES, AND IT IS LIVE (Phase 4): `[packages] enabled` is
    // "Keep ALab tools up to date" (the retired `auto_update` folded in), and the
    // window's package loop re-reads it before every pass and every few seconds of a park
    // — off stands the loop down, on resumes it, no relaunch. The install consent is the
    // one key it names (the retired `seed_install` folded in), and the reroute's
    // announcement is the third row.
    // Each clause only where it is true: a copy without its package tool
    // runs none of this, and "Check & Update Now works" only where it does.
    let (consent_note, consent_lines): (&str, &[&str]) =
        if packages.tool_observed && !packages.available {
            (
                PACKAGE_CONSENT_UNAVAILABLE,
                std::slice::from_ref(&PACKAGE_CONSENT_UNAVAILABLE),
            )
        } else if !packages.tool_observed || packages.manager_enabled {
            (PACKAGE_CONSENT_NOTE, &PACKAGE_CONSENT_LINES)
        } else {
            (PACKAGE_CONSENT_NOTE_INERT, &PACKAGE_CONSENT_LINES_INERT)
        };
    // Each sentence WRAPS to the card's text column, at whole words, as the
    // layout measures it: authored as one line apiece, a narrow card (a 339pt
    // window's 267pt column) cut "Saved for a copy of aterm that has its
    // package tool." to "…its packa…".
    let (note_px, _) = crate::native_ui::text_paint_metrics(SemanticRole::Text, StyleRef::Quiet);
    let consent_painted = consent_lines
        .iter()
        .flat_map(|text| wrapped_copy_lines(text, note_px, consent_text_width))
        .collect::<Vec<_>>();
    let consent_note_height = consent_painted.len() as f32 * consent_line_height;
    let (consent_heading, consent_heading_height) = caption_node(
        "packages/consent-heading",
        "AUTOMATIC MAINTENANCE",
        consent_text_width,
    );
    let mut consent_rows = vec![packages_service_status_row(packages, consent_text_width)];
    for key in PACKAGES_PAGE_SWITCHES {
        if let Some(row) =
            packages_switch_row(state, key, switch_width, switch_height, consent_text_width)
        {
            consent_rows.push(row);
            // The retired key's note sits under the switch whose Off it explains.
            if key == prefs::EDIT_PACKAGES_ENABLED
                && let Some(note) = packages_retired_switch_note(packages, consent_text_width)
            {
                consent_rows.push(note);
            }
        }
    }
    consent_rows.push((
        UiNode::new(
            "packages/consent-note",
            UiContent::Group(GroupSpec {
                label: Some(consent_note.to_string()),
                role: SemanticRole::Text,
                style: StyleRef::Quiet,
            }),
        )
        .layout(Layout::column().height(Length::Fixed(consent_note_height)))
        .children(
            consent_painted
                .into_iter()
                .enumerate()
                .map(|(index, text)| {
                    UiNode::new(
                        format!("packages/consent-note/line/{}", index + 1),
                        UiContent::Text(TextSpec {
                            text,
                            role: SemanticRole::Text,
                            style: StyleRef::Quiet,
                        }),
                    )
                    // Its own line's height, so a screen too short for the
                    // note lists it a part at a time.
                    .layout(Layout::default().height(Length::Fixed(consent_line_height)))
                    .paint_only()
                })
                .collect(),
        ),
        consent_note_height,
    ));
    let consent = SplitCard {
        key: "packages/consent".to_string(),
        spec: GroupSpec::new("Automatic maintenance").style(StyleRef::Secondary),
        padding: Insets::all(20.0),
        gap: 8.0,
        head: vec![(consent_heading, consent_heading_height)],
        rows: consent_rows,
    };

    // The program list (canonical states verbatim; an agent program's row with its
    // vendor, license and size). Bounded rows keep the card height deterministic; the
    // overflow line says how much is elided.
    let row_height = 24.0_f32.max(20.0 * text_scale);
    let programs = SplitCard {
        key: "packages/programs".to_string(),
        spec: GroupSpec::new("Programs").style(StyleRef::Secondary),
        padding: Insets::all(20.0),
        gap: 8.0,
        head: vec![caption_node(
            "packages/programs-heading",
            "PROGRAMS",
            consent_text_width,
        )],
        rows: packages_program_lines(packages, width)
            .iter()
            .map(|line| packages_program_line_row(line, row_height, consent_text_width))
            .collect(),
    };

    // THE ACTIVITY CARD (Phase 4; s-25): the package log's newest events, every line a
    // stop of the page's one list — its heading and "Open Log" repeated on each screen
    // that shows its rows — and "Open Log" for the whole file. No pager of its own: the
    // card's height never changes under the reader.
    // The heading row carries a control (Open Log): it gets a control's height, the
    // action row's, so a 2× text scale never clips the button.
    let activity_heading_height = action_control_height;
    let activity_rows: Vec<(UiNode, f32)> = packages_activity_rows(packages, width)
        .into_iter()
        .map(|row| {
            packages_activity_row(
                row.key,
                &row.text,
                row.trouble,
                row_height,
                consent_text_width,
            )
        })
        .collect();
    let activity = SplitCard {
        key: "packages/activity".to_string(),
        spec: GroupSpec::new("Package activity").style(StyleRef::Secondary),
        padding: Insets::all(20.0),
        gap: 8.0,
        head: vec![packages_activity_heading(
            packages,
            activity_heading_height,
            consent_text_width,
        )],
        rows: activity_rows,
    };

    let viewport = LogicalRect::new(0.0, 0.0, viewport_width, viewport_height);
    let gap = settings_page_gap(state, width, viewport);
    let (mut out, heading_height) = pinned_heading(
        state,
        width,
        viewport,
        gap,
        "Packages",
        packages_page_subtitle(),
    );
    let room = (settings_list_body_height(state, width, viewport) - heading_height)
        .max(scaled_control_height());
    out.push(scroll::list_page_peeking(
        state,
        "packages/list",
        "Packages",
        vec![
            ListItem::Split(hero),
            ListItem::Split(consent),
            ListItem::Split(programs),
            ListItem::Split(activity),
        ],
        room,
        gap,
        settings_list_overhang(state, width, viewport),
    ));
    out
}

/// A node's fixed width (`0` for any other length).
fn fixed_width(node: &UiNode) -> f32 {
    match node.layout.width {
        Length::Fixed(width) => width,
        _ => 0.0,
    }
}

/// A node's fixed height (`0` for any other length).
fn fixed_height(node: &UiNode) -> f32 {
    match node.layout.height {
        Length::Fixed(height) => height,
        _ => 0.0,
    }
}

/// ONE SEARCH, ONE REACH: a Settings search as every surface that lists,
/// counts or previews its results reads it — the query, trimmed and
/// ASCII-lowercased, and how far it reaches ([`MatchReach`]). The reach is
/// the whole search's, never a row's: word hits wherever any source the
/// search lists has one (a visible setting, a page by its words or a control
/// it draws, a cursor style, a key only aterm.toml holds), else loose hits
/// too — so "cat" never adds "Continue A Turn" beside the settings that list
/// the word cat, and "board", a word of no setting, still finds Keyboard &
/// Input. Made once a pass ([`Self::of`]) and handed to the field list, the
/// page results, the aterm.toml card, the count and the preview, so the list,
/// the "N pages · M settings" line, the preview and the card agree.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) struct SearchQuery<'a> {
    /// The query, trimmed and ASCII-lowercased; empty where nothing is typed.
    pub(crate) text: &'a str,
    /// The search's reach.
    pub(crate) reach: MatchReach,
}

impl<'a> SearchQuery<'a> {
    /// `text` (trimmed, ASCII-lowercased) as a search over `state`, at the
    /// reach its results set: [`MatchReach::Words`] where any source the
    /// search lists has a word hit, else [`MatchReach::Loose`].
    pub(crate) fn of(state: &SettingsViewState, text: &'a str) -> Self {
        let words = Self {
            text,
            reach: MatchReach::Words,
        };
        if text.is_empty() || search_has_a_result(state, words) {
            words
        } else {
            Self {
                text,
                reach: MatchReach::Loose,
            }
        }
    }

    /// Whether nothing is typed.
    fn is_empty(self) -> bool {
        self.text.is_empty()
    }
}

/// The trimmed, ASCII-lowercased text of `state`'s search field.
fn folded_search(state: &SettingsViewState) -> String {
    state.search.trim().to_ascii_lowercase()
}

/// Whether `query` lists anything at all: a visible setting, a page, or a key
/// only aterm.toml holds — the very sources the search's lists draw, at its
/// reach, stopping at the first.
fn search_has_a_result(state: &SettingsViewState, query: SearchQuery<'_>) -> bool {
    let mut scratch = String::new();
    state
        .legacy
        .fields
        .iter()
        .filter(|field| settings_field_is_visible(state, field.key, false, true))
        .any(|field| {
            field_match_score_in(field, query, &mut scratch, &state.assets.themes).is_some()
        })
        || !search_page_hits(state, query).is_empty()
        || manual_search_has_match(state, query)
}

/// Stable global-search rank ([`crate::native_config_language::query_match_score`]):
/// a whole word before the start of one, the candidate's first word before a
/// later one, every word of the query starting a word somewhere among the
/// label, key and keywords (loose hits too under a loose search:
/// [`SearchQuery`]). One-shot rank for callers outside a sweep; the sweeps
/// use [`field_match_score_in`] so one scratch buffer serves the whole pass.
fn field_match_score(
    field: &EditField,
    query: SearchQuery<'_>,
    themes: &crate::app_config::ThemeCatalog,
) -> Option<SearchRank> {
    field_match_score_in(field, query, &mut String::new(), themes)
}

/// Rank `field` against `query` (`None` = no match).
///
/// `field.key` and every keyword from `keywords_of` are lowercase by construction
/// (`editable_field_keys_are_unique_and_lowercase`), so only the mixed-case label
/// folds, into the caller's reusable `scratch`: no allocation per key or keyword on
/// every keystroke.
fn field_match_score_in(
    field: &EditField,
    query: SearchQuery<'_>,
    scratch: &mut String,
    themes: &crate::app_config::ThemeCatalog,
) -> Option<SearchRank> {
    use crate::native_config_language::{PREFIX_AT_WORD, candidate_match_score, past_the_start};
    if query.is_empty() {
        return Some(SearchRank::EVERY);
    }
    let own = field_own_match_score(field, query, scratch);
    if field.key != prefs::EDIT_THEME {
        return own;
    }
    // Theme names are the Theme row's corpus too: "nord" finds the Theme
    // control, whose picker then opens filtered to it. A theme name is a
    // value the row holds, never what it is called (a synonym, ranked as a
    // word inside the row's name: [`past_the_start`]), and it counts only
    // where the query starts a word of it, at any reach: a two-letter
    // abbreviation that happens to be some theme's initials, or letters
    // inside a theme's name, are not a search for it — and the picker this
    // row opens seeds its filter by names alone ([`ThemeNaming`]).
    let by_name = theme_search_names(themes)
        .filter_map(|name| {
            candidate_match_score(&name.to_lowercase(), query.text, MatchReach::Words)
        })
        .min()
        .map(|rung| SearchRank::synonym(past_the_start(rung)));
    // A query that names a theme by the rule its picker seeds by ("nord
    // theme", "light gruvbox", "night tokyo": [`ThemeNaming`]) finds the row
    // too, on the last word rung a name reaches (every name word starts a
    // word of the theme's name).
    let named = ThemeNaming::of(query.text)
        .filter(|naming| {
            theme_search_entries(themes)
                .any(|(label, id, appearance)| naming.names(label, id, Some(appearance)))
        })
        .map(|_| SearchRank::synonym(PREFIX_AT_WORD));
    own.into_iter().chain(by_name).chain(named).min()
}

/// Every theme a search can name ([`ThemeNaming`]): the built-ins, and each
/// loaded theme file, with its name, catalog id and the side it is made for.
fn theme_search_entries(
    themes: &crate::app_config::ThemeCatalog,
) -> impl Iterator<Item = (&str, &str, aterm_types::Appearance)> {
    aterm_types::scheme::builtin_theme_list()
        .into_iter()
        .map(|builtin| (builtin.name, builtin.name, builtin.appearance))
        .chain(
            themes
                .ready_themes()
                .map(|(id, meta)| (meta.display_name.as_str(), id, meta.appearance)),
        )
}

/// Every name a theme can be searched by: the built-ins, and each loaded
/// theme file's id and own name.
fn theme_search_names(themes: &crate::app_config::ThemeCatalog) -> impl Iterator<Item = &str> {
    aterm_types::scheme::builtin_names().into_iter().chain(
        themes
            .ready_themes()
            .flat_map(|(id, meta)| [id, meta.display_name.as_str()]),
    )
}

fn field_own_match_score(
    field: &EditField,
    query: SearchQuery<'_>,
    scratch: &mut String,
) -> Option<SearchRank> {
    scratch.clear();
    scratch.extend(
        field
            .label
            .chars()
            .map(|character| character.to_ascii_lowercase()),
    );
    // What the row is called — its label, its key, a name of its own — ranks
    // before what it lists as a synonym on the same rung ([`SearchRank`]).
    let own = [scratch.as_str(), field.key]
        .into_iter()
        .chain(prefs::own_names_of(field.key).into_iter().flatten());
    // The ladder lives once, in the config-schema authority, so Settings search and
    // Manual completion rank alike. Every candidate here is already lowercase (the
    // folded label; keys and keywords by construction), the precondition that ladder
    // documents.
    crate::native_config_language::query_match_rank(
        own,
        prefs::keywords_of(field.key).iter().copied(),
        query.text,
        query.reach,
    )
}

/// The macOS or unsupported-platform subtitle, the same at every width and
/// for every copy: what the page is about, never a promise this copy may not
/// keep (the status card says what it can do). Linux uses a separate subtitle
/// naming its native disk transaction, not the macOS session handoff.
fn update_page_subtitle(native_updater: bool) -> &'static str {
    if !native_updater {
        // The headline ("No in-app updater here.") and the detail line name the rest.
        "Updates arrive by reinstalling."
    } else {
        "Your version of aterm and how it updates."
    }
}

/// Search's subtitle where nothing starts a word with `typed`
/// ([`MatchReach::Loose`]): why what it lists holds the query only inside a
/// word or as initials, with the query as typed.
fn loose_search_subtitle(typed: &str) -> String {
    format!("No word starts with \u{201c}{typed}\u{201d}.")
}

/// A field page's one subtitle, the same at every width.
fn settings_fields_subtitle(
    route: SettingsRoute,
    global_search: bool,
    modified_only: bool,
) -> &'static str {
    if global_search {
        "Matching pages, settings and keys."
    } else if modified_only {
        "Everything you changed."
    } else {
        route_subtitle(route)
    }
}

/// A page's one subtitle, the same at every width.
fn route_subtitle(route: SettingsRoute) -> &'static str {
    match route {
        SettingsRoute::Appearance => "Theme, colors, contrast, and effects.",
        SettingsRoute::Themes => "Browse, try, and tune color themes.",
        SettingsRoute::TextFonts => "Fonts, size, display faces, and ligatures.",
        SettingsRoute::CursorMotion => "Cursor shape, blink, glow, and motion.",
        SettingsRoute::CursorStyles => "Point at a style to preview it; click to save.",
        SettingsRoute::Sound => "Typing sounds, chimes, and the bell.",
        SettingsRoute::WindowTabs => "Size, tabs, padding, and session restore.",
        SettingsRoute::TabColor => "Pick any color for your selected tab.",
        SettingsRoute::Wallpaper => "An image behind every terminal tab.",
        SettingsRoute::KeyboardInput => "Keyboard, clipboard, and typing feedback.",
        SettingsRoute::Terminal => "Scrollback, text direction, shell, and renderer.",
        SettingsRoute::Security => "Program permissions and privacy.",
        SettingsRoute::Home
        | SettingsRoute::Modified
        | SettingsRoute::Manual
        | SettingsRoute::SoftwareUpdate
        | SettingsRoute::Packages
        | SettingsRoute::Harness
        | SettingsRoute::Ai
        | SettingsRoute::Tabs
        | SettingsRoute::Messages
        | SettingsRoute::About => "",
    }
}

fn key_fragment(value: &str) -> String {
    value
        .chars()
        .map(|character| {
            if character.is_ascii_alphanumeric() {
                character.to_ascii_lowercase()
            } else {
                '-'
            }
        })
        .collect::<String>()
        .trim_matches('-')
        .to_string()
}

/// Keep a plain fragment when free; otherwise find a free ordinal suffix.
/// A suffixed fragment may itself be an authored key, so each candidate takes
/// part in the same local set before it is used by a row.
fn unique_key_fragment(value: &str, ordinal: usize, used: &mut BTreeSet<String>) -> String {
    let base = key_fragment(value);
    if used.insert(base.clone()) {
        return base;
    }
    let mut suffix = ordinal;
    loop {
        let candidate = format!("{base}-{suffix}");
        if used.insert(candidate.clone()) {
            return candidate;
        }
        suffix += 1;
    }
}

